_V14_TICKET_LOCKS: weakref.WeakValueDictionary[int, threading.RLock] = weakref.WeakValueDictionary()
_V14_TICKET_LOCKS_GUARD = threading.RLock()

def _v14_ticket_lock(ticket: int) -> threading.RLock:
    """Return a per-ticket lock without retaining closed ticket IDs forever.

    Weak values keep the registry bounded naturally: the lock remains alive while any
    decision path holds it and is discarded automatically after the final holder exits.
    """
    key = int(ticket)
    with _V14_TICKET_LOCKS_GUARD:
        lock = _V14_TICKET_LOCKS.get(key)
        if lock is None:
            lock = threading.RLock()
            _V14_TICKET_LOCKS[key] = lock
        return lock

def _strict_float(value: Any, field: str) -> float:
    try:
        out = float(value)
    except (TypeError, ValueError) as exc:
        raise ValueError(f"{field} must be numeric") from exc
    if not math.isfinite(out):
        raise ValueError(f"{field} must be finite")
    return out

def _v14_dynamic_sl_decision(*, pos: dict[str, Any], state: dict[str, Any], market: dict[str, Any], desired_sl: float | None, desired_tp: float | None, recovery_score: float, invalidated: bool, initial_risk: float, max_giveback: float) -> Any:
    ticket = int(_strict_float(pos.get("ticket"), "ticket"))
    symbol = str(pos.get("symbol") or market.get("symbol") or "").strip()
    side = str(pos.get("direction") or pos.get("side") or "").upper()
    entry = _strict_float(pos.get("entryPrice", pos.get("price_open")), "entry")
    bid = _strict_float(market.get("bid", pos.get("currentPrice", pos.get("price_current"))), "bid")
    ask = _strict_float(market.get("ask", pos.get("currentPrice", pos.get("price_current"))), "ask")
    specs = mt5_bridge.symbol_specs(symbol) or {}
    tick_size = _strict_float(specs.get("tradeTickSize", specs.get("tickSize", specs.get("point", 0.01))), "tick_size")
    point = _strict_float(specs.get("point", tick_size), "point")
    rules = V14BrokerRules(tick_size=tick_size, stops_level_points=float(specs.get("stopsLevel", 0) or 0), freeze_level_points=float(specs.get("freezeLevel", 0) or 0), point=point)
    peak_r = float(state.get("peakDist", 0.0) or 0.0) / max(initial_risk, 1e-9)
    current_price = bid if side == "BUY" else ask
    current_r = ((current_price-entry) if side == "BUY" else (entry-current_price)) / max(initial_risk, 1e-9)
    seq = int(state.get("v14Sequence", 0) or 0) + 1
    snap = V14PositionSnapshot(ticket=ticket, symbol=symbol, side=side, entry=entry, bid=bid, ask=ask, sl=float(pos.get("sl") or 0) or None, tp=float(pos.get("tp") or 0) or None, volume=_strict_float(pos.get("volume", pos.get("lots", 0.01)), "volume"), initial_risk_price=max(initial_risk, tick_size), peak_profit_r=max(0.0, peak_r), current_profit_r=current_r, timestamp=time.time(), sequence=seq)
    try:
        prior = V14DynamicSLState(str(state.get("v14DynamicState") or V14DynamicSLState.INITIAL_PROTECTION.value))
    except ValueError:
        prior = V14DynamicSLState.ERROR_SAFE
    with _v14_ticket_lock(ticket):
        decision = v14_decide(snap, rules, state=prior, recovery_score=max(0.0,min(100.0,float(recovery_score))), invalidated=bool(invalidated), max_giveback_fraction=max_giveback, desired_sl=desired_sl, desired_tp=desired_tp)
        if v14_decision_is_stale(decision, snap):
            raise RuntimeError("V14 Dynamic SL decision became stale before execution")
        state["v14Sequence"] = seq
        state["v14DynamicState"] = decision.state_after.value
        state["v14LastDecision"] = decision.to_dict()
        return decision

def _execution_identity(payload: dict[str, Any]) -> str:
    return ExecutionLedger.explicit_identity(payload)


def _stable_execution_identity(source: str, *parts: Any) -> str:
    """Create one deterministic ID at the decision site and reuse it for every retry."""
    raw = json.dumps(
        {"namespace": "godmode-execution-v1", "source": str(source), "parts": parts},
        sort_keys=True,
        separators=(",", ":"),
        default=str,
    )
    return f"gm-{hashlib.sha256(raw.encode('utf-8')).hexdigest()[:40]}"


def _signal_event_anchor(decision: dict[str, Any], market: dict[str, Any]) -> str:
    """Return the broker-bar anchor that makes one signal stable across scanner retries."""
    for row in reversed(market.get("candles") or []):
        bar_time = row.get("time") or row.get("timestamp") or row.get("epoch")
        if bar_time not in (None, "", 0):
            return f"{market.get('timeframe') or 'M15'}:{bar_time}"
    for field in ("executionId", "signalId", "decisionId", "id"):
        value = str(decision.get(field) or "").strip()
        if value:
            return value
    return ""


def _missing_execution_identity(payload: dict[str, Any]) -> dict[str, Any] | None:
    identity = _execution_identity(payload)
    if not identity:
        return {
            "ok": False,
            "blocked": True,
            "reason": "missing_execution_identity",
            "message": "A stable executionId is required for every order-opening command.",
        }
    if len(identity) > 160:
        return {
            "ok": False,
            "blocked": True,
            "reason": "invalid_execution_identity",
            "message": "executionId is too long (maximum 160 characters).",
        }
    return None

def _pid_alive(pid: int) -> bool:
    if pid <= 0: return False
    try:
        os.kill(pid, 0); return True
    except OSError:
        return False

def _acquire_instance_lock() -> None:
    global _INSTANCE_LOCK_OWNED
    INSTANCE_LOCK_FILE.parent.mkdir(parents=True, exist_ok=True)
    if INSTANCE_LOCK_FILE.exists():
        try:
            row=json.loads(INSTANCE_LOCK_FILE.read_text(encoding="utf-8")); pid=int(row.get("pid") or 0)
        except Exception:
            pid=0
        if _pid_alive(pid):
            raise RuntimeError(f"Another GodMode backend instance already owns {INSTANCE_LOCK_FILE} (pid={pid}).")
        INSTANCE_LOCK_FILE.unlink(missing_ok=True)
    fd=os.open(str(INSTANCE_LOCK_FILE), os.O_CREAT|os.O_EXCL|os.O_WRONLY)
    os.write(fd, json.dumps({"pid":os.getpid(),"engine":ENGINE_INSTANCE_ID,"buildId":BUILD_ID,"created":time.time()}).encode("utf-8")); os.close(fd)
    _INSTANCE_LOCK_OWNED=True

def _release_instance_lock() -> None:
    global _INSTANCE_LOCK_OWNED
    if _INSTANCE_LOCK_OWNED:
        try: INSTANCE_LOCK_FILE.unlink(missing_ok=True)
        finally: _INSTANCE_LOCK_OWNED=False

@asynccontextmanager
async def _app_lifespan(_app: FastAPI):
    _acquire_instance_lock()
    await startup_mt5_autoconnect()
    await startup_auto_trader()
    BACKGROUND_TASKS.append(asyncio.create_task(_automatic_reconciliation_loop(), name="execution-reconciliation"))
    BACKGROUND_TASKS.append(asyncio.create_task(_readiness_component_loop(), name="readiness-components"))
    BACKGROUND_TASKS.append(asyncio.create_task(_readiness_snapshot_loop(), name="readiness-snapshot"))
    try:
        yield
    finally:
        tasks = list(BACKGROUND_TASKS)
        if _AUTO_LOOP_TASK is not None and _AUTO_LOOP_TASK not in tasks:
            tasks.append(_AUTO_LOOP_TASK)
        if _PRIORITY_INTENT_TASK is not None and _PRIORITY_INTENT_TASK not in tasks:
            tasks.append(_PRIORITY_INTENT_TASK)
        for task in tasks:
            if task and not task.done():
                task.cancel()
        if tasks:
            await asyncio.gather(*tasks, return_exceptions=True)
        try:
            mt5_bridge.disconnect()
        except Exception as exc:
            LOGGER.exception("MT5 disconnect during shutdown failed: %s", exc)
        READINESS_COMPONENT_MONITOR.shutdown()
        READINESS_LANE.shutdown()
        _release_instance_lock()

app = FastAPI(title="GodMode Gold Trading Bot API", version=APP_VERSION, lifespan=_app_lifespan)

# V15.4.3: componentised readiness kernel. Slow probes are refreshed independently
# with one in-flight call per component; the aggregate snapshot never performs MT5,
# validation, Tick Guard, certification, or ledger work. This removes the repeating
# aggregate deadline/rotating-executor failure while retaining fail-closed authority.
_READINESS_CACHE_LOCK = threading.RLock()
_READINESS_CACHE: dict[str, Any] = {
    "payload": None, "lastSuccessAt": 0.0, "lastAttemptAt": 0.0, "error": None,
    "consecutiveFailures": 0, "lastDurationMs": 0.0,
}
# Compatibility object retained for existing diagnostics/tests. It is deliberately
# unused by the readiness producer and therefore cannot rotate or accumulate workers.
READINESS_LANE = ProtectedThreadLane("readiness", max_workers=1, timeout_seconds=2.0)
READINESS_COMPONENT_MONITOR = ReadinessComponentMonitor(max_workers=4)
_READINESS_COMPONENTS_REGISTERED = False

def _tick_guard_probe() -> dict[str, Any]:
    mt5 = mt5_bridge.status()
    connected = bool(mt5.get("connected"))
    live_enabled = bool(mt5.get("liveTradingEnabled"))
    if connected and live_enabled:
        return _tick_guard_heartbeat_status()
    automation = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    return {
        "ok": False,
        "required": bool(automation.get("requireTickGuardForLive", False)),
        "configured": bool(str(automation.get("mql5ControlFilePath") or "").strip()),
        "message": "Tick Guard is evaluated when live trading is enabled.",
    }

def _register_readiness_components() -> None:
    global _READINESS_COMPONENTS_REGISTERED
    if _READINESS_COMPONENTS_REGISTERED:
        return
    READINESS_COMPONENT_MONITOR.register(
        "mt5Status", mt5_bridge.status, interval_seconds=0.40, timeout_seconds=0.25,
        critical=True, max_age_seconds=1.5,
    )
    READINESS_COMPONENT_MONITOR.register(
        "market", _market_state, interval_seconds=0.75, timeout_seconds=0.35,
        critical=True, max_age_seconds=2.5,
    )
    READINESS_COMPONENT_MONITOR.register(
        "tickGuard", _tick_guard_probe, interval_seconds=0.75, timeout_seconds=0.45,
        critical=True, max_age_seconds=3.0,
    )
    READINESS_COMPONENT_MONITOR.register(
        "certification", _live_certification_status, interval_seconds=3.0, timeout_seconds=1.2,
        critical=True, max_age_seconds=12.0,
    )
    READINESS_COMPONENT_MONITOR.register(
        "validation", _validation_status, interval_seconds=10.0, timeout_seconds=1.5,
        critical=True, max_age_seconds=35.0,
    )
    READINESS_COMPONENT_MONITOR.register(
        "unresolved", EXECUTION_LEDGER.unresolved, interval_seconds=0.75, timeout_seconds=0.35,
        critical=True, max_age_seconds=3.0,
    )
    _READINESS_COMPONENTS_REGISTERED = True

def _readiness_component_snapshots() -> dict[str, dict[str, Any]]:
    _register_readiness_components()
    return READINESS_COMPONENT_MONITOR.snapshots()

async def _readiness_component_loop() -> None:
    _register_readiness_components()
    await READINESS_COMPONENT_MONITOR.refresh_all(force=True)
    while True:
        try:
            await READINESS_COMPONENT_MONITOR.refresh_due()
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            # Component monitor failures are isolated and retain last-known-good data.
            LOGGER.warning("Readiness component scheduler recovered: %s", exc)
        await asyncio.sleep(0.20)

def _publish_readiness_snapshot() -> dict[str, Any]:
    started = time.perf_counter()
    payload = _compose_cached_readiness()
    now = time.time()
    with _READINESS_CACHE_LOCK:
        _READINESS_CACHE.update(
            payload=payload, lastSuccessAt=now, lastAttemptAt=now, error=None,
            consecutiveFailures=0, lastDurationMs=round((time.perf_counter()-started)*1000.0, 3),
        )
    return payload

def _record_readiness_failure(message: str) -> None:
    with _READINESS_CACHE_LOCK:
        _READINESS_CACHE["lastAttemptAt"] = time.time()
        _READINESS_CACHE["error"] = str(message)
        _READINESS_CACHE["consecutiveFailures"] = int(_READINESS_CACHE.get("consecutiveFailures", 0) or 0) + 1

async def _readiness_snapshot_loop() -> None:
    while True:
        try:
            _publish_readiness_snapshot()
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            _record_readiness_failure(f"{type(exc).__name__}: {exc}")
            LOGGER.exception("Readiness aggregate snapshot failed")
        await asyncio.sleep(0.50)

def _cached_readiness_snapshot() -> dict[str, Any]:
    with _READINESS_CACHE_LOCK:
        payload = deepcopy(_READINESS_CACHE.get("payload"))
        updated = float(_READINESS_CACHE.get("lastSuccessAt") or 0.0)
        attempted = float(_READINESS_CACHE.get("lastAttemptAt") or 0.0)
        error = _READINESS_CACHE.get("error")
        failures = int(_READINESS_CACHE.get("consecutiveFailures", 0) or 0)
        duration_ms = float(_READINESS_CACHE.get("lastDurationMs", 0.0) or 0.0)
    age = max(0.0, time.time() - updated) if updated else None
    attempt_age = max(0.0, time.time() - attempted) if attempted else None
    if not isinstance(payload, dict):
        return {"ok": False, "ready": False, "tradingReady": False, "version": APP_VERSION, "buildId": BUILD_ID,
                "reasons": ["Readiness snapshot is warming up"], "warnings": [], "snapshotAgeSeconds": age,
                "snapshotStatus": "WARMING", "refreshError": error,
                "readinessComponents": _readiness_component_snapshots()}
    payload["snapshotAgeSeconds"] = round(age or 0.0, 3)
    payload["lastAttemptAgeSeconds"] = round(attempt_age, 3) if attempt_age is not None else None
    payload["consecutiveRefreshFailures"] = failures
    payload["readinessDurationMs"] = duration_ms
    payload["readinessLane"] = {"name": "readiness", "mode": "component-kernel", "healthy": True}
    payload["snapshotStatus"] = "LIVE" if age is not None and age <= 2.0 else "STALE"
    if age is None or age > 4.0:
        payload["ready"] = False; payload["ok"] = False; payload["tradingReady"] = False
        payload.setdefault("reasons", []).append(f"Readiness aggregate stale ({round(age or 0.0,1)}s)")
    if error:
        payload["refreshError"] = error
    return payload
