_rate_bucket: dict[str, deque[float]] = {}
_rate_bucket_seen: dict[str, float] = {}
_rate_bucket_lock = threading.Lock()
_MAX_RATE_CLIENTS = 4096


def _request_is_loopback(request: Request) -> bool:
    host = request.client.host if request.client else ""
    if host in {"testclient", "localhost"}:
        return True
    try:
        return ipaddress.ip_address(host).is_loopback
    except ValueError:
        return False


def _request_has_secure_transport(request: Request) -> bool:
    if str(request.url.scheme).lower() == "https":
        return True
    # Only trust proxy scheme metadata from a same-host reverse proxy. A remote
    # client must not be able to claim that its plaintext connection was HTTPS.
    return _request_is_loopback(request) and str(request.headers.get("X-Forwarded-Proto") or "").lower() == "https"


def _host_and_port(value: str, *, scheme: str = "http") -> tuple[str, int]:
    """Normalise a Host header or URL netloc for same-origin checks."""
    raw = str(value or "").strip().lower()
    if not raw:
        return "", 443 if scheme == "https" else 80
    try:
        parsed = urllib.parse.urlsplit(raw if "://" in raw else f"//{raw}", scheme=scheme)
        host = str(parsed.hostname or "").strip().lower()
        port = int(parsed.port or (443 if scheme == "https" else 80))
        return host, port
    except Exception:
        return "", 443 if scheme == "https" else 80


def _browser_origin_is_allowed(request: Request, origin: str) -> bool:
    """Allow the dashboard that served the page to write to its own API.

    V14.1.18 introduced a CSRF origin guard but the default allow-list only
    contained the Vite development server on port 5173. The production dashboard
    is served by FastAPI on port 8000, so every browser POST was rejected with
    HTTP 403 while GET requests continued to work. That made every toggle and
    Save & Apply action appear to revert.
    """
    raw = str(origin or "").strip().rstrip("/")
    if not raw or raw == "null":
        return not raw
    try:
        parsed = urllib.parse.urlsplit(raw)
    except Exception:
        return False
    scheme = str(parsed.scheme or "").lower()
    if scheme not in {"http", "https"} or not parsed.hostname:
        return False

    origin_host, origin_port = _host_and_port(parsed.netloc, scheme=scheme)
    request_host, request_port = _host_and_port(
        str(request.headers.get("host") or request.url.netloc),
        scheme=str(request.url.scheme or "http").lower(),
    )
    if origin_host == request_host and origin_port == request_port:
        return True

    # Treat localhost and 127.0.0.1 as equivalent only on the same port. This
    # supports users who launch with one alias and the browser normalises to the
    # other, without broadening access to arbitrary LAN origins.
    loopbacks = {"localhost", "127.0.0.1", "::1"}
    if origin_host in loopbacks and request_host in loopbacks and origin_port == request_port:
        return True

    normalised = {value.rstrip("/").lower() for value in allowed_origins}
    return raw.lower() in normalised


@app.middleware("http")
async def security_middleware(request: Request, call_next):
    client = request.client.host if request.client else "local"
    now = time.time()
    with _rate_bucket_lock:
        q = _rate_bucket.setdefault(client, deque())
        while q and now - q[0] > 60:
            q.popleft()
        if len(q) >= rate_limit_per_minute:
            return JSONResponse({"detail": "Rate limit exceeded"}, status_code=429)
        q.append(now)
        _rate_bucket_seen[client] = now
        if len(_rate_bucket) > _MAX_RATE_CLIENTS:
            expired = sorted(_rate_bucket_seen, key=_rate_bucket_seen.get)[: len(_rate_bucket) - _MAX_RATE_CLIENTS]
            for key in expired:
                _rate_bucket.pop(key, None)
                _rate_bucket_seen.pop(key, None)

    if request.method not in {"GET", "HEAD", "OPTIONS"} and request.url.path.startswith("/api/"):
        origin = str(request.headers.get("Origin") or "").strip()
        fetch_site = str(request.headers.get("Sec-Fetch-Site") or "").lower()
        if fetch_site == "cross-site" or (origin and not _browser_origin_is_allowed(request, origin)):
            return JSONResponse(
                {
                    "detail": "Cross-site state-changing request rejected.",
                    "requestOrigin": origin or None,
                    "expectedHost": str(request.headers.get("host") or request.url.netloc),
                },
                status_code=403,
            )

    if (
        api_key
        and request.url.path.startswith("/api/")
        and request.method not in {"HEAD", "OPTIONS"}
        and not _request_is_loopback(request)
        and not _request_has_secure_transport(request)
    ):
        return JSONResponse(
            {"detail": "Remote API access requires HTTPS; credentials are never accepted over plaintext HTTP."},
            status_code=426,
        )

    # When a server API key is configured (i.e. the bot is exposed for LAN/mobile/remote access), require
    # it on EVERY /api/ call — reads included — so account, market, trade and settings data can't be read
    # by anyone on the network. The static app shell (non-/api) still loads so you can enter the key in
    # Settings → 13. Local-only users (no key set) are unaffected. (Fixes the GET-endpoint exposure gap.)
    if api_key and request.url.path.startswith("/api/") and request.method not in {"HEAD", "OPTIONS"}:
        supplied = str(request.headers.get("X-GodMode-Key") or "")
        if not hmac.compare_digest(supplied, api_key):
            return JSONResponse({"detail": "GodMode API key required. Enter it in Settings → 13. Mobile & Remote Access."}, status_code=401)
    elif request.url.path.startswith("/api/") and not _request_is_loopback(request):
        return JSONResponse(
            {"detail": "Remote/LAN API access is disabled until GODMODE_API_KEY is configured."},
            status_code=503,
        )

    response: Response = await call_next(request)
    response.headers["X-Content-Type-Options"] = "nosniff"
    response.headers["X-Frame-Options"] = "DENY"
    response.headers["Referrer-Policy"] = "no-referrer"
    response.headers["Permissions-Policy"] = "geolocation=(), microphone=(), camera=()"
    response.headers["Content-Security-Policy"] = (
        "default-src 'self'; img-src 'self' data: blob:; style-src 'self' 'unsafe-inline'; "
        + ("script-src 'self' 'unsafe-inline'; " if request.url.path == "/tools" else "script-src 'self'; ")
        + "connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'"
    )
    if request.url.path.startswith("/api/") or request.url.path.startswith("/assets/"):
        response.headers["Cache-Control"] = "no-store, max-age=0, must-revalidate"
        response.headers["Pragma"] = "no-cache"
        response.headers["Expires"] = "0"
    return response


