_SUPPRESSED_EXCEPTION_LAST: dict[str, float] = {}

def _report_suppressed_exception(component: str, exc: BaseException, *, throttle_seconds: float = 60.0) -> None:
    """Record formerly-silent recoverable exceptions without allowing log storms.

    This helper deliberately never raises: health telemetry must not destabilise the
    trading loop it is observing. Repeated identical component failures are throttled.
    """
    try:
        now = time.time()
        last = float(_SUPPRESSED_EXCEPTION_LAST.get(component, 0.0) or 0.0)
        if now - last < max(1.0, float(throttle_seconds)):
            return
        _SUPPRESSED_EXCEPTION_LAST[component] = now
        detail = f"{type(exc).__name__}: {exc}"[:500]
        RUNTIME_HEALTH.fail(component, detail)
        LOGGER.warning("Recoverable subsystem failure [%s]: %s", component, detail)
    except BaseException:
        # Last-resort containment: telemetry must never interrupt trading or startup.
        return
