def _first_number(text: str) -> float | None:
    import re
    m = re.search(r"-?\d+(?:\.\d+)?", text)
    return float(m.group()) if m else None


def _deep_merge(base: dict[str, Any], patch: dict[str, Any]) -> dict[str, Any]:
    for key, value in patch.items():
        if isinstance(value, dict) and isinstance(base.get(key), dict):
            _deep_merge(base[key], value)
        else:
            base[key] = value
    return base


def _sync_validation_settings(settings: dict[str, Any]) -> dict[str, Any]:
    """Keep the visible Settings toggle and the backend validation gate on one source of truth.

    V14.1.17 fix — the old logic ALWAYS made ``validation.enabled`` authoritative and
    overwrote ``execution.validationLockEnabled`` from it. That meant any imported config
    or UI wired only to the legacy ``execution.validationLockEnabled`` field was silently
    reverted on save. The two fields now sync symmetrically: whichever side is present
    in the payload wins, ties go to ``validation.enabled`` (the V12.37+ canonical field).
    """
    if not isinstance(settings, dict):
        return settings
    validation = settings.setdefault("validation", {})
    execution = settings.setdefault("execution", {})
    if not isinstance(validation, dict):
        validation = settings["validation"] = {}
    if not isinstance(execution, dict):
        execution = settings["execution"] = {}
    v_present = "enabled" in validation
    e_present = "validationLockEnabled" in execution
    if v_present and e_present:
        # Both sides present. If they agree, keep. If they disagree, canonical wins,
        # but log so a stale imported config never blows away a real toggle silently.
        if bool(validation.get("enabled")) != bool(execution.get("validationLockEnabled")):
            LOGGER.info(
                "validation sync: conflicting fields (validation.enabled=%s, execution.validationLockEnabled=%s) — canonical validation.enabled wins",
                validation.get("enabled"), execution.get("validationLockEnabled"),
            )
        canonical = bool(validation.get("enabled"))
        validation["enabled"] = canonical
        execution["validationLockEnabled"] = canonical
    elif v_present:
        execution["validationLockEnabled"] = bool(validation.get("enabled"))
    elif e_present:
        validation["enabled"] = bool(execution.get("validationLockEnabled"))
    else:
        # Neither field defined — default to fail-closed (validation ON).
        validation["enabled"] = True
        execution["validationLockEnabled"] = True
    return settings


def _strip_runtime_settings_keys(settings: dict[str, Any]) -> dict[str, Any]:
    """Remove UI/cache-only keys before merging or writing persistent settings.

    The frontend receives live status keys such as ``mt5`` after a save. If the user
    immediately clicks Save again, those runtime keys used to be posted back and
    written into settings.json. That polluted the config and made later reloads look
    inconsistent.
    """
    clean = deepcopy(settings) if isinstance(settings, dict) else {}
    for key in SETTINGS_RUNTIME_KEYS:
        clean.pop(key, None)
    # Public GET /api/settings responses include derived UI-only flags. They must
    # never be posted back into the persistent settings document.
    telegram = clean.get("telegram")
    if isinstance(telegram, dict):
        telegram.pop("botTokenConfigured", None)
    return clean


# V12.67 DEEP-CONFLICT ROOT-CAUSE FIX ──────────────────────────────────────────────
# GET /api/settings masks mt5Connection.password to "" for safety. The Settings page then
# holds "" and posts the WHOLE settings object on Save. _deep_merge wrote that "" over the
# real stored password — so every Save silently WIPED the MT5 password (and Config Import,
# whose exports mask ALL secrets, wiped Telegram token + every API key). On the next
# restart MT5 could no longer log in and the config looked like it had "rolled back".
# Fix: an empty-string value on a known secret path means "unchanged" — drop it before merging.
SETTINGS_SECRET_PATHS = (
    "mt5Connection.password", "telegram.botToken", "aiProvider.apiKey",
    "dataFeeds.dxyKey", "dataFeeds.us10yKey", "dataFeeds.economicCalendarKey",
    "dataFeeds.marketNewsKey", "strategyLab.feedKey",
)

def _drop_blank_secrets(payload: dict[str, Any]) -> dict[str, Any]:
    """Remove empty-string secret fields from an incoming settings patch.

    An empty masked secret coming back from the UI or an exported config must mean
    'keep the stored value', never 'erase the stored value'.
    """
    if not isinstance(payload, dict):
        return payload
    for dotted in SETTINGS_SECRET_PATHS:
        parts = dotted.split(".")
        node = payload
        for key in parts[:-1]:
            node = node.get(key) if isinstance(node, dict) else None
            if node is None:
                break
        if isinstance(node, dict):
            leaf = parts[-1]
            if leaf in node and (node[leaf] is None or str(node[leaf]).strip() in {"", "••••••••", "********"}):
                node.pop(leaf, None)
    return payload



