def _save_feed_status_cache() -> None:
    try:
        FEED_STATUS_CACHE_FILE.write_text(json.dumps(FEED_STATUS_CACHE, indent=2, default=str), encoding="utf-8")
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_1201", _suppressed_exc)

def _cache_feed_status(key: str, status: dict[str, Any], live_predicate=None, stale_seconds: int = 1800) -> dict[str, Any]:
    """Persist last-known-good feed state so Dashboard navigation does not flicker OFF.
    A current failure returns the last live state marked stale instead of erasing it immediately."""
    now = time.time()
    live_ok = False
    try:
        live_ok = bool(live_predicate(status)) if live_predicate else str(status.get("status", "")).lower() == "live"
    except Exception:
        live_ok = False
    if live_ok:
        status = {**status, "persisted": True, "stale": False, "lastLiveAt": now}
        FEED_STATUS_CACHE[key] = status
        _save_feed_status_cache()
        return status
    cached = FEED_STATUS_CACHE.get(key) if isinstance(FEED_STATUS_CACHE, dict) else None
    if isinstance(cached, dict) and (now - float(cached.get("lastLiveAt", 0) or 0)) <= stale_seconds:
        # Keep the UI and backtester context live while a refresh is temporarily empty/error.
        merged = {**cached, "stale": True, "currentStatus": status.get("status"), "currentDetail": status.get("detail")}
        if str(status.get("status", "")).lower() in {"not_configured", "off"} and not status.get("configured"):
            return status
        return merged
    return status

_CASCADE_LATCH: dict[str, Any] = {}
_CASCADE_LATCH_LOCK = threading.RLock()
_CASCADE_CACHE: dict[str, tuple[float, dict[str, Any]]] = {}
_CASCADE_CACHE_TTL = 2.0   # seconds; a cascade does not change meaningfully faster than this
BREATHING_TELEMETRY: dict[str, Any] = {"requests": 0, "granted": 0, "denied": 0, "deniedScores": []}
AUTO_TRADE_STATE: dict[str, Any] = {"enabled": False, "lastFire": 0.0, "lastResult": None, "cooldownSeconds": 15,
                                    "lossStreak": 0, "winStreak": 0, "postLossUntil": 0.0, "pausedUntil": 0.0, "lastLoser": None,
                                    "lossMemory": [], "sameDirectionLossLock": {}, "lastLossGovernorAlert": 0.0,
                                    "previousPyramidAddFailed": False}
AUTO_TRADE_HEARTBEAT: list[dict[str, Any]] = []

NOTIFICATIONS: list[dict[str, Any]] = []
RECENT_CLOSED_TRADE_CACHE: list[dict[str, Any]] = []

# Decision cache: shared across /dashboard, /signals, /ai/decision so all pages show the same signal
_DECISION_CACHE: dict[str, Any] = {}
_DECISION_CACHE_TS: float = 0.0
_DECISION_CACHE_TTL: float = 4.0  # seconds

# Dashboard cache: avoids slow full reloads when switching pages. The live trade
# loop still runs independently; this cache only protects the UI endpoint from
# repeatedly rebuilding analytics/history on every Dashboard mount.
_DASHBOARD_CACHE: dict[str, Any] = {}
_DASHBOARD_CACHE_TS: float = 0.0
_DASHBOARD_CACHE_TTL: float = 4.0  # seconds — V12.56 reduce dashboard reload lag
_ANALYTICS_CACHE: dict[str, Any] = {}
_ANALYTICS_CACHE_TS: float = 0.0
_ANALYTICS_CACHE_TTL: float = 20.0  # seconds — expensive MT5 history aggregation cache

# V12.58 UI responsiveness guards. MT5 Python calls can be slow or can block during
# terminal/broker IPC. These locks stop duplicate expensive refreshes from piling up
# and allow endpoints to serve the last good snapshot instead of spinning forever.
_DASHBOARD_REFRESH_LOCK = threading.Lock()
_ANALYTICS_REFRESH_LOCK = threading.Lock()
_DECISION_REFRESH_LOCK = threading.Lock()
_TRADES_REFRESH_LOCK = threading.Lock()
_TRADES_CACHE: dict[str, Any] = {}
_TRADES_CACHE_TS: float = 0.0
_TRADES_CACHE_TTL: float = 1.0  # V13.5: was 6.0. Open-trade markers + live PnL read from
# this cache; at 6s the Trades tab could show PnL up to 14s old (6s cache + 8s poll). Open
# positions are a cheap MT5 call, so 1s costs little and makes the marker/PnL feel live.
_ACCOUNT_CACHE: dict[str, Any] = {}
_ACCOUNT_CACHE_TS: float = 0.0
_ACCOUNT_CACHE_TTL: float = 2.0
_MARKET_CACHE: dict[str, Any] = {}
_MARKET_CACHE_TS: float = 0.0
_MARKET_CACHE_TTL: float = 0.6  # V13.5: was 2.0 while the fast-sniper loop ticks at 1.0s —
# so up to half of all entry evaluations re-scored a price the engine had already seen.
# 0.6 < 1.0 guarantees every sniper tick reasons about a fresh snapshot.

# Background worker guard: keeps auto-entry/protection/watchdog work from blocking
# the FastAPI event loop or stacking up if MT5 becomes slow.
_BACKGROUND_JOB_LOCKS: dict[str, threading.Lock] = {}
_BACKGROUND_JOB_LOCKS_GUARD = threading.RLock()
_BACKGROUND_JOB_STATE: dict[str, dict[str, Any]] = {}

def _background_job_lock(label: str) -> threading.Lock:
    with _BACKGROUND_JOB_LOCKS_GUARD:
        return _BACKGROUND_JOB_LOCKS.setdefault(str(label), threading.Lock())

# V12.61 Turbo UI cache: page navigation must never wait for a heavy MT5/history
# refresh. Endpoints return the last good snapshot instantly and refresh in a
# daemon thread when stale. This keeps buttons/pages responsive even during Burst
# management or slow broker IPC.
_TURBO_REFRESH_FLAGS: dict[str, float] = {}

def _spawn_turbo_refresh(name: str, fn) -> None:
    try:
        if _TURBO_REFRESH_FLAGS.get(name):
            return
        _TURBO_REFRESH_FLAGS[name] = time.time()
        def _runner():
            try:
                fn()
            except Exception as exc:
                try:
                    AUTO_TRADE_STATE["lastSlowOperation"] = {"label": f"turbo_refresh_{name}", "error": str(exc), "at": time.time()}
                except Exception as _suppressed_exc:
                    _report_suppressed_exception("suppressed_exception_line_1293", _suppressed_exc)
            finally:
                try:
                    _TURBO_REFRESH_FLAGS.pop(name, None)
                except Exception as _suppressed_exc:
                    _report_suppressed_exception("suppressed_exception_line_1298", _suppressed_exc)
        threading.Thread(target=_runner, name=f"godmode-turbo-{name}", daemon=True).start()
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_1301", _suppressed_exc)


def _market_state() -> dict[str, Any]:
    """Is the market open? {open: bool, reason: str, source: str}. Weekend schedule (UTC) confirmed
    by live tick-staleness when MT5 is connected (see mt5_bridge.market_open)."""
    try:
        state = mt5_bridge.market_open()
        if not isinstance(state, dict) or not isinstance(state.get("open"), bool):
            raise ValueError("market_open returned a malformed state")
        return state
    except Exception as exc:
        LOGGER.exception("Authoritative market-state check failed closed")
        try:
            RUNTIME_HEALTH.fail("market_state", exc)
        except Exception as health_exc:
            LOGGER.warning("Unable to record market-state health failure: %s", health_exc)
        return {
            "open": False,
            "reason": f"Market-state check failed closed: {type(exc).__name__}: {exc}",
            "source": "error",
            "error": True,
        }


def _cached_decision() -> dict[str, Any]:
    global _DECISION_CACHE, _DECISION_CACHE_TS
    now = time.time()
    if now - _DECISION_CACHE_TS < _DECISION_CACHE_TTL and _DECISION_CACHE:
        return _DECISION_CACHE
    # If another request is already building the expensive MTF decision, return the
    # last good decision immediately. This prevents multiple dashboard/topbar/signal
    # calls from freezing the UI together.
    acquired = _DECISION_REFRESH_LOCK.acquire(blocking=False)
    if not acquired:
        if _DECISION_CACHE:
            return {**deepcopy(_DECISION_CACHE), "stale": True, "staleReason": "decision_refresh_in_progress"}
        return {
            "action": "WAIT",
            "confidence": 0,
            "quality": "NO_DATA",
            "reasons": ["Decision cache is warming in another worker."],
            "stale": True,
            "staleReason": "decision_refresh_in_progress",
        }
    try:
        market = _live_market()
        # Let the engine honour the user's enabled sessions (so e.g. Asia trades when ON).
        _tcfg = SETTINGS_STATE.get("trading", {}) if isinstance(SETTINGS_STATE.get("trading"), dict) else {}
        _aicfg = SETTINGS_STATE.get("ai", {}) if isinstance(SETTINGS_STATE.get("ai"), dict) else {}
        market = {**market, "allowedSessions": _tcfg.get("allowedSessions"), "respectAllowedSessions": _aicfg.get("respectAllowedSessions", True), "htfTrendAlignment": _aicfg.get("htfTrendAlignment", False)}
        # STRATEGIES_STATE is defined at module level after _apply_runtime_settings()
        strats = list(globals().get("STRATEGIES_STATE", {}).values())
        result = decision_engine.evaluate(market, strats, memory.stats(live_only=True)) if market.get("connected") else {"action": "WAIT", "confidence": 0, "quality": "NO_DATA", "reasons": ["MT5 not connected."]}
        mkt_state = _market_state()
        if not mkt_state.get("open", False):
            # Market is closed — surface it clearly and stand down (no entries while closed).
            result = {**result, "action": "MARKET_CLOSED", "quality": "MARKET_CLOSED",
                      "reason": f"Market closed — {mkt_state.get('reason', 'outside trading hours')}."}
        _DECISION_CACHE = {**result, "_market": market, "_generatedAt": time.time(),
                           "marketOpen": bool(mkt_state.get("open", False)),
                           "marketStatus": mkt_state.get("reason", "")}
        _DECISION_CACHE_TS = time.time()
        return _DECISION_CACHE
    except Exception as exc:
        if _DECISION_CACHE:
            return {**deepcopy(_DECISION_CACHE), "stale": True, "staleReason": f"decision_refresh_failed: {exc}"}
        return {"action": "WAIT", "confidence": 0, "quality": "NO_DATA", "reasons": [f"Decision refresh failed: {exc}"]}
    finally:
        try:
            if acquired:
                _DECISION_REFRESH_LOCK.release()
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_1352", _suppressed_exc)

def _push_notification(title: str, message: str, kind: str = "info", payload: dict[str, Any] | None = None) -> dict[str, Any]:
    item = {
        "id": int(time.time() * 1000),
        "time": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "title": title,
        "message": message,
        "kind": kind,
        "payload": payload or {},
        "read": False,
    }
    NOTIFICATIONS.insert(0, item)
    del NOTIFICATIONS[50:]
    return item



def _merge_recent_closed(history: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Merge immediately-closed trades into the MT5 history for instant display.

    When a trade closes through the bot UI, it's added to RECENT_CLOSED_TRADE_CACHE
    so it appears instantly in the Trades page without waiting for MT5 history
    propagation (which can take minutes to hours). Once MT5 history has the deal,
    the cached version is excluded to avoid duplicates.
    """
    seen = {str(x.get("ticket")) for x in history if x.get("ticket") is not None}
    # Also prune cache entries older than 24 hours to avoid indefinite accumulation
    cutoff = time.time() - 86400
    fresh = [
        x for x in RECENT_CLOSED_TRADE_CACHE
        if str(x.get("ticket")) not in seen and float(x.get("_cacheTs", time.time())) > cutoff
    ]
    combined = fresh + history
    # V12.99.2: was hard-capped at 250, which silently truncated the trade history the analytics,
    # coach and calibration all read from — so the counter stopped growing no matter how many new
    # trades closed. Raised to 2000 (still bounded to protect memory/latency) and made tunable.
    cap = 2000
    try:
        cap = int((SETTINGS_STATE.get("meta") or {}).get("maxTradeHistory", 2000) or 2000)
    except Exception:
        cap = 2000
    return combined[: max(250, min(cap, 10000))]


def _cache_close_event_with_ts(payload: dict[str, Any], result: dict[str, Any]) -> None:
    """Cache a just-closed trade for immediate display (bypasses MT5 history delay)."""
    if not result.get("ok"):
        return
    item = {
        "ticket": payload.get("ticket") or payload.get("position") or (result.get("request") or {}).get("position"),
        "symbol": payload.get("symbol") or (result.get("request") or {}).get("symbol") or mt5_bridge.symbol,
        "direction": payload.get("direction") or payload.get("side") or "—",
        "lots": payload.get("volume") or payload.get("lots") or (result.get("request") or {}).get("volume") or "—",
        "entryPrice": payload.get("entryPrice") or "—",
        "exitPrice": payload.get("exitPrice") or payload.get("currentPrice") or "—",
        "pnlUsd": payload.get("pnlUsd", 0.0),
        "pnlPct": payload.get("pnlPct", 0.0),
        "holdTime": payload.get("holdTime", "Just closed"),
        "closeTime": time.strftime("%Y-%m-%d %H:%M:%S UTC", time.gmtime()),
        "closeTimestamp": time.time(),
        "reason": result.get("message") or "Close request confirmed",
        "magicNumber": mt5_bridge.magic,
        "comment": f"{mt5_bridge.comment_prefix}recent_close",
        "source": "recent_close_cache",
        "_cacheTs": time.time(),
    }
    RECENT_CLOSED_TRADE_CACHE.insert(0, item)
    del RECENT_CLOSED_TRADE_CACHE[30:]


# (replaced by _cache_close_event_with_ts above)


# ── Strategy attribution + AI learning loop ──────────────────────────────────
def _capture_entry_context(result: dict[str, Any], decision: dict[str, Any] | None, payload: dict[str, Any], entry_type: str, strategy_name: str | None = None) -> None:
    """Persist the real strategy + entry rationale for a just-opened trade, keyed by
    every plausible MT5 identifier so closed-trade history can be attributed later.

    V12.41: also supports split TP1-TP4 executions. Multi-target sends return a
    list of child order responses, so collect every child order/deal/position id
    instead of relying only on the top-level result. This keeps Telegram-approved
    split trades fully managed and correctly attributed in history/learning.
    """
    if not result.get("ok"):
        return
    tickets: list[Any] = []

    def _add_ticket_ids(r: dict[str, Any]) -> None:
        res = r.get("result") if isinstance(r.get("result"), dict) else {}
        req = r.get("request") if isinstance(r.get("request"), dict) else {}
        for x in (r.get("ticket"), res.get("order"), res.get("deal"), res.get("position"), req.get("position")):
            if x is not None:
                tickets.append(x)

    _add_ticket_ids(result)
    for child in result.get("results", []) if isinstance(result.get("results"), list) else []:
        if isinstance(child, dict):
            _add_ticket_ids(child)

    decision = decision or {}
    plan = decision.get("tradePlan", {}) if isinstance(decision.get("tradePlan"), dict) else {}
    strat = strategy_name or (decision.get("selectedStrategy", {}) or {}).get("name") or "GodMode Bot"
    ctx = {
        "strategy": strat,
        "entryType": entry_type,
        "side": str(payload.get("side") or payload.get("direction") or decision.get("side") or "").upper() or None,
        "symbol": payload.get("symbol") or decision.get("symbol") or mt5_bridge.symbol,
        "entry": _to_float(plan.get("entry") or payload.get("price") or 0) or None,
        "sl": _to_float(plan.get("sl") or payload.get("sl") or 0) or None,
        "tp1": _to_float(plan.get("tp1") or 0) or None,
        "tp2": _to_float(plan.get("tp2") or 0) or None,
        "tp3": _to_float(plan.get("tp3") or 0) or None,
        "tp4": _to_float(plan.get("tp4") or 0) or None,
        "confidence": decision.get("confidence"),
        "session": decision.get("sessionName") or _live_market().get("session"),
        "regime": decision.get("marketRegime"),
        "reason": decision.get("reason"),
        "quality": decision.get("quality"),
        "source": decision.get("source"),
        "features": deepcopy(decision.get("features") or {}) if isinstance(decision.get("features"), dict) else {},
        "anticipatoryEntry": bool((decision.get("features") or {}).get("anticipatoryEntry")),
        "progressiveStage": (decision.get("features") or {}).get("progressiveStage"),
        "managementProfile": (decision.get("features") or {}).get("managementProfile"),
        "probeRiskPct": (decision.get("features") or {}).get("probeRiskPct"),
        "probeMaxStopPoints": (decision.get("features") or {}).get("probeMaxStopPoints"),
        "partialsTaken": 0,
        "v15DecisionId": payload.get("v15DecisionId"),
        "v15Forecast": payload.get("v15Forecast") if isinstance(payload.get("v15Forecast"), dict) else {},
    }
    trade_context.record_entry(tickets, ctx)


def _trade_r_multiple(t: dict[str, Any], ctx: dict[str, Any] | None) -> float | None:
    """Best-effort realised R from the planned stop distance (needs entry context)."""
    ctx = ctx or {}
    entry = _to_float(ctx.get("entry") or t.get("entryPrice"))
    sl = _to_float(ctx.get("sl"))
    lots = _to_float(t.get("lots") or t.get("volume"))
    pnl = _to_float(t.get("pnlUsd"))
    if entry and sl and lots:
        risk_usd = abs(entry - sl) * lots * 100  # XAUUSD: ~$100 per $1 move per lot
        if risk_usd > 0:
            return round(pnl / risk_usd, 2)
    return None


def _enrich_closed_trade(t: dict[str, Any]) -> dict[str, Any]:
    """Attach real strategy, human reason, R-multiple and any AI review to a trade."""
    ctx = trade_context.match(
        t.get("ticket"), t.get("positionId"), t.get("symbol"),
        t.get("direction") or t.get("side"), _to_float(t.get("entryPrice")), _to_float(t.get("openTimestamp")),
    )
    comment = str(t.get("comment") or "")
    strategy = (ctx or {}).get("strategy") or strategy_from_comment(comment) or "GodMode Bot"
    entry_label = (ctx or {}).get("entryType") or entry_type_label(comment)
    exit_reason = t.get("exitReason") or t.get("reason") or "Closed"
    r_mult = t.get("rMultiple")
    if r_mult is None:
        r_mult = _trade_r_multiple(t, ctx)
    bits = [strategy] + ([entry_label] if entry_label else [])
    reason = f"{' · '.join(bits)} → {exit_reason}"
    if r_mult is not None:
        reason += f" ({r_mult:+.2f}R)"
    out = {
        **t,
        "strategy": strategy,
        "entryReason": (ctx or {}).get("reason"),
        "exitReason": exit_reason,
        "reason": reason,
        "rMultiple": r_mult,
        "confidence": (ctx or {}).get("confidence", t.get("confidence", 0)) or 0,
        "session": (ctx or {}).get("session") or t.get("session"),
        "marketRegime": (ctx or {}).get("regime") or t.get("marketRegime"),
    }
    review = TRADE_REVIEWS.get(str(t.get("ticket")))
    if review:
        out["aiReview"] = review
        out["aiScore"] = review.get("aiScore")
        out["aiNotes"] = review.get("summary")
        out["lessons"] = review.get("lesson")
        out["improvement"] = review.get("improvement")
        out["aiAdjustment"] = review.get("adjustment")
    return out


def _maybe_learn(t: dict[str, Any]) -> None:
    """Record a closed bot trade into performance memory + run the AI reviewer once.
    Idempotent per ticket; skipped for demo data so the learning DB stays real."""
    if not mt5_bridge.status().get("connected"):
        return  # never learn from demo / offline data
    tk = str(t.get("ticket") or "")
    if not tk or tk == "None" or tk in RECORDED_TICKETS:
        return
    enriched = _enrich_closed_trade(t)
    pnl = _to_float(enriched.get("pnlUsd"))
    outcome = "WIN" if pnl > 0 else "LOSS" if pnl < 0 else "BREAK_EVEN"
    record = {
        "ticket": tk,
        "symbol": enriched.get("symbol", "XAUUSD"),
        "strategy": enriched.get("strategy"),
        "session": enriched.get("session"),
        "side": enriched.get("direction") or enriched.get("side"),
        "confidence": enriched.get("confidence"),
        "spread": None,
        "slippage": None,
        "pnl": pnl,
        "rMultiple": enriched.get("rMultiple"),
        "outcome": outcome,
        "source": "godmode_bot",
        "magic": t.get("magicNumber") or mt5_bridge.magic,
        "comment": t.get("comment"),
    }
    res = memory.record_trade(record)
    if res.get("recorded"):
        RECORDED_TICKETS.add(tk)
        try:
            review = ai_reviewer.review(enriched)
            TRADE_REVIEWS[tk] = review; _cap_trade_reviews()
            memory.auto_journal("TRADE_REVIEW", f"{enriched.get('strategy')} {outcome} {pnl:+.2f} USD", json.dumps(review, default=str))
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_1563", _suppressed_exc)


def _enrich_history(history: list[dict[str, Any]], learn: bool = False) -> list[dict[str, Any]]:
    out: list[dict[str, Any]] = []
    for t in history:
        # V12.75: single choke point for the data epoch. Purged (pre-epoch) trades are dropped
        # here, so they can never reach analytics, calibration, the coach, the journal export,
        # OR the learning path below. One float compare per row — no measurable latency.
        if not _after_epoch(t):
            continue
        if learn:
            _maybe_learn(t)
        out.append(_enrich_closed_trade(t))
    return out


AUDIT_OUTCOMES_FILE = DATA_DIR / "ai_audit_outcomes.jsonl"

def _match_audit_outcome(side: str, pnl: float, ticket: str) -> None:
    """Pair a realised close with the newest unscored ai_audit entry of the same side
    within 6h. Executed verdicts (APPROVE/DOWNGRADE) get WIN/LOSS attached."""
    cutoff = time.time() - 6 * 3600
    for evt in DECISION_JOURNAL:
        if not isinstance(evt, dict) or evt.get("category") != "ai_audit":
            continue
        if float(evt.get("epoch", 0) or 0) < cutoff:
            break
        if evt.get("_scored") or str(evt.get("side") or "").upper() != side:
            continue
        if str(evt.get("decision")) not in {"APPROVE", "DOWNGRADE"}:
            continue   # a VETOed setup never traded — no outcome to attach
        evt["_scored"] = True
        rec = {"ts": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "ticket": ticket,
               "side": side, "verdict": evt.get("decision"), "pnlUsd": round(_to_float(pnl), 2),
               "outcome": "WIN" if pnl > 0 else "LOSS" if pnl < 0 else "FLAT",
               "confidenceAdjust": evt.get("confidenceAdjust"), "reason": str(evt.get("reason") or "")[:160]}
        try:
            AUDIT_OUTCOMES_FILE.open("a", encoding="utf-8").write(json.dumps(rec, default=str) + "\n")
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_1603", _suppressed_exc)
        return


def _audit_scoreboard() -> dict[str, Any]:
    """Aggregate verdict-vs-outcome pairs into the number that matters: is the AI adding edge?"""
    _rotate_jsonl(AUDIT_OUTCOMES_FILE, keep_lines=2000)
    rows: list[dict[str, Any]] = []
    try:
        if AUDIT_OUTCOMES_FILE.exists():
            for ln in AUDIT_OUTCOMES_FILE.read_text(encoding="utf-8").splitlines()[-2000:]:
                if ln.strip():
                    rows.append(json.loads(ln))
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_1617", _suppressed_exc)
    def bucket(verdict: str) -> dict[str, Any]:
        sel = [r for r in rows if r.get("verdict") == verdict]
        wins = [r for r in sel if r.get("outcome") == "WIN"]
        net = round(sum(_to_float(r.get("pnlUsd")) for r in sel), 2)
        return {"trades": len(sel), "wins": len(wins),
                "winRate": round(len(wins) / max(1, len(sel)) * 100, 1), "netUsd": net}
    vetoes = sum(1 for e in DECISION_JOURNAL if isinstance(e, dict) and e.get("category") == "ai_audit" and e.get("decision") == "VETO")
    ap, dg = bucket("APPROVE"), bucket("DOWNGRADE")
    verdict_line = "Not enough scored trades yet — keep running."
    if ap["trades"] + dg["trades"] >= 15:
        if ap["winRate"] >= 55 and ap["netUsd"] > 0:
            verdict_line = f"AI-approved entries are winning {ap['winRate']}% (net {ap['netUsd']}). The audit layer is earning its keep."
        elif dg["trades"] >= 5 and dg["winRate"] < ap["winRate"] - 10:
            verdict_line = f"Downgraded entries win only {dg['winRate']}% vs {ap['winRate']}% for approved — the AI is correctly identifying second-rate setups. Consider letting DOWNGRADE become VETO."
        else:
            verdict_line = "AI verdicts are not separating winners from losers yet — keep it in downgrade-only mode."
    return {"ok": True, "scored": len(rows), "approve": ap, "downgrade": dg,
            "vetoCount": vetoes, "assessment": verdict_line, "recent": rows[-15:][::-1]}


@app.get("/api/ai/audit/scoreboard")
def ai_audit_scoreboard():
    """V12.70 — AI verdicts vs realised outcomes. The only honest measure of the audit layer."""
    return _audit_scoreboard()


def _register_close_outcome(ticket: Any, pnl: float, side: Any, price: Any, session: Any = None) -> None:
    """Drive the post-loss cooldown + loss-streak circuit breaker after every close.
    A loss starts a reanalysis cooldown; a run of losses pauses auto-entry entirely;
    a win resets the streak. Deduped per ticket so one trade counts once. This is what
    stops the bot revenge-stacking entries."""
    tk = str(ticket or "")
    if tk and tk in OUTCOME_REGISTERED:
        return
    if tk:
        OUTCOME_REGISTERED.add(tk)
    auto = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    now = time.time()
    pnl = _to_float(pnl)
    try:
        _journal_record("close", ticket=tk, side=str(side or "").upper(), pnlUsd=round(pnl, 2),
                        price=_to_float(price), session=session,
                        outcome="WIN" if pnl > 0 else "LOSS" if pnl < 0 else "FLAT")
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_1662", _suppressed_exc)
    # V12.70 AUDITOR OUTCOME SCORER: attach the realised result to the most recent matching
    # AI audit verdict (same side, within the last 6 hours, not yet scored). This is the
    # feedback loop that tells you whether the AI's approves/downgrades actually earn money —
    # served by /api/ai/audit/scoreboard and fed into the coach.
    try:
        _match_audit_outcome(str(side or "").upper(), pnl, tk)
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_1670", _suppressed_exc)
    # AI audit outcomes are scored above. Entry enforcement occurs only on the
    # pre-execution path; post-close processing must never be described as a veto.

    # V15.0.5 persistent calibration feedback.
    try:
        _ctx = trade_context.get(tk) if tk else None
        V15_ORCHESTRATOR.record_trade_outcome(
            pnl > 0,
            decision_id=(_ctx or {}).get("v15DecisionId"),
            probabilities=(_ctx or {}).get("v15Forecast") if isinstance((_ctx or {}).get("v15Forecast"), dict) else None,
        )
    except Exception as _suppressed_exc:
        _report_suppressed_exception("v15_probability_outcome", _suppressed_exc)
    # Daily realized P&L (drives the daily-loss circuit breaker), reset per UTC day.
    day = time.strftime("%Y-%m-%d", time.gmtime())
    if AUTO_TRADE_STATE.get("dayKey") != day:
        AUTO_TRADE_STATE["dayKey"] = day
        AUTO_TRADE_STATE["dailyRealizedPnl"] = 0.0
        AUTO_TRADE_STATE["dailyHaltAlerted"] = False
        AUTO_TRADE_STATE["previousPyramidAddFailed"] = False   # fresh day → clear the add lock
    AUTO_TRADE_STATE["dailyRealizedPnl"] = round(float(AUTO_TRADE_STATE.get("dailyRealizedPnl", 0.0)) + pnl, 2)
    if pnl < 0:
        streak = int(AUTO_TRADE_STATE.get("lossStreak", 0)) + 1
        AUTO_TRADE_STATE["lossStreak"] = streak
        AUTO_TRADE_STATE["postLossUntil"] = now + float(auto.get("postLossCooldownMinutes", 10)) * 60
        # V12.54: remember the failed thesis, not just that a loss happened.
        ctx = None
        try:
            ctx = trade_context.get(tk) if tk else None
        except Exception:
            ctx = None
        loss_rec = {
            "ticket": tk,
            "side": str(side or (ctx or {}).get("side") or "").upper(),
            "price": _to_float(price),
            "ts": now,
            "session": session,
            "strategy": (ctx or {}).get("strategy"),
            "confidence": _to_float((ctx or {}).get("confidence")),
            "entry": _to_float((ctx or {}).get("entry")),
            "sl": _to_float((ctx or {}).get("sl")),
            "reason": (ctx or {}).get("reason"),
            "pnl": round(pnl, 2),
        }
        AUTO_TRADE_STATE["lastLoser"] = loss_rec
        mem = list(AUTO_TRADE_STATE.get("lossMemory") or [])
        mem.insert(0, loss_rec)
        # Keep only recent losses so the governor stays lightweight and session-aware.
        cutoff = now - 24 * 3600
        AUTO_TRADE_STATE["lossMemory"] = [x for x in mem[:50] if float(x.get("ts", now)) >= cutoff]
        AUTO_TRADE_STATE["winStreak"] = 0
        limit = int(auto.get("lossStreakPause", 3))
        if limit and streak >= limit:
            pause_min = float(auto.get("lossStreakPauseMinutes", 60))
            AUTO_TRADE_STATE["pausedUntil"] = now + pause_min * 60
            _management_alert("Auto-entry paused", f"{streak} consecutive losses — auto-entry paused {pause_min:.0f} min for re-analysis. Manually review the market before resuming.", "danger")
    elif pnl > 0:
        AUTO_TRADE_STATE["lossStreak"] = 0
        AUTO_TRADE_STATE["winStreak"] = int(AUTO_TRADE_STATE.get("winStreak", 0)) + 1


def _tick_guard_base_dir() -> tuple[Path | None, str, str]:
    """Resolve the active MT5 MQL5/Files directory.

    The installer previously selected the first terminal profile under AppData. On
    machines with more than one broker terminal this often configured a different
    profile from the terminal connected through the MetaTrader5 Python bridge. The
    EA then wrote a heartbeat that the backend never looked at. A stale imported
    path can also still exist on disk, so existence alone is not proof that it is
    the active terminal. Prefer the directory containing the freshest heartbeat;
    otherwise prefer the connected terminal's data_path for new writes.
    """
    auto = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    raw_path = str(auto.get("mql5ControlFilePath") or "").strip()
    heartbeat_name = str(auto.get("tickGuardHeartbeatFileName") or "godmode_tickguard_heartbeat.csv")
    candidates: list[tuple[Path, str]] = []
    configured: Path | None = None
    if raw_path:
        candidate = Path(raw_path).expanduser()
        configured = candidate if candidate.is_dir() or not candidate.suffix else candidate.parent
        if configured.exists():
            candidates.append((configured, "configured"))
    active: Path | None = None
    try:
        terminal = mt5_bridge.status()
        data_path = str(terminal.get("terminalDataPath") or "").strip()
        if data_path:
            active = Path(data_path) / "MQL5" / "Files"
            active.mkdir(parents=True, exist_ok=True)
            if not any(path.resolve() == active.resolve() for path, _source in candidates):
                candidates.append((active, "active_mt5_terminal"))
    except Exception as exc:
        LOGGER.debug("Active MT5 data-path discovery failed: %s", exc)
    heartbeat_candidates: list[tuple[float, Path, str]] = []
    for candidate, source in candidates:
        heartbeat = candidate / heartbeat_name
        try:
            if heartbeat.is_file():
                heartbeat_candidates.append((heartbeat.stat().st_mtime, candidate, source))
        except OSError:
            continue
    if heartbeat_candidates:
        _mtime, chosen, source = max(heartbeat_candidates, key=lambda item: item[0])
        return chosen, source, raw_path
    if active is not None:
        return active, "active_mt5_terminal", raw_path
    if configured is not None:
        return configured, "configured_missing", raw_path
    return None, "unresolved", raw_path


_MQL5_CONTROL_LOCK = threading.RLock()

def _write_mql5_control(lines: list[str]) -> None:
    """Publish Tick Guard directives with Windows-safe retry and read-back verification.

    MT5, antivirus and indexers may briefly hold the destination file. A single atomic
    ``os.replace`` therefore caused WinError 5 and silently disabled manual/protection
    commands. Writes are now serialised, retried with a unique temp file, then fall back
    to an in-place truncate/write when Windows refuses replacement. Every successful
    publish is read back before health is marked OK.
    """
    base_dir, path_source, _configured_path = _tick_guard_base_dir()
    if base_dir is None:
        RUNTIME_HEALTH.fail("mql5_control_bridge", "No active MT5 MQL5/Files directory resolved")
        return
    payload = (("\n".join(lines) + "\n") if lines else "")
    p = base_dir / "godmode_control.csv"
    p.parent.mkdir(parents=True, exist_ok=True)
    last_exc: Exception | None = None
    with _MQL5_CONTROL_LOCK:
        for attempt in range(8):
            tmp = p.with_name(f"{p.name}.{os.getpid()}.{threading.get_ident()}.{attempt}.tmp")
            try:
                with open(tmp, "w", encoding="ascii", errors="strict", newline="") as fh:
                    fh.write(payload)
                    fh.flush()
                    os.fsync(fh.fileno())
                os.replace(tmp, p)
                if p.read_text(encoding="ascii", errors="strict") != payload:
                    raise OSError("control-file read-back mismatch")
                RUNTIME_HEALTH.beat("mql5_control_bridge", detail=f"published {len(lines)} directive(s) via {path_source}", path=str(p), attempts=attempt+1)
                return
            except PermissionError as exc:
                last_exc = exc
                try: tmp.unlink(missing_ok=True)
                except OSError as cleanup_exc:
                    LOGGER.debug("Control temp cleanup failed: %s", cleanup_exc)
                time.sleep(0.03 * (attempt + 1))
            except Exception as exc:
                last_exc = exc
                try: tmp.unlink(missing_ok=True)
                except OSError as cleanup_exc:
                    LOGGER.debug("Control temp cleanup failed: %s", cleanup_exc)
                break
        # Windows fallback: preserve the same pathname and rewrite it in place. The EA
        # opens with FILE_SHARE_READ|FILE_SHARE_WRITE and closes immediately, so this
        # succeeds when rename is blocked by a transient destination handle.
        try:
            with open(p, "w", encoding="ascii", errors="strict", newline="") as fh:
                fh.write(payload)
                fh.flush()
                os.fsync(fh.fileno())
            if p.read_text(encoding="ascii", errors="strict") != payload:
                raise OSError("control-file fallback read-back mismatch")
            RUNTIME_HEALTH.beat("mql5_control_bridge", detail=f"published {len(lines)} directive(s) via in-place Windows fallback", path=str(p), fallback=True)
            return
        except Exception as exc:
            last_exc = exc
    RUNTIME_HEALTH.fail("mql5_control_bridge", str(last_exc or "unknown control bridge error"))
    LOGGER.exception("Failed to publish MQL5 control directives", exc_info=last_exc)
    _push_notification("MT5 guard bridge error", f"Control directives were not published after retry/fallback: {last_exc}", "danger")


def _tick_guard_heartbeat_status() -> dict[str, Any]:
    """Verify that the matching Tick Guard EA is attached and writing fresh heartbeats."""
    auto = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    execution = SETTINGS_STATE.get("execution", {}) if isinstance(SETTINGS_STATE.get("execution"), dict) else {}
    bridge_live_enabled = bool(getattr(mt5_bridge, "live_enabled", False))
    resolver = globals().get("_tick_guard_base_dir")
    if callable(resolver):
        base_dir, path_source, raw_path = resolver()
    else:  # compatibility for isolated regression-test execution of this function
        raw_path = str(auto.get("mql5ControlFilePath") or "").strip()
        if raw_path:
            candidate = Path(raw_path)
            base_dir = candidate if candidate.is_dir() or not candidate.suffix else candidate.parent
            path_source = "configured"
        else:
            base_dir, path_source = None, "unresolved"
    certified_live_required = bool(
        execution.get("requireLiveCertification", True)
        and not execution.get("dryRun", not bridge_live_enabled)
        and bridge_live_enabled
    )
    # Unconfigured dry-run/operator sessions remain usable. Once real live execution
    # is enabled under the exact-build certification policy, the independent EA is
    # mandatory even if an imported configuration omitted its control path.
    required = (
        bool(auto.get("requireTickGuardForLive", False))
        or bool(raw_path)
        or base_dir is not None
        or certified_live_required
    )
    if base_dir is None:
        return {
            "ok": not required,
            "required": required,
            "configured": False,
            "pathSource": path_source,
            "message": ("Tick Guard files directory could not be resolved. Open the exact MT5 "
                        "terminal used by the bot, then reinstall/attach the EA or set automation."
                        "mql5ControlFilePath to that terminal's MQL5\\Files folder."),
        }
    heartbeat = base_dir / str(auto.get("tickGuardHeartbeatFileName") or "godmode_tickguard_heartbeat.csv")
    try:
        raw = heartbeat.read_text(encoding="ascii", errors="strict").strip()
        parts = raw.split(",")
        if len(parts) < 5:
            raise ValueError("heartbeat format is incomplete")
        created = float(parts[0])
        build = parts[1].strip()
        magic = int(float(parts[2]))
        prefix = parts[3].strip()
        symbol = parts[4].strip()
        now_epoch = time.time()
        timestamp_age = now_epoch - created
        file_age = now_epoch - heartbeat.stat().st_mtime
        # Fresh local mtime is accepted as a secondary clock because older EA
        # builds used broker-server TimeCurrent(), which can be hours ahead of UTC.
        # Tick Guard writes TimeGMT(); this tolerance gives a precise diagnosis
        # instead of falsely reporting a dead EA during the upgrade window.
        age = timestamp_age if -5 <= timestamp_age <= 30 else file_age
        expected_magic = int((SETTINGS_STATE.get("trading") or {}).get("magicNumber") or mt5_bridge.magic)
        expected_prefix = str((SETTINGS_STATE.get("trading") or {}).get("commentPrefix") or mt5_bridge.comment_prefix)
        expected_symbol = str((SETTINGS_STATE.get("trading") or {}).get("symbol") or mt5_bridge.symbol).upper()
        reasons = []
        if file_age < -5 or file_age > 30:
            reasons.append(f"heartbeat file age {file_age:.1f}s")
        if -5 <= timestamp_age <= 30:
            clock_note = ""
        elif abs(timestamp_age) >= 300 and file_age <= 30:
            # Do not fail solely for a broker clock offset when the exact-build EA
            # is demonstrably rewriting the local heartbeat file.
            clock_note = f"EA timestamp clock offset {timestamp_age:.1f}s; local file freshness used"
        else:
            reasons.append(f"heartbeat timestamp age {timestamp_age:.1f}s")
            clock_note = ""
        if build != BUILD_ID:
            reasons.append(f"build {build!r} does not match {BUILD_ID!r}")
        if magic != expected_magic:
            reasons.append(f"magic {magic} does not match {expected_magic}")
        if prefix != expected_prefix:
            reasons.append(f"comment prefix {prefix!r} does not match {expected_prefix!r}")
        if symbol.upper() != expected_symbol:
            reasons.append(f"symbol {symbol!r} does not match {expected_symbol!r}")
        ok = not reasons
        payload = {
            "ok": ok,
            "required": required,
            "configured": True,
            "pathSource": path_source,
            "configuredPath": raw_path or None,
            "resolvedFilesPath": str(base_dir),
            "heartbeatPath": str(heartbeat),
            "ageSeconds": round(age, 2),
            "timestampAgeSeconds": round(timestamp_age, 2),
            "fileAgeSeconds": round(file_age, 2),
            "buildId": build,
            "magicNumber": magic,
            "commentPrefix": prefix,
            "symbol": symbol,
            "message": (
                "Tick Guard heartbeat attested." + (f" {clock_note}" if clock_note else "")
                if ok
                else "Tick Guard heartbeat rejected: " + "; ".join(reasons)
            ),
        }
        if ok:
            RUNTIME_HEALTH.beat("tick_guard", detail=f"{symbol} age={age:.1f}s")
        else:
            RUNTIME_HEALTH.fail("tick_guard", payload["message"])
        return payload
    except Exception as exc:
        message = f"Tick Guard heartbeat unavailable: {exc}"
        RUNTIME_HEALTH.fail("tick_guard", message)
        return {
            "ok": False,
            "required": required,
            "configured": True,
            "pathSource": path_source,
            "configuredPath": raw_path or None,
            "resolvedFilesPath": str(base_dir),
            "heartbeatPath": str(heartbeat),
            "message": message,
        }


def _local_runtime_certification_status() -> dict[str, Any]:
    """Attest the live runtime used by a local desktop installation.

    The previous default required a release-officer HMAC package containing nine
    external evidence files. That enterprise process is still available through
    ``liveCertificationMode=enterprise_evidence``, but it is not an install-time
    certificate and could never approve an ordinary local deployment. Local mode
    now certifies the facts that can be verified continuously on the running PC.
    """
    mt5_status = mt5_bridge.status()
    connected = bool(mt5_status.get("connected"))
    trade_allowed = bool(mt5_status.get("tradeAllowed"))
    tick_guard = _tick_guard_heartbeat_status()
    health = RUNTIME_HEALTH.snapshot(
        {"trade_protection": 20, "event_loop": 5, "reconciliation": 60}
    )
    unresolved = EXECUTION_LEDGER.unresolved()
    gates = {
        "exactBuildTickGuard": bool(tick_guard.get("ok") and tick_guard.get("buildId") == BUILD_ID),
        "mt5Connected": connected,
        "mt5TradeAllowed": trade_allowed,
        "tickGuardFresh": bool(tick_guard.get("ok")),
        "eventLoopHealthy": bool(health.get("event_loop", {}).get("ok") and not health.get("event_loop", {}).get("stale")),
        "protectionLoopHealthy": bool(health.get("trade_protection", {}).get("ok") and not health.get("trade_protection", {}).get("stale")),
        "reconciliationHealthy": bool(health.get("reconciliation", {}).get("ok") and not health.get("reconciliation", {}).get("stale")),
        "noUnresolvedBrokerCommands": not bool(unresolved),
        "persistenceWritable": bool(DATA_DIR.exists() and os.access(DATA_DIR, os.W_OK)),
    }
    failures = [name for name, passed in gates.items() if not passed]
    approved = not failures
    return {
        "approved": approved,
        "grade": "LOCAL_RUNTIME_ATTESTED" if approved else "NOT_ATTESTED",
        "certificationType": "local_runtime",
        "buildId": BUILD_ID,
        "certifiedBuildId": tick_guard.get("buildId"),
        "gates": {name: {"passed": passed} for name, passed in gates.items()},
        "missingGates": failures,
        "failures": failures,
        "tickGuard": tick_guard,
        "message": (
            "Local live runtime is freshly attested for this exact build."
            if approved
            else "Local live runtime is waiting for: " + ", ".join(failures)
        ),
    }


def _telegram_creds() -> tuple[str, str]:
    tg = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
    return (str(tg.get("botToken") or os.getenv("TELEGRAM_BOT_TOKEN", "")).strip(),
            str(tg.get("chatId") or os.getenv("TELEGRAM_CHAT_ID", "")).strip())



TELEGRAM_SEND_STATE: dict[str, float] = {}


def _telegram_minimal_category(text: str, buttons: list[list[dict[str, str]]] | None = None) -> str:
    """Classify Telegram messages so Quiet Mode can keep only useful messages.

    This intentionally uses text heuristics so old call-sites do not need a new
    parameter. The aim is: alerts that require action or report a real broker
    event are kept; watchlist noise, repeated controls, BE/trailing chatter and
    market-open heartbeats are suppressed by default.
    """
    t = str(text or "")
    tl = t.lower()
    # Keep auto-generated quick controls quiet unless enabled, but never suppress
    # an approval button row or a user-command button row just because the label
    # says "Choose action". This fixes the case where a chart/photo alert sent,
    # but the TAKE / SCOUT / SKIP buttons were hidden by minimal mode.
    if "quick controls" in tl:
        return "auto_controls"
    callback_values: list[str] = []
    try:
        for row in buttons or []:
            for btn in row or []:
                callback_values.append(str(btn.get("callback_data") or ""))
    except Exception:
        callback_values = []
    if any(cb.startswith(("gm_trade_take:", "gm_trade_scout:", "gm_trade_skip:")) for cb in callback_values):
        return "entry"
    if any(cb in {"gm_burst_on", "gm_burst_off", "gm_burst_allow_once", "gm_burst_now"} for cb in callback_values):
        return "burst"
    if any(cb == "gm_positions" or cb.startswith("gm_pos_") or cb in {"gm_kill", "gm_mode_auto", "gm_mode_semi"} for cb in callback_values):
        return "user_command"
    if t.strip().lower() == "choose action:":
        return "auto_controls"
    if "telegram test" in tl or "alerts are connected" in tl:
        return "test"
    if "daily recap" in tl or "weekly recap" in tl or "godmode recap" in tl:
        return "recap"
    if "market open" in tl or "market closed" in tl:
        return "market_transition"
    if "watchlist" in tl or "no order" in tl or "forecast" in tl or "retest armed" in tl or "momentum spike" in tl or "fast sniper" in tl:
        # Executable approval is useful; generic watch/no-chase alerts are noise in minimal mode.
        if "approval required" in tl or "executable setup" in tl or "take" in tl:
            return "entry"
        return "watchlist"
    if "executable setup" in tl or "approval required" in tl or "trade fired" in tl or "trade sent" in tl or "scout sent" in tl or "order not sent" in tl:
        return "entry"
    if "trade closed" in tl or tl.startswith("✅ closed") or tl.startswith("❌ close failed"):
        return "exit"
    if "protected burst batch sent" in tl or "protected burst ready" in tl or "burst on" in tl or "burst off" in tl or "one protected burst batch approved" in tl:
        return "burst"
    if "daily loss" in tl or "equity stop" in tl or "kill" in tl or "emergency stop" in tl or "auto-entry paused" in tl or "risk" in tl:
        return "risk"
    if "ai optimisation" in tl or "better strategy" in tl or "auto-scan" in tl or "strategy installed" in tl or "strategy uninstalled" in tl:
        return "ai"
    if "godmode modes" in tl or "auto mode enabled" in tl or "semi-auto mode enabled" in tl or "pyramiding on" in tl or "pyramiding off" in tl:
        return "mode"
    if "open position" in tl or "godmode positions" in tl or "position #" in tl or "be requested" in tl:
        return "user_command"
    if "ai dynamic sl" in tl or "tp" in tl or "recovery" in tl or "pyramid add opened" in tl or "entry blocked after loss" in tl:
        return "management"
    return "other"


def _telegram_allowed_by_minimal_mode(text: str, buttons: list[list[dict[str, str]]] | None = None) -> tuple[bool, str]:
    tg = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
    cat = _telegram_minimal_category(text, buttons)
    if not bool(tg.get("minimalMode", True)):
        return True, cat

    # V12.90 FIX: real execution truth must NEVER be suppressed by Quiet Mode. Trade fired,
    # order blocked/not-sent, and the chart that accompanies an entry are execution events, not
    # noise. Previously "Trade fired" passed but its chart caption ("Chart context…") classified
    # as 'other' and was dropped, and the V12.84 "BLOCKED, NOT SENT" loud-block classified as
    # 'watchlist' and was dropped — so the user correctly saw silence on the exact messages that
    # matter most. These now always pass regardless of minimal mode.
    tl = str(text or "").lower()
    always_pass = ("trade fired" in tl or "order sent" in tl or "not sent" in tl or "blocked" in tl
                   or "chart context" in tl or "trade closed" in tl or "close failed" in tl
                   or "🛡️" in str(text or ""))  # burst campaign closed
    if always_pass:
        return True, (cat if cat not in {"other", "watchlist"} else "entry")

    if cat == "auto_controls":
        return bool(tg.get("sendControlButtonsAutomatically", False)), cat
    if cat == "watchlist":
        return bool(tg.get("sendWatchlistAlerts", False)), cat
    if cat == "market_transition":
        return bool(tg.get("sendMarketOpenClose", False)), cat
    if cat == "management":
        # BE/trailing/TP-push/recovery messages can become very noisy. They are
        # visible in the dashboard/journal; Telegram should stay clean by default.
        return bool(tg.get("sendManagementMilestones", False)), cat
    if cat in {"entry", "exit"}:
        return bool(tg.get("sendEntryExitAlerts", True)), cat
    if cat == "burst":
        return bool(tg.get("sendBurstAlerts", True)), cat
    if cat == "risk":
        return bool(tg.get("sendRiskAlerts", True)), cat
    if cat == "ai":
        return bool(tg.get("sendAiCoachAlerts", True)), cat
    if cat == "mode":
        return bool(tg.get("sendModeConfirmations", True)), cat
    if cat in {"test", "recap"}:
        return True, cat
    # User-command replies remain allowed so buttons/commands still feel responsive.
    if cat == "user_command":
        return True, cat
    return False, cat


def _telegram_dedupe_key(text: str, category: str) -> str:
    # Normalize the first line and remove volatile ticket/price fragments enough
    # to stop repeated identical alerts while still allowing new broker events.
    first = str(text or "").strip().splitlines()[0:2]
    raw = " | ".join(first).lower()
    return category + ":" + raw[:160]


def _telegram_should_dedupe(text: str, category: str) -> bool:
    """Only dedupe noisy bot chatter, never broker events or action-required buttons."""
    tl = str(text or "").lower()
    if category in {"user_command", "mode"}:
        return False
    # Broker/order events must always reach the phone. The old 90s dedupe key used
    # only the first lines (e.g. "Trade fired | BUY XAUUSD 0.01"), so a second real
    # fill or close in the same direction could be silently suppressed.
    if category in {"entry", "exit"} and any(x in tl for x in (
        "trade fired", "trade sent", "scout sent", "order not sent",
        "trade closed", "closed #", "close failed"
    )):
        return False
    return True


TELEGRAM_SEND_LOG: list[dict[str, Any]] = []

def _telegram_log(text: str, category: str, outcome: str, detail: str = "") -> None:
    """V12.90: rolling in-memory log of every Telegram send attempt so silence is diagnosable.
    outcome ∈ sent | api_error | send_failed | skipped_minimal | skipped_dedupe | disabled | no_creds."""
    try:
        TELEGRAM_SEND_LOG.insert(0, {
            "ts": time.time(), "tsIso": time.strftime("%H:%M:%S", time.gmtime()),
            "category": category, "outcome": outcome,
            "preview": str(text or "").strip().splitlines()[0][:60] if str(text or "").strip() else "",
            "detail": str(detail)[:160],
        })
        del TELEGRAM_SEND_LOG[80:]
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_1967", _suppressed_exc)


def _telegram_api_result(raw: bytes | str, *, action: str) -> dict[str, Any]:
    """Parse Telegram's JSON envelope; HTTP 200 does not mean the Bot API accepted it."""
    text = raw.decode("utf-8", "ignore") if isinstance(raw, (bytes, bytearray)) else str(raw or "")
    try:
        payload = json.loads(text) if text else {}
    except Exception:
        return {"ok": False, "message": f"Telegram {action} returned invalid JSON.", "telegramResponse": text[:500]}
    if payload.get("ok") is True:
        return {"ok": True, "message": f"Telegram {action} succeeded.", "telegramResponse": text[:500], "telegram": payload}
    description = str(payload.get("description") or payload.get("error") or "Telegram rejected the request.")
    error_code = payload.get("error_code")
    suffix = f" (error {error_code})" if error_code not in (None, "") else ""
    return {"ok": False, "message": f"Telegram {action} failed{suffix}: {description}", "telegramResponse": text[:500], "telegram": payload}


def _telegram_send_text(text: str, buttons: list[list[dict[str, str]]] | None = None) -> dict[str, Any]:
    tg = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
    enabled = bool(tg.get("enabled") or os.getenv("TELEGRAM_ENABLED", "").lower() in {"1", "true", "yes"})
    token, chat_id = _telegram_creds()
    if not enabled:
        _telegram_log(text, "?", "disabled", "telegram.enabled is False")
        return {"ok": False, "skipped": True, "message": "Telegram is disabled in Settings."}
    if not token or not chat_id:
        _telegram_log(text, "?", "no_creds", f"token={'set' if token else 'MISSING'} chatId={'set' if chat_id else 'MISSING'}")
        return {"ok": False, "message": "Telegram Bot Token and Chat ID are required."}

    allowed, category = _telegram_allowed_by_minimal_mode(text, buttons)
    dedupe_key: str | None = None
    if not allowed:
        _telegram_log(text, category, "skipped_minimal", f"minimal mode suppressed {category}")
        return {"ok": False, "skipped": True, "message": f"Telegram minimal mode suppressed {category} alert.", "category": category}
    # Dedupe only bot-generated chatter. User commands, approval buttons and REAL
    # broker/order events must remain immediate and must never be suppressed.
    if _telegram_should_dedupe(text, category):
        try:
            dedupe_s = max(0.0, float(tg.get("dedupeSeconds", 90.0) or 90.0))
            dedupe_key = _telegram_dedupe_key(text, category)
            now = time.time()
            last = float(TELEGRAM_SEND_STATE.get(dedupe_key, 0.0) or 0.0)
            if dedupe_s > 0 and now - last < dedupe_s:
                return {"ok": False, "skipped": True, "message": "Duplicate Telegram alert suppressed.", "category": category}
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_1997", _suppressed_exc)
    try:
        payload = {"chat_id": chat_id, "text": text, "parse_mode": "Markdown"}
        if buttons:   # inline keyboard: [[{"text":..,"callback_data":..}], ...]
            payload["reply_markup"] = json.dumps({"inline_keyboard": buttons})
        data = urllib.parse.urlencode(payload).encode("utf-8")
        req = urllib.request.Request(f"https://api.telegram.org/bot{token}/sendMessage", data=data, method="POST")
        raw = read_public_https(req, timeout=8)
        parsed = _telegram_api_result(raw, action="message send")
        # Markdown entity errors are common with broker/strategy text. Retry once as
        # plain text rather than silently losing an otherwise valid alert.
        if not parsed.get("ok") and "parse entities" in str(parsed.get("message", "")).lower():
            retry_payload = {"chat_id": chat_id, "text": text}
            if buttons:
                retry_payload["reply_markup"] = json.dumps({"inline_keyboard": buttons})
            retry_req = urllib.request.Request(
                f"https://api.telegram.org/bot{token}/sendMessage",
                data=urllib.parse.urlencode(retry_payload).encode("utf-8"),
                method="POST",
            )
            parsed = _telegram_api_result(read_public_https(retry_req, timeout=8), action="plain-text message send")
            parsed["markdownFallback"] = True
        parsed["category"] = category
        if parsed.get("ok") and dedupe_key:
            TELEGRAM_SEND_STATE[dedupe_key] = time.time()
        _telegram_log(text, category, "sent" if parsed.get("ok") else "api_error", str(parsed.get("telegramResponse", ""))[:200])
        return parsed
    except Exception as exc:
        _telegram_log(text, category, "send_failed", str(exc)[:200])
        return {"ok": False, "message": f"Telegram send failed: {exc}", "category": category}


def _telegram_send_photo(image: bytes | None, caption: str = "") -> dict[str, Any]:
    """Send a PNG chart to Telegram (multipart/form-data, stdlib only)."""
    tg = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
    if not bool(tg.get("enabled")) or not tg.get("sendCharts", True) or not image:
        return {"ok": False, "skipped": True}
    allowed, category = _telegram_allowed_by_minimal_mode(caption, None)
    if not allowed:
        return {"ok": False, "skipped": True, "message": f"Telegram minimal mode suppressed {category} chart.", "category": category}
    token = str(tg.get("botToken") or os.getenv("TELEGRAM_BOT_TOKEN", "")).strip()
    chat_id = str(tg.get("chatId") or os.getenv("TELEGRAM_CHAT_ID", "")).strip()
    if not token or not chat_id:
        return {"ok": False, "message": "Telegram credentials required."}
    try:
        boundary = "----GodMode" + str(int(time.time() * 1000))
        def field(name: str, value: str) -> bytes:
            return (f'--{boundary}\r\nContent-Disposition: form-data; name="{name}"\r\n\r\n{value}\r\n').encode()
        body = field("chat_id", chat_id) + field("caption", caption[:1024]) + field("parse_mode", "Markdown")
        body += (f'--{boundary}\r\nContent-Disposition: form-data; name="photo"; filename="chart.png"\r\nContent-Type: image/png\r\n\r\n').encode()
        body += image + b"\r\n" + (f"--{boundary}--\r\n").encode()
        req = urllib.request.Request(f"https://api.telegram.org/bot{token}/sendPhoto", data=body, method="POST")
        req.add_header("Content-Type", f"multipart/form-data; boundary={boundary}")
        parsed = _telegram_api_result(read_public_https(req, timeout=15), action="photo send")
        parsed["category"] = category
        return parsed
    except Exception as exc:
        return {"ok": False, "message": f"Telegram photo failed: {exc}"}


def _trade_chart_image(side: str, entry: Any, sl: Any, tps: list[Any], subtitle: str = "") -> bytes | None:
    """Render the current XAUUSD chart with entry/SL/TP annotated for an alert."""
    if not chart_render.available():
        return None
    try:
        trading = SETTINGS_STATE.get("trading", {}) if isinstance(SETTINGS_STATE.get("trading"), dict) else {}
        symbol = str(trading.get("symbol", mt5_bridge.symbol))
        tf = str(trading.get("timeframe", "M15"))
        # Use the RAW MT5 snapshot — never the demo/synthetic fallback. A live alert must show
        # the user's REAL broker candles or no chart at all; a synthetic chart is exactly what
        # "the candles don't match" was. If MT5 isn't connected we skip the image (text still sends).
        snap = mt5_bridge.market_snapshot(symbol, tf)
        candles = snap.get("candles") or []
        if not snap.get("connected") or not candles:
            return None
        clean_tps = [float(t) for t in (tps or []) if t]
        last = candles[-1]
        try:
            ohlc = f"O{float(last['open']):.2f} H{float(last['high']):.2f} L{float(last['low']):.2f} C{float(last['close']):.2f}"
        except Exception:
            ohlc = ""
        sub = ((subtitle + " · ") if subtitle else "") + f"{tf} • {ohlc} • {last.get('timeLabel','')} server time"
        return chart_render.render_trade_chart(
            candles, side=str(side), entry=float(entry) if entry else None,
            sl=float(sl) if sl else None, tps=clean_tps,
            title=str(snap.get("symbol", symbol)), subtitle=sub, timeframe=tf, live=True,
        )
    except Exception:
        return None


def _telegram_rich_trade_alert(headline: str, side: str, symbol: str, volume: Any,
                               entry: Any, sl: Any, tps: list[Any], confidence: Any,
                               strategy: str, reason: str, kind: str = "info",
                               confidence_label: str = "Confidence",
                               buttons: list[list[dict[str, str]]] | None = None) -> dict[str, Any]:
    """Send a full Telegram alert: side/entry/SL/TP/confidence/strategy/reason + chart."""
    tg = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
    if not tg.get("enabled"):
        return {"ok": False, "skipped": True, "message": "Telegram is disabled."}
    emoji = {"success": "🟢", "warning": "🟡", "danger": "🔴", "info": "🔵"}.get(kind, "🔵")
    tp_line = ""
    clean_tps = [t for t in (tps or []) if t]
    if clean_tps:
        tp_line = "\n".join(f"  TP{i+1}: `{float(t):.2f}`" for i, t in enumerate(clean_tps[:4]))
    lines = [f"{emoji} *GodMode — {headline}*", f"*{side} {symbol}*  ·  {volume} lots"]
    if entry:
        lines.append(f"Entry: `{float(entry):.2f}`")
    if sl:
        lines.append(f"SL: `{float(sl):.2f}`")
    if tp_line:
        lines.append(tp_line)
    if confidence:
        lines.append(f"{confidence_label}: *{int(float(confidence))}%*")
    if strategy:
        lines.append(f"Strategy: _{strategy}_")
    if reason:
        lines.append(f"\n📋 {str(reason)[:900]}")
    _ctf = str((SETTINGS_STATE.get("trading", {}) or {}).get("timeframe", "M15"))
    lines.append(f"\n📊 _Chart = real MT5 {_ctf} candles, server-time axis (matches your platform). Set your chart to {_ctf}; the O/H/L/C printed on it should equal your last {_ctf} candle. No chart = MT5 not connected._")
    lines.append(f"`Build: {BUILD_ID}`")
    text = "\n".join(lines)
    # V12.45 low-latency semi-auto: when TAKE/SCOUT buttons exist, send the executable
    # approval text/buttons FIRST, then send the chart as context. Previously the chart upload
    # blocked the buttons and could cost several seconds on a fast XAUUSD move.
    if buttons and tg.get("approvalButtonsFirst", True):
        primary = _telegram_send_text(text, buttons=buttons)
        if not primary.get("ok"):
            return primary
        if tg.get("sendCharts", True):
            img = _trade_chart_image(side, entry, sl, clean_tps, subtitle=f"{strategy} · conf {int(float(confidence or 0))}%")
            if img:
                _telegram_send_photo(img, "📊 Chart context — buttons were sent first for speed.")
        return primary
    img = _trade_chart_image(side, entry, sl, clean_tps, subtitle=f"{strategy} · conf {int(float(confidence or 0))}%")
    if img:
        photo = _telegram_send_photo(img, text)
        if photo.get("ok"):
            if buttons:
                return _telegram_send_text("Choose action:", buttons=buttons)
            return photo
    return _telegram_send_text(text, buttons=buttons)  # fallback to text if no chart / send failed


def _telegram_rich_close_alert(direction: str, symbol: str, ticket: Any, exit_price: Any,
                               pnl: float, r_mult: Any, reason: str, kind: str = "success") -> None:
    """Send a full Telegram close alert: PnL, R, reason + a chart of the exit."""
    tg = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
    if not tg.get("enabled"):
        return
    emoji = "🟢" if pnl >= 0 else "🔴"
    lines = [f"{emoji} *GodMode — Trade closed*", f"*{direction} {symbol}*  #{ticket}"]
    if exit_price:
        lines.append(f"Exit: `{float(exit_price):.2f}`")
    lines.append(f"PnL: *{pnl:+.2f} USD*" + (f"  ({float(r_mult):+.2f}R)" if r_mult not in (None, "") else ""))
    if reason:
        lines.append(f"\n📋 {str(reason)[:300]}")
    text = "\n".join(lines)
    img = _trade_chart_image(direction, exit_price, None, [], subtitle=f"Closed {pnl:+.2f} USD")
    if img and _telegram_send_photo(img, text).get("ok"):
        return
    _telegram_send_text(text)



def _telegram_position_buttons() -> list[list[dict[str, str]]]:
    burst_on = _protected_burst_enabled()
    pyr_on = bool((SETTINGS_STATE.get("pyramiding") or {}).get("enabled", False))
    rows: list[list[dict[str, str]]] = [
        [{"text": "📊 Positions", "callback_data": "gm_positions"}, {"text": "🛑 Kill Auto", "callback_data": "gm_kill"}],
        [{"text": "⚡ Auto Mode", "callback_data": "gm_mode_auto"}, {"text": "✅ Semi-Auto", "callback_data": "gm_mode_semi"}],
        [{"text": ("🟢 Burst ON" if burst_on else "⚡ Burst OFF"), "callback_data": ("gm_burst_off" if burst_on else "gm_burst_on")},
         {"text": "⚡ Evaluate Burst Now", "callback_data": "gm_burst_now"}],
        [{"text": ("🟢 Pyramid ON" if pyr_on else "🔺 Pyramid OFF"), "callback_data": ("gm_pyramid_off" if pyr_on else "gm_pyramid_on")},
         {"text": "✅ Allow One Burst", "callback_data": "gm_burst_allow_once"}],
    ]
    return rows

