def _save_risk() -> None:
    RISK_FILE.parent.mkdir(parents=True, exist_ok=True)
    tmp = RISK_FILE.with_suffix(".json.tmp")
    payload = json.dumps(RISK_STATE, indent=2, default=str)
    with tmp.open("w", encoding="utf-8") as fh:
        fh.write(payload)
        fh.flush()
        os.fsync(fh.fileno())
    os.replace(tmp, RISK_FILE)
    _restrict_private_path(RISK_FILE)
    if json.loads(RISK_FILE.read_text(encoding="utf-8")) != RISK_STATE:
        raise RuntimeError("risk settings read-back verification mismatch")


def _demo_enabled() -> bool:
    """Demo data fills the UI whenever MT5 is not actually connected.

    Controlled by GODMODE_DEMO_DATA (default 'auto'): 'auto' = use demo only when
    MT5 is offline; 'off' = never; 'on' = always.
    """
    mode = os.getenv("GODMODE_DEMO_DATA", "auto").strip().lower()
    if mode == "off":
        return False
    if mode == "on":
        return True
    return not bool(mt5_bridge.status().get("connected"))


def _safe_public_settings(settings: dict[str, Any]) -> dict[str, Any]:
    """Return settings without exposing secrets, plus explicit configured flags."""
    out = deepcopy(settings)
    configured: dict[str, bool] = {}
    for dotted in SETTINGS_SECRET_PATHS:
        parts = dotted.split(".")
        source: Any = settings
        target: Any = out
        for key in parts[:-1]:
            source = source.get(key) if isinstance(source, dict) else None
            target = target.get(key) if isinstance(target, dict) else None
            if source is None or target is None:
                break
        if isinstance(target, dict) and parts[-1] in target:
            exists = bool(str(source.get(parts[-1]) or "").strip()) if isinstance(source, dict) else False
            target[parts[-1]] = ""
            configured[dotted] = exists
    out["secretConfigured"] = configured
    if isinstance(out.get("telegram"), dict):
        out["telegram"]["botTokenConfigured"] = bool(configured.get("telegram.botToken"))
    if isinstance(out.get("aiProvider"), dict):
        out["aiProvider"]["apiKeyConfigured"] = bool(configured.get("aiProvider.apiKey"))
    if isinstance(out.get("strategyLab"), dict):
        out["strategyLab"]["feedKeyConfigured"] = bool(configured.get("strategyLab.feedKey"))
    return out


_SPREAD_HISTORY: deque = deque(maxlen=240)   # (ts, spread) — ~20 min at 5s polling

def _note_spread(spread: Any) -> None:
    if spread in (None, ""):
        return
    try:
        s = float(spread)
        if s > 0:
            _SPREAD_HISTORY.append((time.time(), s))
    except (TypeError, ValueError):
        return

def _spread_spike_gate(current_spread: Any) -> dict[str, Any]:
    """V12.70 EDGE: block entries fired into a transient spread SPIKE (news, rollover,
    liquidity gap). A static maxSpread can pass 0.38 while the rolling normal is 0.18 —
    that 2x cost hits the scalp's expectancy exactly at the entry tick. Blocks when the
    live spread exceeds 2.2x the rolling median AND is above an absolute floor."""
    try:
        cur = float(current_spread or 0)
    except Exception:
        return {"ok": True}
    if cur <= 0 or len(_SPREAD_HISTORY) < 24:
        return {"ok": True, "reason": "insufficient spread history — static maxSpread gate still applies"}
    vals = sorted(s for _, s in _SPREAD_HISTORY)
    median = vals[len(vals) // 2]
    if median > 0 and cur > max(0.12, median * 2.2):
        return {"ok": False, "current": round(cur, 3), "median": round(median, 3),
                "message": f"Spread spike: {cur:.2f} vs rolling median {median:.2f} (>{2.2:.1f}x). Entry delayed until spread normalises."}
    return {"ok": True, "current": round(cur, 3), "median": round(median, 3)}


