def _trades_kpis(history: list[dict[str, Any]]) -> dict[str, Any]:
    """Compute win rate, profit factor, expectancy from a trade history list."""
    total = len(history)
    if total == 0:
        return {"winRate": 0.0, "profitFactor": 0.0, "expectancy": 0.0, "totalClosed": 0}
    wins   = [t for t in history if float(t.get("pnlUsd", 0) or 0) > 0]
    losses = [t for t in history if float(t.get("pnlUsd", 0) or 0) < 0]
    gross_profit = sum(float(t.get("pnlUsd", 0) or 0) for t in wins)
    gross_loss   = abs(sum(float(t.get("pnlUsd", 0) or 0) for t in losses))
    net = gross_profit - gross_loss
    return {
        "winRate": round((len(wins) / total) * 100, 1),
        "profitFactor": round(gross_profit / gross_loss, 2) if gross_loss else 0.0,
        "expectancy": round(net / total, 2),
        "netPnlToday": 0.0,
        "totalClosed": total,
    }


def _decorate_trade_protection(
    position: dict[str, Any],
    state: dict[str, Any] | None = None,
) -> dict[str, Any]:
    row = dict(position)
    ticket = str(row.get("ticket") or row.get("positionId") or "")
    protection = (
        state
        if isinstance(state, dict)
        else POSITION_PROTECTION_STATE.get(ticket, {})
    )
    protection = protection if isinstance(protection, dict) else {}
    direction = str(row.get("direction") or row.get("side") or "").upper()
    entry = _to_float(row.get("entryPrice") or row.get("entry"))
    current = _to_float(row.get("currentPrice") or row.get("price"))
    stop = _to_float(row.get("sl"))
    risk_basis = _to_float(protection.get("riskBasis"))
    calculated_current_r = None
    calculated_locked_r = None
    if risk_basis > 0 and direction in {"BUY", "SELL"}:
        if current > 0 and entry > 0:
            calculated_current_r = (
                (current - entry) / risk_basis
                if direction == "BUY"
                else (entry - current) / risk_basis
            )
        if stop > 0 and entry > 0:
            calculated_locked_r = (
                (stop - entry) / risk_basis
                if direction == "BUY"
                else (entry - stop) / risk_basis
            )
    current_r = (
        _to_float(protection.get("currentR"))
        if protection.get("currentR") is not None
        else calculated_current_r
    )
    peak_r = (
        _to_float(protection.get("peakR"))
        if protection.get("peakR") is not None
        else None
    )
    decision = (
        protection.get("dynamicSlDecision")
        if isinstance(protection.get("dynamicSlDecision"), dict)
        else {}
    )
    exit_intelligence = (
        protection.get("exitIntelligence")
        if isinstance(protection.get("exitIntelligence"), dict)
        else {}
    )
    created_at = _to_float(decision.get("created_at"))
    row.update(
        {
            "dynamicSlState": decision.get("state_after") or (
                "PROFIT_LOCK"
                if calculated_locked_r is not None and calculated_locked_r > 0
                else "INITIAL_PROTECTION"
            ),
            "dynamicSlDecisionSource": (
                "deterministic_v14" if decision else "awaiting_first_decision"
            ),
            "dynamicSlReasonCodes": list(decision.get("reason_codes") or []),
            "dynamicSlDecisionBlocked": bool(decision.get("blocked", False)),
            "dynamicSlDecisionAgeSeconds": (
                round(max(0.0, time.time() - created_at), 2)
                if created_at
                else None
            ),
            "exitPhase": str(exit_intelligence.get("phase") or "SAFE_HOLD"),
            "exitAction": str(exit_intelligence.get("action") or "HOLD"),
            "exitContinuationScore": (
                round(_to_float(exit_intelligence.get("continuation_score") or exit_intelligence.get("continuationScore")), 1)
                if exit_intelligence
                else None
            ),
            "adaptiveGiveback": (
                round(_to_float(protection.get("adaptiveGiveback")), 3)
                if protection.get("adaptiveGiveback") is not None
                else None
            ),
            "adaptiveTrailAtr": (
                round(_to_float(protection.get("adaptiveTrailAtr")), 3)
                if protection.get("adaptiveTrailAtr") is not None
                else None
            ),
            "rawPeakR": (
                round(_to_float(protection.get("rawPeakR") or protection.get("peakR")), 3)
                if protection.get("rawPeakR") is not None or protection.get("peakR") is not None
                else None
            ),
            "qualifiedPeakR": (
                round(_to_float(protection.get("qualifiedPeakR")), 3)
                if protection.get("qualifiedPeakR") is not None
                else None
            ),
            "singlePositionTpPolicy": dict(protection.get("singlePositionTpPolicy") or {}),
            "exitRecommendedSl": (
                round(_to_float(exit_intelligence.get("recommended_sl") or exit_intelligence.get("recommendedSl")), 3)
                if exit_intelligence.get("recommended_sl") is not None or exit_intelligence.get("recommendedSl") is not None
                else None
            ),
            "exitReasonCodes": list(exit_intelligence.get("reason_codes") or exit_intelligence.get("reasonCodes") or []),
            "riskBasis": risk_basis or None,
            "currentR": round(float(current_r), 3) if current_r is not None else None,
            "peakR": round(float(peak_r), 3) if peak_r is not None else None,
            "lockedR": (
                round(float(calculated_locked_r), 3)
                if calculated_locked_r is not None
                else None
            ),
            "givebackR": (
                round(max(0.0, float(peak_r) - float(current_r)), 3)
                if peak_r is not None and current_r is not None
                else None
            ),
            "recoveryScore": (
                round(_to_float(protection.get("recoveryScore")), 1)
                if protection.get("recoveryScore") is not None
                else None
            ),
            "breathCount": int(protection.get("breathCount", 0) or 0),
            "beMoved": bool(protection.get("beMoved", row.get("beMoved", False))),
            "trailingStop": bool(
                protection.get("trailLevel")
                or protection.get("aiDynamicStopLocked")
            ),
            "brokerProtected": bool(stop > 0),
            "profitProtected": bool(
                calculated_locked_r is not None and calculated_locked_r >= 0
            ),
        }
    )
    return row


def _build_trades_snapshot() -> dict[str, Any]:
    """Build the full trade snapshot. Expensive; call from cache/worker paths only."""
    if not mt5_bridge.status().get("connected") and _demo_enabled():
        return demo_data.trades()
    # V12.61: 30 days is enough for live UI. Deep analytics still reads longer history.
    history = _merge_recent_closed(mt5_bridge.closed_bot_trades(days=30))
    history = _enrich_history(history, learn=True)
    kpis = _trades_kpis(history)
    return {
        "active": [
            _decorate_trade_protection(position)
            for position in mt5_bridge.open_positions(bot_only=True)
        ],
        "pending": mt5_bridge.pending_orders(bot_only=True),
        "history": history,
        "memoryScope": "bot_only",
        "source": "mt5" if mt5_bridge.status().get("connected") else "not_connected",
        "message": "Only positions/deals stamped with the GodMode magic number or comment prefix are shown.",
        **kpis,
    }


def _refresh_trades_cache_sync() -> None:
    global _TRADES_CACHE, _TRADES_CACHE_TS
    if not _TRADES_REFRESH_LOCK.acquire(blocking=False):
        return
    try:
        _TRADES_CACHE = deepcopy(_build_trades_snapshot())
        _TRADES_CACHE_TS = time.time()
    except Exception as exc:
        if not _TRADES_CACHE:
            _TRADES_CACHE = {"active": [], "pending": [], "history": [], "memoryScope": "bot_only", "source": "error", "message": f"Trade refresh failed: {exc}"}
            _TRADES_CACHE_TS = time.time()
    finally:
        try:
            _TRADES_REFRESH_LOCK.release()
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_5131", _suppressed_exc)


def _live_trades() -> dict[str, Any]:
    global _TRADES_CACHE, _TRADES_CACHE_TS
    now = time.time()
    if not _TRADES_CACHE:
        # First paint must be instant. Return a safe skeleton and fill the cache in
        # background; the browser will show live data on the next refresh tick.
        _TRADES_CACHE = {"active": [], "pending": [], "history": [], "memoryScope": "bot_only", "source": "warming", "message": "Loading live MT5 trades in background."}
        _TRADES_CACHE_TS = now
        _spawn_turbo_refresh("trades", _refresh_trades_cache_sync)
        return deepcopy(_TRADES_CACHE)
    if (now - _TRADES_CACHE_TS) >= _TRADES_CACHE_TTL:
        _spawn_turbo_refresh("trades", _refresh_trades_cache_sync)
        cached = deepcopy(_TRADES_CACHE)
        cached["stale"] = True
        cached["staleReason"] = "turbo_trade_cache_refreshing"
        return cached
    return deepcopy(_TRADES_CACHE)

def _live_signals() -> list[dict[str, Any]]:
    decision_cached = _cached_decision()
    market = decision_cached.get("_market") or _live_market()
    if not market.get("connected"):
        return []
    if market.get("source") == "demo":
        return demo_data.signals()
    decision = {k: v for k, v in decision_cached.items() if k != "_market"}
    action = str(decision.get("action", "WAIT")).upper()
    side = str(decision.get("side", market.get("side", "WAIT"))).upper()
    if action not in {"TAKE_TRADE", "WAIT", "SKIP", "BLOCK"}:
        action = "WAIT"
    plan = decision.get("tradePlan", {}) if isinstance(decision.get("tradePlan"), dict) else {}
    selected_strategy = decision.get("selectedStrategy", {}) if isinstance(decision.get("selectedStrategy"), dict) else {}
    price = market.get("price")
    session = market.get("session", "Unknown")
    primary = {
        "id": f"live-{int(time.time())}",
        "time": time.strftime("%H:%M:%S"),
        "date": time.strftime("%Y-%m-%d"),
        "pair": market.get("symbol", "XAUUSD"),
        "symbol": market.get("symbol", "XAUUSD"),
        "side": side if action == "TAKE_TRADE" else "WAIT",
        "strategy": selected_strategy.get("name") or decision.get("strategy") or market.get("activeStrategy", "AI Evaluation"),
        "timeframe": market.get("timeframe", "M15"),
        "entry": plan.get("entry") or price,
        "entryPrice": plan.get("entry") or price,
        "sl": plan.get("sl"),
        "tp1": plan.get("tp1"),
        "tp2": plan.get("tp2"),
        "tp3": plan.get("tp3"),
        "tp4": plan.get("tp4"),
        "rr": plan.get("rrToTP1") or plan.get("rrToTP2"),
        "confidence": int(float(decision.get("confidence", 0) or 0)),
        "status": action,
        "result": "—",
        "price": price,
        "change": "0.00%",
        "session": session,
        "reason": decision.get("reason"),
        "source": "live_ai",
        "isPrimary": True,
    }
    signals = [primary]
    # Ensemble leaderboard: surface the next-best candidate strategies for THIS bar so
    # the "Featured High-Confidence Signals" cards show multiple real strategies, not one.
    candidates = decision.get("strategyCandidates") or []
    for c in candidates[1:4]:
        signals.append({
            "id": f"cand-{c.get('name','')[:6]}-{int(time.time())}",
            "time": time.strftime("%H:%M:%S"),
            "date": time.strftime("%Y-%m-%d"),
            "pair": market.get("symbol", "XAUUSD"),
            "symbol": market.get("symbol", "XAUUSD"),
            "side": side if side in {"BUY", "SELL"} else "WAIT",
            "strategy": c.get("name"),
            "timeframe": market.get("timeframe", "M15"),
            "entry": price,
            "entryPrice": price,
            "rr": plan.get("rrToTP2"),
            "confidence": int(float(c.get("score", 0) or 0)),
            "status": "CANDIDATE",
            "result": "—",
            "price": price,
            "session": session,
            "reason": f"Ensemble candidate · regime fit {c.get('fit')}, live win-rate {c.get('liveWinRate')}% over {c.get('trades',0)} samples ({c.get('source')}).",
            "source": "live_ai_candidate",
        })
    return signals

def _build_dashboard_snapshot() -> dict[str, Any]:
    """Build a fresh dashboard snapshot. Called only by the turbo cache worker."""
    if not mt5_bridge.status().get("connected") and _demo_enabled():
        d = demo_data.dashboard()
        d["status"] = status()
        mkt = _market_state()
        if isinstance(d.get("decision"), dict):
            d["decision"]["marketOpen"] = bool(mkt.get("open", False))
            d["decision"]["marketStatus"] = mkt.get("reason", "")
            if not mkt.get("open", False):
                d["decision"]["action"] = "MARKET_CLOSED"
                d["decision"]["reason"] = f"Market closed — {mkt.get('reason', 'outside trading hours')}."
        return d
    account_data = _live_account()
    decision_cached = _cached_decision()
    market = decision_cached.get("_market") or _live_market()
    trades_data = _live_trades()
    decision = {k: v for k, v in decision_cached.items() if k != "_market"}
    # Never block Dashboard on heavy long-history analytics. Use whatever is cached
    # and refresh analytics independently in the background.
    analytics_snapshot = (_ANALYTICS_CACHE.get("data") if isinstance(_ANALYTICS_CACHE, dict) else None) or {"equityCurve": [], "topStrategies": []}
    if not _ANALYTICS_CACHE or (time.time() - _ANALYTICS_CACHE_TS) > _ANALYTICS_CACHE_TTL:
        _spawn_turbo_refresh("analytics", _refresh_analytics_cache_sync)
    return {
        "status": status(),
        "account": account_data,
        "market": market,
        "decision": decision,
        "trades": trades_data,
        "why": decision.get("reasons", ["Waiting for live MT5 data."]),
        "equityCurve": analytics_snapshot.get("equityCurve", []),
        "topStrategies": analytics_snapshot.get("topStrategies", []),
        "source": "mt5" if market.get("connected") else "not_connected",
    }


def _refresh_dashboard_cache_sync() -> None:
    global _DASHBOARD_CACHE, _DASHBOARD_CACHE_TS
    if not _DASHBOARD_REFRESH_LOCK.acquire(blocking=False):
        return
    try:
        _DASHBOARD_CACHE = deepcopy(_build_dashboard_snapshot())
        _DASHBOARD_CACHE_TS = time.time()
    except Exception as exc:
        if not _DASHBOARD_CACHE:
            _DASHBOARD_CACHE = {"status": {}, "account": {}, "market": {}, "trades": {"active": [], "pending": [], "history": []}, "why": [f"Dashboard refresh failed: {exc}"], "source": "error"}
            _DASHBOARD_CACHE_TS = time.time()
    finally:
        try:
            _DASHBOARD_REFRESH_LOCK.release()
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_5273", _suppressed_exc)


def _live_dashboard() -> dict[str, Any]:
    global _DASHBOARD_CACHE, _DASHBOARD_CACHE_TS
    now = time.time()
    if not _DASHBOARD_CACHE:
        _DASHBOARD_CACHE = {"status": {"app":"GodMode Gold Trading Bot", "agentStatus":"Warming"}, "account": {}, "market": {}, "trades": {"active": [], "pending": [], "history": []}, "why": ["Loading live dashboard in background."], "source": "warming"}
        _DASHBOARD_CACHE_TS = now
        _spawn_turbo_refresh("dashboard", _refresh_dashboard_cache_sync)
        return deepcopy(_DASHBOARD_CACHE)
    if (now - _DASHBOARD_CACHE_TS) >= _DASHBOARD_CACHE_TTL:
        _spawn_turbo_refresh("dashboard", _refresh_dashboard_cache_sync)
        cached = deepcopy(_DASHBOARD_CACHE)
        cached["stale"] = True
        cached["staleReason"] = "turbo_dashboard_cache_refreshing"
        return cached
    return deepcopy(_DASHBOARD_CACHE)

def _risk_limits_view() -> dict[str, Any]:
    """Structured, persisted risk limits the Risk page renders and edits."""
    return {
        "maxDailyLossPct": RISK_STATE.get("maxDailyLossPct", RISK_DEFAULTS["maxDailyLossPct"]),
        "maxDrawdownPct": RISK_STATE.get("maxDrawdownPct", RISK_DEFAULTS["maxDrawdownPct"]),
        "maxRiskPerTradePct": RISK_STATE.get("maxRiskPerTradePct", RISK_DEFAULTS["maxRiskPerTradePct"]),
        "maxOpenRiskPct": RISK_STATE.get("maxOpenRiskPct", RISK_DEFAULTS["maxOpenRiskPct"]),
        "maxExposurePct": RISK_STATE.get("maxExposurePct", RISK_DEFAULTS["maxExposurePct"]),
        "lossStreakLimit": RISK_STATE.get("lossStreakLimit", RISK_DEFAULTS["lossStreakLimit"]),
        "newsFilterMinutes": RISK_STATE.get("newsFilterMinutes", RISK_DEFAULTS["newsFilterMinutes"]),
        "circuitBreakerPct": RISK_STATE.get("circuitBreakerPct", RISK_DEFAULTS["circuitBreakerPct"]),
        "maxSpreadXau": RISK_STATE.get("maxSpreadXau", RISK_DEFAULTS["maxSpreadXau"]),
        "sessionCaps": RISK_STATE.get("sessionCaps", RISK_DEFAULTS["sessionCaps"]),
        "rules": RISK_STATE.get("rules", {}),
    }

def _live_risk() -> dict[str, Any]:
    account_data = _live_account()
    trades_data = _live_trades()
    market = _live_market()
    warnings: list[dict[str, Any]] = []
    if not account_data.get("connected"):
        warnings.append({"type": "warning", "title": "MT5 Not Connected", "detail": account_data.get("detail", "Open MT5 and log in to a broker account."), "time": "now"})
    if int(account_data.get("unprotectedPositions") or 0) > 0:
        warnings.insert(0, {
            "type": "danger",
            "title": "Unprotected Broker Position",
            "detail": f"{int(account_data['unprotectedPositions'])} GodMode position(s) have no measurable protective SL. New stacking is blocked.",
            "time": "now",
        })
    if kill_switch.status().get("active"):
        warnings.insert(0, {"type": "danger", "title": "Emergency Kill Switch Active", "detail": kill_switch.status().get("reason", "Trading blocked."), "time": "now"})
    history = trades_data.get("history", []) if isinstance(trades_data, dict) else []
    loss_streak = 0
    for trade in history if isinstance(history, list) else []:
        pnl = float(trade.get("pnlUsd") or trade.get("pnl") or 0.0)
        if pnl < 0:
            loss_streak += 1
        elif pnl > 0:
            break
    automation = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    risk_telemetry = {
        "lossStreak": loss_streak,
        "correlation": None,
        "correlationStatus": "not_applicable_single_symbol",
        "spread": market.get("spread") if isinstance(market, dict) else None,
        "riskEngineEnabled": True,
        "volatilitySizingEnabled": bool(automation.get("volNormalizedSizing", False)),
        "newsGuardEnabled": bool(automation.get("newsFailClosed", True)),
        "emergencyStopActive": bool(kill_switch.status().get("active")),
        "openRiskKnown": bool(account_data.get("openRiskKnown", False)),
    }
    return {
        "account": account_data,
        "trades": trades_data,
        "market": market,
        "warnings": warnings,
        "limits": _risk_limits_view(),
        "overrides": RISK_STATE,
        "strategies": list(STRATEGIES_STATE.values()),
        "telemetry": risk_telemetry,
        "source": account_data.get("source", "not_connected"),
    }

def _day_insight(day_trades: list[dict[str, Any]]) -> dict[str, str]:
    """From a single day's REAL closed trades, derive (1) what the AI effectively detected that day
    and (2) the best optimisation for the FOLLOWING day. Everything here is computed from that day's
    own outcomes — it's guidance grounded in real results, not a generic tip."""
    n = len(day_trades)
    if not n:
        return {"detected": "No trades — the tape never cleared the bot's entry gates (low efficiency / "
                            "insufficient confluence / wide spread).",
                "optimization": "Keep your settings. Wait for a clean London–NY trend setup; quiet days are "
                                "correctly skipped, not forced."}
    pnls = [float(t.get("pnlUsd", 0) or 0) for t in day_trades]
    wins = sum(1 for p in pnls if p > 0)
    losses = sum(1 for p in pnls if p < 0)
    net = round(sum(pnls), 2)
    confs = [float(t.get("confidence", 0) or 0) for t in day_trades if t.get("confidence") is not None]
    avg_conf = round(sum(confs) / len(confs), 0) if confs else 0
    wr = round(wins / n * 100)
    sess_counts: dict[str, int] = {}
    for t in day_trades:
        s = str(t.get("session") or "Unknown")
        sess_counts[s] = sess_counts.get(s, 0) + 1
    top_sess = max(sess_counts, key=sess_counts.get) if sess_counts else "—"
    # What the AI detected (framed by the day's realised behaviour)
    if net > 0 and wr >= 50:
        detected = (f"Clean, tradeable tape — {n} trade(s), {wins}W/{losses}L, net {net:+}, "
                    f"avg confidence {avg_conf:.0f}%. Best activity in {top_sess}. Signals followed through.")
    elif net < 0 and wr < 50:
        detected = (f"Choppy / low follow-through — {n} trade(s), {wins}W/{losses}L, net {net:+}. "
                    f"Entries triggered (avg conf {avg_conf:.0f}%) but price reversed before target — classic chop.")
    else:
        detected = (f"Mixed tape — {n} trade(s), {wins}W/{losses}L, net {net:+}, avg confidence "
                    f"{avg_conf:.0f}%. Some setups worked, some faded; no decisive regime.")
    # Best optimisation for the FOLLOWING day
    if net < 0:
        if avg_conf and avg_conf < 75:
            optimization = ("Raise Standard Confidence and require 5/12 confluence tomorrow — most losers were "
                            "marginal signals that wouldn't pass a stricter gate.")
        else:
            optimization = ("Signal quality was OK but costs/timing bled it — tighten Max Spread and trade "
                            "London–NY only tomorrow so cost drag can't turn break-even into a loss.")
    elif net > 0 and wr >= 60:
        optimization = ("Keep the current config — it matched the regime. On A+ continuations consider letting "
                        "the prove/confirm/press pyramid scale the winners.")
    elif net > 0:
        optimization = "Hold settings; the edge showed but the sample is small. Let it prove out before changing anything."
    else:
        optimization = ("Stay defensive tomorrow: keep range-awareness on and confluence high until a clean "
                        "trend re-establishes — don't loosen gates chasing a flat day.")
    return {"detected": detected, "optimization": optimization}


def _build_returns_calendar(history: list[dict[str, Any]], starting_balance: float) -> list[dict[str, Any]]:
    """Per-DAY calendar cells (Mon–Fri grid the UI groups by ISO week) with PnL, trade counts and a
    clickable AI insight for each day. Built from the same real closed-trade history as the heatmap."""
    import datetime as _dt
    _wd = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
    day_map: dict[str, dict[str, Any]] = {}
    for t in history:
        cts = int(t.get("closeTimestamp", 0) or 0)
        if not cts:
            continue
        try:
            dd = _dt.datetime.utcfromtimestamp(cts)
        except Exception:
            continue
        iso_year, iso_week, iso_wd = dd.isocalendar()
        if iso_wd > 5:   # weekend (XAUUSD closed) — skip
            continue
        key = dd.strftime("%Y-%m-%d")
        cell = day_map.setdefault(key, {"date": key, "week": f"W{iso_week:02d}", "dow": _wd[iso_wd - 1],
                                        "pnl": 0.0, "trades": 0, "wins": 0, "losses": 0, "_t": []})
        cell["pnl"] = round(cell["pnl"] + float(t.get("pnlUsd", 0) or 0), 2)
        cell["trades"] += 1
        p = float(t.get("pnlUsd", 0) or 0)
        if p > 0:
            cell["wins"] += 1
        elif p < 0:
            cell["losses"] += 1
        cell["_t"].append(t)
    base = max(starting_balance, 1.0)
    out: list[dict[str, Any]] = []
    for key in sorted(day_map.keys()):
        cell = day_map[key]
        cell["pct"] = round(cell["pnl"] / base * 100, 2)
        cell.update(_day_insight(cell.pop("_t")))
        out.append(cell)
    return out[-40:]   # last ~8 trading weeks


def _build_analytics_snapshot(date_from: str | None = None, date_to: str | None = None) -> dict[str, Any]:
    global _ANALYTICS_CACHE, _ANALYTICS_CACHE_TS
    now = time.time()
    cache_key = f"{date_from or ''}|{date_to or ''}|{bool(mt5_bridge.status().get('connected'))}"
    if not date_from and not date_to and _ANALYTICS_CACHE.get("key") == cache_key and (now - _ANALYTICS_CACHE_TS) < _ANALYTICS_CACHE_TTL:
        return deepcopy(_ANALYTICS_CACHE.get("data") or {})
    if not mt5_bridge.status().get("connected") and _demo_enabled():
        data = demo_data.analytics(date_from, date_to)
        if not date_from and not date_to:
            _ANALYTICS_CACHE = {"key": cache_key, "data": deepcopy(data)}; _ANALYTICS_CACHE_TS = now
        return data
    account_data = _live_account()
    currency = account_data.get("currency") or ""
    starting_balance = float(account_data.get("balance", 10000) or 10000)
    history = _enrich_history(_merge_recent_closed(mt5_bridge.closed_bot_trades(days=365)))
    if date_from or date_to:
        def _in(t):
            d = str(t.get("closeTime") or t.get("date") or "")[:10]
            return (not date_from or d >= date_from) and (not date_to or d <= date_to)
        history = [t for t in history if _in(t)]
    total = len(history)
    wins = [t for t in history if float(t.get("pnlUsd", 0) or 0) > 0]
    losses = [t for t in history if float(t.get("pnlUsd", 0) or 0) < 0]
    gross_profit = sum(float(t.get("pnlUsd", 0) or 0) for t in wins)
    gross_loss = abs(sum(float(t.get("pnlUsd", 0) or 0) for t in losses))
    net = gross_profit - gross_loss

    # Build equity curve from cumulative PnL.
    # Chart components read: EquityCurve -> {date, equity, benchmark}; DrawdownChart -> {date, value}
    equity_curve: list[dict[str, Any]] = []
    running = starting_balance - net  # reconstruct starting balance
    base = running
    for i, t in enumerate(reversed(history)):
        running += float(t.get("pnlUsd", 0) or 0)
        equity_curve.append({"x": i, "value": round(running, 2), "equity": round(running, 2),
                             "benchmark": round(base, 2),
                             "date": str(t.get("closeTime", ""))[:10] or f"#{i+1}"})

    # Max drawdown from equity curve
    peak, max_dd = 0.0, 0.0
    for pt in equity_curve:
        v = pt["value"]
        if v > peak:
            peak = v
        dd = (peak - v) / peak * 100 if peak else 0.0
        if dd > max_dd:
            max_dd = dd

    # Drawdown series — DrawdownChart reads {date, value}
    drawdown_series: list[dict[str, Any]] = []
    peak2 = 0.0
    for pt in equity_curve:
        v = pt["value"]
        if v > peak2:
            peak2 = v
        drawdown_series.append({"x": pt["x"], "date": pt["date"], "value": -round((peak2 - v) / peak2 * 100, 2) if peak2 else 0.0})

    # Session performance
    session_map: dict[str, dict[str, Any]] = {}
    for t in history:
        sess = str(t.get("session") or "Unknown")
        pnl = float(t.get("pnlUsd", 0) or 0)
        s = session_map.setdefault(sess, {"Session": sess, "Net PnL": 0.0, "Wins": 0, "Trades": 0, "Expectancy": 0.0})
        s["Net PnL"] = round(s["Net PnL"] + pnl, 2)
        s["Trades"] += 1
        if pnl > 0:
            s["Wins"] += 1
    sessions = []
    for s in session_map.values():
        t2 = s["Trades"]
        sessions.append({**s, "Win Rate": f"{round(s['Wins']/t2*100,1) if t2 else 0}%", "Expectancy": round(s["Net PnL"]/t2, 2) if t2 else 0})

    # Top strategies grouped by the REAL strategy name (from the trade-context store /
    # stamped comment), not the raw entry-type comment. Each row carries BOTH the
    # capitalised keys the Analytics table reads AND the lowercase name/winRate keys
    # the Dashboard card reads, so both surfaces render correctly.
    strat_map: dict[str, dict[str, Any]] = {}
    for t in history:
        # V13.16: prefer the recorded real strategy; else decode the comment. If the decode returns
        # None (a TP1..TP4 partial-close leg or other exit artifact), SKIP it — those are exit
        # events, not strategies, and were showing up as cryptic "Tp3" rows on the dashboard.
        _recorded = str(t.get("strategy") or "").strip()
        if _recorded:
            name = _recorded
        else:
            _decoded = strategy_from_comment(str(t.get("comment") or ""))
            if _decoded is None:
                _cmt = str(t.get("comment") or "")
                # only bucket as GodMode Bot if there is genuinely no strategy signal at all;
                # a comment that decoded to None because it's a TP leg is skipped.
                if _cmt and any(x in _cmt for x in ("Tp", "TP", "_BE", "_SL", "trail")):
                    continue
                name = "GodMode Bot"
            else:
                name = _decoded
        pnl = float(t.get("pnlUsd", 0) or 0)
        s = strat_map.setdefault(name, {"Strategy": name, "name": name, "Net PnL": 0.0, "netPnl": 0.0, "Wins": 0, "Trades": 0})
        s["Net PnL"] = round(s["Net PnL"] + pnl, 2)
        s["netPnl"] = s["Net PnL"]
        s["Trades"] += 1
        if pnl > 0:
            s["Wins"] += 1
    top_strategies = sorted(strat_map.values(), key=lambda x: x["Net PnL"], reverse=True)[:8]
    for s in top_strategies:
        t3 = s["Trades"]
        wr = round(s["Wins"] / t3 * 100, 1) if t3 else 0
        s["Win Rate"] = f"{wr}%"
        s["winRate"] = wr
        s["trades"] = s["Trades"]
        s["enabled"] = True

    # Returns heatmap — ReturnsHeatmap reads rows of {week, Mon, Tue, Wed, Thu, Fri}
    # Build a per-ISO-week, per-weekday PnL grid from close timestamps.
    import datetime as _dt
    _wd = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]
    week_grid: dict[str, dict[str, float]] = {}
    for t in history:
        cts = int(t.get("closeTimestamp", 0) or 0)
        if not cts:
            continue
        try:
            d = _dt.datetime.utcfromtimestamp(cts)
        except Exception:
            continue
        iso_year, iso_week, iso_wd = d.isocalendar()
        wk = f"W{iso_week:02d}"
        day = _wd[iso_wd - 1]
        row = week_grid.setdefault(wk, {})
        row[day] = round(row.get(day, 0.0) + float(t.get("pnlUsd", 0) or 0), 2)
    returns = [{"week": wk, **{d: round(week_grid[wk].get(d, 0.0), 1) for d in ["Mon", "Tue", "Wed", "Thu", "Fri"]}}
               for wk in sorted(week_grid.keys())][-8:]
    # Monthly bars for the market-heatmap card — BarDistribution reads {x, v}
    month_map: dict[str, float] = {}
    for t in history:
        d = str(t.get("closeTime") or "")[:7]
        if d:
            month_map[d] = round(month_map.get(d, 0.0) + float(t.get("pnlUsd", 0) or 0), 2)
    market_heatmap = [{"x": k, "v": v} for k, v in sorted(month_map.items())]

    # Execution quality histogram (hold time in hours)
    exec_map: dict[str, int] = {"<1h": 0, "1-4h": 0, "4-24h": 0, "1-3d": 0, ">3d": 0}
    for t in history:
        ht = str(t.get("holdTime", "") or "")
        if "m" in ht.lower() or not ht:
            exec_map["<1h"] += 1
        elif "h" in ht.lower():
            try:
                h = float(ht.lower().replace("h", "").strip().split()[0])
                if h < 1:
                    exec_map["<1h"] += 1
                elif h < 4:
                    exec_map["1-4h"] += 1
                else:
                    exec_map["4-24h"] += 1
            except Exception:
                exec_map["4-24h"] += 1
        else:
            exec_map[">3d"] += 1
    # BarDistribution reads {x, v}
    execution_quality = [{"x": k, "v": v} for k, v in exec_map.items()]

    # ScatterPerformance reads {confidence, result}
    confidence_result = [{"confidence": float(t.get("confidence", 50) or 50), "result": float(t.get("pnlUsd", 0) or 0)} for t in history]
    # Expectancy vs win rate scatter (per strategy) — reuse confidence/result keys
    expectancy_scatter = [{"confidence": float(str(s.get("Win Rate","0%")).replace("%","")), "result": round(s["Net PnL"] / s["Trades"], 2) if s["Trades"] else 0, "name": s["Strategy"]} for s in top_strategies]
    buy_wins = sum(1 for t in history if float(t.get("pnlUsd",0)or 0)>0 and str(t.get("direction","")).upper()=="BUY")
    sell_wins = sum(1 for t in history if float(t.get("pnlUsd",0)or 0)>0 and str(t.get("direction","")).upper()=="SELL")
    buy_total = sum(1 for t in history if str(t.get("direction","")).upper()=="BUY") or 1
    sell_total = sum(1 for t in history if str(t.get("direction","")).upper()=="SELL") or 1

    out = {
        "source": "mt5_bot_history" if total else "no_bot_history",
        "kpis": {
            "netProfit": round(net, 2),
            "returnPct": round(net / (starting_balance - net) * 100, 2) if (starting_balance - net) > 0 else 0.0,
            "totalTrades": total,
            "winRate": round((len(wins) / total) * 100, 2) if total else 0.0,
            "profitFactor": round(gross_profit / gross_loss, 2) if gross_loss else 0.0,
            "expectancy": round(net / total, 2) if total else 0.0,
            "maxDrawdown": round(max_dd, 2),
        },
        "equityCurve": equity_curve,
        "drawdown": drawdown_series,
        "returns": returns,
        "returnsCalendar": _build_returns_calendar(history, starting_balance - net),
        "topStrategies": top_strategies,
        "sessions": sessions,
        "executionQuality": execution_quality,
        "confidenceResult": confidence_result,
        "expectancyScatter": expectancy_scatter,
        "marketHeatmap": market_heatmap,
        "buyWinRate": round(buy_wins / buy_total * 100, 1) if buy_total else 0.0,
        "sellWinRate": round(sell_wins / sell_total * 100, 1) if sell_total else 0.0,
        "breakEvenRate": 0.0,
        "lossRate": round((len(losses) / total * 100), 1) if total else 0.0,
        "startingBalance": round(starting_balance - net, 2),
        "endingBalance": round(starting_balance, 2),
        "avgSlippage": "< 0.5 pts",
        "fillQuality": "Good" if total > 0 else "Waiting",
        "history": history,
        "currency": currency,
        "account": account_data,
    }
    if not date_from and not date_to:
        _ANALYTICS_CACHE = {"key": cache_key, "data": deepcopy(out)}; _ANALYTICS_CACHE_TS = time.time()
    return out


def _refresh_analytics_cache_sync() -> None:
    global _ANALYTICS_CACHE, _ANALYTICS_CACHE_TS
    if not _ANALYTICS_REFRESH_LOCK.acquire(blocking=False):
        return
    try:
        # V15.0.8 RACE FIX: this used to set _ANALYTICS_CACHE = {} *before* the
        # rebuild. Any concurrent reader in _live_analytics() that hit the window
        # between the blanking and the repopulation crashed with KeyError: 'data'
        # (confirmed: it broke POST /api/telegram/recap outright, and made the
        # analytics/dashboard reads intermittently 500). The cache is never
        # blanked now — it is swapped atomically once the new snapshot is built.
        # _ANALYTICS_REFRESH_LOCK already prevents the recursion this guarded against.
        data = _build_analytics_snapshot(None, None)
        _ANALYTICS_CACHE = {"key": f"||{bool(mt5_bridge.status().get('connected'))}", "data": deepcopy(data)}
        _ANALYTICS_CACHE_TS = time.time()
    except Exception as exc:
        if not _ANALYTICS_CACHE:
            _ANALYTICS_CACHE = {"key": "", "data": {"source":"error", "message": f"Analytics refresh failed: {exc}", "equityCurve": [], "topStrategies": [], "history": []}}
            _ANALYTICS_CACHE_TS = time.time()
    finally:
        try:
            _ANALYTICS_REFRESH_LOCK.release()
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_5651", _suppressed_exc)


def _live_analytics(date_from: str | None = None, date_to: str | None = None) -> dict[str, Any]:
    global _ANALYTICS_CACHE, _ANALYTICS_CACHE_TS
    # Filtered analytics are explicit user requests; build them normally. Dashboard
    # and general pages use instant cache + background refresh.
    if date_from or date_to:
        return _build_analytics_snapshot(date_from, date_to)
    key = f"||{bool(mt5_bridge.status().get('connected'))}"
    now = time.time()
    if not _ANALYTICS_CACHE:
        _ANALYTICS_CACHE = {"key": key, "data": {"source":"warming", "equityCurve": [], "topStrategies": [], "history": [], "message":"Loading analytics in background."}}
        _ANALYTICS_CACHE_TS = now
        _spawn_turbo_refresh("analytics", _refresh_analytics_cache_sync)
        # V15.0.8: .get() not ["data"] — _spawn_turbo_refresh may complete inline
        # and swap the cache before this line runs.
        return deepcopy(_ANALYTICS_CACHE.get("data") or {"source": "warming", "equityCurve": [], "topStrategies": [], "history": []})
    data = deepcopy(_ANALYTICS_CACHE.get("data") or {})
    if _ANALYTICS_CACHE.get("key") != key or (now - _ANALYTICS_CACHE_TS) >= _ANALYTICS_CACHE_TTL:
        _spawn_turbo_refresh("analytics", _refresh_analytics_cache_sync)
        data["stale"] = True
        data["staleReason"] = "turbo_analytics_cache_refreshing"
    return data

def _manual_to_entry(m: dict[str, Any]) -> dict[str, Any]:
    """Map a user-written manual entry onto the journal-entry shape the UI renders."""
    pnl = float(m.get("pnl", 0) or 0)
    side = str(m.get("side") or m.get("direction") or "—").upper()
    return {
        "manual": True, "id": m.get("id"), "symbol": m.get("symbol") or "XAUUSD",
        "direction": side, "side": side, "outcome": m.get("outcome") or ("WIN" if pnl > 0 else "LOSS" if pnl < 0 else "BREAK_EVEN"),
        "pnl": pnl, "pnlUsd": pnl, "time": m.get("time") or m.get("date") or "", "date": str(m.get("date") or m.get("time") or "")[:10],
        "strategy": m.get("strategy") or "Manual note", "session": m.get("session") or "—",
        "marketRegime": m.get("marketRegime") or "Manual entry", "confidence": m.get("confidence", 0),
        "entryPrice": m.get("entryPrice") or "—", "exitPrice": m.get("exitPrice") or "—",
        "sl": m.get("sl") or "—", "tp": m.get("tp") or "—",
        "lessons": m.get("lessons") or "", "improvement": m.get("improvement") or "",
        "aiNotes": m.get("notes") or m.get("aiNotes") or "", "aiScore": "—",
        "tags": (m.get("tags") or ["manual"]), "candles": [], "currency": m.get("currency", ""),
    }


def _merge_manual_journal(entries: list[dict[str, Any]], date_from: str | None, date_to: str | None) -> list[dict[str, Any]]:
    out = list(entries) + [_manual_to_entry(m) for m in MANUAL_JOURNAL]
    if date_from:
        out = [e for e in out if str(e.get("date", "")) >= date_from]
    if date_to:
        out = [e for e in out if str(e.get("date", "")) <= date_to]
    out.sort(key=lambda e: str(e.get("time") or e.get("date") or ""), reverse=True)
    return out


def _live_journal(date_from: str | None = None, date_to: str | None = None) -> list[dict[str, Any]]:
    if not mt5_bridge.status().get("connected") and _demo_enabled():
        return _merge_manual_journal(demo_data.journal(date_from, date_to), date_from, date_to)
    raw = _enrich_history(_merge_recent_closed(mt5_bridge.closed_bot_trades(days=90)))
    entries = []
    for t in raw:
        pnl = float(t.get("pnlUsd", 0) or 0)
        # Strategy + reason now come from the enriched trade (context store / stamped comment).
        strategy = t.get("strategy") or "GodMode Bot"
        # Session: prefer the entry-context session; else derive from close-time hour.
        session = t.get("session") or "Unknown"
        if session in (None, "", "Unknown"):
            ct = str(t.get("closeTime") or "")
            try:
                h = int(ct[11:13]) if len(ct) > 12 else 12
                session = "Asian" if (22 <= h or h < 7) else "London" if h < 12 else "New York" if h < 17 else "London/NY Overlap"
            except Exception:
                session = "Unknown"
        r_multiple = t.get("rMultiple")
        review = t.get("aiReview") or {}
        ai_notes = t.get("aiNotes") or review.get("summary") or f"{strategy} · {t.get('exitReason','closed')}. PnL {pnl:+.2f} USD."
        entries.append({
            **t,
            "outcome": "WIN" if pnl > 0 else ("LOSS" if pnl < 0 else "BREAK_EVEN"),
            "rMultiple": r_multiple if r_multiple is not None else 0.0,
            "pnl": pnl,
            "time": t.get("closeTime", ""),
            "date": str(t.get("closeTime", ""))[:10],
            "strategy": strategy,
            "session": session,
            "marketRegime": t.get("marketRegime") or "Live MT5 Bot Trade",
            "htfTrend": "—",
            "newsImpact": "Filtered",
            "structure": "—",
            "confidence": t.get("confidence", 0),
            "aiScore": t.get("aiScore", "—"),
            "aiNotes": ai_notes,
            "entryReason": t.get("entryReason") or "",
            "lessons": t.get("lessons") or review.get("lesson") or "",
            "improvement": t.get("improvement") or review.get("improvement") or "",
            "tags": ["bot-only", "mt5", str(session).lower().replace("/", "-").replace(" ", "-")],
            "candles": [],
            "currency": t.get("currency", ""),
        })
    return _merge_manual_journal(entries, date_from, date_to)

def _strategies_with_live_stats() -> list[dict[str, Any]]:
    """Catalog strategies enriched with LIVE win-rate / sample size computed from the
    bot's own recorded trades. The catalog numbers remain as a labelled fallback so
    the Strategy page reflects what is actually working, not just static placeholders."""
    stats = memory.stats()
    by_name = {r.get("name"): r for r in stats.get("strategyPerformance", [])}
    # V12.76: the Strategies tab was showing a hardcoded "M15" and no live ranking. The
    # execution timeframe now comes from settings (so switching to M5 is reflected), and each
    # strategy carries its live ranking score + an honest PROVEN/LEARNING/UNPROVEN badge so a
    # 3-trade 100% win rate can never masquerade as an edge.
    tf = str((SETTINGS_STATE.get("trading", {}) or {}).get("timeframe", "M15"))
    try:
        dec = _cached_decision()
        sel_name = str(((dec.get("selectedStrategy") or {}).get("name")) or "")
        ranked = {r.get("name"): r for r in (dec.get("strategyCandidates") or [])}
    except Exception:
        ranked, sel_name = {}, ""
    session = ""
    try:
        session = str((_MARKET_CACHE or {}).get("session", "") or "")
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_5769", _suppressed_exc)
    out: list[dict[str, Any]] = []
    for s in STRATEGIES_STATE.values():
        row = dict(s)
        m = by_name.get(s.get("name"))
        trades = int(m.get("trades", 0)) if m else 0
        row["liveTrades"] = trades
        row["catalogWinRate"] = s.get("winRate")
        row["timeframe"] = tf
        rk = ranked.get(s.get("name")) or {}
        row["rankScore"] = rk.get("score")
        row["regimeFit"] = rk.get("fit")
        row["sessionFit"] = rk.get("sessionFit")
        row["isSelected"] = (s.get("name") == sel_name)
        row["currentSession"] = session
        if trades >= 20:
            row["evidence"] = "PROVEN"
        elif trades >= 5:
            row["evidence"] = "LEARNING"
        else:
            row["evidence"] = "UNPROVEN"
        row["evidenceNote"] = (f"{trades} live trades on this engine"
                               if trades else "No live trades yet on this engine — catalog estimate only.")
        if m and trades > 0:
            row["liveWinRate"] = m.get("winRate")
            row["liveNetPnl"] = m.get("pnl")
            row["totalTrades"] = trades
            if trades >= 5:  # only let a real sample override the headline number
                row["winRate"] = m.get("winRate")
                row["statsSource"] = "live_memory"
            else:
                row["statsSource"] = "catalog_small_sample"
        else:
            row["statsSource"] = "catalog"
        out.append(row)
    out.sort(key=lambda r: (r.get("rankScore") is None, -(r.get("rankScore") or 0)))
    return out


class StrategyToggle(BaseModel):
    id: str


def _decision() -> dict[str, Any]:
    return _cached_decision()


def _action_matrix(decision: dict[str, Any] | None = None, position: dict[str, Any] | None = None, market: dict[str, Any] | None = None) -> dict[str, Any]:
    decision = decision or _decision()
    market = market or _live_market()
    position = position or {}
    management = trade_manager.live_management_decision(position or {"profitR": 0.0})
    broker_quality = _broker_execution_quality()
    pyramid = pyramiding_engine.evaluate(decision, position=position or None, market=market, broker_quality=broker_quality, kill_switch=kill_switch.status())
    action = str(decision.get("action", "WAIT")).upper()
    quality = str(decision.get("quality", "WAIT")).upper()
    confidence = float(decision.get("confidence", 0) or 0)
    features = decision.get("features", {}) if isinstance(decision.get("features"), dict) else {}
    required_confidence = float(decision_engine.min_take_score)
    # Anticipatory lanes have their own validated probability floors. Applying the
    # generic scout floor after predictor qualification creates a hidden second gate.
    if features.get("anticipatoryEntry"):
        try:
            required_confidence = float(features.get("entryThresholdPct", required_confidence) or required_confidence)
        except (TypeError, ValueError):
            required_confidence = float(decision_engine.min_take_score)
    dirty = bool(kill_switch.status().get("active") or market.get("newsBlackout") or market.get("dirtyConditions"))
    take = action == "TAKE_TRADE" and quality in {"SCOUT", "STANDARD", "HIGH", "SNIPER"} and confidence >= required_confidence and not dirty
    wait = not take and not dirty and action not in {"SKIP", "BLOCK", "MARKET_CLOSED"}
    return {
        "takeThisTrade": take,
        "skipThisTrade": not take and not wait,
        "waitForBetterEntry": wait,
        "holdWinner": management.get("action") in {"HOLD_WINNER", "HOLD", "PUSH_TP", "TRAIL_STRUCTURE"},
        "moveToBreakEven": management.get("action") == "MOVE_TO_BREAKEVEN",
        "trailStructure": management.get("action") == "TRAIL_STRUCTURE",
        "pushTP": management.get("action") == "PUSH_TP",
        "pyramidOnlyIfProven": bool(pyramid.get("allowed")),
        "stopTradingDirtyConditions": dirty or management.get("action") == "STOP_TRADING_DIRTY_CONDITIONS",
        "decision": decision,
        "management": management,
        "pyramiding": pyramid,
        "safety": {"killSwitch": kill_switch.status(), "botOnlyMemory": True, "liveTradingEnabled": mt5_bridge.live_enabled, "validation": _validation_status(), "brokerQuality": broker_quality},
        "strictness": decision_engine.strictness_dict(),
        "requiredConfidence": round(required_confidence, 2),
        "blockedReasons": decision.get("decisionBlocks", []),
        "softBlocks": decision.get("softBlocks", []),
    }


# ─────────────────────────────────────────────────────────────────────────────
# V12.45 LOW-LATENCY FAST SNIPER LANE
# M15 context + M5 trigger. This gives speed without trading M1/tick noise.
# ─────────────────────────────────────────────────────────────────────────────
FAST_SNIPER_STATE: dict[str, Any] = {
    "lastAt": 0.0,
    "last": {},
    "earlyIntent": {"stage": "STARTING", "runtimeStatus": "STARTING", "probability": 0.0, "reason": "Predictor has not scanned yet."},
    "earlyImpulse": {"stage": "STARTING", "runtimeStatus": "STARTING", "probability": 0.0, "reason": "Predictor has not scanned yet."},
}
FAST_SNIPER_MTF_STATE: dict[str, Any] = {"cache": {}}
PREDICTOR_TICK_BUFFERS: dict[str, list[dict[str, Any]]] = {}
PREDICTOR_TICK_LOCK = threading.RLock()
MOMENTUM_FALLBACK_STATE: dict[str, Any] = {"side": None, "candleTime": 0, "updatedAt": 0.0}
PRIORITY_INTENT_STATE: dict[str, Any] = {
    "runtimeStatus": "STARTING", "lastScanAt": 0.0, "lastCompletedAt": 0.0,
    "lastCandidate": {}, "lastExecution": {}, "lastBlocker": "",
    "consecutiveFailures": 0, "scanSequence": 0, "buildId": BUILD_ID,
}
PRIORITY_INTENT_LOCK = threading.RLock()
PREDICTOR_TICK_LAST_FETCH_MSC: dict[str, int] = {}
PREDICTOR_TICK_LAST_BACKFILL_AT: dict[str, float] = {}
PREDICTOR_CANDLE_CACHE: dict[tuple[str, str, int], dict[str, Any]] = {}
PREDICTOR_CANDLE_LOCK = threading.RLock()


def _priority_intent_health() -> dict[str, Any]:
    """Return loop liveness without executing a market scan or touching MT5 history."""
    now = time.time()
    cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    interval = max(0.15, min(float(cfg.get("earlyIntentPriorityLoopSeconds", 0.25) or 0.25), 2.0))
    stale_after = max(3.0, interval * 8.0)
    last_scan = float(PRIORITY_INTENT_STATE.get("lastScanAt", 0.0) or 0.0)
    last_completed = float(PRIORITY_INTENT_STATE.get("lastCompletedAt", 0.0) or 0.0)
    liveness_at = last_completed or last_scan
    age = round(max(0.0, now - liveness_at), 3) if liveness_at else None
    runtime = str(PRIORITY_INTENT_STATE.get("runtimeStatus") or "STARTING").upper()
    task_done = bool(_PRIORITY_INTENT_TASK is not None and _PRIORITY_INTENT_TASK.done())
    in_flight = bool(PRIORITY_INTENT_STATE.get("inFlight"))
    if runtime == "ERROR" or task_done:
        status, ok = "error", False
    elif runtime == "RECOVERING" and not in_flight:
        status, ok = "recovering", False
    elif not last_scan:
        status, ok = "starting", False
    elif age is not None and age > stale_after:
        status, ok = "stale", False
    else:
        status, ok = "live", True
    return {
        "ok": ok,
        "status": status,
        "runtimeStatus": runtime,
        "lastScanAt": last_scan,
        "lastCompletedAt": last_completed,
        "lastScanAgeSeconds": age,
        "expectedIntervalSeconds": interval,
        "staleAfterSeconds": stale_after,
        "taskPresent": _PRIORITY_INTENT_TASK is not None,
        "taskDone": task_done,
        "inFlight": in_flight,
        "lastBlocker": str(PRIORITY_INTENT_STATE.get("lastBlocker") or ""),
        "consecutiveFailures": int(PRIORITY_INTENT_STATE.get("consecutiveFailures", 0) or 0),
        "lastCycleLatencyMs": _fs_float(PRIORITY_INTENT_STATE.get("lastCycleLatencyMs"), 0.0),
        "scanSequence": int(PRIORITY_INTENT_STATE.get("scanSequence", 0) or 0),
        "buildId": BUILD_ID,
    }


def _predictor_extension_atr(candles: list[dict[str, Any]], atr: float, period: int = 20) -> float:
    """Compute live EMA extension from raw MT5 rate rows.

    MT5 copy-rates rows do not contain precomputed EMA fields. Earlier predictor lanes
    read ``row["ema20"]`` and silently fell back to the current close, reporting zero
    extension and weakening the anti-chase guard. This helper derives EMA20 directly
    from the cached M5 closes so the extension gate is truthful without another MT5 call.
    """
    closes = [_fs_float(row.get("close"), 0.0) for row in candles if _fs_float(row.get("close"), 0.0) > 0]
    atr_value = _fs_float(atr, 0.0)
    if not closes or atr_value <= 0:
        return 0.0
    alpha = 2.0 / (max(1, int(period)) + 1.0)
    ema = closes[0]
    for value in closes[1:]:
        ema = alpha * value + (1.0 - alpha) * ema
    return abs(closes[-1] - ema) / atr_value


def _predictor_candle_series(symbol: str, timeframe: str, count: int, ttl_seconds: float,
                             market: dict[str, Any], now: float) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Return bounded cached candles and patch the forming close from the live tick.

    The priority lane used to request 90 M5 and 90 M15 bars every 250 ms. MT5 serialises
    terminal IPC, so those repeated full-history calls queued behind dashboard and trade
    management requests. The cache retains structural history while the current bid/ask
    updates the forming M5 candle without another terminal round-trip.
    """
    key = (str(symbol), str(timeframe).upper(), int(count))
    with PREDICTOR_CANDLE_LOCK:
        cached = deepcopy(PREDICTOR_CANDLE_CACHE.get(key) or {})
    age = now - float(cached.get("fetchedAt", 0.0) or 0.0)
    fetch_ms = 0.0
    cache_hit = bool(cached.get("candles")) and age <= max(0.25, float(ttl_seconds))
    candles = deepcopy(cached.get("candles") or []) if cache_hit else []
    if not cache_hit:
        started = time.perf_counter()
        fresh = mt5_bridge.copy_rates(symbol, timeframe, count) if mt5_bridge.status().get("connected") else []
        fetch_ms = round((time.perf_counter() - started) * 1000.0, 2)
        if fresh:
            candles = fresh
            age = 0.0
            with PREDICTOR_CANDLE_LOCK:
                PREDICTOR_CANDLE_CACHE[key] = {"candles": deepcopy(fresh), "fetchedAt": now, "fetchLatencyMs": fetch_ms}
        elif cached.get("candles"):
            candles = deepcopy(cached["candles"])
            cache_hit = True
    # Keep the active M5 candle live between terminal history refreshes.
    if candles and str(timeframe).upper() == "M5":
        price = _fs_float(market.get("price"), 0.0)
        if price > 0:
            last = dict(candles[-1])
            last["close"] = round(price, 3)
            last["high"] = round(max(_fs_float(last.get("high"), price), price), 3)
            last["low"] = round(min(_fs_float(last.get("low"), price), price), 3)
            candles[-1] = last
    return candles, {
        "timeframe": str(timeframe).upper(), "cacheHit": cache_hit,
        "cacheAgeMs": round(max(0.0, age) * 1000.0, 2) if cached else None,
        "fetchLatencyMs": fetch_ms if not cache_hit else float(cached.get("fetchLatencyMs", 0.0) or 0.0),
    }


def _canonical_predictor_tick(tick: dict[str, Any]) -> dict[str, Any] | None:
    if not isinstance(tick, dict):
        return None
    msc = int(_fs_float(tick.get("time_msc") or tick.get("timeMsc") or tick.get("tickTimeMsc"), 0.0))
    epoch = int(_fs_float(tick.get("time"), 0.0))
    if msc <= 0 and epoch > 0:
        msc = epoch * 1000
    if msc <= 0:
        return None
    bid = _fs_float(tick.get("bid"), 0.0)
    ask = _fs_float(tick.get("ask"), 0.0)
    last = _fs_float(tick.get("last"), 0.0)
    if bid <= 0 and ask <= 0 and last <= 0:
        return None
    return {"time": epoch or int(msc / 1000), "time_msc": msc, "timeMsc": msc,
            "bid": bid, "ask": ask, "last": last, "volume": _fs_float(tick.get("volume"), 0.0),
            "flags": int(_fs_float(tick.get("flags"), 0.0))}


def _predictor_tick_window(symbol: str, window_seconds: float, now: float, market: dict[str, Any]) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    """Fetch once, retain a canonical rolling buffer, and reuse it for both predictors."""
    # V15.2.7: fetch only the unseen tail after the initial warm-up. Re-reading the
    # entire 12-second range four times per second saturated the serialized MT5 IPC lane
    # and made a nominal 250 ms predictor behave like a multi-second scanner.
    with PREDICTOR_TICK_LOCK:
        buffered = list(PREDICTOR_TICK_BUFFERS.get(symbol, []))
        last_msc = int(PREDICTOR_TICK_LAST_FETCH_MSC.get(symbol, 0) or 0)
        if not last_msc and buffered:
            last_msc = int(buffered[-1].get("time_msc") or 0)
    fetch_start = (last_msc / 1000.0 - 0.20) if last_msc > 0 else (now - max(window_seconds, 2.0) - 1.0)
    auto_cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    backfill_interval = max(0.50, min(float(auto_cfg.get("earlyIntentTickBackfillSeconds", 0.75) or 0.75), 3.0))
    last_backfill = float(PREDICTOR_TICK_LAST_BACKFILL_AT.get(symbol, 0.0) or 0.0)
    history_backfill = not buffered or now - last_backfill >= backfill_interval
    fetch_latency_ms = 0.0
    fetched: list[dict[str, Any]] = []
    if history_backfill:
        fetch_started = time.perf_counter()
        fetched = mt5_bridge.copy_ticks_range(symbol, fetch_start, now + 0.20) if mt5_bridge.status().get("connected") else []
        fetch_latency_ms = round((time.perf_counter() - fetch_started) * 1000.0, 2)
        PREDICTOR_TICK_LAST_BACKFILL_AT[symbol] = now
    current = _canonical_predictor_tick({
        "time": market.get("tickTime"), "tickTimeMsc": market.get("tickTimeMsc"),
        "bid": market.get("bid"), "ask": market.get("ask"), "last": market.get("price"),
    })
    with PREDICTOR_TICK_LOCK:
        merged = list(PREDICTOR_TICK_BUFFERS.get(symbol, []))
        merged.extend(fetched)
        if current:
            merged.append(current)
        canonical = [row for row in (_canonical_predictor_tick(t) for t in merged) if row]
        dedup: dict[tuple[int, float, float, float], dict[str, Any]] = {}
        for row in canonical:
            dedup[(int(row["time_msc"]), float(row.get("bid") or 0), float(row.get("ask") or 0), float(row.get("last") or 0))] = row
        ordered = sorted(dedup.values(), key=lambda row: int(row["time_msc"]))
        retention_floor = int((now - 90.0) * 1000)
        ordered = [row for row in ordered if int(row["time_msc"]) >= retention_floor]
        PREDICTOR_TICK_BUFFERS[symbol] = ordered
        if ordered:
            PREDICTOR_TICK_LAST_FETCH_MSC[symbol] = int(ordered[-1]["time_msc"])
        cutoff = int((now - max(window_seconds, 2.0)) * 1000)
        active = [row for row in ordered if int(row["time_msc"]) >= cutoff]
    latest_msc = int(active[-1]["time_msc"]) if active else 0
    age_ms = max(0, int(now * 1000) - latest_msc) if latest_msc else None
    return active, {
        "tickCount": len(active), "latestTickAgeMs": age_ms,
        "tickSource": "mt5_incremental+rolling_buffer",
        "tickFetchLatencyMs": fetch_latency_ms,
        "tickFetchRangeSeconds": round(max(0.0, now + 0.20 - fetch_start), 3),
        "historyBackfill": bool(history_backfill),
        "historyBackfillIntervalSeconds": round(backfill_interval, 2),
    }


def _publish_predictor_state(key: str, result: dict[str, Any] | None, now: float, meta: dict[str, Any] | None = None,
                             runtime_status: str | None = None, reason: str | None = None) -> dict[str, Any]:
    state = deepcopy(result or {})
    stage = str(state.get("stage") or runtime_status or "WATCH").upper()
    status = str(runtime_status or stage).upper()
    if status == "NONE":
        status = "WATCH"
    state.update(deepcopy(meta or {}))
    state["stage"] = stage
    state["runtimeStatus"] = status
    state["updatedAt"] = now
    if reason:
        state["reason"] = reason
    FAST_SNIPER_STATE[key] = state
    return state


def _resolve_momentum_fallback(*, candle_side: str, move_atr: float, candle_time: int, now: float) -> dict[str, Any]:
    """Lock fallback alerts to the active predictor leg and suppress unconfirmed flips."""
    candidates = []
    for key in ("earlyIntent", "earlyImpulse"):
        state = FAST_SNIPER_STATE.get(key) if isinstance(FAST_SNIPER_STATE.get(key), dict) else {}
        age = now - float(state.get("updatedAt", 0.0) or 0.0)
        side = str(state.get("side") or "").upper()
        if age <= 12.0 and side in {"BUY", "SELL"}:
            candidates.append((float(state.get("probability", 0.0) or 0.0), str(state.get("stage") or "WATCH").upper(), side))
    candidates.sort(reverse=True)
    predictor_probability, predictor_stage, predictor_side = candidates[0] if candidates else (0.0, "WATCH", "")
    preferred_side = predictor_side or candle_side
    previous_side = str(MOMENTUM_FALLBACK_STATE.get("side") or "").upper()
    same_candle = int(MOMENTUM_FALLBACK_STATE.get("candleTime", 0) or 0) == int(candle_time or 0)
    confirmed_reversal = predictor_stage == "CONFIRMED" and predictor_side == candle_side and predictor_probability >= 0.80
    if same_candle and previous_side in {"BUY", "SELL"} and preferred_side != previous_side and not confirmed_reversal:
        return {"allowed": False, "side": previous_side, "quality": round(max(0.0, predictor_probability * 100.0), 1),
                "reason": "opposing forming-candle flip suppressed until predictor confirmation"}
    if not same_candle or confirmed_reversal or not previous_side:
        MOMENTUM_FALLBACK_STATE.update({"side": preferred_side, "candleTime": int(candle_time or 0), "updatedAt": now})
    quality = predictor_probability * 100.0 if predictor_probability > 0 else min(95.0, 55.0 + max(0.0, move_atr) * 28.0)
    return {"allowed": True, "side": str(MOMENTUM_FALLBACK_STATE.get("side") or preferred_side),
            "quality": round(quality, 1), "predictorStage": predictor_stage}


def _execution_readiness_snapshot() -> dict[str, Any]:
    execution = SETTINGS_STATE.get("execution", {}) if isinstance(SETTINGS_STATE.get("execution"), dict) else {}
    mt5_state = mt5_bridge.status()
    blockers: list[str] = []
    if kill_switch.status().get("active"):
        blockers.append("Emergency kill switch is active")
    if not mt5_state.get("connected"):
        blockers.append("MT5 is disconnected")
    if not execution.get("liveTradingEnabled") or execution.get("dryRun", True):
        blockers.append("Live Trading is OFF or Dry Run is ON")
    if not execution.get("autoTradingEnabled"):
        blockers.append("Auto Trading switch is OFF")
    return {
        "ready": not blockers, "blockers": blockers,
        "mode": _execution_mode(),
        "liveTradingEnabled": bool(execution.get("liveTradingEnabled")),
        "autoTradingEnabled": bool(execution.get("autoTradingEnabled")),
        "dryRun": bool(execution.get("dryRun", True)),
        "mt5Connected": bool(mt5_state.get("connected")),
    }


def _priority_candidate_key(decision: dict[str, Any]) -> str:
    features = decision.get("features") if isinstance(decision.get("features"), dict) else {}
    plan = decision.get("tradePlan") if isinstance(decision.get("tradePlan"), dict) else {}
    source = str(decision.get("source") or ("early_impulse" if features.get("earlyImpulse") else "early_intent"))
    return f"{source}:{str(decision.get('side') or '').upper()}:{str(features.get('progressiveStage') or '')}:{round(_fs_float(plan.get('entry'), 0.0), 2)}"


def _patch_market_with_tick(market: dict[str, Any], tick: dict[str, Any] | None) -> dict[str, Any]:
    """Patch a cached market snapshot with the freshest executable MT5 quote."""
    out = deepcopy(market or {})
    canonical = _canonical_predictor_tick(tick or {})
    if not canonical:
        return out
    bid = _fs_float(canonical.get("bid"), 0.0)
    ask = _fs_float(canonical.get("ask"), 0.0)
    last = _fs_float(canonical.get("last"), 0.0)
    side = str(out.get("side") or "BUY").upper()
    executable = ask if side == "BUY" and ask > 0 else bid if side == "SELL" and bid > 0 else ask or bid or last
    out.update({
        "bid": bid or out.get("bid"),
        "ask": ask or out.get("ask"),
        "price": executable or out.get("price"),
        "last": last or executable or out.get("last"),
        "spread": max(0.0, ask - bid) if ask > 0 and bid > 0 else _fs_float(out.get("spread"), 0.0),
        "tickTime": int(canonical.get("time") or 0),
        "tickTimeMsc": int(canonical.get("time_msc") or 0),
        "liveTickSource": "mt5_symbol_info_tick",
    })
    return out


def _priority_intent_tick() -> dict[str, Any]:
    """High-priority anticipatory scan and immediate execution dispatch.

    This lane is independent from Telegram chart rendering, breakout maintenance
    and missed-move autopsy. Every normal execution, risk and broker gate remains
    authoritative because the candidate is dispatched through _auto_trade_tick.
    """
    started = time.perf_counter()
    now = time.time()
    PRIORITY_INTENT_STATE["lastScanAt"] = now
    PRIORITY_INTENT_STATE["buildId"] = BUILD_ID
    mt5_status = mt5_bridge.status()
    if not mt5_status.get("connected"):
        result = {"ok": False, "blocked": True, "message": "MT5 is disconnected.", "runtimeStatus": "OFFLINE"}
        PRIORITY_INTENT_STATE.update({"runtimeStatus": "OFFLINE", "lastBlocker": result["message"], "lastMt5ConnectedAt": 0.0})
        return result
    PRIORITY_INTENT_STATE.update({
        "lastMt5ConnectedAt": now,
        "lastMt5Symbol": str(mt5_status.get("symbol") or (SETTINGS_STATE.get("trading") or {}).get("symbol") or "XAUUSD"),
    })
    if not _market_state().get("open", False):
        result = {"ok": False, "blocked": True, "message": "Market is closed.", "runtimeStatus": "MARKET_CLOSED"}
        PRIORITY_INTENT_STATE.update({"runtimeStatus": "MARKET_CLOSED", "lastBlocker": result["message"]})
        return result
    market = _live_market()
    symbol = str(market.get("symbol") or (SETTINGS_STATE.get("trading") or {}).get("symbol") or "XAUUSD")
    market = _patch_market_with_tick(market, mt5_bridge.latest_tick(symbol))
    PRIORITY_INTENT_STATE["scanSequence"] = int(PRIORITY_INTENT_STATE.get("scanSequence", 0) or 0) + 1
    decision = _fast_sniper_decision(market)
    features = decision.get("features") if isinstance(decision.get("features"), dict) else {}
    anticipatory = bool(features.get("anticipatoryEntry")) and str(decision.get("action") or "").upper() == "TAKE_TRADE"
    if not anticipatory:
        PRIORITY_INTENT_STATE.update({
            "runtimeStatus": str((FAST_SNIPER_STATE.get("earlyIntent") or {}).get("runtimeStatus") or "WATCH"),
            "lastDecision": {"action": decision.get("action"), "reason": str(decision.get("reason") or "")[:300]},
            "scanLatencyMs": round((time.perf_counter() - started) * 1000.0, 2),
        })
        return {"ok": True, "candidate": False, "decision": decision}

    key = _priority_candidate_key(decision)
    previous = PRIORITY_INTENT_STATE.get("lastCandidate") if isinstance(PRIORITY_INTENT_STATE.get("lastCandidate"), dict) else {}
    first_seen = float(previous.get("firstSeenAt") or now) if previous.get("key") == key else now
    predictor = features.get("intentPrediction") or features.get("impulsePrediction") or {}
    candidate = {
        "key": key, "firstSeenAt": first_seen, "lastSeenAt": now,
        "source": decision.get("source") or ("early_impulse" if features.get("earlyImpulse") else "early_intent"),
        "side": decision.get("side"), "stage": features.get("progressiveStage"),
        "confidence": decision.get("confidence"), "moveAtr": predictor.get("displacement_atr"),
        "decisionLatencyMs": decision.get("latencyMs"), "sourceTickAgeMs": features.get("sourceTickAgeMs"),
    }
    PRIORITY_INTENT_STATE["lastCandidate"] = candidate
    readiness = _execution_readiness_snapshot()
    if not readiness["ready"]:
        blocker = "; ".join(readiness["blockers"])
        PRIORITY_INTENT_STATE.update({
            "runtimeStatus": "QUALIFIED_BLOCKED", "lastBlocker": blocker,
            "executionReadiness": readiness,
            "scanLatencyMs": round((time.perf_counter() - started) * 1000.0, 2),
        })
        return {"ok": False, "blocked": True, "candidate": True, "message": blocker, "decision": decision, "readiness": readiness}

    retry_seconds = max(0.5, float((SETTINGS_STATE.get("automation") or {}).get("earlyIntentCandidateRetrySeconds", 2.0) or 2.0))
    last_attempt = float(PRIORITY_INTENT_STATE.get("lastAttemptAt", 0.0) or 0.0)
    if PRIORITY_INTENT_STATE.get("lastAttemptKey") == key and now - last_attempt < retry_seconds:
        return {"ok": True, "candidate": True, "throttled": True, "decision": decision}

    with PRIORITY_INTENT_LOCK:
        PRIORITY_INTENT_STATE["lastAttemptAt"] = now
        PRIORITY_INTENT_STATE["lastAttemptKey"] = key
        dispatch_started = time.perf_counter()
        execution_result = _auto_trade_tick(reason="priority_intent_loop", precomputed_decision=decision, precomputed_market=market)
        dispatch_ms = round((time.perf_counter() - dispatch_started) * 1000.0, 2)
    execution_record = {
        "at": time.time(), "candidateKey": key, "dispatchLatencyMs": dispatch_ms,
        "endToEndSinceFirstSeenMs": round((time.time() - first_seen) * 1000.0, 2),
        "ok": bool(execution_result.get("ok")), "blocked": bool(execution_result.get("blocked")),
        "message": str(execution_result.get("message") or "")[:500],
    }
    PRIORITY_INTENT_STATE.update({
        "runtimeStatus": "ORDER_SENT" if execution_result.get("ok") else "QUALIFIED_BLOCKED",
        "lastExecution": execution_record,
        "lastBlocker": "" if execution_result.get("ok") else execution_record["message"],
        "scanLatencyMs": round((time.perf_counter() - started) * 1000.0, 2),
    })
    return {"ok": bool(execution_result.get("ok")), "candidate": True, "decision": decision, "execution": execution_result, "latency": execution_record}


def _apply_priority_cycle_result(result: Any, elapsed_ms: float) -> bool:
    """Record actual worker health without confusing an execution veto with a dead lane."""
    now = time.time()
    payload = result if isinstance(result, dict) else {}
    transient_overlap = bool(payload.get("skipped")) and not bool(payload.get("timeout"))
    if transient_overlap:
        message = str(payload.get("message") or "Previous Priority Intent cycle is completing.")[:300]
        PRIORITY_INTENT_STATE.update({
            "runtimeStatus": "BUSY", "lastBlocker": message, "inFlight": True,
            "lastCycleAt": now, "lastCycleLatencyMs": round(float(elapsed_ms), 2),
        })
        RUNTIME_HEALTH.beat("priority_intent_loop", detail="BUSY — previous cycle completing")
        return True
    infrastructure_failure = bool(payload.get("wedged") or payload.get("timeout"))
    if infrastructure_failure:
        message = str(payload.get("message") or "Priority Intent worker did not complete.")[:300]
        failures = int(PRIORITY_INTENT_STATE.get("consecutiveFailures", 0) or 0) + 1
        PRIORITY_INTENT_STATE.update({
            "runtimeStatus": "RECOVERING", "lastBlocker": message, "inFlight": False,
            "consecutiveFailures": failures, "lastCycleAt": now,
            "lastCycleLatencyMs": round(float(elapsed_ms), 2),
        })
        RUNTIME_HEALTH.fail("priority_intent_loop", RuntimeError(message))
        return False
    PRIORITY_INTENT_STATE.update({
        "lastCompletedAt": now, "lastCycleAt": now, "inFlight": False,
        "lastCycleLatencyMs": round(float(elapsed_ms), 2),
        "consecutiveFailures": 0,
    })
    RUNTIME_HEALTH.beat("priority_intent_loop", detail=str(PRIORITY_INTENT_STATE.get("runtimeStatus") or "WATCH"))
    return True


async def _priority_intent_loop() -> None:
    while True:
        cycle_started = time.perf_counter()
        try:
            PRIORITY_INTENT_STATE["inFlight"] = True
            result = await _run_background_job("priority_intent_tick", _priority_intent_tick, timeout=2.0)
            _apply_priority_cycle_result(result, (time.perf_counter() - cycle_started) * 1000.0)
        except asyncio.CancelledError:
            raise
        except Exception as exc:
            PRIORITY_INTENT_STATE.update({
                "runtimeStatus": "RECOVERING", "lastBlocker": str(exc)[:300], "inFlight": False,
                "consecutiveFailures": int(PRIORITY_INTENT_STATE.get("consecutiveFailures", 0) or 0) + 1,
            })
            RUNTIME_HEALTH.fail("priority_intent_loop", exc)
        cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
        interval = max(0.15, min(float(cfg.get("earlyIntentPriorityLoopSeconds", 0.25) or 0.25), 2.0))
        elapsed = time.perf_counter() - cycle_started
        await asyncio.sleep(max(0.01, interval - elapsed))


# ── V12.71 ARMED RETEST STATE MACHINE ────────────────────────────────────────────
# Before: "armed retest" was only a Telegram label. Nothing stored the armed setup and
# nothing watched for the pullback, so in a waterfall the lane re-armed on every scan
# (extension stays > max the whole way down) and the bot missed the ENTIRE move.
# Now: arming stores the impulse; every fast-lane scan first checks whether a closed
# trigger-TF candle has (a) pulled back into the retrace zone of the CURRENT leg and
# (b) rejected back in trend direction. That converts into a real continuation entry
# which still passes every governor (risk, spread-spike, HTF matrix, AI auditor).
FAST_SNIPER_RETEST_STATE: dict[str, Any] = {}

# ── V12.83 Expired-Arm Opportunity-Cost Tracker ───────────────────────────────────────────
# Records every armed retest that expired UNTRIGGERED, then (>=90 min later) measures what
# price actually did next. Pure measurement — it never changes trading behaviour. It exists to
# turn "the bot misses fast moves" into a countable number: how many expired arms would have
# paid if a shallow-retest mode had entered at expiry, vs how many would have lost.
EXPIRED_ARMS_FILE = DATA_DIR / "expired_arms.jsonl"
_EXPIRED_ARM_EVAL_DELAY_S = 90 * 60      # judge the counterfactual over the next ~90 minutes
_EXPIRED_ARM_SWEEP_STATE = {"lastRun": 0.0}


def _log_expired_arm(st: dict[str, Any], market: dict[str, Any], atr5: float, now: float) -> None:
    rec = {
        "ts": now, "tsIso": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(now)),
        "side": str(st.get("side") or ""), "symbol": str(market.get("symbol") or "XAUUSD"),
        "legStart": _fs_float(st.get("legStart")), "extreme": _fs_float(st.get("extreme")),
        "priceAtExpiry": _fs_float(market.get("price")), "atr": float(atr5 or 0.0),
        "reason": str(st.get("reason") or ""), "status": "pending",
        "evaluateAfter": now + _EXPIRED_ARM_EVAL_DELAY_S,
    }
    with open(EXPIRED_ARMS_FILE, "a", encoding="utf-8") as f:
        f.write(json.dumps(rec) + "\n")


def _load_expired_arms() -> list[dict[str, Any]]:
    if not EXPIRED_ARMS_FILE.exists():
        return []
    out = []
    for line in EXPIRED_ARMS_FILE.read_text(encoding="utf-8").splitlines():
        try:
            out.append(json.loads(line))
        except Exception:
            continue
    return out


def _save_expired_arms(rows: list[dict[str, Any]]) -> None:
    tmp = EXPIRED_ARMS_FILE.with_suffix(".tmp")
    tmp.write_text("\n".join(json.dumps(r) for r in rows) + ("\n" if rows else ""), encoding="utf-8")
    tmp.replace(EXPIRED_ARMS_FILE)


def _sweep_expired_arm_outcomes() -> None:
    """Evaluate pending expired arms whose judgment window has passed. Cheap: throttled to once
    per 5 minutes, exits immediately when nothing is pending, and reads candles we already pull.
    Counterfactual: enter at priceAtExpiry in the armed side; stop 1.1*ATR against, target
    1.1*ATR with (a 1R scalp — deliberately conservative). Outcome = which level the NEXT
    ~90 minutes of M5 candles touch first. Marked as an ESTIMATE everywhere it is shown."""
    now = time.time()
    if now - _EXPIRED_ARM_SWEEP_STATE["lastRun"] < 300:
        return
    _EXPIRED_ARM_SWEEP_STATE["lastRun"] = now
    rows = _load_expired_arms()
    pending = [r for r in rows if r.get("status") == "pending" and now >= _fs_float(r.get("evaluateAfter"))]
    if not pending:
        return
    try:
        candles = mt5_bridge.copy_rates(str(SETTINGS_STATE.get("trading", {}).get("symbol", "XAUUSD")), "M5", 300) or []
    except Exception:
        candles = []
    if not candles:
        return
    changed = False
    for r in pending:
        t0 = _fs_float(r.get("ts"))
        after = [c for c in candles if _fs_float(c.get("time") or c.get("ts") or 0) > t0]
        if len(after) < 6:
            # candle history no longer reaches back far enough (e.g. bot was off) — mark unknowable
            if now - t0 > 12 * 3600:
                r["status"] = "unevaluable"; changed = True
            continue
        window = after[: int(_EXPIRED_ARM_EVAL_DELAY_S / 300)]
        entry = _fs_float(r.get("priceAtExpiry")); atr = max(0.5, _fs_float(r.get("atr")))
        risk = 1.1 * atr
        side = r.get("side")
        tp = entry - risk if side == "SELL" else entry + risk
        sl = entry + risk if side == "SELL" else entry - risk
        outcome = "open"; max_fav = 0.0; max_adv = 0.0
        for c in window:
            hi = _fs_float(c.get("high")); lo = _fs_float(c.get("low"))
            fav = (entry - lo) if side == "SELL" else (hi - entry)
            adv = (hi - entry) if side == "SELL" else (entry - lo)
            max_fav = max(max_fav, fav); max_adv = max(max_adv, adv)
            hit_tp = lo <= tp if side == "SELL" else hi >= tp
            hit_sl = hi >= sl if side == "SELL" else lo <= sl
            if hit_tp and hit_sl:
                outcome = "ambiguous"; break   # both in one candle — do not claim a win
            if hit_tp:
                outcome = "would_have_won"; break
            if hit_sl:
                outcome = "would_have_lost"; break
        if outcome == "open":
            outcome = "would_have_won" if max_fav >= risk * 0.8 and max_adv < risk else "faded"
        r["status"] = "evaluated"; r["outcome"] = outcome
        r["maxFavorableAtr"] = round(max_fav / atr, 2); r["maxAdverseAtr"] = round(max_adv / atr, 2)
        changed = True
    if changed:
        _save_expired_arms(rows)


def _expired_arm_summary(days: int = 30) -> dict[str, Any]:
    cutoff = time.time() - days * 86400
    rows = [r for r in _load_expired_arms() if _fs_float(r.get("ts")) >= cutoff]
    ev = [r for r in rows if r.get("status") == "evaluated"]
    won = [r for r in ev if r.get("outcome") == "would_have_won"]
    lost = [r for r in ev if r.get("outcome") == "would_have_lost"]
    return {
        "totalExpired": len(rows), "evaluated": len(ev), "pending": sum(1 for r in rows if r.get("status") == "pending"),
        "wouldHaveWon": len(won), "wouldHaveLost": len(lost),
        "faded": sum(1 for r in ev if r.get("outcome") == "faded"),
        "ambiguous": sum(1 for r in ev if r.get("outcome") == "ambiguous"),
        "estNetR": round(len(won) * 1.0 - len(lost) * 1.0, 1),
        "note": ("ESTIMATE ONLY — counterfactual 1R scalp entered at arm expiry. It measures what the "
                 "no-chase rule forfeited; it does not include spread/slippage and is not a promise a "
                 "shallow-retest mode would capture it."),
        "recent": sorted(rows, key=lambda r: -_fs_float(r.get("ts")))[:10],
    }


@app.get("/api/ai/expired-arms")
def api_expired_arms(days: int = 30):
    """V12.83 — opportunity cost of the no-chase rule, measured. See _sweep_expired_arm_outcomes."""
    _sweep_expired_arm_outcomes()
    return {"ok": True, **_expired_arm_summary(days=days)}



MT5_WATCHDOG: dict[str, Any] = {"downSince": None, "lastKick": 0.0, "alerted": False}  # V13.9 reconnect watchdog
BREAKOUT_BRACKET_STATE: dict[str, Any] = {}

def _missed_move_autopsy() -> None:
    """Record one executable, candle-identified missed event for tick replay.

    The event is keyed by symbol/side/timeframe/closed-pump-candle time. Entry is
    the first executable live quote available when the blocked decision is known:
    BUY uses ask; SELL uses bid. No candle-open hindsight is recorded.
    """
    try:
        cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
        if not mt5_bridge.status().get("connected"):
            return
        market = _live_market()
        fast = _fast_sniper_decision(market)
        disp = float(fast.get("displacementAtr") or 0.0)
        bar = float(cfg.get("momentumCounterHtfMinAtr", 1.25) or 1.25)
        floor = min(bar, float(cfg.get("strongMomentumDisplacementAtr", 1.05) or 1.05))
        if disp < floor or fast.get("action") == "TAKE_TRADE" or bool(BREAKOUT_BRACKET_STATE.get("active")):
            return

        try:
            has_pos = bool(mt5_bridge.open_positions(bot_only=True))
        except Exception:
            has_pos = False
        symbol = str(market.get("symbol") or (SETTINGS_STATE.get("trading") or {}).get("symbol") or mt5_bridge.symbol or "XAUUSD")
        side = str(fast.get("side") or fast.get("computedSide") or "?").upper()
        candle_epoch = 0
        rows = mt5_bridge.copy_rates(symbol, "M5", 3)
        if rows:
            pump = rows[-2] if len(rows) >= 2 else rows[-1]
            candle_epoch = int(_fs_float(pump.get("time") or pump.get("epoch"), 0.0))
            po, pc = _fs_float(pump.get("open"), 0.0), _fs_float(pump.get("close"), 0.0)
            if side not in ("BUY", "SELL") and po and pc:
                side = "BUY" if pc >= po else "SELL"
        if side not in ("BUY", "SELL") or candle_epoch <= 0:
            return

        event_id = event_identity(symbol, side, "M5", candle_epoch)
        if any(str(row.get("eventId") or "") == event_id for row in DECISION_JOURNAL[:1000]):
            return
        seen = list(RECAP_STATE.get("missedEventIds") or [])
        if event_id in seen:
            return
        RECAP_STATE["missedEventIds"] = (seen + [event_id])[-500:]

        bid = _fs_float(market.get("bid"), 0.0)
        ask = _fs_float(market.get("ask"), 0.0)
        entry_price = ask if side == "BUY" else bid
        entry_time_msc = int(_fs_float(market.get("tickTimeMsc"), 0.0) or time.time() * 1000)
        if entry_price <= 0 or entry_time_msc <= 0:
            return

        reason = str(fast.get("reason") or "")
        if fast.get("armedRetest"):
            reason = "Armed retest (waited for pullback, never filled): " + reason
        elif has_pos:
            reason = "Position already open elsewhere — could not take this spike: " + reason
        _journal_record(
            "missed_pump", eventId=event_id, side=side, symbol=symbol, timeframe="M5",
            pumpCandleEpoch=candle_epoch, displacementAtr=round(disp, 2),
            entryPrice=round(entry_price, 5), price=round(entry_price, 5),
            entryBid=round(bid, 5), entryAsk=round(ask, 5), entryTimeMsc=entry_time_msc,
            replaySource="first_executable_quote", armedRetest=bool(fast.get("armedRetest")),
            hadOpenPosition=has_pos, sideInferred=str(fast.get("side") or "").upper() not in ("BUY", "SELL"),
            blockedBy=reason[:300],
        )
    except Exception as exc:
        _report_suppressed_exception("missed_move_autopsy_v1507", exc)


def _breakout_engine_tick() -> dict[str, Any]:
    """V13.13 — THE FIX for 'we built brackets but they never fire'. Arming AND management used to
    live INSIDE _fast_sniper_decision, which returns early on dozens of gates (regime stand-down,
    spread, news, exhaustion, veto...). So on exactly the compressed tape where a squeeze forms,
    the bracket code was never reached. This runs from the MAIN loop every tick, independent of
    whatever the sniper decides, so pre-positioning actually happens and OCO/expiry always manages.

    Flow: (1) always manage any live bracket first (OCO + expiry). (2) if enabled and flat and no
    bracket active, fetch candles, detect squeeze, and if coiled -> arm both-sided brackets so the
    next real spike FILLS at the level instead of being chased.
    """
    out: dict[str, Any] = {"managed": False, "armed": False}
    cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    try:
        _manage_breakout_bracket()
        out["managed"] = True
    except Exception as exc:
        out["manageError"] = str(exc)
    if not bool(cfg.get("breakoutStopEnabled", False)):
        return out
    if not bool(cfg.get("squeezeAutoArm", True)):
        return out  # squeeze-arming can be toggled off independently of passive base-arming
    try:
        if not mt5_bridge.status().get("connected"):
            return out
        if mt5_bridge.open_positions(bot_only=True):
            return out  # already in a trade
        if BREAKOUT_BRACKET_STATE.get("active"):
            return out  # bracket already live
        market = _live_market()
        symbol = str((SETTINGS_STATE.get("trading") or {}).get("symbol") or "XAUUSD")
        candles = mt5_bridge.copy_rates(symbol, "M5", 120) or []
        if len(candles) < 60:
            return out
        atr5 = _fs_atr(candles[:-1])
        if atr5 <= 0:
            return out
        # regime policy: no brackets on a dead QUIET tape (targets can't clear cost)
        if bool(cfg.get("regimeSwitchingEnabled", True)):
            try:
                reg = classify_regime(candles, news_blackout=bool(market.get("newsBlackout")))
                pol = (cfg.get("regimePolicy") or {}).get(reg.get("regime"), DEFAULT_REGIME_POLICY.get(reg.get("regime"), {}))
                if not pol.get("brackets", True):
                    out["regimeBlock"] = reg.get("regime")
                    return out
            except Exception as _suppressed_exc:
                _report_suppressed_exception("suppressed_exception_line_6116", _suppressed_exc)
        sq = _detect_squeeze(candles, atr5, cfg)
        out["squeeze"] = sq
        if not sq.get("squeeze"):
            return out
        # coiled spring detected -> pre-position. matrix decides which side(s) if HTF align is on.
        matrix = None
        try:
            matrix = _fast_sniper_mtf_matrix(symbol, "BUY", candles) if "_fast_sniper_mtf_matrix" in globals() else None
        except Exception:
            matrix = None
        armed = _maybe_arm_breakout_bracket(candles, market, atr5, matrix)
        if armed and armed.get("ok"):
            out["armed"] = True
            out["bracket"] = armed
            _journal_record("squeeze_arm", symbol=symbol, compression=sq.get("compression"),
                            rangeAtr=sq.get("rangeAtr"), legs=armed.get("legs"))
            try:
                legs = armed.get("legs") or []
                lines = " / ".join(f"{l['side']} stop {l['trigger']}" for l in legs if l.get("ok"))
                _telegram_send_text(f"🎯 *Squeeze detected — brackets pre-positioned*\nCoiled {sq.get('compression')}x baseline. Orders resting: {lines}\nNext real break FILLS at the level instead of chasing.")
            except Exception as _suppressed_exc:
                _report_suppressed_exception("suppressed_exception_line_6138", _suppressed_exc)
    except Exception as exc:
        out["armError"] = str(exc)
    return out


def _detect_squeeze(candles: list[dict[str, Any]], atr5: float, cfg: dict[str, Any]) -> dict[str, Any]:
    """V13.13 — the genuine PRE-spike tell. Spikes don't come from nowhere; they come from
    volatility COMPRESSION. This measures whether the recent range has contracted to a small
    fraction of its own baseline — a coiled spring. It does NOT predict direction (that's why we
    bracket both sides); it predicts that a big move is more likely IMMINENT than usual.

    Compression ratio = (recent N-bar range / ATR) vs the same measure over a longer baseline.
    A ratio well below 1.0 means the tape has tightened relative to itself = squeeze.
    """
    closed = candles[:-1] if bool(cfg.get("fastSniperRequireClosedM5", True)) and len(candles) > 1 else candles
    n = int(cfg.get("squeezeLookback", 6) or 6)
    base_n = int(cfg.get("squeezeBaselineLookback", 48) or 48)
    if len(closed) < base_n + 2:
        return {"squeeze": False, "reason": "not enough candles"}
    atr = max(0.5, float(atr5 or 0.0))
    recent = closed[-n:]
    rng_recent = max(_fs_float(c.get("high")) for c in recent) - min(_fs_float(c.get("low")) for c in recent)
    base = closed[-base_n:]
    # median single-bar true range over the baseline, as the "normal" bar size
    bar_ranges = sorted(_fs_float(c.get("high")) - _fs_float(c.get("low")) for c in base)
    med_bar = bar_ranges[len(bar_ranges) // 2] if bar_ranges else atr
    # recent per-bar average vs baseline median: <1 means bars are shrinking = coiling
    avg_recent_bar = rng_recent / max(1, n)
    compression = avg_recent_bar / max(med_bar, 1e-9)
    rng_atr = rng_recent / atr
    thresh = float(cfg.get("squeezeCompressionRatio", 0.65) or 0.65)
    max_rng_atr = float(cfg.get("squeezeMaxRangeAtr", 1.10) or 1.10)
    is_squeeze = compression <= thresh and rng_atr <= max_rng_atr
    return {"squeeze": bool(is_squeeze), "compression": round(compression, 3), "rangeAtr": round(rng_atr, 2),
            "reason": (f"coiled: bars {compression:.2f}x baseline, {rng_atr:.2f} ATR range"
                       if is_squeeze else f"no squeeze: compression {compression:.2f} (need <= {thresh})")}


def _breakout_range(candles: list[dict[str, Any]], n: int) -> tuple[float, float]:
    window = [c for c in candles[-(n + 1):-1]] if len(candles) > n else candles[:-1]
    if not window:
        return 0.0, 0.0
    hi = max(_fs_float(c.get("high")) for c in window)
    lo = min(_fs_float(c.get("low")) for c in window)
    return hi, lo


def _maybe_arm_breakout_bracket(candles: list[dict[str, Any]], market: dict[str, Any], atr5: float, matrix: dict[str, Any] | None) -> dict[str, Any] | None:
    """V12.93 — when price is in a TIGHT consolidation, pre-place breakout-STOP orders at both
    edges (or the HTF-aligned edge only), so a fast break fills at the level instead of chasing.
    Pure pending-order placement; nothing is at market until price actually breaks."""
    cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    if not bool(cfg.get("breakoutStopEnabled", False)):
        return None
    # demo gate
    if bool(cfg.get("breakoutStopDemoOnly", True)):
        acct = _live_account()
        if acct.get("connected") and not (acct.get("demo") or acct.get("isDemo") or str(acct.get("accountType","")).lower()=="demo"):
            return {"ok": False, "skipped": "breakout demo-only: live account, not arming"}
    if BREAKOUT_BRACKET_STATE.get("active"):
        return None  # one bracket at a time; managed elsewhere
    n = int(cfg.get("breakoutMinBaseCandles", 6) or 6)
    closed = candles[:-1] if bool(cfg.get("fastSniperRequireClosedM5", True)) and len(candles) > 1 else candles
    if len(closed) < n + 1:
        return None
    hi, lo = _breakout_range(closed, n)
    if hi <= 0 or lo <= 0:
        return None
    rng = hi - lo
    atr = max(0.5, float(atr5 or 0.0))
    rng_atr = rng / atr
    if not (float(cfg.get("breakoutMinRangeAtr", 0.35)) <= rng_atr <= float(cfg.get("breakoutMaxRangeAtr", 1.20))):
        return None  # not a tight base
    buf = float(cfg.get("breakoutTriggerBufferAtr", 0.08)) * atr
    beyond = float(cfg.get("breakoutStopBeyondOppositeAtr", 0.25)) * atr
    buy_trigger = round(hi + buf, 2); buy_sl = round(lo - beyond, 2)
    sell_trigger = round(lo - buf, 2); sell_sl = round(hi + beyond, 2)
    symbol = str(market.get("symbol") or "XAUUSD")
    # HTF alignment: only arm the side the matrix agrees with (avoids bracketing into the HTF river)
    sides = ["BUY", "SELL"]
    if bool(cfg.get("breakoutRequireHtfAlign", True)) and matrix:
        score = _fs_float(matrix.get("score"))
        if score > 0.15:
            sides = ["BUY"]
        elif score < -0.15:
            sides = ["SELL"]
        else:
            return None  # HTF flat -> a break here is a coin toss, don't bracket
    # size each leg by the existing risk model over its own stop distance
    placed = []
    for side in sides:
        trig = buy_trigger if side == "BUY" else sell_trigger
        sl = buy_sl if side == "BUY" else sell_sl
        try:
            ceil = _lot_risk_ceiling(symbol, trig, sl, risk_pct=float((SETTINGS_STATE.get("trading") or {}).get("riskPerTrade", 0.5) or 0.5))
            lot = float(ceil.get("lot") or 0.01)
        except Exception as exc:
            LOGGER.exception("Breakout pending lot sizing failed side=%s", side)
            RUNTIME_HEALTH.fail("risk_sizing", exc, source="breakout_pending")
            placed.append({"side": side, "trigger": trig, "sl": sl, "ok": False, "message": f"Lot sizing failed closed: {exc}"})
            continue
        res = _execute_mt5_mutation_serialized("PLACE_PENDING", {
            "symbol": symbol, "side": side, "volume": lot, "price": trig, "sl": sl, "tp": None,
            "expirySeconds": int(float(cfg.get("breakoutExpiryMinutes", 25) or 25) * 60),
            "comment": comment_for("Breakout Stop", f"brk_{side.lower()}", mt5_bridge.comment_prefix),
        }, "breakout_pending")
        placed.append({"side": side, "trigger": trig, "sl": sl, "lot": lot, "ok": res.get("ok"), "ticket": res.get("ticket"), "message": res.get("message")})
    BREAKOUT_BRACKET_STATE.clear()
    BREAKOUT_BRACKET_STATE.update({
        "active": True, "armedAt": time.time(), "symbol": symbol,
        "rangeHi": hi, "rangeLo": lo, "rangeAtr": round(rng_atr, 2),
        "legs": placed, "expiresAt": time.time() + float(cfg.get("breakoutExpiryMinutes", 25) or 25) * 60,
        "sides": sides,
    })
    return {"ok": any(p.get("ok") for p in placed), "reason": "breakout_bracket", "legs": placed,
            "rangeHi": hi, "rangeLo": lo, "rangeAtr": round(rng_atr, 2)}


def _manage_breakout_bracket() -> None:
    """OCO + expiry for the breakout bracket: if one side fills, cancel the other; if the window
    passes with neither filled, cancel both. Throttled/cheap; safe to call each scan."""
    st = BREAKOUT_BRACKET_STATE
    if not st.get("active"):
        return
    cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    now = time.time()
    try:
        open_pos = mt5_bridge.open_positions(bot_only=True) or []
        pend = mt5_bridge.pending_orders(bot_only=True) or []
    except Exception:
        return
    # V13.13 BUGFIX: this matched comment substring "BREAKOUT", but comment_for("Breakout Stop")
    # encodes to GODMODE_BS_A — no "BREAKOUT" in it. So OCO NEVER fired: a filled leg left the
    # opposite stop dangling under a live position. Match by the leg tickets we actually placed
    # (authoritative), with the comment code as a fallback.
    _leg_tickets = {leg.get("ticket") for leg in st.get("legs", []) if leg.get("ticket")}
    filled_breakout = [p for p in open_pos
                       if p.get("ticket") in _leg_tickets
                       or "_BS_" in str(p.get("comment") or "").upper()
                       or "BREAKOUT" in str(p.get("comment") or "").upper()]
    pend_tickets = {p.get("ticket") for p in pend}
    # OCO: a leg filled -> cancel any still-pending sibling
    if filled_breakout and bool(cfg.get("breakoutCancelOppositeOnFill", True)):
        for leg in st.get("legs", []):
            if leg.get("ticket") in pend_tickets:
                _execute_mt5_mutation_serialized("CANCEL_PENDING", {"ticket": leg.get("ticket")}, "pending_cancel")
        BREAKOUT_BRACKET_STATE.clear()
        try:
            _telegram_send_text("🚀 *Breakout STOP filled* — bracket triggered, opposite leg cancelled. Fast BE now protecting.")
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_6289", _suppressed_exc)
        return
    # expiry: cancel any unfilled legs
    if now >= float(st.get("expiresAt", 0) or 0):
        for leg in st.get("legs", []):
            if leg.get("ticket") in pend_tickets:
                _execute_mt5_mutation_serialized("CANCEL_PENDING", {"ticket": leg.get("ticket")}, "pending_cancel")
        BREAKOUT_BRACKET_STATE.clear()


def _arm_fast_retest(side: str, trigger_candles: list[dict[str, Any]], atr5: float, reason: str) -> None:
    cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    if not cfg.get("fastSniperRetestTrackerEnabled", True):
        return
    closed = trigger_candles[:-1] if len(trigger_candles) > 1 else trigger_candles
    if len(closed) < 12:
        return
    window = closed[-12:]
    # V12.84: anchor the leg to the LOCAL pre-breakout base, not the furthest extreme in
    # twelve candles. The old anchor often made the Fibonacci zone far too deep, so a valid
    # shallow retest around 4061–4063 never qualified after the impulse.
    impulse = window[-1]
    pre = window[-6:-1] or window[:-1]
    if side == "SELL":
        extreme = min(_fs_float(x.get("low")) for x in window[-3:])
        local_origin = max([_fs_float(impulse.get("open"))] + [_fs_float(x.get("high")) for x in pre[-4:]])
        leg_start = local_origin
    else:
        extreme = max(_fs_float(x.get("high")) for x in window[-3:])
        local_origin = min([_fs_float(impulse.get("open"))] + [_fs_float(x.get("low")) for x in pre[-4:]])
        leg_start = local_origin
    now = time.time()
    st = FAST_SNIPER_RETEST_STATE
    if st.get("side") == side and st.get("active"):
        # already armed same direction — extend the leg (waterfall keeps making new extremes)
        if side == "SELL":
            st["extreme"] = min(_fs_float(st.get("extreme"), extreme), extreme)
        else:
            st["extreme"] = max(_fs_float(st.get("extreme"), extreme), extreme)
        # Keep the original local origin. Re-arming used to move legStart farther away on every
        # scan, continuously pushing the required retrace zone out of reach.
        st["expiresAt"] = now + float(cfg.get("fastSniperRetestExpiryMinutes", 45) or 45) * 60
        st["atr5"] = atr5
        return
    FAST_SNIPER_RETEST_STATE.clear()
    FAST_SNIPER_RETEST_STATE.update({
        "active": True, "side": side, "extreme": extreme, "legStart": leg_start,
        "atr5": atr5, "armedAt": now, "armedReason": str(reason)[:160],
        "armedBarTime": _fs_float(impulse.get("time") or impulse.get("timestamp") or 0),
        "barsObserved": 0,
        "expiresAt": now + float(cfg.get("fastSniperRetestExpiryMinutes", 45) or 45) * 60,
        "triggeredAt": 0.0})
def _check_armed_retest(trigger_candles: list[dict[str, Any]], context_candles: list[dict[str, Any]],
                        market: dict[str, Any], symbol: str, atr5: float, rsi5: float,
                        started: float, now: float) -> dict[str, Any] | None:
    """Return a TAKE_TRADE continuation decision if the armed retest has completed, else None."""
    st = FAST_SNIPER_RETEST_STATE
    cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    if not st.get("active") or not cfg.get("fastSniperRetestTrackerEnabled", True):
        return None
    if now > _fs_float(st.get("expiresAt")):
        st["active"] = False
        # V12.83 — EXPIRED-ARM OPPORTUNITY-COST TRACKER (measurement only, no behaviour change).
        # Every time an armed retest dies untriggered we record it, then a later sweep checks
        # where price actually went. Over ~50 trades this answers, with numbers instead of
        # feelings: "how much did the no-chase retest requirement cost in missed moves?"
        try:
            _log_expired_arm(st, market, atr5, now)
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_6358", _suppressed_exc)
        return None
    side = str(st.get("side") or "")
    closed = trigger_candles[:-1] if len(trigger_candles) > 1 else trigger_candles
    if len(closed) < 3 or side not in {"BUY", "SELL"}:
        return None
    trig = closed[-1]
    o, h, l, c = map(_fs_float, (trig.get("open"), trig.get("high"), trig.get("low"), trig.get("close")))
    extreme = _fs_float(st.get("extreme")); leg_start = _fs_float(st.get("legStart"))
    # Extend the leg with every candle SINCE arming except the trigger candle itself —
    # intermediate waterfall candles keep pushing the extreme (so the retrace zone tracks the
    # CURRENT leg), but the candle being judged as the retest must not extend the leg it is
    # retracing.
    for x in closed[-9:-1]:
        if side == "SELL":
            xl = _fs_float(x.get("low"))
            if xl < extreme:
                extreme = xl
        else:
            xh = _fs_float(x.get("high"))
            if xh > extreme:
                extreme = xh
    st["extreme"] = extreme
    leg = abs(leg_start - extreme)
    if leg < max(0.8 * atr5, 1e-6):
        return None   # leg too small to define a meaningful retrace
    fib_lo = float(cfg.get("fastSniperRetestFibMin", 0.25) or 0.25)
    fib_hi = float(cfg.get("fastSniperRetestFibMax", 0.62) or 0.62)
    body_min = float(cfg.get("fastSniperRetestMinBodyAtr", 0.12) or 0.12) * atr5
    prev = closed[-2] if len(closed) >= 2 else trig
    po, ph, pl, pc = map(_fs_float, (prev.get("open"), prev.get("high"), prev.get("low"), prev.get("close")))
    allow_two = bool(cfg.get("fastSniperRetestAllowTwoCandleConfirm", True))
    if side == "SELL":
        zone_lo = extreme + fib_lo * leg
        zone_hi = extreme + fib_hi * leg
        if c > leg_start:   # structure invalidated — full reclaim of the leg origin
            st["active"] = False
            return None
        touched = h >= zone_lo or (allow_two and ph >= zone_lo)
        one_candle = c < o and (o - c) >= body_min and c <= zone_hi
        two_candle = allow_two and ph >= zone_lo and c < pc and c < o and h < ph and c <= zone_hi
        rejected = one_candle or two_candle
    else:
        zone_lo = extreme - fib_hi * leg
        zone_hi = extreme - fib_lo * leg
        if c < leg_start:
            st["active"] = False
            return None
        touched = l <= zone_hi or (allow_two and pl <= zone_hi)
        one_candle = c > o and (c - o) >= body_min and c >= zone_lo
        two_candle = allow_two and pl <= zone_hi and c > pc and c > o and l > pl and c >= zone_lo
        rejected = one_candle or two_candle
    # V12.85 strict retest truth: a 74.7% pullback must never be described as being inside
    # a 12–58% zone. The previous code only checked that price touched the near edge and
    # closed back inside, so an oversized collapse candle could falsely complete the retest.
    max_overshoot = float(cfg.get("fastSniperRetestMaxOvershoot", 0.08) or 0.08)
    max_retrace = min(0.95, fib_hi + max_overshoot)
    raw_retrace = abs(((h if side == "SELL" else l) - extreme)) / max(leg, 1e-9)
    trigger_body_atr = abs(c - o) / max(atr5, 1e-9)
    max_trigger_body_atr = float(cfg.get("fastSniperRetestMaxTriggerBodyAtr", 1.10) or 1.10)
    st["barsObserved"] = int(st.get("barsObserved", 0) or 0) + 1
    min_bars = int(cfg.get("fastSniperRetestMinBarsAfterArm", 2) or 2)
    counter_pullback = (pc > po) if side == "SELL" else (pc < po)
    if not bool(cfg.get("fastSniperRetestRequireCounterPullback", True)):
        counter_pullback = True
    if raw_retrace > max_retrace or trigger_body_atr > max_trigger_body_atr or st["barsObserved"] < min_bars or not counter_pullback:
        return None
    if not (touched and rejected):
        return None
    # HTF matrix must not be CLEARLY opposed to the continuation. Threshold is deliberately
    # loose (-0.35): the retest trigger itself is already strict, and in a genuine waterfall
    # every timeframe is aligned — this gate exists only to refuse fighting a hard reversal.
    mtf_matrix = _fast_sniper_mtf_matrix(symbol, side, context_candles)
    if _fs_float(mtf_matrix.get("score"), 0.0) < _fs_float(cfg.get("fastSniperRetestMinMtfScore", -0.35), -0.35):
        return None
    price = _fs_float(market.get("price"), c)
    if side == "SELL":
        sl = max(h, zone_hi) + 0.35 * atr5
        risk = max(sl - price, 0.3 * atr5)
        tp1, tp2, tp3, tp4 = price - 1.0 * risk, price - 1.8 * risk, price - 2.6 * risk, price - 3.5 * risk
    else:
        sl = min(l, zone_lo) - 0.35 * atr5
        risk = max(price - sl, 0.3 * atr5)
        tp1, tp2, tp3, tp4 = price + 1.0 * risk, price + 1.8 * risk, price + 2.6 * risk, price + 3.5 * risk
    quality = str(cfg.get("fastSniperRetestQuality", "SCOUT") or "SCOUT").upper()
    retrace_pct = round(raw_retrace * 100, 1)
    mtf_score = _fs_float(mtf_matrix.get("score"), 0.0)
    body_strength = min(1.0, abs(c - o) / max(body_min * 2.0, 1e-9))
    retrace_quality = max(0.0, 1.0 - abs(raw_retrace - 0.38) / 0.30)
    rsi_quality = max(0.0, 1.0 - abs(rsi5 - 50.0) / 50.0)
    confidence = max(70.0, min(96.0, 72.0 + max(-0.2, mtf_score) * 12.0 + body_strength * 7.0 + retrace_quality * 5.0 + rsi_quality * 3.0))
    decision = {
        "ok": True, "action": "TAKE_TRADE", "quality": quality,
        "contextLabel": "retest-continuation", "counterTrend": False,
        "confidence": round(confidence, 1),
        "side": side, "symbol": symbol,
        "strategy": "Fast Sniper Retest Continuation",
        "selectedStrategy": {"name": "Fast Sniper Retest Continuation"},
        "reason": (f"Armed-retest COMPLETED: {side} impulse leg {leg:.1f} pulled back {retrace_pct}% into the "
                   f"{fib_lo:.0%}-{fib_hi:.0%} zone and printed a rejection close (body {abs(c-o):.2f} ≥ {body_min:.2f}). "
                   f"Continuation entry — no chase, second-leg discipline. MTF {mtf_matrix.get('summary')}."),
        "decisionBlocks": [], "softBlocks": [],
        "features": {"fastSniper": True, "retestContinuation": True, "retestCompleted": True,
                     "lateEntryOriginReset": True, "legSize": round(leg, 2),
                     "retracePct": retrace_pct, "retestEntryPrice": round(price, 3),
                     "retestTriggerHigh": round(h, 3), "retestTriggerLow": round(l, 3),
                     "rejectionBodyAtr": round(trigger_body_atr, 3), "rsi5": round(rsi5, 1),
                     "armedReason": st.get("armedReason"), "mtfScore": mtf_matrix.get("score"),
                     "mtfSummary": mtf_matrix.get("summary")},
        "mtfMatrix": mtf_matrix,
        "tradePlan": {"entry": round(price, 3), "sl": round(sl, 3), "tp1": round(tp1, 3), "tp2": round(tp2, 3),
                      "tp3": round(tp3, 3), "tp4": round(tp4, 3), "rr": 1.8, "reason": "Fast-lane armed-retest continuation"},
        "latencyMs": round((time.perf_counter() - started) * 1000),
    }
    # Commit the one-shot arm only after the decision is fully constructed.
    # A calculation error must leave the arm available for the next safe poll.
    st["active"] = False
    st["triggeredAt"] = now
    try:
        _journal_record("entry", decision="RETEST_TRIGGERED", side=side, confidence=decision["confidence"],
                        strategy="Fast Sniper Retest Continuation", reason=decision["reason"][:200])
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_6471", _suppressed_exc)
    return decision

def _fs_float(x: Any, default: float = 0.0) -> float:
    try:
        return float(x)
    except Exception:
        return default


def _fs_atr(candles: list[dict[str, Any]], period: int = 14) -> float:
    if len(candles) < period + 2:
        return 0.0
    trs: list[float] = []
    prev = _fs_float(candles[-period-1].get("close"))
    for c in candles[-period:]:
        high, low, close = _fs_float(c.get("high")), _fs_float(c.get("low")), _fs_float(c.get("close"))
        trs.append(max(high - low, abs(high - prev), abs(low - prev)))
        prev = close
    return sum(trs) / max(len(trs), 1)


def _fs_rsi(candles: list[dict[str, Any]], period: int = 14) -> float:
    if len(candles) < period + 2:
        return 50.0
    gains = losses = 0.0
    closes = [_fs_float(c.get("close")) for c in candles[-period-1:]]
    for a, b in zip(closes, closes[1:]):
        delta = b - a
        if delta >= 0:
            gains += delta
        else:
            losses += abs(delta)
    if losses <= 1e-9:
        return 100.0 if gains > 0 else 50.0
    rs = gains / losses
    return 100.0 - (100.0 / (1.0 + rs))


def _fs_tf_bias(candles: list[dict[str, Any]]) -> dict[str, Any]:
    """Compact trend/bias score for a single timeframe.

    Returns BUY/SELL/NEUTRAL with strength. It uses EMA position and EMA20 slope,
    which is fast to compute because copy_rates already attaches the EMAs.
    """
    if len(candles) < 30:
        return {"bias": "NEUTRAL", "strength": 0.0, "reason": "collecting"}
    last = candles[-2] if len(candles) >= 2 else candles[-1]
    prev = candles[-7] if len(candles) >= 7 else candles[0]
    close = _fs_float(last.get("close"))
    ema20 = _fs_float(last.get("ema20"), close)
    ema50 = _fs_float(last.get("ema50"), close)
    ema200 = _fs_float(last.get("ema200"), ema50)
    slope20 = ema20 - _fs_float(prev.get("ema20"), ema20)
    if close > ema20 >= ema50 and slope20 >= 0:
        strength = 1.0 if ema50 >= ema200 else 0.75
        return {"bias": "BUY", "strength": strength, "close": round(close,3), "ema20": round(ema20,3), "ema50": round(ema50,3), "slope20": round(slope20,4)}
    if close < ema20 <= ema50 and slope20 <= 0:
        strength = 1.0 if ema50 <= ema200 else 0.75
        return {"bias": "SELL", "strength": strength, "close": round(close,3), "ema20": round(ema20,3), "ema50": round(ema50,3), "slope20": round(slope20,4)}
    if close >= ema50 and slope20 >= 0:
        return {"bias": "BUY", "strength": 0.45, "close": round(close,3), "ema20": round(ema20,3), "ema50": round(ema50,3), "slope20": round(slope20,4)}
    if close <= ema50 and slope20 <= 0:
        return {"bias": "SELL", "strength": 0.45, "close": round(close,3), "ema20": round(ema20,3), "ema50": round(ema50,3), "slope20": round(slope20,4)}
    return {"bias": "NEUTRAL", "strength": 0.0, "close": round(close,3), "ema20": round(ema20,3), "ema50": round(ema50,3), "slope20": round(slope20,4)}


def _fast_sniper_mtf_matrix(symbol: str, side: str, context_candles: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    """Cached D1/H4/H1/M30/M15 hierarchy for the fast lane.

    The matrix is deliberately a score, not a demand for perfect alignment. This keeps
    sniper entries fast while avoiding M5 noise into strong H4/D1 opposition.
    """
    auto_cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    if not auto_cfg.get("fastSniperMtfMatrixEnabled", True):
        return {"enabled": False, "score": 0.0, "allowFull": True, "allowScout": True, "hardVeto": False, "summary": "MTF matrix disabled"}
    side = str(side or "").upper()
    if side not in {"BUY", "SELL"}:
        return {"enabled": True, "score": 0.0, "allowFull": False, "allowScout": False, "hardVeto": True, "summary": "invalid side"}
    now = time.time()
    cache_seconds = max(10.0, float(auto_cfg.get("fastSniperMtfCacheSeconds", 45.0) or 45.0))
    weights = {"D1": 1.35, "H4": 1.25, "H1": 1.10, "M30": 0.85, "M15": 1.00}
    details: dict[str, Any] = {}
    weighted = 0.0
    total_w = 0.0
    cache = FAST_SNIPER_MTF_STATE.setdefault("cache", {})
    for tf in ("D1", "H4", "H1", "M30", "M15"):
        candles = None
        if tf == "M15" and context_candles:
            candles = context_candles
        else:
            key = f"{symbol}:{tf}"
            item = cache.get(key) if isinstance(cache, dict) else None
            if isinstance(item, dict) and (now - float(item.get("at", 0.0) or 0.0)) <= cache_seconds:
                candles = item.get("candles") or []
            else:
                candles = mt5_bridge.copy_rates(symbol, tf, 120) if mt5_bridge.status().get("connected") else []
                cache[key] = {"at": now, "candles": candles}
        b = _fs_tf_bias(candles or [])
        bias = str(b.get("bias", "NEUTRAL")).upper()
        strength = float(b.get("strength", 0.0) or 0.0)
        w = float(weights.get(tf, 1.0))
        if bias == side:
            contribution = strength * w
        elif bias in {"BUY", "SELL"}:
            contribution = -strength * w
        else:
            contribution = 0.0
        weighted += contribution
        total_w += w
        details[tf] = {**b, "weight": w, "contribution": round(contribution, 3)}
    score = weighted / max(total_w, 1e-9)
    minimum = float(auto_cfg.get("fastSniperMtfMinimumScore", 0.18) or 0.18)
    scout_floor = float(auto_cfg.get("fastSniperMtfScoutFloor", -0.12) or -0.12)
    d1 = details.get("D1", {})
    h4 = details.get("H4", {})
    hard_opp = bool(auto_cfg.get("fastSniperHigherTfHardVeto", True)) and (
        str(d1.get("bias", "")).upper() in {"BUY", "SELL"} and str(h4.get("bias", "")).upper() in {"BUY", "SELL"}
        and str(d1.get("bias")).upper() != side and str(h4.get("bias")).upper() != side
        and float(d1.get("strength", 0) or 0) >= 0.75 and float(h4.get("strength", 0) or 0) >= 0.75
    )
    allow_full = (score >= minimum) and not hard_opp
    allow_scout = (score >= scout_floor) and not hard_opp
    aligned = [tf for tf, d in details.items() if str(d.get("bias", "")).upper() == side]
    opposing = [tf for tf, d in details.items() if str(d.get("bias", "")).upper() in {"BUY", "SELL"} and str(d.get("bias", "")).upper() != side]
    summary = f"MTF score {score:.2f}; aligned: {', '.join(aligned) or 'none'}; opposing: {', '.join(opposing) or 'none'}"
    return {
        "enabled": True,
        "score": round(score, 3),
        "allowFull": allow_full,
        "allowScout": allow_scout,
        "hardVeto": hard_opp,
        "minimumScore": minimum,
        "scoutFloor": scout_floor,
        "summary": summary,
        "details": details,
    }


def _fs_publish(res: dict, now: float) -> dict:
    """V13.48 — single exit point for the fast-sniper lane. Publishes the result to
    FAST_SNIPER_STATE and, when the result is a counter-trend fade, records it in
    RECENT_FADE_SIGNALS so the management loop can stamp the position with the tighter
    fade protection profile (V13.42). Previously this recording was spliced in at the
    wrong place and referenced `res` before assignment, which raised
    "cannot access local variable 'res'" on EVERY scan, killed the watcher, and stopped
    all trading."""
    try:
        FAST_SNIPER_STATE.update({"last": res, "lastAt": now})
        if isinstance(res, dict) and (res.get("counterTrend") or str(res.get("contextLabel", "")) == "exhaustion-reversal"):
            RECENT_FADE_SIGNALS.append({
                "side": str(res.get("side", "")).upper(),
                "price": _fs_float(res.get("entry") or 0),
                "ts": now,
            })
            del RECENT_FADE_SIGNALS[:-40]
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_6628", _suppressed_exc)
    return res


def _fast_sniper_decision(market: dict[str, Any]) -> dict[str, Any]:
    """Return a TAKE_TRADE decision for only the cleanest swift momentum shifts.

    Design choice for the user's bot: M15 = context, M5 = trigger. We do NOT use M1 as
    an entry signal because it is too noisy on XAUUSD; tick data is used only to execute
    the approved M5/M15 signal at the current bid/ask.
    """
    auto_cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    ai_cfg = SETTINGS_STATE.get("ai", {}) if isinstance(SETTINGS_STATE.get("ai"), dict) else {}
    if not auto_cfg.get("fastSniperEnabled", True):
        return {"ok": False, "reason": "Fast Sniper Lane disabled."}

    ttl = max(0.2, float(auto_cfg.get("fastSniperDecisionTtlSeconds", 0.9) or 0.9))
    if bool(auto_cfg.get("earlyIntentEnabled", True)):
        ttl = min(ttl, max(0.15, float(auto_cfg.get("earlyIntentDecisionTtlSeconds", 0.35) or 0.35)))
    now = time.time()
    cached = FAST_SNIPER_STATE.get("last") or {}
    if cached and (now - float(FAST_SNIPER_STATE.get("lastAt", 0.0) or 0.0)) <= ttl:
        return cached

    started = time.perf_counter()
    symbol = str(market.get("symbol") or (SETTINGS_STATE.get("trading", {}) or {}).get("symbol") or mt5_bridge.symbol or "XAUUSD")
    trigger_tf = str(auto_cfg.get("fastSniperTriggerTf", "M5") or "M5").upper()
    context_tf = str(auto_cfg.get("fastSniperContextTf", "M15") or "M15").upper()
    if trigger_tf not in {"M5", "M15"}:
        trigger_tf = "M5"
    if context_tf not in {"M15", "M30", "H1"}:
        context_tf = "M15"

    trigger_candles, _trigger_candle_meta = _predictor_candle_series(
        symbol, trigger_tf, 90, float(auto_cfg.get("earlyIntentTriggerCandleCacheSeconds", 0.50) or 0.50), market, now
    )
    context_candles, _context_candle_meta = _predictor_candle_series(
        symbol, context_tf, 90, float(auto_cfg.get("earlyIntentContextCandleCacheSeconds", 5.0) or 5.0), market, now
    )
    if len(trigger_candles) < 55 or len(context_candles) < 55:
        res = {"ok": False, "reason": "Not enough M5/M15 candles for fast sniper lane.", "latencyMs": round((time.perf_counter()-started)*1000)}
        return _fs_publish(res, now)

    use_closed = bool(auto_cfg.get("fastSniperRequireClosedM5", True))
    trig = trigger_candles[-2] if use_closed and len(trigger_candles) >= 2 else trigger_candles[-1]
    prev_window = trigger_candles[-(int(auto_cfg.get("fastSniperBreakoutLookback", 6) or 6)+3):-2 if use_closed else -1]
    if len(prev_window) < 3:
        prev_window = trigger_candles[-8:-2]
    ctx = context_candles[-2] if len(context_candles) >= 2 else context_candles[-1]
    ctx_prev = context_candles[-6] if len(context_candles) >= 6 else context_candles[0]

    atr5 = _fs_atr(trigger_candles[:-1] if use_closed else trigger_candles)
    atr15 = _fs_atr(context_candles)
    rsi5 = _fs_rsi(trigger_candles[:-1] if use_closed else trigger_candles)
    if atr5 <= 0:
        res = {"ok": False, "reason": "No ATR for fast sniper lane.", "latencyMs": round((time.perf_counter()-started)*1000)}
        return _fs_publish(res, now)

    # V13.17 BACKSTOP FIX — convert an ALREADY-ARMED retest BEFORE the regime/spread/news gates.
    # Root cause of "missing every spike": the arm is placed under clean conditions, but the
    # rejection candle that should FIRE the second leg often prints minutes later, and by then a
    # news-blackout / wide-spread / regime-standdown gate had opened. Those gates used to sit ABOVE
    # the converter, so the completed retest returned early and the arm expired untriggered. A
    # second-leg fill on a pre-existing arm is disciplined completion, NOT a fresh chase — news
    # protection still guards all FRESH entries further down. So the converter runs first.
    if FAST_SNIPER_RETEST_STATE.get("active"):
        try:
            _early_retest = _check_armed_retest(trigger_candles, context_candles, market, symbol, atr5, rsi5, started, now)
        except Exception as exc:
            RUNTIME_HEALTH.fail("fast_sniper_retest", str(exc))
            LOGGER.exception("Armed-retest conversion failed")
            _early_retest = None
        if _early_retest is not None:
            FAST_SNIPER_STATE.update({"last": _early_retest, "lastAt": now})
            return _early_retest

    o, h, l, c = map(_fs_float, (trig.get("open"), trig.get("high"), trig.get("low"), trig.get("close")))
    body = abs(c - o)
    displacement_atr = body / max(atr5, 1e-9)
    # V13.11 Phase 3 — regime gate. Classify the weather ONCE per scan from candles already in
    # hand (no extra fetch), publish it on every result (so the journal + why-silent can explain
    # decisions in regime terms), and stand the sniper down where its math cannot work.
    _regime_info = {"regime": "UNKNOWN"}
    _rpolicy = dict(DEFAULT_REGIME_POLICY.get("UNKNOWN", {}))
    if bool(auto_cfg.get("regimeSwitchingEnabled", True)):
        try:
            _regime_info = classify_regime(trigger_candles, news_blackout=bool(market.get("newsBlackout")))
            _pol_map = auto_cfg.get("regimePolicy") if isinstance(auto_cfg.get("regimePolicy"), dict) else {}
            _rpolicy = dict(_pol_map.get(_regime_info["regime"], DEFAULT_REGIME_POLICY.get(_regime_info["regime"], DEFAULT_REGIME_POLICY["UNKNOWN"])))
        except Exception:
            _regime_info = {"regime": "UNKNOWN", "reason": "classifier error"}
    _intent_enabled = bool(auto_cfg.get("earlyIntentEnabled", True))
    _impulse_enabled = bool(auto_cfg.get("earlyImpulsePredictorEnabled", True))
    _intent_window_cfg = max(2.0, float(auto_cfg.get("earlyIntentWindowSeconds", 4.0) or 4.0))
    _impulse_window_cfg = max(4.0, float(auto_cfg.get("earlyImpulseWindowSeconds", 12.0) or 12.0))
    _shared_predictor_ticks: list[dict[str, Any]] = []
    _shared_tick_meta: dict[str, Any] = {
        "tickCount": 0, "latestTickAgeMs": None, "tickSource": "not-fetched",
        "triggerCandleCache": _trigger_candle_meta, "contextCandleCache": _context_candle_meta,
    }
    if _intent_enabled or _impulse_enabled:
        try:
            _shared_predictor_ticks, _tick_window_meta = _predictor_tick_window(
                symbol, max(_intent_window_cfg if _intent_enabled else 0.0, _impulse_window_cfg if _impulse_enabled else 0.0), now, market
            )
            _shared_tick_meta.update(_tick_window_meta)
        except Exception as _tick_exc:
            RUNTIME_HEALTH.fail("predictor_tick_feed", str(_tick_exc))
            LOGGER.exception("Predictor tick acquisition failed")
            _shared_tick_meta = {"tickCount": 0, "latestTickAgeMs": None, "tickSource": "error", "tickError": str(_tick_exc)[:180]}

    # V15.2.7 EARLY INTENT ENGINE. This pre-entry lane operates before the conventional
    # impulse predictor. It seeks a short, accelerating tick burst near structural release and
    # may emit a tightly capped SCOUT probe at very low displacement. It cannot bypass news,
    # dirty-market, spread, reversal, extension, SL, risk, broker-admission or certification gates.
    if bool(auto_cfg.get("earlyIntentEnabled", True)):
        try:
            _intent_spread = _fs_float(market.get("spread"), 0.0)
            _intent_max_spread = float(ai_cfg.get("maxSpread", 0.40) or 0.40)
            _intent_clean = not bool(market.get("newsBlackout") or market.get("dirtyConditions"))
            _intent_window = _intent_window_cfg
            _intent_ticks = _shared_predictor_ticks if _intent_clean and (not _intent_spread or _intent_spread <= _intent_max_spread) else []
            _intent_cfg = {
                "windowSeconds": _intent_window,
                "minTicks": int(auto_cfg.get("earlyIntentMinTicks", 10) or 10),
                "hardMinTicks": int(auto_cfg.get("earlyIntentHardMinTicks", 6) or 6),
                "velocityAtrPerSecond": float(auto_cfg.get("earlyIntentVelocityAtrPerSecond", 0.020) or 0.020),
                "accelerationAtrPerSecond": float(auto_cfg.get("earlyIntentAccelerationAtrPerSecond", 0.015) or 0.015),
                "compressionRatio": float(auto_cfg.get("earlyIntentCompressionRatio", 0.78) or 0.78),
                "spreadExpansionMultiple": float(auto_cfg.get("earlyIntentSpreadExpansionMultiple", 1.55) or 1.55),
                "prebreakBufferAtr": float(auto_cfg.get("earlyIntentPrebreakBufferAtr", 0.08) or 0.08),
                "intentProbability": float(auto_cfg.get("earlyIntentProbability", 0.68) or 0.68),
                "minDisplacementAtr": float(auto_cfg.get("earlyIntentMinDisplacementAtr", 0.07) or 0.07),
            }
            _intent = predict_early_intent(
                ticks=_intent_ticks, candles=trigger_candles, atr=atr5,
                current_spread=_intent_spread, max_spread=_intent_max_spread, config=_intent_cfg,
            )
            _intent_extension = _predictor_extension_atr(trigger_candles, atr5)
            _context_cfg = {
                "minScore": float(auto_cfg.get("earlyIntentContextMinScore", 0.58) or 0.58),
                "maxLegMoveAtr": float(auto_cfg.get("earlyIntentContextMaxLegMoveAtr", 1.10) or 1.10),
                "maxRunBars": int(auto_cfg.get("earlyIntentContextMaxRunBars", 6) or 6),
                "terminalSwingPosition": float(auto_cfg.get("earlyIntentContextTerminalSwingPosition", 0.12) or 0.12),
                "maxExtensionAtr": float(auto_cfg.get("earlyIntentContextMaxExtensionAtr", 0.70) or 0.70),
                "maxReversalPenalty": float(auto_cfg.get("earlyIntentMaxReversalPenalty", 0.28) or 0.28),
                "requireM15Support": bool(auto_cfg.get("earlyIntentContextRequireM15Support", True)),
                "exhaustionRsiHigh": float(auto_cfg.get("earlyIntentExhaustionRsiHigh", 72.0) or 72.0),
                "exhaustionRsiLow": float(auto_cfg.get("earlyIntentExhaustionRsiLow", 28.0) or 28.0),
            }
            _intent_context = qualify_intent_context(
                side=str(_intent.side or ""), m5_candles=trigger_candles,
                m15_candles=context_candles, atr=atr5, intent=_intent.as_dict(), config=_context_cfg,
            ) if _intent.side in {"BUY", "SELL"} else None
            _intent_state_payload = _intent.as_dict()
            if _intent_context is not None:
                _intent_state_payload["context"] = _intent_context.as_dict()
            _context_blocked = bool(
                auto_cfg.get("earlyIntentContextGateEnabled", True)
                and _intent.stage == "INTENT" and _intent_context is not None and not _intent_context.allowed
            )
            _runtime_status = None
            _runtime_reason = None
            if not _intent_clean or (_intent_spread and _intent_spread > _intent_max_spread):
                _runtime_status = "BLOCKED"
                _runtime_reason = "Market/news/spread gate blocks intent scoring."
            elif _context_blocked:
                _runtime_status = "BLOCKED_CONTEXT"
                _runtime_reason = "; ".join(_intent_context.reasons[:3])
            _publish_predictor_state("earlyIntent", _intent_state_payload, now, _shared_tick_meta,
                                     runtime_status=_runtime_status, reason=_runtime_reason)
            _intent_allowed = (
                _intent_clean and _intent.side in {"BUY", "SELL"} and _intent.stage == "INTENT"
                and _intent.reversal_penalty <= float(auto_cfg.get("earlyIntentMaxReversalPenalty", 0.28) or 0.28)
                and _intent_extension <= float(auto_cfg.get("earlyIntentMaxExtensionAtr", 0.45) or 0.45)
                and _intent.spread_score >= float(auto_cfg.get("earlyIntentMinSpreadScore", 0.20) or 0.20)
                and (not bool(auto_cfg.get("earlyIntentContextGateEnabled", True)) or (_intent_context is not None and _intent_context.allowed))
            )
            if _intent_allowed:
                _intent_side = str(_intent.side)
                _intent_entry = _fs_float(market.get("ask") if _intent_side == "BUY" else market.get("bid"), _fs_float(market.get("price"), c))
                _probe_stop = build_probe_stop(
                    side=_intent_side, entry=_intent_entry, atr=atr5, recent_candles=trigger_candles[-3:],
                    config={
                        "minStopPoints": float(auto_cfg.get("earlyIntentProbeMinStopPoints", 1.50) or 1.50),
                        "maxStopPoints": float(auto_cfg.get("earlyIntentProbeMaxStopPoints", 3.50) or 3.50),
                        "stopAtr": float(auto_cfg.get("earlyIntentProbeStopAtr", auto_cfg.get("earlyIntentStopAtr", 0.45)) or 0.45),
                        "structureBufferAtr": float(auto_cfg.get("earlyIntentProbeStructureBufferAtr", 0.05) or 0.05),
                    },
                )
                if not _probe_stop.allowed:
                    _intent_state_payload["probeStop"] = _probe_stop.as_dict()
                    _publish_predictor_state("earlyIntent", _intent_state_payload, now, _shared_tick_meta,
                                             runtime_status="BLOCKED_RISK", reason=_probe_stop.reason)
                else:
                    _intent_conf = round(max(0.0, min(86.0, _intent.probability * 100.0)), 1)
                    _intent_decision = {
                        "ok": True, "action": "TAKE_TRADE", "marketRegime": _regime_info.get("regime"),
                        "regimeInfo": _regime_info, "quality": "SCOUT", "confidence": _intent_conf,
                        "side": _intent_side, "symbol": symbol, "source": "early_intent",
                        "strategy": "Early Intent Engine",
                        "selectedStrategy": {"name": "Early Intent Engine"},
                        "reason": _intent.reason + " | context-qualified probe",
                        "decisionBlocks": [], "softBlocks": [],
                        "features": {
                            "fastSniper": True, "earlyIntent": True, "anticipatoryEntry": True,
                            "progressiveStage": "PROBE", "managementProfile": "anticipatory_probe",
                            "entryThresholdPct": round(float(_intent_cfg["intentProbability"]) * 100.0, 2),
                            "probeLotMultiplier": float(auto_cfg.get("earlyIntentProbeLotMultiplier", 0.35) or 0.35),
                            "probeRiskPct": float(auto_cfg.get("earlyIntentProbeRiskPct", 0.12) or 0.12),
                            "probeMaxStopPoints": float(auto_cfg.get("earlyIntentProbeMaxStopPoints", 3.50) or 3.50),
                            "intentPrediction": _intent.as_dict(),
                            "intentContext": _intent_context.as_dict() if _intent_context is not None else {},
                            "extensionAtr": round(_intent_extension, 3),
                            "sourceTickAgeMs": _shared_tick_meta.get("latestTickAgeMs"),
                            "tickFetchLatencyMs": _shared_tick_meta.get("tickFetchLatencyMs"),
                            "tickCount": _shared_tick_meta.get("tickCount"),
                            "detectedAtEpoch": now,
                        },
                        "tradePlan": {
                            "entry": round(_intent_entry, 3), "sl": _probe_stop.sl,
                            "tp1": _probe_stop.tp1, "tp2": _probe_stop.tp2,
                            "tp3": _probe_stop.tp3, "tp4": _probe_stop.tp4,
                            "rr": 1.5, "reason": "context-qualified early intent probe",
                        },
                        "latencyMs": round((time.perf_counter() - started) * 1000),
                    }
                    return _fs_publish(_intent_decision, now)
        except Exception as _intent_exc:
            _publish_predictor_state("earlyIntent", None, now, _shared_tick_meta, "ERROR", f"Early intent engine error: {str(_intent_exc)[:180]}")
            RUNTIME_HEALTH.fail("early_intent_engine", str(_intent_exc))
            LOGGER.exception("Early intent engine failed; later impulse lanes remain available")
    else:
        _publish_predictor_state("earlyIntent", None, now, _shared_tick_meta, "DISABLED", "Early Intent is disabled in settings.")

    # V15.2.0 EARLY IMPULSE PREDICTION ENGINE.
    # This lane triggers from tick velocity/acceleration and compression release BEFORE the
    # legacy full-candle ATR threshold is reached. It is deliberately deterministic, bounded,
    # spread-aware and liquidity-sweep-aware. PROBE entries are scout-sized; CONFIRMED entries
    # use standard size. Existing execution, risk, broker-admission and position limits remain
    # authoritative downstream.
    if bool(auto_cfg.get("earlyImpulsePredictorEnabled", True)):
        try:
            _imp_spread = _fs_float(market.get("spread"), 0.0)
            _imp_max_spread = float(ai_cfg.get("maxSpread", 0.40) or 0.40)
            _imp_clean = not bool(market.get("newsBlackout") or market.get("dirtyConditions"))
            _imp_ticks = _shared_predictor_ticks if _imp_clean and (not _imp_spread or _imp_spread <= _imp_max_spread) else []
            _imp_cfg = {
                "windowSeconds": float(auto_cfg.get("earlyImpulseWindowSeconds", 12.0) or 12.0),
                "minTicks": int(auto_cfg.get("earlyImpulseMinTicks", 8) or 8),
                "velocityAtrPerSecond": float(auto_cfg.get("earlyImpulseVelocityAtrPerSecond", 0.018) or 0.018),
                "accelerationAtrPerSecond": float(auto_cfg.get("earlyImpulseAccelerationAtrPerSecond", 0.012) or 0.012),
                "compressionRatio": float(auto_cfg.get("earlyImpulseCompressionRatio", 0.72) or 0.72),
                "earlyBodyAtr": float(auto_cfg.get("earlyImpulseBodyAtr", 0.32) or 0.32),
                "spreadExpansionMultiple": float(auto_cfg.get("earlyImpulseSpreadExpansionMultiple", 1.8) or 1.8),
                "probeProbability": float(auto_cfg.get("earlyImpulseProbeProbability", 0.70) or 0.70),
                "confirmProbability": float(auto_cfg.get("earlyImpulseConfirmProbability", 0.82) or 0.82),
                "minProbeDisplacementAtr": float(auto_cfg.get("earlyImpulseMinProbeAtr", 0.16) or 0.16),
                "minConfirmDisplacementAtr": float(auto_cfg.get("earlyImpulseMinConfirmAtr", 0.30) or 0.30),
                "dynamicThresholds": bool(auto_cfg.get("earlyImpulseDynamicThresholds", True)),
                "liveCandleAnalysis": bool(auto_cfg.get("earlyImpulseLiveCandleAnalysis", True)),
                "progressiveExecution": bool(auto_cfg.get("earlyImpulseProgressiveExecution", True)),
            }
            _imp = predict_impulse(ticks=_imp_ticks, candles=trigger_candles, atr=atr5,
                                   current_spread=_imp_spread, max_spread=_imp_max_spread, config=_imp_cfg)
            _imp_context_input = {
                "structure_score": float(getattr(_imp, "compression_release_score", 0.0) or 0.0),
                "reversal_penalty": float(getattr(_imp, "sweep_penalty", 0.0) or 0.0),
                "acceleration_score": float(getattr(_imp, "acceleration_score", 0.0) or 0.0),
            }
            _imp_context = qualify_intent_context(
                side=str(_imp.side or ""), m5_candles=trigger_candles,
                m15_candles=context_candles, atr=atr5, intent=_imp_context_input,
                config={
                    "minScore": float(auto_cfg.get("earlyIntentContextMinScore", 0.58) or 0.58),
                    "maxLegMoveAtr": float(auto_cfg.get("earlyIntentContextMaxLegMoveAtr", 1.10) or 1.10),
                    "maxRunBars": int(auto_cfg.get("earlyIntentContextMaxRunBars", 6) or 6),
                    "terminalSwingPosition": float(auto_cfg.get("earlyIntentContextTerminalSwingPosition", 0.12) or 0.12),
                    "maxExtensionAtr": float(auto_cfg.get("earlyIntentContextMaxExtensionAtr", 0.70) or 0.70),
                    "maxReversalPenalty": float(auto_cfg.get("earlyImpulseMaxSweepPenalty", 0.45) or 0.45),
                    "requireM15Support": bool(auto_cfg.get("earlyIntentContextRequireM15Support", True)),
                    "exhaustionRsiHigh": float(auto_cfg.get("earlyIntentExhaustionRsiHigh", 72.0) or 72.0),
                    "exhaustionRsiLow": float(auto_cfg.get("earlyIntentExhaustionRsiLow", 28.0) or 28.0),
                },
            ) if _imp.side in {"BUY", "SELL"} else None
            _imp_state_payload = _imp.as_dict()
            if _imp_context is not None:
                _imp_state_payload["context"] = _imp_context.as_dict()
            _imp_context_blocked = bool(
                auto_cfg.get("earlyIntentContextGateEnabled", True)
                and _imp.stage in {"PROBE", "CONFIRMED"}
                and _imp_context is not None and not _imp_context.allowed
            )
            _imp_runtime_status = None
            _imp_runtime_reason = None
            if not _imp_clean or (_imp_spread and _imp_spread > _imp_max_spread):
                _imp_runtime_status = "BLOCKED"
                _imp_runtime_reason = "Market/news/spread gate blocks impulse scoring."
            elif _imp_context_blocked:
                _imp_runtime_status = "BLOCKED_CONTEXT"
                _imp_runtime_reason = "; ".join(_imp_context.reasons[:3])
            _publish_predictor_state("earlyImpulse", _imp_state_payload, now, _shared_tick_meta,
                                     runtime_status=_imp_runtime_status, reason=_imp_runtime_reason)
            _imp_max_extension = float(auto_cfg.get("earlyImpulseMaxExtensionAtr", 0.85) or 0.85)
            _imp_extension = _predictor_extension_atr(trigger_candles, atr5)
            _imp_allowed = (
                _imp_clean and _imp.side in {"BUY", "SELL"} and _imp.stage in {"PROBE", "CONFIRMED"}
                and _imp.sweep_penalty <= float(auto_cfg.get("earlyImpulseMaxSweepPenalty", 0.45) or 0.45)
                and _imp_extension <= _imp_max_extension
                and (not bool(auto_cfg.get("earlyIntentContextGateEnabled", True)) or (_imp_context is not None and _imp_context.allowed))
            )
            if _imp_allowed:
                _imp_side = str(_imp.side)
                _imp_entry = _fs_float(market.get("ask") if _imp_side == "BUY" else market.get("bid"), _fs_float(market.get("price"), c))
                _imp_is_probe = str(_imp.stage).upper() == "PROBE"
                if _imp_is_probe:
                    _imp_probe_stop = build_probe_stop(
                        side=_imp_side, entry=_imp_entry, atr=atr5, recent_candles=trigger_candles[-3:],
                        config={
                            "minStopPoints": float(auto_cfg.get("earlyIntentProbeMinStopPoints", 1.50) or 1.50),
                            "maxStopPoints": float(auto_cfg.get("earlyIntentProbeMaxStopPoints", 3.50) or 3.50),
                            "stopAtr": float(auto_cfg.get("earlyIntentProbeStopAtr", 0.45) or 0.45),
                            "structureBufferAtr": float(auto_cfg.get("earlyIntentProbeStructureBufferAtr", 0.05) or 0.05),
                        },
                    )
                    if not _imp_probe_stop.allowed:
                        _imp_state_payload["probeStop"] = _imp_probe_stop.as_dict()
                        _publish_predictor_state("earlyImpulse", _imp_state_payload, now, _shared_tick_meta,
                                                 runtime_status="BLOCKED_RISK", reason=_imp_probe_stop.reason)
                        _imp_allowed = False
                    else:
                        _imp_sl = _imp_probe_stop.sl
                        _imp_tps = [_imp_probe_stop.tp1, _imp_probe_stop.tp2, _imp_probe_stop.tp3, _imp_probe_stop.tp4]
                else:
                    _imp_min_stop = float(ai_cfg.get("minXauStopPoints", 7.0) or 7.0)
                    _imp_stop_dist = max(_imp_min_stop, atr5 * float(auto_cfg.get("earlyImpulseStopAtr", 0.90) or 0.90))
                    if _imp_side == "BUY":
                        _imp_struct = min((_fs_float(x.get("low")) for x in trigger_candles[-5:]), default=l) - 0.10 * atr5
                        _imp_sl = min(_imp_entry - _imp_stop_dist, _imp_struct)
                        _imp_risk = max(_imp_entry - _imp_sl, _imp_min_stop)
                        _imp_tps = [_imp_entry + _imp_risk*r for r in (1.0, 1.8, 2.8, 4.0)]
                    else:
                        _imp_struct = max((_fs_float(x.get("high")) for x in trigger_candles[-5:]), default=h) + 0.10 * atr5
                        _imp_sl = max(_imp_entry + _imp_stop_dist, _imp_struct)
                        _imp_risk = max(_imp_sl - _imp_entry, _imp_min_stop)
                        _imp_tps = [_imp_entry - _imp_risk*r for r in (1.0, 1.8, 2.8, 4.0)]
                if _imp_allowed:
                    _imp_quality = "SCOUT" if _imp_is_probe else "STANDARD"
                    _imp_conf = round(max(0.0, min(92.0, _imp.probability * 100.0)), 1)
                    _imp_features = {
                        "fastSniper": True, "earlyImpulse": True,
                        "anticipatoryEntry": _imp_is_probe,
                        "progressiveStage": _imp.stage,
                        "managementProfile": "anticipatory_probe" if _imp_is_probe else "confirmed_impulse",
                        "entryThresholdPct": round(float(_imp_cfg["probeProbability" if _imp_is_probe else "confirmProbability"]) * 100.0, 2),
                        "impulsePrediction": _imp.as_dict(),
                        "intentContext": _imp_context.as_dict() if _imp_context is not None else {},
                        "extensionAtr": round(_imp_extension, 3),
                        "sourceTickAgeMs": _shared_tick_meta.get("latestTickAgeMs"),
                        "tickFetchLatencyMs": _shared_tick_meta.get("tickFetchLatencyMs"),
                        "tickCount": _shared_tick_meta.get("tickCount"),
                        "detectedAtEpoch": now,
                    }
                    if _imp_is_probe:
                        _imp_features.update({
                            "probeLotMultiplier": float(auto_cfg.get("earlyImpulseProbeLotMultiplier", 0.50) or 0.50),
                            "probeRiskPct": float(auto_cfg.get("earlyIntentProbeRiskPct", 0.12) or 0.12),
                            "probeMaxStopPoints": float(auto_cfg.get("earlyIntentProbeMaxStopPoints", 3.50) or 3.50),
                        })
                    _imp_decision = {
                        "ok": True, "action": "TAKE_TRADE", "marketRegime": _regime_info.get("regime"),
                        "regimeInfo": _regime_info, "quality": _imp_quality, "confidence": _imp_conf,
                        "side": _imp_side, "symbol": symbol, "source": "early_impulse",
                        "strategy": "Early Impulse Predictor",
                        "selectedStrategy": {"name": "Early Impulse Predictor"},
                        "reason": _imp.reason + " | context-qualified",
                        "decisionBlocks": [], "softBlocks": [],
                        "features": _imp_features,
                        "tradePlan": {"entry": round(_imp_entry, 3), "sl": round(_imp_sl, 3),
                                      "tp1": round(_imp_tps[0], 3), "tp2": round(_imp_tps[1], 3),
                                      "tp3": round(_imp_tps[2], 3), "tp4": round(_imp_tps[3], 3),
                                      "rr": 1.5 if _imp_is_probe else 1.8,
                                      "reason": f"context-qualified {_imp.stage.lower()} early impulse"},
                        "latencyMs": round((time.perf_counter() - started) * 1000),
                    }
                    return _fs_publish(_imp_decision, now)
        except Exception as _imp_exc:
            _publish_predictor_state("earlyImpulse", None, now, _shared_tick_meta, "ERROR", f"Early impulse predictor error: {str(_imp_exc)[:180]}")
            RUNTIME_HEALTH.fail("early_impulse_predictor", str(_imp_exc))
            LOGGER.exception("Early impulse prediction failed; legacy fast lane remains available")
    else:
        _publish_predictor_state("earlyImpulse", None, now, _shared_tick_meta, "DISABLED", "Early Impulse Predictor is disabled in settings.")

    # V15.1.1 IMPULSE CAPTURE OVERRIDE. A genuine pump/dump is classified as SHOCK, but
    # the old SHOCK policy disabled the sniper before the strong-momentum branch could run.
    # That made the requested behaviour structurally unreachable. Permit only an undeniable
    # forming-candle impulse through this early gate; all later spread, extension, RSI,
    # exhaustion, MTF, risk and execution protections remain active.
    shock_impulse = bool(
        auto_cfg.get("shockImpulseEntryEnabled", True)
        and str(_regime_info.get("regime", "")).upper() == "SHOCK"
        and displacement_atr >= float(auto_cfg.get("shockImpulseMinDisplacementAtr", 1.10) or 1.10)
    )
    if shock_impulse:
        _rpolicy = {**_rpolicy, "sniper": True, "momentum": True, "counterHtfMomentum": True}
    if not _rpolicy.get("sniper", True):
        res = {"ok": False, "reason": f"Regime stand-down ({_regime_info.get('regime')}): {_regime_info.get('reason')}. Sniper lane disabled by regime policy; brackets {'stay armed' if _rpolicy.get('brackets') else 'also off'}.",
               "regime": _regime_info, "displacementAtr": round(displacement_atr, 2), "latencyMs": round((time.perf_counter()-started)*1000)}
        if _rpolicy.get("brackets", False):
            try:
                _mtf_for_arm = _fast_sniper_mtf_matrix(symbol, "BUY", context_candles) if "_fast_sniper_mtf_matrix" in globals() else None
                _maybe_arm_breakout_bracket(trigger_candles, market, atr5, _mtf_for_arm)
            except Exception as _suppressed_exc:
                _report_suppressed_exception("suppressed_exception_line_6722", _suppressed_exc)
        return _fs_publish(res, now)
    min_disp = float(auto_cfg.get("fastSniperMinDisplacementAtr", 0.75) or 0.75)
    max_ext = float(auto_cfg.get("fastSniperMaxExtensionAtr", 1.15) or 1.15)
    recent_high = max(_fs_float(x.get("high")) for x in prev_window)
    recent_low = min(_fs_float(x.get("low")) for x in prev_window)
    ema20 = _fs_float(trig.get("ema20"), c)
    ema50 = _fs_float(trig.get("ema50"), c)
    ctx_close = _fs_float(ctx.get("close"))
    ctx_ema20 = _fs_float(ctx.get("ema20"), ctx_close)
    ctx_slope20 = ctx_ema20 - _fs_float(ctx_prev.get("ema20"), ctx_ema20)

    spread = _fs_float(market.get("spread"), 0.0)
    max_spread = float(ai_cfg.get("maxSpread", 0.40) or 0.40)
    if spread and spread > max_spread:
        res = {"ok": False, "reason": f"Fast sniper blocked by spread {spread:.2f} > max {max_spread:.2f}.", "displacementAtr": round(displacement_atr, 2), "latencyMs": round((time.perf_counter()-started)*1000)}
        return _fs_publish(res, now)
    if market.get("newsBlackout") or market.get("dirtyConditions"):
        res = {"ok": False, "reason": "Fast sniper blocked by news/dirty conditions.", "displacementAtr": round(displacement_atr, 2), "latencyMs": round((time.perf_counter()-started)*1000)}
        return _fs_publish(res, now)

    # V13.17: firing conversion was HOISTED above the gates (see BACKSTOP FIX). Here we only run
    # the throttled opportunity-cost sweep. The converter is not re-called: if an arm was going to
    # fire this scan it already did so above; if it did not, it stays armed for the next scan.
    _sweep_expired_arm_outcomes()   # V12.83: throttled (5 min) opportunity-cost evaluation; no-op when nothing pending
    retest_decision = None
    if retest_decision is not None:
        FAST_SNIPER_STATE.update({"last": retest_decision, "lastAt": now})
        return retest_decision
    # V12.93: if no retest is arming and price is in a tight base, pre-place a breakout-stop bracket
    try:
        # V13.11: brackets obey the regime policy (QUIET tape = no brackets either)
        if _rpolicy.get("brackets", True):
            _mtf = _fast_sniper_mtf_matrix(symbol, "BUY", context_candles) if "_fast_sniper_mtf_matrix" in globals() else None
            _maybe_arm_breakout_bracket(trigger_candles, market, atr5, _mtf)
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_6758", _suppressed_exc)

    buy_break = c > o and c > recent_high and c > ema20 and displacement_atr >= min_disp
    sell_break = c < o and c < recent_low and c < ema20 and displacement_atr >= min_disp
    buy_context_clean = ctx_close >= ctx_ema20 and ctx_slope20 >= 0
    sell_context_clean = ctx_close <= ctx_ema20 and ctx_slope20 <= 0
    buy_context_transition = c > ema20 and ema20 >= ema50 and ctx_close > ctx_ema20 - 0.25 * max(atr15, atr5)
    sell_context_transition = c < ema20 and ema20 <= ema50 and ctx_close < ctx_ema20 + 0.25 * max(atr15, atr5)

    # V12.49: Transition Pullback/Reclaim Scout. Many clean gold continuations do NOT
    # print a fresh breakout candle; they pull back to M5 EMA20/50 then reclaim. The old
    # fast lane only saw breakout displacement, so it skipped the cleaner entry and waited
    # until the move was late. This path stays strict: only scout, only near EMA structure,
    # only when M15 is at least transitioning, and HTF matrix still protects the trade.
    reclaim_enabled = bool(auto_cfg.get("fastSniperTransitionPullbackEnabled", True)) and bool(auto_cfg.get("fastSniperAllowTransitionScout", True))
    reclaim_n = max(2, min(int(auto_cfg.get("fastSniperReclaimLookback", 4) or 4), 8))
    reclaim_window = trigger_candles[-(reclaim_n+1):-1] if use_closed else trigger_candles[-reclaim_n:]
    if not reclaim_window:
        reclaim_window = trigger_candles[-5:-1]
    recent_retest_ema20 = any(_fs_float(x.get("low")) <= ema20 + 0.20 * atr5 and _fs_float(x.get("high")) >= ema20 - 0.20 * atr5 for x in reclaim_window)
    recent_retest_ema50 = any(_fs_float(x.get("low")) <= ema50 + 0.25 * atr5 and _fs_float(x.get("high")) >= ema50 - 0.25 * atr5 for x in reclaim_window)
    reclaim_body_min = float(auto_cfg.get("fastSniperReclaimMinBodyAtr", 0.25) or 0.25)
    prev_close = _fs_float(trigger_candles[-3 if use_closed and len(trigger_candles) >= 3 else -2].get("close"), c)
    buy_reclaim = reclaim_enabled and c > o and c > ema20 and c >= ema50 and (recent_retest_ema20 or recent_retest_ema50) and body / max(atr5, 1e-9) >= reclaim_body_min and c >= prev_close - 0.10 * atr5
    sell_reclaim = reclaim_enabled and c < o and c < ema20 and c <= ema50 and (recent_retest_ema20 or recent_retest_ema50) and body / max(atr5, 1e-9) >= reclaim_body_min and c <= prev_close + 0.10 * atr5

    # V12.84 exhaustion reversal: catches the second setup in the supplied chart — a peak
    # rejection, failed higher high/lower high, then consecutive bearish confirmation candles.
    # This is not a blind counter-trend sell; it requires a visible liquidity rejection and
    # structure failure, and is always SCOUT quality unless the higher-timeframe matrix agrees.
    reversal_enabled = bool(auto_cfg.get("fastSniperReversalEnabled", False))  # V12.87: OFF unless explicitly opted in
    closed_bars = trigger_candles[:-1] if use_closed else trigger_candles
    sell_reversal = False
    buy_reversal = False
    reversal_meta = {}
    if reversal_enabled and len(closed_bars) >= 8:
        rb = closed_bars[-7:]
        # Find the most recent local high/low rejection before the last confirmation candle.
        hi_idx = max(range(len(rb)-1), key=lambda i: _fs_float(rb[i].get("high")))
        lo_idx = min(range(len(rb)-1), key=lambda i: _fs_float(rb[i].get("low")))
        last2 = rb[-2:]
        peak = rb[hi_idx]; trough = rb[lo_idx]
        p_o,p_h,p_l,p_c = map(_fs_float,(peak.get("open"),peak.get("high"),peak.get("low"),peak.get("close")))
        t_o,t_h,t_l,t_c = map(_fs_float,(trough.get("open"),trough.get("high"),trough.get("low"),trough.get("close")))
        upper_wick = p_h - max(p_o,p_c)
        lower_wick = min(t_o,t_c) - t_l
        min_wick = float(auto_cfg.get("fastSniperReversalMinWickAtr",0.42) or 0.42) * atr5
        min_rev_body = float(auto_cfg.get("fastSniperReversalMinBodyAtr",0.18) or 0.18) * atr5
        b1o,b1h,b1l,b1c = map(_fs_float,(last2[0].get("open"),last2[0].get("high"),last2[0].get("low"),last2[0].get("close")))
        b2o,b2h,b2l,b2c = map(_fs_float,(last2[1].get("open"),last2[1].get("high"),last2[1].get("low"),last2[1].get("close")))
        sell_reversal = (hi_idx <= len(rb)-3 and upper_wick >= min_wick and b1c < b1o and b2c < b2o
                         and b2h < p_h and b2c < b1c and abs(b2c-b2o) >= min_rev_body
                         and b2c < (p_h+p_l)/2)
        buy_reversal = (lo_idx <= len(rb)-3 and lower_wick >= min_wick and b1c > b1o and b2c > b2o
                        and b2l > t_l and b2c > b1c and abs(b2c-b2o) >= min_rev_body
                        and b2c > (t_h+t_l)/2)
        reversal_meta = {"peak":round(p_h,3),"trough":round(t_l,3),"upperWickAtr":round(upper_wick/max(atr5,1e-9),2),"lowerWickAtr":round(lower_wick/max(atr5,1e-9),2)}

    side = None
    quality = "STANDARD"
    context_label = "clean"
    trigger_pattern = "breakout"
    # V13.18 DEAD-ZONE FIX: breakout RSI bands used to be BUY 54-78 / SELL 22-46, leaving a silent
    # gap at RSI 46-54 where a clean, structurally-valid, M15-aligned breakout matched NO branch and
    # returned "no clean trigger" — skipping the FIRST impulse candle (RSI often sits neutral there
    # before momentum extends). Structure + displacement + M15 context already prove directional
    # intent; RSI's job here is only to veto EXHAUSTION (the >78 / <22 ends, still guarded by the
    # strong-momentum override and the extension gate). Bands now meet at 50 — no gap, no overlap.
    if buy_break and buy_context_clean and 50 <= rsi5 <= 78:
        side = "BUY"
    elif sell_break and sell_context_clean and 22 <= rsi5 <= 50:
        side = "SELL"
    elif auto_cfg.get("fastSniperAllowTransitionScout", True) and buy_break and buy_context_transition and 50 <= rsi5 <= 80:
        side, quality, context_label = "BUY", "SCOUT", "transition"
    elif auto_cfg.get("fastSniperAllowTransitionScout", True) and sell_break and sell_context_transition and 20 <= rsi5 <= 50:
        side, quality, context_label = "SELL", "SCOUT", "transition"
    elif reclaim_enabled and buy_reclaim and buy_context_transition and 50 <= rsi5 <= 78:
        side, quality, context_label, trigger_pattern = "BUY", "SCOUT", "transition-reclaim", "pullback-reclaim"
    elif reclaim_enabled and sell_reclaim and sell_context_transition and 22 <= rsi5 <= 50:
        side, quality, context_label, trigger_pattern = "SELL", "SCOUT", "transition-reclaim", "pullback-reclaim"
    elif sell_reversal and 28 <= rsi5 <= 68:
        side, quality, context_label, trigger_pattern = "SELL", "SCOUT", "exhaustion-reversal", "rejection-lower-high"
    elif buy_reversal and 32 <= rsi5 <= 72:
        side, quality, context_label, trigger_pattern = "BUY", "SCOUT", "exhaustion-reversal", "rejection-higher-low"

    if not side:
        # V12.97 — STRONG-MOMENTUM CONTINUATION OVERRIDE. The recurring miss (user's 4090->4060
        # dump): a hard breakdown pins RSI BELOW the 20-22 SELL floor, so the continuation never
        # armed — then at the exhaustion LOW, RSI recovered back into 22-46 and the bot sold the
        # bottom. The RSI floor was systematically pushing entries to the END of moves. This
        # override lets a STRONG, HTF-aligned break take the continuation past the floor, but only
        # with real momentum (displacement) AND not already over-extended, so it is not a blind
        # chase of a vertical spike. Ships ON: it is a gate-fix to existing continuation logic.
        if bool(auto_cfg.get("fastSniperStrongMomentumOverride", True)):
            strong_disp = displacement_atr >= float(auto_cfg.get("strongMomentumDisplacementAtr", 1.05) or 1.05)
            ext = abs(c - ema20) / max(atr5, 1e-9)
            not_overextended = ext <= float(auto_cfg.get("strongMomentumMaxStretchAtr", 1.50) or 1.50)
            try:
                _mtf_probe = _fast_sniper_mtf_matrix(symbol, "SELL" if sell_break else "BUY", context_candles if context_tf == "M15" else None)
                _mtf_score = _fs_float(_mtf_probe.get("score"))
                _mtf_hard = bool(_mtf_probe.get("hardVeto"))
            except Exception:
                _mtf_score, _mtf_hard = 0.0, False
            # V13.9: counter-HTF permission — displacement must clear the HIGHER bar (1.25 ATR
            # default vs 1.05 aligned). Same stretch cap, same RSI capitulation floors, and the
            # exhaustion guard downstream still applies: this buys/sells a RUNNING move, it does
            # not fade one. HTF score bands and the hard veto are bypassed for this lane only.
            counter_ok = (bool(auto_cfg.get("momentumIgnoreHtf", True))
                          and displacement_atr >= float(auto_cfg.get("momentumCounterHtfMinAtr", 1.25) or 1.25)
                          and _rpolicy.get("counterHtfMomentum", True))  # V13.11: no counter-chasing in RANGE chop
            if strong_disp and not_overextended and (not _mtf_hard or counter_ok) and _rpolicy.get("momentum", True):
                # SELL breakdown with RSI below the normal floor (but not single-print capitulation)
                if sell_break and sell_context_clean and rsi5 < 22 and rsi5 >= float(auto_cfg.get("strongMomentumRsiFloorSell", 8.0) or 8.0) and (_mtf_score <= 0.10 or counter_ok):
                    side, quality, context_label, trigger_pattern = "SELL", "STRONG", "momentum-continuation", ("strong-breakdown-counter-htf" if (_mtf_score > 0.10 or _mtf_hard) else "strong-breakdown")
                # BUY breakout with RSI above the normal ceiling (but not blow-off top)
                elif buy_break and buy_context_clean and rsi5 > 78 and rsi5 <= float(auto_cfg.get("strongMomentumRsiCeilBuy", 92.0) or 92.0) and (_mtf_score >= -0.10 or counter_ok):
                    side, quality, context_label, trigger_pattern = "BUY", "STRONG", "momentum-continuation", ("strong-breakout-counter-htf" if (_mtf_score < -0.10 or _mtf_hard) else "strong-breakout")

    if not side:
        # If the move is real but already overheated/oversold, do not label it a plain rejection.
        # Hand it to Impulse Retest Mode so the bot can catch the second leg instead of chasing.
        if (buy_break and (buy_context_clean or buy_context_transition) and rsi5 > 78) or (sell_break and (sell_context_clean or sell_context_transition) and rsi5 < 22):
            hot_side = "BUY" if buy_break else "SELL"
            _arm_fast_retest(hot_side, trigger_candles, atr5, f"RSI {rsi5:.0f} too hot")
            res = {"ok": False, "armedRetest": True, "side": hot_side, "reason": f"Fast sniper detected {hot_side} momentum but RSI {rsi5:.0f} is too hot for immediate entry — arming retest instead. Retest tracker is LIVE: a pullback into the retrace zone with a rejection close will trigger the continuation entry automatically.", "rsi5": round(rsi5,1), "displacementAtr": round(displacement_atr,2), "latencyMs": round((time.perf_counter()-started)*1000)}
            return _fs_publish(res, now)
        res = {"ok": False, "reason": "No clean M5 breakout or pullback/reclaim + M15 context fast-lane trigger.", "rsi5": round(rsi5,1), "displacementAtr": round(displacement_atr,2), "latencyMs": round((time.perf_counter()-started)*1000)}
        return _fs_publish(res, now)

    mtf_matrix = _fast_sniper_mtf_matrix(symbol, side, context_candles if context_tf == "M15" else None)
    # V13.22 CRASH FIX — reversal_setup was USED at the exhaustion guard below but not DEFINED until
    # after it, raising "cannot access local variable 'reversal_setup'" every scan and killing the
    # entire fast-sniper watcher (26 consecutive telegram_signal_watch_error rows). It only depends
    # on trigger_pattern, already set in side-detection, so define it here before first use.
    reversal_setup = trigger_pattern in {"rejection-lower-high", "rejection-higher-low"}
    # V12.94 — EXHAUSTION GUARD. The recurring loss on the user's charts: the fast lane sold the
    # LAST gasp of a downtrend (or bought the top) right as price bottomed and reversed up. It
    # happens because the HTF matrix at a turning point is only "mixed" (lagging), not a hard veto,
    # so a SELL is allowed as SCOUT while price is actually basing. Guard: refuse a continuation
    # SELL when price is already stretched BELOW the M5 EMA band AND RSI is oversold-and-rising
    # (a bottom, not a continuation); symmetric for BUY at a stretched top with RSI overbought-and-
    # falling. Reversal setups are exempt (they are explicitly counter-trend and separately gated).
    if not reversal_setup and bool(auto_cfg.get("fastSniperExhaustionGuard", True)):
        try:
            rsi_prev = _fs_rsi([_fs_float(x.get("close")) for x in (trigger_candles[:-1] if use_closed else trigger_candles)][:-1], 14) if len(trigger_candles) > 16 else rsi5
        except Exception:
            rsi_prev = rsi5
        stretch = abs(c - ema20) / max(atr5, 1e-9)
        stretch_min = float(auto_cfg.get("exhaustionStretchAtr", 1.10) or 1.10)
        os_level = float(auto_cfg.get("exhaustionOversold", 34.0) or 34.0)
        ob_level = float(auto_cfg.get("exhaustionOverbought", 66.0) or 66.0)
        if side == "SELL" and stretch >= stretch_min and rsi5 <= os_level and rsi5 > rsi_prev:
            _arm_fast_retest(side, trigger_candles, atr5, "exhaustion guard: oversold+turning, waiting for real continuation")
            res = {"ok": False, "armedRetest": True, "reason": f"Fast sniper HELD: SELL into oversold exhaustion (RSI {rsi5:.0f} rising, {stretch:.2f} ATR below EMA) — this is a bottoming zone, not a continuation. Armed retest instead of selling the low.", "side": side, "mtfMatrix": mtf_matrix, "displacementAtr": round(displacement_atr, 2), "latencyMs": round((time.perf_counter()-started)*1000)}
            return _fs_publish(res, now)
        if side == "BUY" and stretch >= stretch_min and rsi5 >= ob_level and rsi5 < rsi_prev:
            _arm_fast_retest(side, trigger_candles, atr5, "exhaustion guard: overbought+turning, waiting for real continuation")
            res = {"ok": False, "armedRetest": True, "reason": f"Fast sniper HELD: BUY into overbought exhaustion (RSI {rsi5:.0f} falling, {stretch:.2f} ATR above EMA) — this is a topping zone, not a continuation. Armed retest instead of buying the high.", "side": side, "mtfMatrix": mtf_matrix, "displacementAtr": round(displacement_atr, 2), "latencyMs": round((time.perf_counter()-started)*1000)}
            return _fs_publish(res, now)
    reversal_floor = float(auto_cfg.get("fastSniperReversalMtfFloor", -0.35) or -0.35)
    if reversal_setup and _fs_float(mtf_matrix.get("score"), 0.0) < reversal_floor:
        res = {"ok": False, "reason": f"Fast sniper reversal blocked: MTF score {_fs_float(mtf_matrix.get('score')):.2f} < {reversal_floor:.2f}.", "mtfMatrix": mtf_matrix, "side": side, "displacementAtr": round(displacement_atr, 2), "latencyMs": round((time.perf_counter()-started)*1000)}
        return _fs_publish(res, now)
    # V13.9: pump-grade displacement earns permission to trade AGAINST the HTF river — for CLEAN
    # breaks and the STRONG momentum lane only. Scouts/reversals (the historical oversized-loser
    # class) stay fully protected by the veto. Entry catches the move; fastfail(5m)/BE/trailing
    # own the risk from there — Johnson's explicit design call.
    _momentum_counter = (bool(auto_cfg.get("momentumIgnoreHtf", True))
                         and displacement_atr >= float(auto_cfg.get("momentumCounterHtfMinAtr", 1.25) or 1.25)
                         and quality in ("STANDARD", "STRONG")
                         and _rpolicy.get("counterHtfMomentum", True))
    if mtf_matrix.get("hardVeto") and not reversal_setup and not _momentum_counter:
        res = {"ok": False, "reason": f"Fast sniper blocked by higher-timeframe hard veto: {mtf_matrix.get('summary')}", "mtfMatrix": mtf_matrix, "side": side, "displacementAtr": round(displacement_atr, 2), "latencyMs": round((time.perf_counter()-started)*1000)}
        return _fs_publish(res, now)
    if not mtf_matrix.get("allowFull", True) and not reversal_setup:
        if quality != "SCOUT" and auto_cfg.get("fastSniperAllowTransitionScout", True) and mtf_matrix.get("allowScout", False):
            quality, context_label = "SCOUT", "mixed-higher-tf"
        else:
            res = {"ok": False, "reason": f"Fast sniper blocked by MTF matrix: {mtf_matrix.get('summary')}", "mtfMatrix": mtf_matrix, "side": side, "displacementAtr": round(displacement_atr, 2), "latencyMs": round((time.perf_counter()-started)*1000)}
            return _fs_publish(res, now)

    # ── V15.2.0 ADAPTIVE BODY-ATR QUALITY GATE ──────────────────────────
    # Supports OFF, SHADOW and ENFORCE modes. SHADOW records the weak print but
    # does not block it, allowing the operator to collect enough evidence before
    # enforcing a journal-derived threshold. Qualified SHOCK impulses bypass the
    # gate because their displacement confirmation is stronger and time-critical.
    _body = abs(c - o) / max(atr5, 1e-9)
    _auto_fsmms = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    _gate_enabled = bool(_auto_fsmms.get("fsmmsBodyAtrGateEnabled", True))
    _gate_mode = str(_auto_fsmms.get("fsmmsBodyAtrGateMode", "SHADOW") or "SHADOW").upper()
    _base_min_body = float(_auto_fsmms.get("fsmmsMinBodyAtr", 0.70) or 0.70)
    _adaptive = bool(_auto_fsmms.get("fsmmsAdaptiveBodyAtr", True))
    _min_body = _base_min_body
    if _adaptive:
        # Compression needs a slightly lower threshold to avoid suppressing genuine
        # early expansion. High-volatility/SHOCK conditions demand more conviction,
        # unless already qualified as a dedicated shock impulse.
        _regime_name = str((_regime_info or {}).get("regime") or "").lower()
        if "compression" in _regime_name or atr5 <= max(float(auto_cfg.get("fsmmsLowVolAtr", 3.0) or 3.0), 1e-9):
            _min_body = max(0.50, _base_min_body - 0.10)
        elif "expansion" in _regime_name or "shock" in _regime_name:
            _min_body = min(0.85, _base_min_body + 0.05)
    if _gate_enabled and _gate_mode != "OFF" and not shock_impulse and _body < _min_body:
        _gate_info = {"bodyAtr": round(_body, 3), "minBodyAtr": round(_min_body, 3),
                      "mode": _gate_mode, "adaptive": _adaptive}
        if _gate_mode == "ENFORCE":
            _arm_fast_retest(side, trigger_candles, atr5, f"body {_body:.2f}ATR < {_min_body:.2f} adaptive minimum")
            res = {"ok": False, "armedRetest": True,
                   "reason": f"Body {_body:.2f} ATR below {_min_body:.2f} adaptive minimum. Weak print blocked; retest tracker armed.",
                   **_gate_info, "side": side, "displacementAtr": round(displacement_atr, 2)}
            return _fs_publish(res, now)
        # SHADOW: preserve the candidate and expose telemetry for journal analysis.
        context_label = f"{context_label}|body-gate-shadow"

    # Don't chase if the trigger candle closed too far from M5 EMA20. Let V12.44 Impulse Retest handle it.
    extension_atr = abs(c - ema20) / max(atr5, 1e-9)
    if shock_impulse:
        max_ext = min(max_ext, float(auto_cfg.get("shockImpulseMaxStretchAtr", 1.25) or 1.25))
    if extension_atr > max_ext and not reversal_setup:
        _arm_fast_retest(side, trigger_candles, atr5, f"extension {extension_atr:.2f} ATR > {max_ext:.2f}")
        res = {"ok": False, "armedRetest": True, "reason": f"Fast sniper armed retest instead of chasing: extension {extension_atr:.2f} ATR > {max_ext:.2f}. Retest tracker is LIVE: a pullback into the retrace zone with a rejection close will trigger the continuation entry automatically.", "side": side, "displacementAtr": round(displacement_atr, 2), "latencyMs": round((time.perf_counter()-started)*1000)}
        return _fs_publish(res, now)

    min_stop = float(ai_cfg.get("minXauStopPoints", 7.0) or 7.0)
    stop_dist = max(min_stop, atr5 * 1.05)
    entry = _fs_float(market.get("ask") if side == "BUY" else market.get("bid"), _fs_float(market.get("price"), c))
    if side == "BUY":
        structural = min(recent_low, l) - 0.15 * atr5
        sl = min(entry - stop_dist, structural)
        risk = max(entry - sl, min_stop)
        tp1, tp2, tp3, tp4 = entry + risk, entry + risk*1.8, entry + risk*2.8, entry + risk*4.0
    else:
        structural = max(recent_high, h) + 0.15 * atr5
        sl = max(entry + stop_dist, structural)
        risk = max(sl - entry, min_stop)
        tp1, tp2, tp3, tp4 = entry - risk, entry - risk*1.8, entry - risk*2.8, entry - risk*4.0

    confidence = 68.0
    if reversal_setup:
        confidence += 7.0
        confidence += 3.0 if reversal_meta.get("upperWickAtr", 0) >= 0.6 or reversal_meta.get("lowerWickAtr", 0) >= 0.6 else 0.0
    elif trigger_pattern == "pullback-reclaim":
        # Reclaim entries are deliberately cleaner but less explosive; reward EMA retest + context,
        # not only large candle body. This prevents a good scout from being scored below threshold
        # simply because it is not a breakout candle.
        confidence += 4.0
        confidence += 3.0 if (recent_retest_ema20 or recent_retest_ema50) else 0.0
    else:
        confidence += min(10.0, max(0.0, (displacement_atr - min_disp) * 8.0))
    confidence += 5.0 if quality == "STANDARD" else 2.0
    confidence += 4.0 if (side == "BUY" and ema20 >= ema50) or (side == "SELL" and ema20 <= ema50) else 0.0
    confidence += 3.0 if spread <= max_spread * 0.75 else 0.0
    if mtf_matrix.get("enabled", False):
        confidence += max(-10.0, min(8.0, float(mtf_matrix.get("score", 0.0) or 0.0) * 12.0))
    confidence = round(min(92.0, max(50.0, confidence)), 1)
    min_conf = float(auto_cfg.get("fastSniperMinConfidence", 76.0) or 76.0)
    # Transition scout entries are intentionally smaller and earlier. Allow a small near-threshold
    # buffer so 71.5 vs 72 does not become a hard miss in London momentum conditions.
    eff_min_conf = min_conf
    if quality == "SCOUT" and context_label in {"transition", "transition-reclaim", "mixed-higher-tf"}:
        eff_min_conf = max(68.0, min_conf - 4.0)
    if confidence < eff_min_conf:
        res = {"ok": False, "reason": f"Fast sniper confidence {confidence:.0f}% < {eff_min_conf:.0f}%.", "displacementAtr": round(displacement_atr, 2), "latencyMs": round((time.perf_counter()-started)*1000)}
        return _fs_publish(res, now)

    decision = {
        "ok": True,
        "action": "TAKE_TRADE",
        # V13.11: every entry is stamped with the regime it was taken in, so the journal can
        # answer "which engine pays in which weather" — the question the switcher will be tuned by.
        "marketRegime": _regime_info.get("regime"),
        "regimeInfo": _regime_info,
        "quality": quality,
        "confidence": confidence,
        "side": side,
        "symbol": symbol,
        "strategy": "Fast Sniper M5/M15 Momentum Shift",
        "selectedStrategy": {"name": "Fast Sniper M5/M15 Momentum Shift"},
        "reason": (f"Fast sniper {side}: M5 {trigger_pattern} trigger ({displacement_atr:.2f} ATR body), "
                   f"M15/M30/H1/H4/D1 matrix {context_label} ({mtf_matrix.get('summary')}), RSI {rsi5:.0f}. Tick used only for final price/spread."),
        "decisionBlocks": [],
        "softBlocks": [],
        "features": {"fastSniper": True, "triggerTf": trigger_tf, "contextTf": context_tf, "rsi5": round(rsi5,1), "displacementAtr": round(displacement_atr,2), "extensionAtr": round(extension_atr,2), "triggerPattern": trigger_pattern, "reversalMeta": reversal_meta if reversal_setup else {}, "mtfScore": mtf_matrix.get("score"), "mtfSummary": mtf_matrix.get("summary")},
        "mtfMatrix": mtf_matrix,
        "tradePlan": {"entry": round(entry, 3), "sl": round(sl, 3), "tp1": round(tp1, 3), "tp2": round(tp2, 3), "tp3": round(tp3, 3), "tp4": round(tp4, 3), "rr": 1.8, "reason": "M5/M15 fast-lane momentum shift"},
        "latencyMs": round((time.perf_counter() - started) * 1000),
    }
    FAST_SNIPER_STATE.update({"last": decision, "lastAt": now})
    return decision
def _effective_auto_loop_sleep() -> float:
    auto_cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    if auto_cfg.get("fastSniperEnabled", True):
        return max(0.5, min(float(auto_cfg.get("fastSniperLoopSeconds", 1.0) or 1.0), 3.0))
    return 3.0


INDEX_NO_STORE = {"Cache-Control": "no-store, max-age=0, must-revalidate"}

def _serve_index_with_overlay():
    """V12.78 — serve index.html with a runtime overlay injected by the BACKEND.

    The compiled dashboard can lag behind the source for weeks (npm never run). Instead of
    hoping the user notices a changelog line, the served HTML itself now carries:
      * a fixed banner when the bundle is stale (with the exact rebuild command), and
      * a floating "Tools" button linking to /tools (purge, CSV/PDF export, diagnostics),
    both appended to <body>, outside the React root — the old bundle cannot hide them and
    React never reconciles them. Zero effect once the bundle is rebuilt (banner disappears,
    the Tools button stays as a small convenience).
    """
    index_file = FRONTEND_DIST / "index.html"
    if not index_file.exists():
        return JSONResponse({"ok": False, "message": "Frontend build not found. Run npm run build or use start_frontend.bat."}, status_code=404)
    try:
        html = index_file.read_text(encoding="utf-8")
        bs = _frontend_build_status()
        banner = ""
        if bs.get("stale"):
            banner = (
                "<div id='gm-stale' style=\"position:fixed;top:0;left:0;right:0;z-index:99999;"
                "background:#2a1f10;color:#c9a961;border-bottom:1px solid #c9a961;"
                "font:12px/1.5 -apple-system,Segoe UI,sans-serif;padding:8px 14px;text-align:center\">"
                "&#9888;&#65039; <b>OLD DASHBOARD BUILD</b> — new features exist but are not compiled. "
                "Run <code style='background:#0e1116;padding:2px 6px;border-radius:4px'>cd frontend && npm install && npm run build</code>, "
                "restart, then Ctrl+F5. Meanwhile use <a href='/tools' style='color:#e6c98a'>/tools</a>."
                "<span onclick=\"this.parentNode.style.display='none'\" style='float:right;cursor:pointer;padding:0 6px'>&#10005;</span></div>")
        tools_btn = (
            "<a id='gm-tools' href='/tools' title='GodMode Tools: purge, exports, diagnostics' "
            "style=\"position:fixed;bottom:18px;right:18px;z-index:99998;background:#161a21;"
            "color:#c9a961;border:1px solid #c9a961;border-radius:24px;padding:9px 16px;"
            "font:600 12px -apple-system,Segoe UI,sans-serif;text-decoration:none;"
            "box-shadow:0 4px 18px rgba(0,0,0,.45)\">&#9881;&#65039; Tools</a>")
        html = html.replace("</body>", banner + tools_btn + "</body>") if "</body>" in html else html + banner + tools_btn
        return HTMLResponse(html, headers=INDEX_NO_STORE)
    except Exception:
        return FileResponse(index_file, headers=INDEX_NO_STORE)


@app.get("/", include_in_schema=False)
def root():
    if (FRONTEND_DIST / "index.html").exists():
        return _serve_index_with_overlay()
    return {"ok": True, "message": "GodMode API running", "docs": "/docs", "ui": "frontend/dist not found"}


@app.get("/api/root")
def api_root():
    return {"ok": True, "message": "GodMode API running", "docs": "/docs"}


def _compose_readiness(
    *,
    mt5: dict[str, Any],
    market: dict[str, Any],
    unresolved: list[Any],
    health: dict[str, Any],
    priority_health: dict[str, Any],
    persistence_writable: bool,
    validation: dict[str, Any],
    tick_guard: dict[str, Any],
    certification: dict[str, Any],
    component_diagnostics: dict[str, Any] | None = None,
    stale_component_blockers: list[str] | None = None,
) -> dict[str, Any]:
    """Compose readiness from already-collected values without I/O."""
    connected = bool(mt5.get("connected"))
    live_enabled = bool(mt5.get("liveTradingEnabled"))
    execution_cfg = SETTINGS_STATE.get("execution", {}) if isinstance(SETTINGS_STATE.get("execution"), dict) else {}

    required_health: set[str] = set()
    if connected:
        required_health.add("reconciliation")
    if connected and live_enabled:
        required_health.update({"auto_loop", "trade_protection", "event_loop"})
        auto = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
        if str(auto.get("mql5ControlFilePath") or "").strip():
            required_health.add("mql5_control_bridge")
    unhealthy = [
        name for name in required_health
        if name not in health or not health.get(name, {}).get("ok") or health.get(name, {}).get("stale")
    ]

    priority_required = bool(
        connected and live_enabled and execution_cfg.get("autoTradingEnabled")
        and (SETTINGS_STATE.get("automation") or {}).get("earlyIntentEnabled", True)
    )
    priority_unhealthy = bool(priority_required and priority_health.get("taskPresent") and not priority_health.get("ok"))
    block_readiness_requested = bool((SETTINGS_STATE.get("validation") or {}).get("blockReadiness", False))
    certification_required = bool((SETTINGS_STATE.get("execution") or {}).get("requireLiveCertification", True))

    app_reasons: list[str] = []
    app_warnings: list[str] = []
    if not persistence_writable:
        app_reasons.append("Persistence directory is not writable")
    app_ready = not app_reasons

    gates: list[dict[str, Any]] = []

    def gate(name: str, passed: bool, message: str, category: str = "critical") -> None:
        gates.append({"name": name, "passed": bool(passed), "message": message, "category": category})

    gate("MT5", connected, "MT5 connected" if connected else "MT5 is disconnected")
    gate("Live trading", live_enabled, "Live trading enabled" if live_enabled else "Live Trading is OFF")
    dry_run = bool(execution_cfg.get("dryRun", not live_enabled))
    gate("Dry run", not dry_run, "Dry run disabled" if not dry_run else "Dry Run is ON")
    market_open = bool(market.get("open", False))
    gate("Market", market_open, "Market is open" if market_open else str(market.get("reason") or "Market is closed"))
    kill_active = bool(kill_switch.status().get("active"))
    gate("Kill switch", not kill_active, "Kill switch clear" if not kill_active else "Kill switch active")
    gate("Broker reconciliation", not unresolved, "No unresolved broker commands" if not unresolved else f"{len(unresolved)} unresolved broker command(s)")
    validation_ok = bool(validation.get("passed")) if validation.get("enabled") else True
    gate("Validation", validation_ok, "Validation passed" if validation_ok else "Validation gate not passed")
    certification_ok = bool(certification.get("approved")) or not certification_required
    gate("Certification", certification_ok, "Live certification approved" if certification_ok else "Live runtime certification incomplete")
    tick_guard_ok = not (connected and live_enabled and tick_guard.get("required")) or bool(tick_guard.get("ok"))
    gate("Tick Guard", tick_guard_ok, "Tick Guard attested" if tick_guard_ok else str(tick_guard.get("message") or "Tick Guard heartbeat not attested"))
    runtime_ok = not unhealthy
    gate("Trading loops", runtime_ok, "Critical trading loops healthy" if runtime_ok else "Critical component unhealthy: " + ", ".join(sorted(unhealthy)))
    priority_ok = not priority_unhealthy
    gate("Priority Intent", priority_ok, "Priority Intent healthy" if priority_ok else f"Priority Intent unhealthy: {priority_health.get('status')} ({priority_health.get('runtimeStatus')})")

    for blocker in stale_component_blockers or []:
        gate("Readiness component", False, blocker)

    execution_blockers = [row["message"] for row in gates if row["category"] == "critical" and not row["passed"]]
    trading_ready = bool(app_ready and not execution_blockers)

    if not connected:
        app_warnings.append("MT5 not connected")
    if not live_enabled:
        app_warnings.append("Live Trading is OFF")
    if not market_open:
        app_warnings.append("Market is closed")
    if validation.get("enabled") and not validation_ok:
        app_warnings.append(
            "Validation gate not passed; live orders remain protected"
            + (" (legacy blockReadiness ignored for UI availability)" if block_readiness_requested else "")
        )
    if not certification_ok:
        app_warnings.append("Live certification is incomplete; live entries remain locked")

    authority = {
        "armed": trading_ready,
        "state": "ARMED" if trading_ready else "BLOCKED",
        "blockers": execution_blockers,
        "gates": gates,
    }
    return {
        "ok": app_ready,
        "ready": app_ready,
        "appReady": app_ready,
        "tradingReady": trading_ready,
        "executionAuthority": authority,
        "version": APP_VERSION,
        "buildId": BUILD_ID,
        "engineInstance": ENGINE_INSTANCE_ID,
        "mt5Connected": connected,
        "liveTradingEnabled": live_enabled,
        "marketOpen": market_open,
        "unresolvedCount": len(unresolved),
        "validationPassed": validation_ok,
        "persistenceWritable": persistence_writable,
        "tickGuard": tick_guard,
        "liveCertification": certification,
        "reasons": app_reasons,
        "warnings": app_warnings,
        "executionBlockers": execution_blockers,
        "readinessComponents": component_diagnostics or {},
        "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
    }


def _authoritative_readiness() -> dict[str, Any]:
    # blockReadiness remains an execution-policy control only; it must never make
    # the operator UI or backend application appear unavailable.
    """Synchronous diagnostic probe retained for tests and explicit deep diagnostics.

    Live order admission and the readiness background producer do not call this
    function. They use the componentised cache so slow certification/validation
    work cannot delay entries or create repeating executor rotations.
    """
    mt5 = mt5_bridge.status()
    connected = bool(mt5.get("connected"))
    live_enabled = bool(mt5.get("liveTradingEnabled"))
    market = _market_state()
    unresolved = EXECUTION_LEDGER.unresolved()
    health = RUNTIME_HEALTH.snapshot({
        "auto_loop": 60, "priority_intent_loop": 5, "telegram": 120,
        "market_data": 60, "trade_protection": 20, "mql5_control_bridge": 30, "event_loop": 5,
    })
    validation = _validation_status()
    tick_guard = _tick_guard_heartbeat_status() if connected and live_enabled else _tick_guard_probe()
    certification = _live_certification_status()
    return _compose_readiness(
        mt5=mt5, market=market, unresolved=unresolved, health=health,
        priority_health=_priority_intent_health(),
        persistence_writable=DATA_DIR.exists() and os.access(DATA_DIR, os.W_OK),
        validation=validation, tick_guard=tick_guard, certification=certification,
    )


def _compose_cached_readiness() -> dict[str, Any]:
    """O(1) readiness aggregate from independently refreshed component snapshots."""
    components = _readiness_component_snapshots()
    execution_cfg = SETTINGS_STATE.get("execution", {}) if isinstance(SETTINGS_STATE.get("execution"), dict) else {}
    automation_cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    stale_blockers: list[str] = []

    def component_payload(name: str, fallback: Any, *, required: bool) -> Any:
        row = components.get(name) or {}
        payload = row.get("payload")
        if required and not row.get("fresh"):
            label = {
                "tickGuard": "Tick Guard", "certification": "Certification",
                "validation": "Validation", "unresolved": "Broker reconciliation",
            }.get(name, name)
            age = row.get("lastSuccessAgeSeconds")
            detail = f" ({age}s old)" if age is not None else " (not collected)"
            stale_blockers.append(f"{label} readiness data stale{detail}")
        return deepcopy(payload) if payload is not None else deepcopy(fallback)

    mt5 = component_payload(
        "mt5Status", {"connected": False, "liveTradingEnabled": False}, required=True,
    )
    market = component_payload(
        "market", {"open": False, "reason": "Market readiness data unavailable."}, required=True,
    )
    connected = bool(mt5.get("connected"))
    live_enabled = bool(mt5.get("liveTradingEnabled"))

    tick_required = bool(connected and live_enabled and automation_cfg.get("requireTickGuardForLive", False))
    certification_required = bool(execution_cfg.get("requireLiveCertification", True) and connected and live_enabled)
    validation_required = bool((SETTINGS_STATE.get("validation") or {}).get("enabled", False) and connected and live_enabled)
    unresolved_required = bool(connected)

    validation = component_payload("validation", {"enabled": validation_required, "passed": False}, required=validation_required)
    tick_guard = component_payload(
        "tickGuard",
        {"required": tick_required, "ok": False, "message": "Tick Guard readiness data unavailable."},
        required=tick_required,
    )
    certification = component_payload("certification", {"approved": False}, required=certification_required)
    unresolved = component_payload("unresolved", [{"status": "unknown"}], required=unresolved_required)
    if not isinstance(unresolved, list):
        unresolved = [{"status": "invalid_cached_value"}]

    health = RUNTIME_HEALTH.snapshot({
        "auto_loop": 60, "priority_intent_loop": 5, "telegram": 120,
        "market_data": 60, "trade_protection": 20, "mql5_control_bridge": 30, "event_loop": 5,
    })
    return _compose_readiness(
        mt5=mt5, market=market, unresolved=unresolved, health=health,
        priority_health=_priority_intent_health(),
        persistence_writable=DATA_DIR.exists() and os.access(DATA_DIR, os.W_OK),
        validation=validation, tick_guard=tick_guard, certification=certification,
        component_diagnostics=components, stale_component_blockers=stale_blockers,
    )

