@app.get("/api/readiness")
def readiness():
    # Always return the latest immutable snapshot immediately. A degraded trading state
    # is represented in the JSON, not by blocking the operator UI with a slow 503 path.
    return JSONResponse(_cached_readiness_snapshot(), status_code=200, headers={"Cache-Control":"no-store"})

@app.post("/api/readiness/refresh")
async def readiness_refresh():
    _register_readiness_components()
    results = await READINESS_COMPONENT_MONITOR.refresh_all(force=True)
    payload = _publish_readiness_snapshot()
    timed_out = [name for name, row in results.items() if row.get("timedOut")]
    failed = [name for name, row in results.items() if not row.get("ok") and not row.get("timedOut")]
    if timed_out:
        message = "Refresh completed with component(s) still running: " + ", ".join(sorted(timed_out))
    elif failed:
        message = "Refresh completed using last-known-good component data: " + ", ".join(sorted(failed))
    else:
        message = "Readiness components refreshed successfully"
    cached = _cached_readiness_snapshot()
    return {**cached, "ok": not timed_out and not failed, "message": message, "refreshResults": results}

@app.get("/api/runtime/lanes")
def runtime_lanes():
    pressure = _live_runtime_pressure()
    with JOBS_LOCK:
        research = [deepcopy(row) for row in JOBS.values() if row.get("status") in {"queued", "running"}]
    return {
        "ok": True, "buildId": BUILD_ID,
        "readiness": {"name": "readiness", "mode": "component-kernel", "healthy": True},
        "readinessComponents": _readiness_component_snapshots(),
        "researchPressure": pressure,
        "activeResearchJobs": len(research),
        "researchJobs": [{k:v for k,v in row.items() if k not in {"result"}} for row in research[:5]],
        "priorityIntent": _priority_intent_health(),
    }

@app.get("/api/status")
def status():
    mt5 = mt5_bridge.status()
    demo = _demo_enabled()
    mkt = _market_state()
    connected = bool(mt5.get("connected"))
    RUNTIME_HEALTH.beat("market_data", "status sampled", connected=connected, demo=demo)
    # Explicit truth flags: dataSource says whether numbers are REAL or synthetic; tradingAllowed says
    # whether a live order could actually be placed right now. Demo/synthetic data can NEVER set
    # tradingAllowed=True, so the UI/automation can't mistake simulated data for a live, tradable state.
    live_enabled = bool(mt5.get("liveTradingEnabled"))
    execution_settings = (
        SETTINGS_STATE.get("execution", {})
        if isinstance(SETTINGS_STATE.get("execution"), dict)
        else {}
    )
    dry_run = bool(execution_settings.get("dryRun", not mt5_bridge.live_enabled))
    base_trading_allowed = bool(
        connected
        and live_enabled
        and not dry_run
        and mkt.get("open", False)
        and not kill_switch.status().get("active")
    )
    execution_gate = (
        _execution_validation_check("status")
        if base_trading_allowed
        else {"ok": False}
    )
    trading_allowed = bool(base_trading_allowed and execution_gate.get("ok"))
    data_source = "live_mt5" if connected else ("synthetic_demo" if demo else "offline")
    return {
        "app": "GodMode Gold Trading Bot",
        "version": APP_VERSION,
        "buildId": BUILD_ID,
        "liveConnection": connected,
        "mt5Connected": connected,
        "marketSession": mt5_bridge.current_session(),
        "marketOpen": bool(mkt.get("open", False)),
        "marketStatus": mkt.get("reason", ""),
        "riskEngine": "ACTIVE" if not kill_switch.status().get("active") else "BLOCKED",
        "agentStatus": "Live" if connected else ("Demo" if demo else "Waiting for MT5"),
        "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "mt5": mt5,
        "demo": demo,
        "dataSource": data_source,
        "tradingAllowed": trading_allowed,
        "executionMode": "DRY_RUN" if dry_run else ("LIVE" if live_enabled else "DISABLED"),
        "tradingBlockedReason": "" if trading_allowed else (
            "MT5 not connected" if not connected else
            "Live Trading is OFF" if not live_enabled else
            "Dry-run mode is ON" if dry_run else
            "Market closed" if not mkt.get("open", False) else
            "Kill switch active" if kill_switch.status().get("active") else
            str(execution_gate.get("message") or "Execution safety gate blocked")),
        "source": "demo" if demo else mt5.get("source", "not_connected"),
        "security": {"corsRestricted": True, "apiKeyEnabled": bool(api_key), "rateLimitPerMinute": rate_limit_per_minute},
    }


@app.get("/api/health/full")
def health_full():
    """V13.26 HEALTH CENTER — one honest aggregate of every subsystem. Each component reports a
    real status derived from live state (never a hardcoded green). 'dataSource' distinguishes REAL
    MT5 data from synthetic demo so a demo UI can never masquerade as live."""
    mt5 = mt5_bridge.status()
    connected = bool(mt5.get("connected"))
    demo = _demo_enabled()
    mkt = _market_state()
    ks = kill_switch.status()
    live_enabled = bool(mt5.get("liveTradingEnabled"))
    execution_settings = (
        SETTINGS_STATE.get("execution", {})
        if isinstance(SETTINGS_STATE.get("execution"), dict)
        else {}
    )
    dry_run = bool(execution_settings.get("dryRun", not mt5_bridge.live_enabled))
    certification_required = bool(
        execution_settings.get("requireLiveCertification", True)
    )
    certification = _live_certification_status()
    runtime_health = RUNTIME_HEALTH.snapshot({"event_loop": 5})
    event_loop_health = runtime_health.get("event_loop", {})
    base_trading_allowed = bool(
        connected
        and live_enabled
        and not dry_run
        and mkt.get("open", False)
        and not ks.get("active")
    )
    execution_gate = (
        _execution_validation_check("health_status")
        if base_trading_allowed
        else {"ok": False, "message": "Base live-trading prerequisites are not met."}
    )
    trading_allowed = bool(base_trading_allowed and execution_gate.get("ok"))
    data_source = "live_mt5" if connected else ("synthetic_demo" if demo else "offline")

    now = time.time()
    # V13.33 — TRUE engine liveness is loopAliveAt (updated every loop iteration regardless of
    # whether auto-trade is on). The old check used "last decision logged", which only updates when
    # auto-trading FIRES — so with auto OFF it falsely reported the engine DOWN. Use both signals:
    # loop alive = engine running; last decision = separate info.
    loop_alive_at = float(AUTO_TRADE_STATE.get("loopAliveAt", 0.0) or 0.0)
    loop_age = round(now - loop_alive_at, 1) if loop_alive_at else None
    scan_alive = (loop_age is not None and loop_age < 60)   # V13.34: loop ticks ~1s but stacked MT5 job timeouts can take ~40s; 60s = genuinely stalled
    last_dec = DECISION_JOURNAL[0] if DECISION_JOURNAL else None
    last_dec_age = round(now - float(last_dec.get("epoch", 0)), 1) if last_dec else None
    _slowop = AUTO_TRADE_STATE.get("lastSlowOperation") if isinstance(AUTO_TRADE_STATE.get("lastSlowOperation"), dict) else None

    def _feed(key):
        c = FEED_STATUS_CACHE.get(key) if isinstance(FEED_STATUS_CACHE, dict) else None
        if not c: return {"status": "unknown", "live": False, "detail": "no data yet"}
        return {"status": c.get("status", "unknown"), "live": c.get("status") == "live",
                "detail": c.get("detail", ""), "cachedLive": bool(c.get("_wasLive"))}

    components = [
        {"id": "mt5", "label": "MT5 Connection",
         "status": "up" if connected else ("demo" if demo else "down"),
         "detail": mt5.get("source", "not connected") if connected else ("Synthetic demo data" if demo else "MT5 bridge not connected"),
         "critical": True, "reconnect": "/api/mt5/connect"},
        {"id": "dataSource", "label": "Data Source",
         "status": "up" if data_source == "live_mt5" else ("warn" if data_source == "synthetic_demo" else "down"),
         "detail": {"live_mt5": "REAL live MT5 prices", "synthetic_demo": "DEMO — simulated data, NOT real", "offline": "No data"}[data_source],
         "critical": True},
        {"id": "trading", "label": "Live Trading",
         "status": "up" if trading_allowed else "warn",
         "detail": "Orders can be placed" if trading_allowed else (
             "MT5 not connected" if not connected else
             "Live Trading OFF" if not live_enabled else
             "Dry-run mode is ON — orders are simulated, not sent to MT5" if dry_run else
             "Market closed" if not mkt.get("open", False) else
             "Kill switch active" if ks.get("active") else
             str(execution_gate.get("message") or "Execution gate blocked")),
         "critical": True},
        {"id": "liveCertification", "label": (
             "Local Live Runtime Attestation"
             if certification.get("certificationType") == "local_runtime"
             else "Unattended Enterprise Certification"
         ),
         "status": "up" if certification.get("approved") else "warn",
         "detail": (
             (
                 "The connected MT5 terminal, exact-build Tick Guard, persistence, event loop, protection loop and broker reconciliation are freshly attested."
                 if certification.get("certificationType") == "local_runtime"
                 else "A+ evidence bundle is valid for this exact build."
             )
             if certification.get("approved")
             else str(
                 certification.get("detail")
                 or certification.get("message")
                 or "; ".join(str(item) for item in certification.get("failures", [])[:3])
                 or "Required Windows/MT5, broker, failure-drill, and soak evidence is incomplete."
             )
         ),
         "critical": certification_required},
        {"id": "eventLoop", "label": "Event-Loop Latency Guard",
         "status": (
             "warn"
             if not event_loop_health
             else "up"
             if event_loop_health.get("ok") and not event_loop_health.get("stale")
             else "down"
         ),
         "detail": (
             str(event_loop_health.get("detail") or "Latency watchdog healthy.")
             if event_loop_health
             else "No watchdog sample yet; live entry remains subject to the runtime gate."
         ),
         "critical": True},
        {"id": "scanLoop", "label": "Decision Engine",
         "status": "up" if scan_alive else "down",
         "detail": ((f"Engine ALIVE — loop ticked {loop_age}s ago" + (f"; last entry decision {last_dec_age}s ago" if last_dec_age is not None else "; no entry decisions yet (auto-trade may be off)") + ((f"; SLOW: {_slowop.get('label')} took {_slowop.get('seconds')}s" + (" (TIMEOUT)" if _slowop.get('timeout') else "")) if (_slowop and (time.time()-float(_slowop.get('at',0)) < 30)) else "")) if scan_alive
                    else f"STALLED — loop hasn't ticked for {loop_age}s" + (f"; last slow op: {_slowop.get('label')} {_slowop.get('seconds')}s{' TIMEOUT' if _slowop.get('timeout') else ''}" if _slowop else "") if loop_age is not None
                    else "Engine has not started — no loop heartbeat yet"),
         "critical": True},
        {"id": "priorityIntent", "label": "Priority Intent Execution", **(lambda h: {
            "status": "up" if h.get("ok") else ("warn" if h.get("status") == "starting" else "down"),
            "detail": (
                f"{h.get('runtimeStatus')} — last scan {h.get('lastScanAgeSeconds')}s ago; target {h.get('expectedIntervalSeconds')}s"
                if h.get("lastScanAgeSeconds") is not None
                else f"{h.get('runtimeStatus')} — waiting for first priority scan"
            ) + (f"; blocker: {h.get('lastBlocker')}" if h.get("lastBlocker") else ""),
            "critical": bool((SETTINGS_STATE.get("automation") or {}).get("earlyIntentEnabled", True)),
        })(_priority_intent_health())},
        {"id": "autoLoop", "label": "Auto-Trade Loop", **(lambda: (lambda en, plu: {
            "status": "up" if en and now >= plu else "warn",
            "detail": ("Armed — auto-trading ON" if en and now >= plu
                       else f"PAUSED — cooldown/loss-streak active for {int((plu-now)/60)+1} more min" if en and plu > now
                       else "Auto-trading is OFF (enable it in Settings to trade automatically)"),
            "critical": True,
        })(bool((SETTINGS_STATE.get("execution") or {}).get("autoTradingEnabled")) and bool((SETTINGS_STATE.get("execution") or {}).get("liveTradingEnabled")) and not bool((SETTINGS_STATE.get("execution") or {}).get("dryRun", True)), float(AUTO_TRADE_STATE.get("postLossUntil", 0) or 0)))()},
        {"id": "journal", "label": "Journal Persistence",
         "status": "up" if JOURNAL_PERSIST_STATE.get("ok") is not False else "down",
         "detail": (JOURNAL_PERSIST_STATE.get("error") or "Writing to disk OK") if JOURNAL_PERSIST_STATE.get("ok") is not None else "No write yet this session",
         "critical": False},
        {"id": "riskEngine", "label": "Risk Engine / Kill Switch",
         "status": "up" if not ks.get("active") else "down",
         "detail": "Active — guarding" if not ks.get("active") else f"KILL SWITCH ACTIVE: {ks.get('reason','')}",
         "critical": True},
        {"id": "feedCalendar", "label": "Economic Calendar", **{k: v for k, v in {
            "status": "up" if _feed("economicCalendar")["live"] else "warn"}.items()},
         "detail": _feed("economicCalendar")["detail"] or "cached/idle", "critical": False},
        {"id": "feedNews", "label": "Market News",
         "status": "up" if _feed("marketNews")["live"] else "warn",
         "detail": _feed("marketNews")["detail"] or "cached/idle", "critical": False},
        {"id": "feedMacro", "label": "Macro Feed",
         "status": "up" if _feed("macro")["live"] else "warn",
         "detail": _feed("macro")["detail"] or "cached/idle", "critical": False},
    ]
    crit_down = [c for c in components if c.get("critical") and c["status"] == "down"]
    any_warn = [c for c in components if c["status"] == "warn"]
    overall = "healthy" if not crit_down and not any_warn else ("degraded" if not crit_down else "critical")

    return {
        "ok": True,
        "build": BUILD_ID,
        "overall": overall,
        "dataSource": data_source,
        "tradingAllowed": trading_allowed,
        "executionMode": "DRY_RUN" if dry_run else ("LIVE" if live_enabled else "DISABLED"),
        "liveCertification": certification,
        "eventLoopHealth": event_loop_health,
        "isRealData": data_source == "live_mt5",
        "timestamp": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "components": components,
        "summary": {
            "up": sum(1 for c in components if c["status"] == "up"),
            "warn": sum(1 for c in components if c["status"] == "warn"),
            "down": sum(1 for c in components if c["status"] == "down"),
            "criticalDown": [c["label"] for c in crit_down],
        },
        "config": {
            "conditionalTimeStop": bool((SETTINGS_STATE.get("trading", {}).get("tradeManagement", {}) or {}).get("conditionalTimeStopEnabled", True)),
            # V14.1.7/9 — surface the retained-peak fraction that ACTUALLY governs live trades.
            # profitLockFraction is a phantom knob (assigned then overwritten whenever
            # aiDynamicStopEnabled is True); six releases "fixed" it with zero behavioural
            # effect. Showing the effective value here means the operator can see the real
            # number instead of inferring it from a setting that does nothing.
            "effectiveRetainedPeakFraction": DEFAULTS.effective_retained_peak_fraction(
                bool((SETTINGS_STATE.get("trading", {}).get("tradeManagement", {}) or {}).get("aiDynamicStopEnabled", True))
            ),
            "profitLockFractionIsPhantom": bool(
                (SETTINGS_STATE.get("trading", {}).get("tradeManagement", {}) or {}).get("aiDynamicStopEnabled", True)
            ),
            "convictionTiering": bool((SETTINGS_STATE.get("automation") or {}).get("convictionTieringEnabled", False)),
            "htfAlignment": bool((SETTINGS_STATE.get("automation") or {}).get("htfTrendAlignment", False)),
        },
    }


@app.post("/api/mt5/connect")
def mt5_connect(payload: dict[str, Any] = Body(default={})):
    # Persist connection configuration through the same revisioned transaction before touching MT5.
    expected = payload.get("expectedRevision")
    patch: dict[str, Any] = {"mt5Connection": {}}
    for key in ("terminalPath", "server"):
        if payload.get(key) is not None:
            patch["mt5Connection"][key] = payload.get(key)
    if payload.get("login") is not None:
        patch["mt5Connection"]["login"] = str(payload.get("login") or "")
    if payload.get("password"):
        patch["mt5Connection"]["password"] = payload.get("password")
    try:
        if patch["mt5Connection"]:
            receipt = _commit_settings_patch(patch, reason="mt5_connection_config", expected_revision=int(expected) if expected is not None else None)
        else:
            receipt = {"revision": _settings_revision()}
        mt5_cfg = deepcopy(SETTINGS_STATE.get("mt5Connection") or {})
        connect_payload = {k: v for k, v in payload.items() if k != "expectedRevision"}
        result = mt5_bridge.connect({**mt5_cfg, **connect_payload, "symbol": SETTINGS_STATE.get("trading", {}).get("symbol", mt5_bridge.symbol), "magicNumber": SETTINGS_STATE.get("trading", {}).get("magicNumber", mt5_bridge.magic)})
        result["revision"] = receipt.get("revision")
        return result
    except SettingsConflictError as exc:
        return JSONResponse({"ok": False, "conflict": True, "message": str(exc), "currentRevision": exc.current}, status_code=409)
    except Exception as exc:
        return JSONResponse({"ok": False, "message": f"MT5 connection update failed: {exc}"}, status_code=500)


