@app.post("/api/telegram/save")
def telegram_save(payload: dict[str, Any] = Body(default={})):
    """Persist Telegram credentials independently from network testing.

    Saving must not depend on Telegram, DNS, firewall, chat permissions, or API availability.
    """
    incoming_token = str(payload.get("botToken") or "").strip()
    incoming_chat = str(payload.get("chatId") or "").strip()
    current = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
    token = str(current.get("botToken") or os.getenv("TELEGRAM_BOT_TOKEN", "")).strip() if incoming_token in {"", "••••••••", "********"} else incoming_token
    chat_id = incoming_chat or str(current.get("chatId") or os.getenv("TELEGRAM_CHAT_ID", "")).strip()
    if not token or not chat_id:
        return JSONResponse({"ok": False, "saved": False, "message": "Telegram bot token and chat ID are required."}, status_code=422)
    try:
        receipt = _commit_settings_patch({"telegram": {**payload, "enabled": bool(payload.get("enabled", True)), "botToken": token, "chatId": chat_id}}, reason="telegram_credentials_save")
        return {"ok": True, "saved": True, "configured": True, "message": "Telegram credentials saved. Use Send Test to verify delivery.", "revision": receipt.get("revision")}
    except Exception as exc:
        return JSONResponse({"ok": False, "saved": False, "message": f"Telegram credentials could not be saved: {exc}"}, status_code=500)


@app.post("/api/telegram/test")
def telegram_test(payload: dict[str, Any] = Body(default={})):
    import urllib.parse, urllib.request
    incoming_token = str(payload.get("botToken") or "").strip()
    current = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
    token = str(current.get("botToken") or os.getenv("TELEGRAM_BOT_TOKEN", "")).strip() if incoming_token in {"", "••••••••", "********"} else incoming_token
    chat_id = str(payload.get("chatId") or current.get("chatId") or os.getenv("TELEGRAM_CHAT_ID", "")).strip()
    if not token or not chat_id:
        return JSONResponse({"ok": False, "saved": False, "authenticated": False, "message": "Telegram bot token and chat ID are required."}, status_code=422)
    # Persist first. A failed send must never discard valid credentials.
    try:
        receipt = _commit_settings_patch({"telegram": {**payload, "enabled": bool(payload.get("enabled", True)), "botToken": token, "chatId": chat_id}}, reason="telegram_test_credentials_save")
    except Exception as exc:
        return JSONResponse({"ok": False, "saved": False, "authenticated": False, "message": f"Telegram credentials could not be saved: {exc}"}, status_code=500)
    text_msg = "GodMode Gold Bot Telegram test: alerts are connected."
    try:
        data = urllib.parse.urlencode({"chat_id": chat_id, "text": text_msg}).encode()
        req = urllib.request.Request(f"https://api.telegram.org/bot{token}/sendMessage", data=data, method="POST")
        parsed = _telegram_api_result(read_public_https(req, timeout=12), action="test message")
        if not parsed.get("ok"):
            return JSONResponse({**parsed, "saved": True, "authenticated": False, "configured": True, "revision": receipt.get("revision")}, status_code=502)
        return {**parsed, "saved": True, "authenticated": True, "configured": True, "message": "Telegram credentials saved and test sent.", "revision": receipt.get("revision")}
    except Exception as exc:
        return JSONResponse({"ok": False, "saved": True, "authenticated": False, "configured": True, "message": f"Credentials were saved, but Telegram test failed: {exc}"}, status_code=502)


@app.post("/api/telegram/recap")
def telegram_recap(payload: dict[str, Any] = Body(default={})):
    """Send a recap now and report the actual Telegram delivery outcome."""
    weekly = bool(payload.get("weekly"))
    recap_result = _send_recap(weekly)
    forecast_result: dict[str, Any] | None = None
    if payload.get("withForecast"):
        RECAP_STATE["lastWaitForecast"] = 0.0
        forecast_result = _send_wait_forecast()
    forecast_requested = bool(payload.get("withForecast"))
    recap_ok = bool(recap_result.get("ok"))
    forecast_ok = not forecast_requested or bool((forecast_result or {}).get("ok"))
    response = {
        "ok": recap_ok and forecast_ok,
        "message": recap_result.get("message") or f"{'Weekly' if weekly else 'Daily'} recap delivery failed.",
        "chartsAvailable": chart_render.available(),
        "recap": recap_result,
        "forecast": forecast_result,
    }
    if response["ok"]:
        response["message"] = f"{'Weekly' if weekly else 'Daily'} recap sent successfully." + (" Forecast sent successfully." if forecast_requested else "")
        return response
    failed_result = recap_result if not recap_ok else (forecast_result or {})
    response["message"] = str(failed_result.get("message") or response["message"])
    status_code = 409 if failed_result.get("skipped") else 502
    return JSONResponse(response, status_code=status_code)


