def _epoch_of(v: Any) -> float | None:
    """V13.6 — parse the bridge's '%Y-%m-%d %H:%M:%S UTC' timestamps into a UTC epoch so the
    journal can fuzzy-match a closed trade back to its entry context. Returns None on anything
    unparseable, which match() treats as 'no time evidence' rather than a wrong match."""
    if v in (None, ""):
        return None
    if isinstance(v, (int, float)):
        return float(v)
    try:
        s = str(v).strip().replace(" UTC", "")
        return _dt.strptime(s, "%Y-%m-%d %H:%M:%S").replace(tzinfo=_tz.utc).timestamp()
    except Exception:
        return None


def _vetting_journal_rows(days: int = 30) -> list[dict[str, Any]]:
    """V12.74 — assemble the full vetting-grade journal: every closed trade joined with its
    entry context (strategy, confidence, reason) and any AI-audit outcome. One flat row per
    trade so CSV/PDF exports can be analysed in Excel or handed to a reviewer."""
    history = _live_trades().get("history") or []
    audit_by_ticket: dict[str, dict[str, Any]] = {}
    try:
        if AUDIT_OUTCOMES_FILE.exists():
            for ln in AUDIT_OUTCOMES_FILE.read_text(encoding="utf-8").splitlines():
                if ln.strip():
                    rec = json.loads(ln)
                    audit_by_ticket[str(rec.get("ticket"))] = rec
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_7421", _suppressed_exc)
    rows: list[dict[str, Any]] = []
    for t in history:
        if not isinstance(t, dict):
            continue
        ticket = str(t.get("ticket") or "")
        # V13.6: was trade_context.get(ticket, positionId) — a STRICT lookup. MT5 closes a trade
        # under a different deal id than the order id we recorded at entry, so this missed on
        # essentially every trade, and every ctx-derived column (sl, confidence, session,
        # entryReason, quality) exported BLANK — 0/200 populated in Johnson's journal. match()
        # already existed for exactly this: exact ticket first, then fuzzy attribution on
        # symbol/side/entry/time. Use it, so the journal can actually explain itself.
        ctx = trade_context.match(
            ticket, t.get("positionId"), t.get("symbol"), t.get("direction"),
            _to_float(t.get("entryPrice")), _epoch_of(t.get("openTime")),
        ) or trade_context.get(ticket, t.get("positionId")) or {}
        aud = audit_by_ticket.get(ticket, {})
        entry = _to_float(t.get("entryPrice")); exitp = _to_float(t.get("exitPrice"))
        sl = _to_float(ctx.get("sl") or t.get("sl")); pnl = _to_float(t.get("pnlUsd"))
        risk = abs(entry - sl) if entry and sl else 0.0
        r_mult = round(((exitp - entry) if t.get("direction") == "BUY" else (entry - exitp)) / risk, 2) if risk else None
        hold_s = _to_float(t.get("holdTime"))
        rows.append({
            "closeTime": t.get("closeTime"), "openTime": t.get("openTime"),
            "ticket": ticket, "symbol": t.get("symbol"), "side": t.get("direction"),
            "lots": t.get("lots"), "entry": entry, "exit": exitp, "sl": sl or "",
            "pnlUsd": pnl, "rMultiple": r_mult if r_mult is not None else "",
            "holdMinutes": round(hold_s / 60, 1) if hold_s else "",
            "outcome": "WIN" if pnl > 0 else "LOSS" if pnl < 0 else "FLAT",
            "strategy": ctx.get("strategy") or t.get("strategy") or "",
            "confidence": ctx.get("confidence") or "",
            "session": ctx.get("session") or "",
            "quality": ctx.get("quality") or "",
            "entryReason": str(ctx.get("reason") or "")[:220],
            "exitReason": str(t.get("exitReason") or "")[:160],
            # V13.6: THE columns that were missing. mfeR/maeR are already captured on every close
            # (V12.80) into trade_context — they were just never exported, which is exactly why
            # "would a tighter stop have killed this winner?" was unanswerable. maeR = worst R the
            # trade went against you BEFORE it resolved. Now every loss-cap question is testable.
            # V13.12: regime was recorded at entry (V13.11) but never exported — the whole point
            # of stamping it was "which engine pays in which weather", which needs the column.
            "regime": ctx.get("regime") or "",
            "maeR": ctx.get("maeR", ""),
            "mfeR": ctx.get("mfeR", ""),
            "riskBasis": ctx.get("riskBasis", ""),
            "beMoved": ctx.get("beMoved", ""),
            "checksSeen": ctx.get("checksSeen", ""),
            "aiAuditVerdict": aud.get("verdict") or "",
            "aiAuditReason": str(aud.get("reason") or "")[:160],
            "comment": str(t.get("comment") or "")[:60],
        })
    return rows


DATA_EPOCH_FILE = DATA_DIR / "data_epoch.json"
_HISTORY_EPOCH_CACHE: dict[str, float] = {"value": 0.0}   # declared before use; primed at boot

def _history_epoch() -> float:
    """V12.75 — unix timestamp before which broker deals are IGNORED.

    Every version of the bot has used the same magic number and 'GODMODE_' comment prefix,
    so `_is_bot_record()` claims deals from EVERY past version as current-version trades.
    That is why old trades kept reappearing after upgrades and why analytics/calibration
    were polluted by results from engines that no longer exist. Purging sets this epoch to
    'now', which hides prior deals from every read path at once — without deleting anything
    on the broker side.
    """
    try:
        if DATA_EPOCH_FILE.exists():
            return float(json.loads(DATA_EPOCH_FILE.read_text(encoding="utf-8")).get("epoch", 0) or 0)
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_7492", _suppressed_exc)
    return 0.0


def _set_history_epoch(epoch: float, reason: str = "manual_purge") -> None:
    try:
        DATA_EPOCH_FILE.write_text(json.dumps(
            {"epoch": float(epoch), "reason": reason,
             "setAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}), encoding="utf-8")
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_7502", _suppressed_exc)


def _after_epoch(row: dict[str, Any]) -> bool:
    """True if a trade row is on/after the active data epoch. Cheap: one float compare."""
    ep = _HISTORY_EPOCH_CACHE["value"]
    if ep <= 0:
        return True
    for key in ("closeEpoch", "closeTs", "openEpoch", "timestamp"):
        v = row.get(key)
        if v:
            try:
                return float(v) >= ep
            except Exception:
                continue
    for key in ("closeTime", "openTime"):
        v = row.get(key)
        if v:
            # Parse once, then stash the numeric epoch back on the row. Trade rows are re-filtered
            # on every refresh; strptime is ~6us/row, the cached compare is ~0.14us/row.
            cached = row.get("_epochTs")
            if cached is not None:
                return float(cached) >= ep
            try:
                ts = time.mktime(time.strptime(str(v)[:19], "%Y-%m-%d %H:%M:%S"))
                row["_epochTs"] = ts
                return ts >= ep
            except Exception:
                continue
    return True   # undated rows are never hidden


_HISTORY_EPOCH_CACHE["value"] = _history_epoch()   # one disk read at boot; O(1) float compare thereafter


def _auto_epoch_on_version_change(current_version: str) -> None:
    """V12.76 — a new bot version must never inherit the previous engine's trades.

    Because every version shares the same magic number and 'GODMODE_' comment prefix, a fresh
    build silently adopts all past deals into analytics, calibration and the AI coach. On the
    first boot of a NEW version we stamp the data epoch to 'now', so only trades taken by THIS
    engine onward are counted. Nothing is deleted on the broker; older trades are simply not
    attributed to the current engine. Set GODMODE_KEEP_HISTORY_ON_UPGRADE=1 to opt out.
    """
    if os.getenv("GODMODE_KEEP_HISTORY_ON_UPGRADE", "").strip() in {"1", "true", "yes"}:
        return
    marker = DATA_DIR / "engine_version.json"
    try:
        prev = json.loads(marker.read_text(encoding="utf-8")).get("version", "") if marker.exists() else ""
    except Exception:
        prev = ""
    if prev == current_version:
        return
    now = time.time()
    if prev:   # marker existed: a normal version upgrade
        _set_history_epoch(now, reason=f"auto_on_upgrade {prev} -> {current_version}")
        _HISTORY_EPOCH_CACHE["value"] = now
        print(f"[GodMode] New engine version detected ({prev} -> {current_version}). "
              f"Trade history reset: only trades from this version onward will be counted. "
              f"(Set GODMODE_KEEP_HISTORY_ON_UPGRADE=1 to keep old trades.)")
    else:
        # V12.78 FIX: no marker means EITHER a genuinely fresh install OR an upgrade from a
        # pre-marker version — and every pre-marker version shares the same magic/comment
        # prefix, so a 365-day broker pull would adopt ALL its old trades. V12.76 skipped the
        # stamp here, which is exactly why old trades kept showing after the upgrade. We now
        # stamp on first boot too: a truly fresh account has no bot-tagged deals, so the
        # cutoff is a no-op for them, while upgraders finally start clean.
        if _HISTORY_EPOCH_CACHE["value"] <= 0:   # never override a purge the user already did
            _set_history_epoch(now, reason=f"auto_on_first_boot {current_version}")
            _HISTORY_EPOCH_CACHE["value"] = now
            print(f"[GodMode] First boot of {current_version}: counting trades from now onward. "
                  f"Older GODMODE-tagged broker deals (from any previous version) are not attributed "
                  f"to this engine. Set GODMODE_KEEP_HISTORY_ON_UPGRADE=1 before first start to keep them.")
    try:
        marker.write_text(json.dumps({"version": current_version,
                                      "seenAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}), encoding="utf-8")
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_7579", _suppressed_exc)


_auto_epoch_on_version_change(APP_VERSION)


def _frontend_build_status() -> dict[str, Any]:
    """V12.76 — detect a STALE frontend bundle.

    Every backend feature can ship perfectly and still be invisible, because the bot serves
    `frontend/dist` while all UI work lives in `frontend/src`. If dist is older than any
    source file, the running UI is literally from a previous release. The bot now says so
    loudly instead of silently rendering old screens.
    """
    src_dir = FRONTEND_DIST.parent / "src"
    try:
        assets = list((FRONTEND_DIST / "assets").glob("*.js"))
        if not assets:
            return {"ok": False, "built": False, "stale": True,
                    "message": "No frontend build found. Run: cd frontend && npm install && npm run build"}
        bundle_mtime = max(a.stat().st_mtime for a in assets)
        newest_src, newest_file = 0.0, ""
        if src_dir.exists():
            for p in src_dir.rglob("*"):
                if p.suffix in {".tsx", ".ts", ".css"} and p.is_file():
                    mt = p.stat().st_mtime
                    if mt > newest_src:
                        newest_src, newest_file = mt, p.name
        stale = newest_src > bundle_mtime + 2
        return {"ok": True, "built": True, "stale": stale,
                "bundleBuiltAt": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(bundle_mtime)),
                "newestSourceAt": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(newest_src)) if newest_src else None,
                "newestSourceFile": newest_file,
                "message": (f"STALE UI: your dashboard bundle was built {time.strftime('%b %d %H:%M', time.localtime(bundle_mtime))} "
                            f"but '{newest_file}' changed {time.strftime('%b %d %H:%M', time.localtime(newest_src))}. "
                            f"New features will NOT appear until you run:  cd frontend && npm install && npm run build"
                            if stale else "Frontend build is up to date with source.")}
    except Exception as exc:
        return {"ok": False, "built": False, "stale": False, "message": f"Build check failed: {exc}"}


@app.get("/tools", include_in_schema=False)
def godmode_tools_page():
    """V12.77 — a self-contained control page served STRAIGHT FROM THE BACKEND.

    The compiled dashboard (frontend/dist) can lag behind source, which hid Purge and the
    journal exports. This page needs no build step: open http://127.0.0.1:8000/tools
    """
    bs = _frontend_build_status()
    ep = data_epoch_status()
    warn = ("<div class='warn'><b>Stale dashboard build.</b> " + str(bs.get("message", "")) +
            "</div>") if bs.get("stale") else ""
    html = f"""<!doctype html><html><head><meta charset="utf-8"><title>GodMode Tools</title>
<style>
:root{{--bg:#0e1116;--fg:#e6e1d5;--gold:#c9a961;--dim:#8a8f98;--line:#242a35;--card:#161a21}}
*{{box-sizing:border-box}}
body{{margin:0;background:var(--bg);color:var(--fg);font:15px/1.6 -apple-system,Segoe UI,Roboto,sans-serif;padding:32px}}
h1{{font-family:Georgia,serif;color:var(--gold);letter-spacing:.5px;margin:0 0 4px}}
.sub{{color:var(--dim);font-size:13px;margin-bottom:26px}}
.card{{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:20px;margin-bottom:18px}}
.card h2{{font-size:13px;letter-spacing:1.4px;text-transform:uppercase;color:var(--gold);margin:0 0 12px}}
button,a.btn{{background:transparent;color:var(--fg);border:1px solid var(--line);border-radius:8px;
 padding:10px 16px;margin:4px 6px 4px 0;cursor:pointer;font-size:13px;text-decoration:none;display:inline-block}}
button:hover,a.btn:hover{{border-color:var(--gold);color:var(--gold)}}
button.danger{{border-color:#5a2b2b;color:#c25b4e}} button.danger:hover{{background:#2a1414;border-color:#c25b4e}}
.warn{{background:#2a1f10;border:1px solid var(--gold);color:var(--gold);padding:12px 16px;border-radius:10px;margin-bottom:18px;font-size:13px}}
.muted{{color:var(--dim);font-size:12px;margin-top:10px}}
#out{{white-space:pre-wrap;background:#0b0e12;border:1px solid var(--line);border-radius:8px;padding:14px;
 margin-top:14px;font-family:ui-monospace,Menlo,monospace;font-size:12px;color:#7fb069;min-height:20px}}
.kv{{display:flex;justify-content:space-between;border-bottom:1px solid var(--line);padding:8px 0;font-size:13px}}
.kv span{{color:var(--dim)}}
</style></head><body>
<h1>GodMode — Tools</h1>
<div class="sub">Served directly by the backend. Works even when the dashboard bundle is out of date.</div>
{warn}
<div class="card"><h2>Trade Journal Export</h2>
  <a class="btn" href="/api/journal/export?format=csv" target="_blank">Download CSV</a>
  <a class="btn" href="/api/journal/export?format=pdf" target="_blank">Download PDF</a>
  <div class="muted">One row per closed trade: entry/exit, R-multiple, hold time, strategy, confidence, entry reason, exit reason and the AI auditor's verdict. PDF adds a KPI + calibration summary page.</div>
</div>
<div class="card"><h2>Data Epoch</h2>
  <div class="kv"><span>Purge active</span><b>{'YES' if ep.get('active') else 'no'}</b></div>
  <div class="kv"><span>Counting trades since</span><b>{ep.get('since') or 'all history'}</b></div>
  <div class="muted">{ep.get('message','')}</div>
</div>
<div class="card"><h2>Purge Database (danger zone)</h2>
  <button onclick="purge('history','Hide ALL broker trade history before now?')">Purge Trade History</button>
  <button onclick="purge('memory','Clear learned strategy performance and calibration?')">Purge Learned Memory</button>
  <button onclick="purge('journal','Clear the decision journal and AI audit outcomes?')">Purge Decision Journal</button>
  <button class="danger" onclick="purge('all','PURGE EVERYTHING. This cannot be undone locally. Continue?')">Purge Everything</button>
  <div class="muted"><b>Your broker account is never touched.</b> No positions are closed, no deals deleted, settings untouched. Purging only stops older trades from counting toward this engine's analytics, calibration, AI coach and loss governors.</div>
  <div id="out"></div>
</div>
<div class="card"><h2>Trade Review Engine (learns from wins & losses)</h2>
  <button onclick="loadReview()">Run Deterministic Review</button>
  <button onclick="whySilent()" style="margin-left:8px;background:#7a3b3b">Why is the bot silent?</button>
  <button onclick="loadMomentum()" style="margin-left:8px;background:#3b5a7a">Pump &amp; Dump Engine</button>
  <div id="momentum"></div>
  <script>
  const MOM_FIELDS=[
    {{k:'breakoutStopEnabled',t:'bool',label:'Breakout-STOP entries',help:'Pre-place BUY_STOP/SELL_STOP at the edges of a tight base so a pump/dump fills AT the level instead of chasing it. THIS is the feature that catches the ramp into a spike.'}},
    {{k:'breakoutStopDemoOnly',t:'bool',label:'  ↳ Demo only (safety)',help:'While true, breakout-stops refuse to arm on a live account. Turn off only after demo proves it.'}},
    {{k:'fastSniperStrongMomentumOverride',t:'bool',label:'Strong-momentum continuation',help:'V12.97 fix: lets a strong HTF-aligned breakdown/breakout take the continuation past the RSI floor, instead of waiting until RSI recovers at the exhausted END of the move. This is the late-entry fix.'}},
    {{k:'strongMomentumDisplacementAtr',t:'num',label:'  ↳ Min displacement (ATR)',help:'How strong the break body must be. Lower = fires on weaker breaks (more trades, more noise). 1.05 default.'}},
    {{k:'strongMomentumMaxStretchAtr',t:'num',label:'  ↳ Max stretch (ATR)',help:'Refuse if price is already this far from EMA = the un-catchable vertical spike. 2.20 default.'}},
    {{k:'fastSniperExhaustionGuard',t:'bool',label:'Exhaustion guard',help:'V12.94 fix: refuses to SELL a bottom / BUY a top when price is stretched and RSI is turning. This stopped the wrong-way entries.'}},
    {{k:'exhaustionStretchAtr',t:'num',label:'  ↳ Stretch trigger (ATR)',help:'How far from EMA counts as stretched. 1.10 default.'}},
    {{k:'fastSniperRetestFibMin',t:'num',label:'Shallow retest floor',help:'Shallow pullbacks now qualify (0.12 = 12%). Lower catches shallower retests in fast trends.'}},
    {{k:'fastSniperReversalEnabled',t:'bool',label:'Reversal scouts (counter-trend)',help:'OFF by design — counter-trend, bypasses the HTF veto. This is what produced oversized losers historically.'}}
  ];
  const BURST_FIELDS=[
    {{k:'enabled',t:'bool',label:'Protected Burst',help:'Adds extra legs to an already-winning, protected base.'}},
    {{k:'demoOnlyUntilValidated',t:'bool',label:'  ↳ Demo only (safety)',help:'While true, burst refuses to fire on a live account. Turn off only after demo proves it.'}},
    {{k:'riskModel',t:'txt',label:'Risk model',help:'account_pct = the WHOLE burst risks one trade\\'s worth (% of balance). fixed_usd = legacy ladder.'}},
    {{k:'burstRiskPctOfBalance',t:'num',label:'  ↳ Burst risk % of balance',help:'Total max loss for the entire burst basket, as % of balance. Basket hard-loss + giveback derive from this, so it scales with lot size automatically.'}},
    {{k:'lotDistribution',t:'txt',label:'  ↳ Lot distribution',help:'incremental_down = biggest leg first, each add smaller (safest). Also: incremental_up, equal.'}},
    {{k:'incrementalDownStep',t:'num',label:'  ↳ Step factor',help:'Each leg = this x the previous. 0.6 default -> 0.05, 0.03, 0.01.'}},
    {{k:'nearBeEarlyArm',t:'bool',label:'Near-BE early arm',help:'Fire the burst slightly BEFORE BE fully locks, so slow grinds do not miss the window.'}},
    {{k:'nearBeArmFraction',t:'num',label:'  ↳ Arm fraction',help:'0.80 = fire once base is 80% of the way to a locked BE.'}},
    {{k:'nearBeLegStopAtr',t:'num',label:'  ↳ Early leg own-stop (ATR)',help:'Early legs carry their OWN stop this far from entry, so the basket is never unprotected.'}},
    {{k:'requireEdgeValidAtFire',t:'bool',label:'  ↳ Require edge valid at fire',help:'Refuse to add if recovery score decayed or price over-extended.'}}
  ];
  async function loadMomentum(){{
    const el=document.getElementById('momentum');
    el.innerHTML='<p style="color:#8a93a3">Loading…</p>';
    try{{
      const s=await (await fetch('/api/settings')).json();
      const au=(s.automation)||{{}};
      const bu=((s.tradingModes)||{{}}).protectedBurst||{{}};
      let h=`<div style='margin:8px 0;padding:8px 12px;border-left:3px solid #3b5a7a;background:#12161c;font-size:12px;color:#8a93a3'>These live in the backend and work now. Changes save immediately.</div>`;
      const render=(fields,src,root)=>fields.map(f=>{{
        const v=src[f.k];
        let ctl;
        if(f.t==='bool') ctl=`<button onclick="setMom('${{f.k}}',${{!v}},'${{root}}')" style="min-width:64px;background:${{v?'#2f6b45':'#5a3b3b'}}">${{v?'ON':'OFF'}}</button>`;
        else ctl=`<input id="mom_${{root}}_${{f.k}}" value="${{v}}" style="width:${{f.t==='txt'?'150':'70'}}px;background:#0d1117;color:#e6edf3;border:1px solid #30363d;border-radius:4px;padding:3px 6px"> <button onclick="setMom('${{f.k}}',${{f.t==='txt'?`document.getElementById('mom_${{root}}_${{f.k}}').value`:`parseFloat(document.getElementById('mom_${{root}}_${{f.k}}').value)`}},'${{root}}')">Save</button>`;
        return `<div style='margin:8px 0;padding:8px;border-bottom:1px solid #1e242c'>
          <div style='display:flex;align-items:center;gap:10px'><b style='font-size:13px;flex:1;white-space:pre'>${{f.label}}</b>${{ctl}}</div>
          <div style='font-size:11px;color:#6b7280;margin-top:3px'>${{f.help}}</div></div>`;
      }}).join('');
      h+=`<h3 style='font-size:13px;color:#8ab4ff;margin:12px 0 4px'>Entry engine (V12.93–97)</h3>`+render(MOM_FIELDS,au,'automation');
      h+=`<h3 style='font-size:13px;color:#8ab4ff;margin:16px 0 4px'>Protected Burst (V12.91–92)</h3>`+render(BURST_FIELDS,bu,'burst');
      el.innerHTML=h;
    }}catch(e){{ el.innerHTML='<p style="color:#ff8a80">Failed: '+e+'</p>'; }}
  }}
  async function setMom(key,val,root){{
    try{{
      const body = root==='burst' ? {{tradingModes:{{protectedBurst:{{[key]:val}}}}}} : {{automation:{{[key]:val}}}};
      const r=await (await fetch('/api/settings',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(body)}})).json();
      if(!r.ok) alert('Save failed: '+(r.message||'unknown'));
      loadMomentum();
    }}catch(e){{ alert('Save failed: '+e); }}
  }}
  </script>
  <div id="whysilent"></div>
  <script>
  async function whySilent(){{
    const el=document.getElementById('whysilent');
    el.innerHTML='<p style="color:#8a93a3">Checking every gate…</p>';
    try{{
      const r=await (await fetch('/api/system/why-silent')).json();
      let h=`<div style='margin:8px 0;padding:8px 12px;border-left:3px solid ${{r.checks.every(c=>c.ok)?'#3fae6a':'#c0504d'}};background:#12161c;font-size:13px'><b>${{r.verdict}}</b></div>`;
      h+=r.checks.map(c=>`<div style='margin:4px 0;font-size:12px;color:${{c.ok?'#3fae6a':'#ff8a80'}}'>${{c.ok?'✓':'✗'}} <b>${{c.check}}</b> — <span style='color:#8a93a3'>${{c.detail}}</span></div>`).join('');
      if(r.loopLastResult&&r.loopLastResult.message) h+=`<div style='margin-top:8px;font-size:11px;color:#6b7280'>last loop result: ${{String(r.loopLastResult.message).slice(0,160)}}</div>`;
      try{{
        const tl=await (await fetch('/api/system/telegram-log?limit=12')).json();
        if(tl.items&&tl.items.length){{
          h+=`<div style='margin-top:10px;font-size:12px'><b>Recent Telegram attempts</b> <span style='color:#6b7280'>(${{JSON.stringify(tl.counts)}})</span></div>`;
          h+=tl.items.map(it=>`<div style='font-size:11px;color:${{it.outcome==='sent'?'#3fae6a':(it.outcome.startsWith('skipped')?'#c9a961':'#ff8a80')}}'>${{it.tsIso}} [${{it.outcome}}] ${{it.category}} — ${{it.preview}} ${{it.detail?('· '+it.detail):''}}</div>`).join('');
        }} else {{ h+=`<div style='margin-top:10px;font-size:11px;color:#6b7280'>No Telegram attempts logged yet — no setup has tried to alert since restart.</div>`; }}
      }}catch(e){{}}
      el.innerHTML=h;
    }}catch(e){{ el.innerHTML='<p style="color:#ff8a80">Diagnostic failed: '+e+'</p>'; }}
  }}
  </script>
  <button onclick="testNews()" style="margin-left:8px">Test News Feeds Now</button>
  <div id="newstest"></div>
  <script>
  async function testNews(){{
    const el=document.getElementById('newstest');
    el.innerHTML='<p style="color:#8a93a3">Fetching both feeds live…</p>';
    try{{
      const r=await (await fetch('/api/news/test')).json();
      const row=(p)=>`<div style='margin:6px 0;padding:8px 12px;border-left:3px solid ${{p.result==='ok'?'#3fae6a':(p.result==='ok_but_empty'?'#c9a961':'#c0504d')}};background:#12161c;font-size:12px'>`+
        `<b>${{p.name}}</b> — <span style='color:${{p.result==='ok'?'#3fae6a':(p.result==='ok_but_empty'?'#c9a961':'#ff8a80')}}'>${{p.result}}</span>`+
        (p.httpStatus?` · HTTP ${{p.httpStatus}} · ${{p.bytes}} bytes · ${{p.eventCount}} event(s) · ${{p.ms}}ms`:``)+
        (p.error?`<br><span style='color:#ff8a80'>${{p.error}}</span>`:``)+
        (p.firstEvent?`<br><span style='color:#8a93a3'>sample: ${{JSON.stringify(p.firstEvent).slice(0,140)}}</span>`:``)+
        `<br><span style='color:#5b6270'>${{(p.url||'').slice(0,90)}}</span></div>`;
      el.innerHTML=row(r.calendar)+row(r.marketNews)+`<p style='color:#5b6270;font-size:11px'>${{r.hint}}</p>`;
    }}catch(e){{ el.innerHTML='<p style="color:#ff8a80">Test failed: '+e+'</p>'; }}
  }}
  </script>
  <button onclick="loadReviewLLM()">Deeper AI Diagnosis</button>
  <div class="muted">Deterministic review is pure arithmetic on your closed trades — expectancy source, loss/win asymmetry, deep losers, winner giveback, best/worst strategy &amp; session. Proposals appear only once you have enough trades, and you approve each one. The AI diagnosis reads aggregates only (never single trades) so it can't overfit.</div>
  <div id="review">Not run yet.</div>
</div>
<div class="card"><h2>Live Intelligence (rendered fresh each load)</h2>
  <div id="intel">Loading…</div>
</div>
<div class="card"><h2>Diagnostics</h2>
  <a class="btn" href="/api/system/build-status" target="_blank">Build status</a>
  <a class="btn" href="/api/news/status" target="_blank">News / feed status</a>
  <a class="btn" href="/api/strategies" target="_blank">Live strategy ranking</a>
  <a class="btn" href="/api/ai/audit/scoreboard" target="_blank">AI audit scoreboard</a>
</div>
<script>
async function purge(scope,msg){{
  if(!confirm(msg)) return;
  const o=document.getElementById('out'); o.textContent='Working...';
  try{{
    const r=await fetch('/api/data/purge',{{method:'POST',headers:{{'Content-Type':'application/json'}},
      body:JSON.stringify({{scope:scope,confirm:true}})}});
    const j=await r.json();
    o.textContent=(j.message||JSON.stringify(j))+(j.cleared?'\\n\\nCleared: '+j.cleared.join(', '):'');
    setTimeout(()=>location.reload(),1600);
  }}catch(e){{ o.textContent='Failed: '+e; }}
}}
function tbl(rows,cols){{
  if(!rows||!rows.length) return "<div class='muted'>No data yet.</div>";
  let h="<table style='width:100%;border-collapse:collapse;font-size:12px'><tr>"+cols.map(c=>`<th style='text-align:left;color:#c9a961;border-bottom:1px solid #242a35;padding:6px 8px'>${{c[0]}}</th>`).join('')+"</tr>";
  for(const r of rows) h+="<tr>"+cols.map(c=>`<td style='border-bottom:1px solid #1b212b;padding:6px 8px'>${{c[1](r)??'—'}}</td>`).join('')+"</tr>";
  return h+"</table>";
}}
function sevColor(s){{return s==='high'?'#c25b4e':s==='warn'?'#c9a961':'#7fb069';}}
function renderReview(d){{
  const el=document.getElementById('review'); const s=d.stats||{{}};
  if(!s.sampleSize){{el.innerHTML="<div class='muted'>No closed trades yet.</div>";return;}}
  let h=`<div style='margin:10px 0;font-size:13px'>`
    +`<b>${{s.sampleSize}}</b> trades · <b>${{s.winRate}}%</b> WR · net <b style='color:${{s.netUsd>=0?'#7fb069':'#c25b4e'}}'>${{s.netUsd>=0?'+':''}}${{s.netUsd}}</b> USD · PF <b>${{s.profitFactor??'—'}}</b> · avg <b>${{s.avgR}}R</b><br>`
    +`avg win +${{s.avgWinUsd}} vs avg loss ${{s.avgLossUsd}} · <b>loss/win size ${{s.lossWinSizeRatio}}x</b> · deep losers ${{s.deepLoserCount}} · giveback ${{s.winnerGivebackPct??'—'}}%`
    +`</div>`;
  h+=`<div style='margin:6px 0 10px;padding:8px 12px;border-left:3px solid #c9a961;background:#12161c;font-size:13px'>${{d.verdict||''}}</div>`;
  const ea=d.expiredArms||{{}};
  if(ea.totalExpired!==undefined) h+=`<div style='margin:6px 0 10px;padding:8px 12px;border-left:3px solid #4a6a8a;background:#101620;font-size:12px'><b style='color:#8ab4ff'>No-chase opportunity cost (estimate):</b> ${{ea.totalExpired}} armed retest(s) expired untriggered · evaluated ${{ea.evaluated}} · would-have-won ${{ea.wouldHaveWon}} · would-have-lost ${{ea.wouldHaveLost}} · faded ${{ea.faded}} · est net ${{ea.estNetR>=0?'+':''}}${{ea.estNetR}}R<br><span style='color:#6b7280'>${{ea.note||''}}</span></div>`;
  if(d.llmDiagnosis) h+=`<div style='margin:10px 0;padding:10px 12px;border:1px solid #2a3550;border-radius:8px;background:#0e1420;font-size:13px;white-space:pre-wrap'><b style='color:#8ab4ff'>AI diagnosis:</b>\\n${{d.llmDiagnosis}}</div>`;
  h+="<h3 style='color:#c9a961;font-size:12px;letter-spacing:1px;margin:14px 0 6px'>FINDINGS</h3>";
  for(const f of (d.findings||[]))
    h+=`<div style='margin:6px 0;padding:8px 10px;border-left:3px solid ${{sevColor(f.severity)}};background:#12161c'><b>${{f.title}}</b> <span style='color:#6b7280;font-size:11px'>[${{f.confidence}}]</span><br><span style='color:#9aa0aa;font-size:12px'>${{f.detail}}</span></div>`;
  if((d.proposals||[]).length){{
    h+="<h3 style='color:#c9a961;font-size:12px;letter-spacing:1px;margin:16px 0 6px'>PROPOSED CHANGES (you approve each)</h3>";
    for(const p of d.proposals)
      h+=`<div style='margin:6px 0;padding:10px;border:1px solid #2a3038;border-radius:8px'><b>${{p.title}}</b> <span style='color:#6b7280;font-size:11px'>[risk: ${{p.risk}}]</span><br><span style='color:#9aa0aa;font-size:12px'>${{p.rationale}}</span><br><code style='font-size:11px;color:#8ab4ff'>${{p.path}} → ${{p.suggest}}</code> <span style='color:#6b7280;font-size:11px'>(now ${{p.current_hint}})</span><br><button style='margin-top:8px' onclick='approveProposal(${{JSON.stringify(JSON.stringify(p))}})'>Approve this change</button></div>`;
  }} else {{
    h+="<div class='muted' style='margin-top:10px'>No proposals — sample too small to change settings safely. Keep collecting.</div>";
  }}
  el.innerHTML=h;
}}
async function loadReview(){{
  const el=document.getElementById('review'); el.textContent='Running…';
  try{{ renderReview(await fetch('/api/ai/trade-review-engine').then(r=>r.json())); }}catch(e){{el.textContent='Failed: '+e;}}
}}
async function loadReviewLLM(){{
  const el=document.getElementById('review'); el.textContent='Asking the model (aggregates only)…';
  try{{ renderReview(await fetch('/api/ai/trade-review-llm',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:'{{}}'}}).then(r=>r.json())); }}catch(e){{el.textContent='Failed: '+e;}}
}}
async function approveProposal(pjson){{
  const p=JSON.parse(pjson);
  if(!confirm('Apply: '+p.title+'\\n\\n'+p.path+' → '+p.suggest+'\\n\\nThis changes a live setting.')) return;
  try{{
    const r=await fetch('/api/ai/apply-proposal',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify(p)}});
    const j=await r.json();
    alert(j.message||JSON.stringify(j));
    if(j.ok) loadReview();
  }}catch(e){{alert('Failed: '+e);}}
}}
(async()=>{{
  const el=document.getElementById('intel');
  try{{
    const [strats,rev,sb]=await Promise.all([
      fetch('/api/strategies').then(r=>r.json()).catch(()=>[]),
      fetch('/api/ai/performance-review?period=daily').then(r=>r.json()).catch(()=>({{}})),
      fetch('/api/ai/audit/scoreboard').then(r=>r.json()).catch(()=>({{}}))
    ]);
    let h="<h3 style='color:#c9a961;font-size:12px;letter-spacing:1px;margin:6px 0'>STRATEGY RANKING (this bar)</h3>";
    h+=tbl((strats||[]).slice(0,6),[["Strategy",r=>r.name],["Rank",r=>r.rankScore!=null?Number(r.rankScore).toFixed(0):'—'],
      ["Evidence",r=>r.evidence],["Live trades",r=>r.liveTrades],["Win",r=>`${{r.winRate??0}}%${{r.statsSource==='live_memory'?' live':' est'}}`],
      ["TF",r=>r.timeframe],["Picked",r=>r.isSelected?'&#9679;':'']]);
    const bs2=(rev&&rev.blockStats)||{{}};
    h+="<h3 style='color:#c9a961;font-size:12px;letter-spacing:1px;margin:16px 0 6px'>WHY THE BOT SKIPPED SETUPS ("+((bs2.takeCount||0)+" took / "+(bs2.skipCount||0)+" skipped, fire rate "+(bs2.takeRatePct??'—')+"%)</h3>";
    h+=tbl((bs2.topBlockReasons||[]).slice(0,6),[["Skip reason",r=>r.reason],["Count",r=>r.count]]);
    if(rev&&rev.diagnosis&&rev.diagnosis.length){{
      h+="<h3 style='color:#c9a961;font-size:12px;letter-spacing:1px;margin:16px 0 6px'>AI COACH DIAGNOSIS</h3>";
      h+="<ul style='margin:0;padding-left:18px;font-size:12px'>"+rev.diagnosis.map(d=>`<li style='margin:4px 0'>${{d}}</li>`).join('')+"</ul>";
    }}
    if(sb&&sb.ok){{
      h+="<h3 style='color:#c9a961;font-size:12px;letter-spacing:1px;margin:16px 0 6px'>AI ENTRY-AUDIT SCOREBOARD</h3>";
      h+=`<div class='muted'>${{sb.assessment||''}} — approves: ${{sb.approve?.trades??0}} trades / ${{sb.approve?.winRate??0}}% · downgrades: ${{sb.downgrade?.trades??0}} / ${{sb.downgrade?.winRate??0}}% · vetoes: ${{sb.vetoCount??0}}</div>`;
    }}
    el.innerHTML=h;
  }}catch(e){{ el.textContent='Failed to load: '+e; }}
}})();
</script></body></html>"""
    return HTMLResponse(html)


@app.get("/api/system/build-status")
def system_build_status():
    return _frontend_build_status()


@app.get("/api/data/epoch")
def data_epoch_status():
    ep = _HISTORY_EPOCH_CACHE["value"]
    return {"ok": True, "epoch": ep, "active": ep > 0,
            "since": time.strftime("%Y-%m-%d %H:%M:%S UTC", time.gmtime(ep)) if ep > 0 else None,
            "message": ("Only trades after this time are counted."
                        if ep > 0 else "No purge active — all bot-tagged broker history is counted.")}


@app.post("/api/data/purge")
def data_purge(payload: dict[str, Any] = Body(default={})):
    """V12.75 — manual database purge. Hides all prior broker trade history from the bot and
    clears local learned state. Does NOT touch your broker account, positions, or settings."""
    scope = str(payload.get("scope", "history")).lower()
    if not bool(payload.get("confirm")):
        return {"ok": False, "message": "Purge requires confirm=true.",
                "wouldClear": {"history": "hide all broker deals before now",
                               "memory": "learned strategy performance + calibration",
                               "journal": "decision journal + AI audit outcomes"}}
    cleared: list[str] = []
    now = time.time()
    if scope in {"history", "all"}:
        _set_history_epoch(now, reason=str(payload.get("reason", "manual_purge"))[:80])
        _HISTORY_EPOCH_CACHE["value"] = now
        globals()["_TRADES_CACHE"] = None
        globals()["_TRADES_CACHE_TS"] = 0.0
        globals()["_ANALYTICS_CACHE"] = None
        cleared.append("broker trade history hidden before now")
    if scope in {"memory", "all"}:
        try:
            memory.reset() if hasattr(memory, "reset") else None
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_7911", _suppressed_exc)
        try:
            if EXECUTION_MEMORY_FILE.exists():
                EXECUTION_MEMORY_FILE.unlink()
            EXECUTION_MEMORY.clear()
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_7917", _suppressed_exc)
        cleared.append("learned performance memory")
    if scope in {"journal", "all"}:
        try:
            DECISION_JOURNAL.clear()
            if DECISION_JOURNAL_FILE.exists():
                DECISION_JOURNAL_FILE.unlink()
            if AUDIT_OUTCOMES_FILE.exists():
                AUDIT_OUTCOMES_FILE.unlink()
        except Exception as _suppressed_exc:
            _report_suppressed_exception("suppressed_exception_line_7927", _suppressed_exc)
        cleared.append("decision journal + AI audit outcomes")
    try:
        AUTO_TRADE_STATE.update({"lossStreak": 0, "winStreak": 0, "postLossUntil": 0.0,
                                 "pausedUntil": 0.0, "lastLoser": None})
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_7933", _suppressed_exc)
    _journal_record("system", decision="DATA_PURGE", reason=f"scope={scope}: {', '.join(cleared)}")
    return {"ok": True, "scope": scope, "cleared": cleared,
            "epoch": _HISTORY_EPOCH_CACHE["value"],
            "message": f"Purge complete ({scope}). Nothing on your broker account was changed."}


@app.get("/api/journal/export")
def journal_export(format: str = "csv", days: int = 30):
    """V12.74 — vetting-grade trade journal export. format=csv (Excel-safe, properly quoted)
    or format=pdf (summary page with KPIs + calibration + per-strategy table, then the full
    trade table). Everything a reviewer needs to audit the bot's decisions."""
    rows = _vetting_journal_rows(days=days)
    fname_base = f"godmode_trade_journal_{time.strftime('%Y%m%d')}"
    if format.lower() == "csv":
        import csv as _csv
        import io as _io
        buf = _io.StringIO()
        cols = ["closeTime", "openTime", "ticket", "symbol", "side", "lots", "entry", "exit", "sl",
                "pnlUsd", "rMultiple", "holdMinutes", "outcome", "strategy", "confidence", "session",
                "quality", "entryReason", "exitReason",
                # V13.6 — excursion + management columns. maeR is the one that matters: it makes
                # "would a tighter stop have cut this winner?" answerable instead of a guess.
                "regime", "maeR", "mfeR", "riskBasis", "beMoved", "checksSeen",
                "aiAuditVerdict", "aiAuditReason", "comment"]
        w = _csv.DictWriter(buf, fieldnames=cols, extrasaction="ignore", quoting=_csv.QUOTE_MINIMAL)
        w.writeheader()
        for r in rows:
            w.writerow(r)
        return Response(buf.getvalue(), media_type="text/csv",
                        headers={"Content-Disposition": f"attachment; filename={fname_base}.csv"})
    if format.lower() == "pdf":
        pdf_bytes = _render_journal_pdf(rows)
        if not pdf_bytes:
            return JSONResponse({"ok": False, "message": "PDF rendering unavailable (matplotlib not installed). Use format=csv."}, status_code=501)
        return Response(pdf_bytes, media_type="application/pdf",
                        headers={"Content-Disposition": f"attachment; filename={fname_base}.pdf"})
    return JSONResponse({"ok": True, "rows": rows, "count": len(rows)})


def _render_journal_pdf(rows: list[dict[str, Any]]) -> bytes | None:
    """Dark-editorial PDF: page 1 = KPI summary + probability calibration + per-strategy table;
    following pages = the full trade table. Uses lazy matplotlib via chart_render's loader."""
    st = chart_render._mpl()
    if not st.get("have"):
        return None
    plt = st["plt"]
    import io as _io
    from matplotlib.backends.backend_pdf import PdfPages
    BG, FG, GOLD, DIM = "#0e1116", "#e6e1d5", "#c9a961", "#8a8f98"
    buf = _io.BytesIO()

    wins = [r for r in rows if r["outcome"] == "WIN"]; losses = [r for r in rows if r["outcome"] == "LOSS"]
    net = round(sum(_to_float(r["pnlUsd"]) for r in rows), 2)
    gp = sum(_to_float(r["pnlUsd"]) for r in wins); gl = abs(sum(_to_float(r["pnlUsd"]) for r in losses))
    kpis = [("Closed trades", len(rows)), ("Win rate", f"{(len(wins)/max(1,len(rows))*100):.1f}%"),
            ("Net P&L", f"{net} USD"), ("Profit factor", f"{(gp/gl):.2f}" if gl else "—"),
            ("Expectancy/trade", f"{(net/max(1,len(rows))):.2f} USD"),
            ("Avg win / Avg loss", f"{(gp/max(1,len(wins))):.2f} / {(gl/max(1,len(losses))):.2f}")]
    try:
        calib = memory.stats().get("probabilityCalibration", [])
    except Exception:
        calib = []
    by_strat: dict[str, dict[str, float]] = {}
    for r in rows:
        s = by_strat.setdefault(str(r["strategy"] or "Unknown"), {"n": 0, "w": 0, "pnl": 0.0})
        s["n"] += 1; s["w"] += 1 if r["outcome"] == "WIN" else 0; s["pnl"] += _to_float(r["pnlUsd"])

    def _style_ax(ax):
        ax.set_facecolor(BG); ax.axis("off")

    with PdfPages(buf) as pdf:
        # ── Page 1: summary ──
        fig = plt.figure(figsize=(11.7, 8.3), dpi=130); fig.patch.set_facecolor(BG)
        fig.text(0.06, 0.93, "GODMODE — TRADE JOURNAL", color=GOLD, fontsize=20, fontweight="bold", family="serif")
        fig.text(0.06, 0.89, f"Generated {time.strftime('%Y-%m-%d %H:%M UTC', time.gmtime())} · last {len(rows)} closed trades · for vetting & review", color=DIM, fontsize=9)
        for i, (k, v) in enumerate(kpis):
            x = 0.06 + (i % 3) * 0.32; y = 0.78 - (i // 3) * 0.12
            fig.text(x, y, str(v), color=FG, fontsize=17, fontweight="bold")
            fig.text(x, y - 0.035, k.upper(), color=DIM, fontsize=8)
        # strategy table
        ax = fig.add_axes([0.06, 0.08, 0.42, 0.40]); _style_ax(ax)
        ax.set_title("BY STRATEGY", color=GOLD, fontsize=10, loc="left", pad=8)
        srows = [[k[:26], s["n"], f"{s['w']/max(1,s['n'])*100:.0f}%", f"{s['pnl']:.2f}"] for k, s in sorted(by_strat.items(), key=lambda kv: -kv[1]["pnl"])][:10]
        if srows:
            tb = ax.table(cellText=srows, colLabels=["Strategy", "N", "Win%", "PnL"], loc="upper left", cellLoc="left")
            tb.auto_set_font_size(False); tb.set_fontsize(7.5)
            for (ri, ci), cell in tb.get_celld().items():
                cell.set_facecolor("#161a21" if ri else "#1e2530"); cell.set_edgecolor("#2a2f3a")
                cell.set_text_props(color=GOLD if ri == 0 else FG)
        # calibration table
        ax2 = fig.add_axes([0.54, 0.08, 0.40, 0.40]); _style_ax(ax2)
        ax2.set_title("PROBABILITY CALIBRATION (confidence vs reality)", color=GOLD, fontsize=10, loc="left", pad=8)
        crows = [[c.get("bucket"), c.get("samples"), f"{c.get('actualWinRate')}%"] for c in calib][:10]
        if crows:
            tb2 = ax2.table(cellText=crows, colLabels=["Confidence", "Samples", "Actual win"], loc="upper left", cellLoc="left")
            tb2.auto_set_font_size(False); tb2.set_fontsize(7.5)
            for (ri, ci), cell in tb2.get_celld().items():
                cell.set_facecolor("#161a21" if ri else "#1e2530"); cell.set_edgecolor("#2a2f3a")
                cell.set_text_props(color=GOLD if ri == 0 else FG)
        else:
            ax2.text(0, 0.8, "No calibration samples yet.", color=DIM, fontsize=9)
        pdf.savefig(fig, facecolor=BG); plt.close(fig)

        # ── Trade table pages ──
        cols = ["closeTime", "side", "lots", "entry", "exit", "pnlUsd", "rMultiple", "holdMinutes", "strategy", "aiAuditVerdict", "exitReason"]
        heads = ["Close", "Side", "Lots", "Entry", "Exit", "PnL", "R", "Min", "Strategy", "AI", "Exit reason"]
        per_page = 26
        for start in range(0, max(1, len(rows)), per_page):
            chunk = rows[start:start + per_page]
            fig = plt.figure(figsize=(11.7, 8.3), dpi=130); fig.patch.set_facecolor(BG)
            fig.text(0.04, 0.95, f"TRADES {start + 1}–{start + len(chunk)}", color=GOLD, fontsize=11, fontweight="bold")
            ax = fig.add_axes([0.02, 0.03, 0.96, 0.88]); _style_ax(ax)
            data = [[str(r.get(c, ""))[:34 if c in ("strategy", "exitReason") else 18] for c in cols] for r in chunk]
            if data:
                tb = ax.table(cellText=data, colLabels=heads, loc="upper left", cellLoc="left")
                tb.auto_set_font_size(False); tb.set_fontsize(6.6)
                for (ri, ci), cell in tb.get_celld().items():
                    cell.set_edgecolor("#242a35")
                    if ri == 0:
                        cell.set_facecolor("#1e2530"); cell.set_text_props(color=GOLD, fontweight="bold")
                    else:
                        row = chunk[ri - 1]
                        pnl_v = _to_float(row.get("pnlUsd"))
                        cell.set_facecolor("#12161d" if ri % 2 else "#161a21")
                        color = "#7fb069" if pnl_v > 0 else "#c25b4e" if pnl_v < 0 else FG
                        cell.set_text_props(color=color if heads[ci] in ("PnL", "R") else FG)
            else:
                ax.text(0.4, 0.5, "No closed trades in range.", color=DIM)
            pdf.savefig(fig, facecolor=BG); plt.close(fig)
    return buf.getvalue()


@app.get("/api/export/{dataset}")
def export_dataset(dataset: str, format: str = "json"):
    dataset = dataset.lower()
    data: Any
    if dataset == "trades":
        data = _live_trades()
    elif dataset == "analytics":
        data = _live_analytics()
    elif dataset == "signals":
        data = _live_signals()
    elif dataset == "journal":
        data = _live_journal()
    elif dataset == "settings":
        data = _safe_public_settings(SETTINGS_STATE)
    else:
        return JSONResponse({"ok": False, "message": "Unknown export dataset."}, status_code=404)
    if format.lower() == "csv":
        rows = data if isinstance(data, list) else data.get("history") or data.get("active") or []
        if not rows:
            return Response("message\nNo rows available\n", media_type="text/csv")
        keys = sorted({k for row in rows if isinstance(row, dict) for k in row.keys()})
        lines = [",".join(keys)]
        for row in rows:
            lines.append(",".join(str(row.get(k, "")).replace(",", " ").replace("\n", " ") for k in keys))
        return Response("\n".join(lines), media_type="text/csv", headers={"Content-Disposition": f"attachment; filename=godmode_{dataset}.csv"})
    return JSONResponse(data, headers={"Content-Disposition": f"attachment; filename=godmode_{dataset}.json"})


