_CHART_CANDLES_CACHE: dict[str, tuple[float, list]] = {}

@app.get("/api/market/candles")
def market_candles(tf: str = "M15", count: int = 400):
    """V13.1: timeframe-aware candles for the chart's TF switcher. Lets the dashboard chart show
    M1..D1 without touching the global trading timeframe. Short per-TF cache (2s live / 20s
    higher TFs) so rapid switching costs nothing. Falls back to demo candles when MT5 is off so
    the chart is never a white rectangle."""
    tf = str(tf or "M15").upper()
    if tf not in {"M1", "M5", "M15", "M30", "H1", "H4", "D1"}:
        tf = "M15"
    count = max(50, min(int(count or 400), 1500))
    ttl = 2.0 if tf in {"M1", "M5"} else 20.0
    key = f"{tf}:{count}"
    now = time.time()
    hit = _CHART_CANDLES_CACHE.get(key)
    if hit and now - hit[0] < ttl:
        return {"ok": True, "tf": tf, "candles": hit[1], "cached": True}
    symbol = str(SETTINGS_STATE.get("trading", {}).get("symbol", "XAUUSD"))
    candles: list = []
    try:
        if mt5_bridge.status().get("connected"):
            candles = mt5_bridge.copy_rates(symbol, tf, count) or []
        if not candles and _demo_enabled():
            snap = demo_data.market_snapshot(symbol, tf)
            candles = (snap or {}).get("candles") or []
    except Exception:
        candles = []
    _CHART_CANDLES_CACHE[key] = (now, candles)
    return {"ok": True, "tf": tf, "candles": candles, "cached": False}


