@app.post("/api/journal/entry")
def journal_add_entry(payload: dict[str, Any] = Body(default={})):
    """Add a manual journal entry (a reflection / lesson the user writes). Persisted to disk so it
    survives restarts and shows alongside the bot's auto trade-journal entries."""
    now = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
    entry = {
        "id": f"man-{int(time.time()*1000)}",
        "date": str(payload.get("date") or now[:10]),
        "time": str(payload.get("date") or now[:10]) + " " + now[11:19] + " UTC",
        "symbol": str(payload.get("symbol") or "XAUUSD")[:20],
        "side": str(payload.get("side") or "—")[:8],
        "outcome": str(payload.get("outcome") or "NOTE")[:16],
        "pnl": float(payload.get("pnl", 0) or 0),
        "strategy": str(payload.get("strategy") or "Manual note")[:80],
        "session": str(payload.get("session") or "—")[:40],
        "confidence": float(payload.get("confidence", 0) or 0),
        "lessons": str(payload.get("lessons") or "")[:2000],
        "improvement": str(payload.get("improvement") or "")[:2000],
        "notes": str(payload.get("notes") or "")[:2000],
        "tags": [str(t)[:24] for t in (payload.get("tags") or ["manual"])][:8],
        "createdAt": now,
    }
    MANUAL_JOURNAL.append(entry)
    try:
        with MANUAL_JOURNAL_FILE.open("a", encoding="utf-8") as f:
            f.write(json.dumps(entry) + "\n")
    except Exception as exc:
        return {"ok": False, "message": f"Could not save: {exc}"}
    return {"ok": True, "message": "Journal entry saved.", "entry": _manual_to_entry(entry)}


@app.get("/api/analysis/exit-lab")
def analysis_exit_lab(days: int = 30, min_sample: int = 30):
    """V13.11 — Exit Lab (Phase 1 of the GodMode roadmap): turns maeR/mfeR into arithmetic.

    THE two open questions in this system are exit questions:
      1. LOSS CAP — would cutting losers at -X R have saved money, or would it have killed
         winners that dip before they pay? Unanswerable without maeR; pure arithmetic with it.
      2. TRAIL GIVEBACK — how much of the winners' peak (mfeR) is actually banked? If winners
         peak at 2R and bank 0.4R, the trail is the biggest lever in the system.
    Refuses to recommend below min_sample instrumented trades — an answer from 5 trades is
    worse than no answer. Recommendations map to already-whitelisted coach paths.
    """
    rows = _vetting_journal_rows(days=days)
    inst = [r for r in rows if str(r.get("maeR", "")).strip() not in ("", "None") and _to_float(r.get("rMultiple")) is not None]
    wins = [r for r in inst if _to_float(r.get("pnlUsd"), 0.0) > 0]
    losses = [r for r in inst if _to_float(r.get("pnlUsd"), 0.0) <= 0]
    resp: dict[str, Any] = {"ok": True, "instrumented": len(inst), "minSample": int(min_sample),
                            "wins": len(wins), "losses": len(losses)}
    if len(inst) < int(min_sample):
        resp["status"] = "insufficient_data"
        resp["message"] = (f"Only {len(inst)} instrumented trades (need {min_sample}). Every closed trade since "
                          f"V13.7 records maeR/mfeR — keep trading; this page answers itself when the sample lands.")
        return resp
    # 1) LOSS-CAP SWEEP — for each candidate cap in R: losers saved vs winners killed (winner killed
    #    = its maeR went deeper than the cap BEFORE it won; it would have been stopped at the cap).
    sweep = []
    for cap in (-0.4, -0.5, -0.6, -0.8, -1.0):
        saved = sum((_to_float(r.get("rMultiple"), 0.0) - cap) * -1 for r in losses if _to_float(r.get("rMultiple"), 0.0) < cap)
        killed = [r for r in wins if _to_float(r.get("maeR"), 0.0) <= cap]
        killed_cost = sum(_to_float(r.get("rMultiple"), 0.0) - cap for r in killed)
        sweep.append({"capR": cap, "losersCut": sum(1 for r in losses if _to_float(r.get("rMultiple"), 0.0) < cap),
                      "savedR": round(saved, 2), "winnersKilled": len(killed),
                      "killedCostR": round(killed_cost, 2), "netR": round(saved - killed_cost, 2)})
    best = max(sweep, key=lambda x: x["netR"])
    resp["lossCapSweep"] = sweep
    resp["lossCap"] = {"bestCapR": best["capR"], "netR": best["netR"],
                       "recommend": best["netR"] > 0.5,
                       "coachPath": "trading.tradeManagement.fastFailLossR",
                       "verdict": (f"Cap at {best['capR']}R nets {best['netR']:+.2f}R on this sample"
                                   if best["netR"] > 0.5 else
                                   "No cap tested beats the current exits — winners dip too deep before paying; leave it alone.")}
    # 2) TRAIL GIVEBACK — banked fraction of peak, per winner
    give = []
    for r in wins:
        mfe = _to_float(r.get("mfeR"), 0.0); banked = _to_float(r.get("rMultiple"), 0.0)
        if mfe and mfe > 0.2:
            give.append({"banked": banked, "peak": mfe, "frac": banked / mfe})
    if give:
        import statistics as _st
        med_frac = _st.median(g["frac"] for g in give)
        med_peak = _st.median(g["peak"] for g in give)
        resp["trailGiveback"] = {
            "winnersWithPeak": len(give),
            "medianBankedFractionOfPeak": round(med_frac, 2),
            "medianPeakR": round(med_peak, 2),
            "coachPath": "trading.tradeManagement.aiDynamicMaxGivebackFraction",
            "verdict": (f"Winners bank only {med_frac:.0%} of a {med_peak:.1f}R median peak — the trail is "
                        f"strangling them; widen giveback tolerance." if med_frac < 0.55 else
                        f"Winners bank {med_frac:.0%} of peak — trail is doing its job; the leak is elsewhere.")}
    else:
        resp["trailGiveback"] = {"winnersWithPeak": 0, "verdict": "No winners with recorded peaks yet."}
    resp["status"] = "ok"
    return resp


@app.get("/api/journal/missed-pumps")
def journal_missed_pumps(limit: int = 40, lookahead_minutes: int = 60):
    """Replay missed moves from executable bid/ask ticks in chronological order."""
    raw = [e for e in DECISION_JOURNAL if e.get("category") == "missed_pump"]
    rows = deduplicate_events(raw)
    rows = rows[-max(1, min(int(limit or 40), 200)):]
    if not rows:
        return {"ok": True, "items": [], "totals": {"count": 0, "scored": 0, "realMisses": 0, "couldHaveMadeUsd": 0.0, "pending": 0},
                "note": "No missed pumps logged yet."}

    now_ts = time.time()
    horizon_ms = max(1, int(lookahead_minutes or 60)) * 60 * 1000
    mature = [r for r in rows if int(_fs_float(r.get("entryTimeMsc"), 0.0)) > 0 and now_ts * 1000 - int(_fs_float(r.get("entryTimeMsc"), 0.0)) >= horizon_ms]
    ticks_by_symbol: dict[str, list[dict[str, Any]]] = {}
    for symbol in sorted({str(r.get("symbol") or (SETTINGS_STATE.get("trading") or {}).get("symbol") or mt5_bridge.symbol or "XAUUSD") for r in mature}):
        symbol_rows = [r for r in mature if str(r.get("symbol") or symbol) == symbol]
        starts = [int(_fs_float(r.get("entryTimeMsc"), 0.0)) for r in symbol_rows]
        if not starts:
            continue
        try:
            ticks_by_symbol[symbol] = mt5_bridge.copy_ticks_range(symbol, min(starts) / 1000.0, (max(starts) + horizon_ms) / 1000.0)
        except Exception as exc:
            LOGGER.warning("Missed-move tick replay unavailable symbol=%s: %s", symbol, exc)
            ticks_by_symbol[symbol] = []

    out: list[dict[str, Any]] = []
    for event in rows:
        item = dict(event)
        side = str(event.get("side") or "").upper()
        entry = _fs_float(event.get("entryPrice") or event.get("price"), 0.0)
        start_msc = int(_fs_float(event.get("entryTimeMsc"), 0.0))
        symbol = str(event.get("symbol") or (SETTINGS_STATE.get("trading") or {}).get("symbol") or mt5_bridge.symbol or "XAUUSD")
        item.update({"couldHaveMadeUsd": None, "worstFirstUsd": None, "verdict": "unknown"})
        if side not in ("BUY", "SELL") or entry <= 0 or start_msc <= 0:
            item["verdict"] = "legacy_no_executable_quote"
            out.append(item)
            continue
        if now_ts * 1000 - start_msc < horizon_ms:
            item["verdict"] = "pending"
            out.append(item)
            continue
        end_msc = start_msc + horizon_ms
        ticks = [tick for tick in ticks_by_symbol.get(symbol, []) if start_msc <= int(tick.get("timeMsc") or 0) <= end_msc]
        replay = replay_executable_ticks(side, entry_price=entry, entry_time_msc=start_msc, ticks=ticks)
        item["replay"] = replay
        if not replay.get("ok"):
            item["verdict"] = "no_tick_data"
            out.append(item)
            continue
        best = float(replay.get("bestFavourable") or 0.0)
        worst_before_best = float(replay.get("worstBeforeBest") or 0.0)
        replay_volume = 0.01
        best_exit_price = _fs_float(replay.get("bestExitPrice"), 0.0)
        worst_exit_price = _fs_float(replay.get("worstBeforeBestExitPrice"), 0.0)
        best_pnl = mt5_bridge.order_calc_profit(side, symbol, replay_volume, entry, best_exit_price) if best_exit_price > 0 else 0.0
        worst_pnl = mt5_bridge.order_calc_profit(side, symbol, replay_volume, entry, worst_exit_price) if worst_exit_price > 0 else 0.0
        pnl_source = "broker_order_calc_profit"
        if best_pnl is None:
            best_pnl = best
            pnl_source = "xau_0_01_price_distance_fallback"
        if worst_pnl is None:
            worst_pnl = -worst_before_best
            pnl_source = "xau_0_01_price_distance_fallback"
        item.update({"replayVolume": 0.01, "pnlSource": pnl_source})
        item["couldHaveMadeUsd"] = round(max(0.0, float(best_pnl)), 2)
        item["worstFirstUsd"] = round(min(0.0, float(worst_pnl)), 2)
        item["bestTimeMsc"] = replay.get("bestTimeMsc")
        if best >= 2.0 and worst_before_best <= 1.0:
            item["verdict"] = "real_miss"
        elif best >= 2.0:
            item["verdict"] = "would_have_hurt_first"
        elif best < 1.0:
            item["verdict"] = "not_worth_it"
        else:
            item["verdict"] = "marginal"
        out.append(item)

    scored = [i for i in out if isinstance(i.get("couldHaveMadeUsd"), (int, float))]
    real = [i for i in scored if i.get("verdict") == "real_miss"]
    hurt = [i for i in scored if i.get("verdict") == "would_have_hurt_first"]
    gross = round(sum(float(i.get("couldHaveMadeUsd") or 0.0) for i in scored if float(i.get("couldHaveMadeUsd") or 0.0) > 0), 2)
    return {
        "ok": True, "items": out,
        "totals": {
            "count": len(out), "scored": len(scored), "realMisses": len(real),
            "couldHaveMadeUsd": round(sum(float(i.get("couldHaveMadeUsd") or 0.0) for i in real), 2),
            "grossReachableUsd": gross, "wouldHaveHurtFirst": len(hurt),
            "pending": sum(1 for i in out if i.get("verdict") == "pending"),
            "noData": sum(1 for i in out if i.get("verdict") in {"no_tick_data", "legacy_no_executable_quote"}),
        },
        "note": "Replay starts at the first executable quote after the blocked decision (BUY ask / SELL bid) and exits on chronological broker ticks (BUY bid / SELL ask). Duplicate candle events are consolidated by eventId.",
    }


@app.get("/api/journal/decisions")
def journal_decisions(category: str | None = None, limit: int = 250):
    """The Decision & Management Journal: WHY the bot did or didn't trade (entry decisions with
    confidence + blocking reasons), every management action (BE/trail/recovery-room/fast-fail/
    partials), and close outcomes — persisted across restarts."""
    items = DECISION_JOURNAL
    if category and category not in ("all", ""):
        items = [e for e in items if e.get("category") == category]
    counts: dict[str, int] = {}
    for e in DECISION_JOURNAL:
        c = str(e.get("category", "?"))
        counts[c] = counts.get(c, 0) + 1
    return {"ok": True, "items": items[: max(1, min(int(limit or 250), 1000))],
            "counts": counts, "total": len(DECISION_JOURNAL)}


