@app.get("/api/ai/trade-review-engine")
def ai_trade_review_engine(days: int = 30):
    """V12.80 — Deterministic trade-review engine. Pure arithmetic over closed trades:
    expectancy source, loss/win asymmetry, deep-loser count, winner giveback, per-strategy
    and per-session breakdown, plus sample-gated PROPOSALS (never auto-applied). No LLM."""
    rows = _vetting_journal_rows(days=days)
    stats = trade_review.summarise(rows)
    verdict = trade_review.findings_and_proposals(stats)
    # V12.83: opportunity cost of the no-chase rule, measured alongside realised performance
    try:
        expired = _expired_arm_summary(days=days)
    except Exception:
        expired = {}
    return {"ok": True, "stats": stats, "expiredArms": expired, **verdict}


@app.post("/api/ai/trade-review-llm")
def ai_trade_review_llm(payload: dict[str, Any] = Body(default={})):
    """V12.80 — Optional deeper review. Runs the LLM over the DETERMINISTIC AGGREGATES only
    (never raw trades, so it cannot overfit), and only when the sample is large enough. Falls
    back to the deterministic verdict if no API key is configured."""
    days = int(payload.get("days", 30) or 30)
    rows = _vetting_journal_rows(days=days)
    stats = trade_review.summarise(rows)
    det = trade_review.findings_and_proposals(stats)
    n = int(stats.get("sampleSize", 0) or 0)
    if not det.get("canPropose"):
        return {"ok": True, "mode": "deterministic_only",
                "message": f"Only {n} trades — too few for an LLM review (need "
                           f"{trade_review.MIN_SAMPLE_PROPOSAL}). Showing deterministic findings.",
                "stats": stats, **det}
    prompt = trade_review.build_llm_prompt(stats, det)
    # Reuse the same provider the AI reviewer is configured with.
    if not (ai_reviewer.enabled and ai_reviewer.api_key):
        return {"ok": True, "mode": "deterministic_only",
                "message": "No AI provider key set (Settings 12d). Showing deterministic findings; "
                           "add a key to enable the written diagnosis.",
                "stats": stats, **det}
    try:
        llm_text = ai_reviewer.freeform(prompt) if hasattr(ai_reviewer, "freeform") else None
    except Exception as e:
        llm_text = None
        det["llmError"] = str(e)[:160]
    return {"ok": True, "mode": "llm" if llm_text else "deterministic_only",
            "llmDiagnosis": llm_text, "stats": stats, **det}


@app.post("/api/ai/apply-proposal")
def ai_apply_proposal(payload: dict[str, Any] = Body(default={})):
    """V12.80 — apply ONE user-approved review proposal. This is the only path that writes a
    setting from the review engine, and it only accepts a whitelisted set of dotted paths so a
    malformed or malicious proposal can't touch anything arbitrary. Snapshots first (rollback)."""
    # V12.99.2 BUGFIX: the coach proposes 15 different paths but this whitelist only allowed 5,
    # and they barely overlapped — so clicking "Approve" on almost any suggestion silently did
    # nothing ("not in the approved whitelist"). The proposer and the applier were built with
    # different vocabularies. Every path the coach can emit is now here, each with a safe range.
    ALLOWED = {
        # trade management
        "trading.tradeManagement.fastFailLossR": (-1.0, -0.10),
        "trading.tradeManagement.trailTightenAfterR": (0.2, 2.0),
        "trading.tradeManagement.fastFailNoProgressMinutes": (5.0, 60.0),
        "trading.tradeManagement.aiDynamicMaxGivebackFraction": (0.10, 0.80),
        "trading.tradeManagement.aiDynamicMinLockFraction": (0.10, 0.90),
        # V13.12 scraps fix: noise floor before the profit ratchet engages (Exit Lab will tune it)
        "trading.tradeManagement.profitLockMinPeakAtr": (0.30, 1.20),
        # V13.9 counter-HTF momentum lane (coach may tune the bar, never below 1.05 = aligned bar)
        "automation.momentumCounterHtfMinAtr": (1.05, 2.50),
        # loss governor
        "automation.postLossConfidenceCap": (80.0, 95.0),
        "automation.postLossProofNeeded": (3, 6),
        "automation.postLossReentryMinConfidence": (70.0, 95.0),
        "automation.postLossReentryConfidenceDelta": (0.0, 15.0),
        "automation.maxSameDirectionLossesBeforeHardLock": (1, 5),
        # fast lane
        "automation.fastSniperMinConfidence": (70.0, 95.0),
        "automation.fastSniperMaxExtensionAtr": (0.50, 2.00),
        # entry strictness
        "ai.scoutConfidence": (65.0, 90.0),
        "ai.standardConfidence": (70.0, 95.0),
        "ai.maxSpread": (0.10, 1.00),
        # pyramiding
        "pyramiding.maxAdds": (0, 5),
        "pyramiding.minAddConfidence": (70.0, 95.0),
        "pyramiding.minProfitRFirstAdd": (0.1, 2.0),
    }
    path = str(payload.get("path") or "")
    if path not in ALLOWED:
        return {"ok": False, "message": f"Proposal path '{path}' is not in the approved whitelist."}
    lo, hi = ALLOWED[path]
    try:
        val = float(payload.get("suggest"))
    except Exception:
        return {"ok": False, "message": "Proposal value is not numeric."}
    if not (lo <= val <= hi):
        return {"ok": False, "message": f"Value {val} outside safe range [{lo}, {hi}] for {path}."}
    # integer-typed settings stay integers
    # V12.99.2: coerce every integer-typed setting, not just postLossProofNeeded — writing 2.0
    # into a counter like maxAdds/maxSameDirectionLossesBeforeHardLock could break comparisons.
    if path in {"automation.postLossProofNeeded", "automation.maxSameDirectionLossesBeforeHardLock",
                "pyramiding.maxAdds", "trading.tradeManagement.fastFailNoProgressMinutes"}:
        val = int(round(val))
    with SETTINGS_LOCK:
        _settings_snapshot(f"before_review_proposal_{payload.get('id','')}")
        node = SETTINGS_STATE
        parts = path.split(".")
        for k in parts[:-1]:
            node = node.setdefault(k, {})
            if not isinstance(node, dict):
                return {"ok": False, "message": f"Settings path {path} is not writable."}
        old = node.get(parts[-1])
        node[parts[-1]] = val
        receipt = _save_settings(f"review_proposal:{payload.get('id','')}")
    return {"ok": True, "message": f"Applied {path}: {old} → {val}. Saved (rollback snapshot taken).",
            "path": path, "old": old, "new": val, "saveReceipt": receipt}


@app.get("/api/ai/unified-recommendations")
def ai_unified_recommendations(days: int = 30):
    """V12.81 — ONE place for every setting-change the system wants to suggest.

    Previously the AI Agent page had four separate 'apply' surfaces: the coach's recommendedFixes
    table, its configRecommendation, the Adaptive Config Library, and the V12.80 review engine.
    That meant multiple buttons all telling the user to 'apply a fix'. This endpoint merges them
    into a single, de-duplicated, severity-ranked list. Each item is applied through the SAME
    approval path (/api/ai/apply-proposal for setting diffs, /api/config-library/apply for whole
    profiles), so there is one mental model: review -> approve -> done.
    """
    items: list[dict[str, Any]] = []
    seen_paths: set[str] = set()

    # (1) deterministic trade-review proposals (highest trust: pure arithmetic, sample-gated)
    try:
        rows = _vetting_journal_rows(days=days)
        stats = trade_review.summarise(rows)
        det = trade_review.findings_and_proposals(stats)
        for p in det.get("proposals", []):
            path = str(p.get("path") or "")
            if path and path not in seen_paths:
                seen_paths.add(path)
                items.append({
                    "kind": "setting", "source": "trade_review", "id": p.get("id"),
                    "title": p.get("title"), "rationale": p.get("rationale"),
                    "path": path, "suggest": p.get("suggest"), "current_hint": p.get("current_hint"),
                    "risk": p.get("risk", "medium"), "confidence": p.get("confidence", "LOW"),
                })
        review_meta = {"sampleSize": det.get("sampleSize"), "canPropose": det.get("canPropose"),
                       "verdict": det.get("verdict"), "findings": det.get("findings", [])}
    except Exception as e:
        review_meta = {"error": str(e)[:120]}

    # (2) coach recommendedFixes (from the self-training review), de-duplicated against (1)
    try:
        rv = ai_performance_review(period="daily", use_ai=False)
        for fx in (rv.get("recommendedFixes") or []):
            path = str(fx.get("path") or "")
            if path and path not in seen_paths:
                seen_paths.add(path)
                items.append({
                    "kind": "setting", "source": "coach", "id": f"coach_{path}",
                    "title": f"Coach: adjust {path.split('.')[-1]}",
                    "rationale": fx.get("reason", ""), "path": path,
                    "suggest": fx.get("to"), "current_hint": str(fx.get("from")),
                    "risk": "low", "confidence": "MEDIUM",
                })
        # (3) the coach's single config recommendation -> one profile item
        cr = rv.get("configRecommendation")
        if cr and cr.get("name"):
            items.append({
                "kind": "profile", "source": "coach", "id": cr.get("id") or cr.get("name"),
                "title": f"Switch profile: {cr.get('name')}",
                "rationale": cr.get("reason", ""), "profileId": cr.get("id") or cr.get("name"),
                "risk": "medium", "confidence": "MEDIUM",
            })
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_8673", _suppressed_exc)

    order = {"high": 0, "HIGH": 0, "medium": 1, "MEDIUM": 1, "low": 2, "LOW": 2}
    items.sort(key=lambda x: order.get(x.get("risk", "medium"), 1))
    return {"ok": True, "count": len(items), "items": items, "review": review_meta,
            "note": ("No changes proposed yet — sample too small to act on safely."
                     if not items else "Approve each change individually; all use one apply flow.")}


