def _order_payload_from_market(payload: dict[str, Any] | None = None) -> dict[str, Any]:
    payload = payload or {}
    market = _live_market()
    trading = SETTINGS_STATE.get("trading", {}) if isinstance(SETTINGS_STATE.get("trading"), dict) else {}
    symbol = str(payload.get("symbol") or trading.get("symbol") or market.get("symbol") or "XAUUSD")
    side = str(payload.get("side") or payload.get("direction") or market.get("side") or "BUY").upper()
    volume = float(payload.get("volume") or payload.get("lot") or payload.get("lots") or 0.01)
    price = float(payload.get("price") or market.get("price") or 0.0)
    sl = payload.get("sl")
    tp = payload.get("tp")
    # If no SL/TP is supplied, build conservative placeholders around the current price.
    if price and (sl is None or tp is None):
        dist = 6.0
        if side == "BUY":
            sl = sl if sl is not None else round(price - dist, 3)
            tp = tp if tp is not None else round(price + dist * 1.8, 3)
        else:
            sl = sl if sl is not None else round(price + dist, 3)
            tp = tp if tp is not None else round(price - dist * 1.8, 3)
    order = {
        "symbol": symbol,
        "side": side,
        "volume": volume,
        "sl": sl,
        "tp": tp,
        "deviation": int(payload.get("deviation") or mt5_bridge.max_deviation),
        "magic": mt5_bridge.magic,
        "comment": str(payload.get("comment") or "GODMODE_manual"),
        "source": "godmode_bot",
    }
    for field in ExecutionLedger.IDENTITY_FIELDS:
        if payload.get(field):
            order[field] = payload[field]
    if payload.get("operation"):
        order["operation"] = str(payload["operation"]).upper()
    return order

def _record_auto_heartbeat(result: dict[str, Any]) -> dict[str, Any]:
    entry = {
        "id": int(time.time() * 1000),
        "time": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()),
        "ok": bool(result.get("ok")),
        "blocked": bool(result.get("blocked")),
        "message": result.get("message", "Auto-trade checked."),
        "reason": result.get("reason", "auto_trade"),
        "quality": ((result.get("actionMatrix") or {}).get("decision") or {}).get("quality"),
        "confidence": ((result.get("actionMatrix") or {}).get("decision") or {}).get("confidence"),
        "blockedReasons": (result.get("actionMatrix") or {}).get("blockedReasons") or ((result.get("actionMatrix") or {}).get("decision") or {}).get("decisionBlocks", []),
        "softBlocks": (result.get("actionMatrix") or {}).get("softBlocks") or ((result.get("actionMatrix") or {}).get("decision") or {}).get("softBlocks", []),
    }
    AUTO_TRADE_HEARTBEAT.insert(0, entry)
    del AUTO_TRADE_HEARTBEAT[100:]
    try:
        _journal_entry_decision(result, entry)
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_8762", _suppressed_exc)
    return entry


def _lot_risk_ceiling(symbol: str, entry: float, sl: float, risk_pct: float | None = None) -> dict[str, Any]:
    """Maximum lot allowed by account equity, stop distance and configured risk.
    This is a HARD safety ceiling used by normal entries, Telegram TAKE/SCOUT and win-streak scaling."""
    try:
        tcfg = SETTINGS_STATE.get("trading", {}) if isinstance(SETTINGS_STATE.get("trading"), dict) else {}
        risk_pct = float(risk_pct if risk_pct is not None else tcfg.get("riskPerTrade", 0.5) or 0.5)
        stop_dist = abs(float(entry) - float(sl))
        equity = float(_live_account().get("equity") or _live_account().get("balance") or 0)
        specs = mt5_bridge.symbol_specs(symbol)
        minv = float(specs.get("volumeMin", 0.01) or 0.01)
        step = float(specs.get("volumeStep", 0.01) or 0.01) or 0.01
        broker_max = float(specs.get("volumeMax", 100.0) or 100.0)
        if stop_dist <= 0 or equity <= 0 or risk_pct <= 0:
            return {"lot": minv, "rawLot": minv, "source": "fallback_no_inputs", "minLot": minv, "step": step, "brokerMax": broker_max}
        tick_val = float(specs.get("tradeTickValue") or 0.0)
        tick_size = float(specs.get("tradeTickSize") or 0.0)
        loss_per_lot = (stop_dist / tick_size) * tick_val if tick_val > 0 and tick_size > 0 else stop_dist * 100.0
        if loss_per_lot <= 0:
            return {"lot": minv, "rawLot": minv, "source": "fallback_bad_specs", "minLot": minv, "step": step, "brokerMax": broker_max}
        risk_cash = equity * risk_pct / 100.0
        raw_lot = risk_cash / loss_per_lot
        stepped = math.floor(raw_lot / step + 1e-9) * step
        lot = max(minv, min(broker_max, stepped))
        return {"lot": round(lot, 2), "rawLot": round(raw_lot, 4), "riskCash": round(risk_cash, 2),
                "actualRisk": round(lot * loss_per_lot, 2), "lossPerLot": round(loss_per_lot, 2),
                "riskPct": risk_pct, "stopDist": round(stop_dist, 3), "minClamped": stepped < minv,
                "minLot": minv, "step": step, "brokerMax": broker_max, "source": specs.get("source", "calc")}
    except Exception as exc:
        return {"lot": float((SETTINGS_STATE.get("pyramiding", {}) or {}).get("baseLot") or 0.01), "source": f"fallback_err:{exc}", "minLot": 0.01, "step": 0.01, "brokerMax": 100.0}


def _normalise_lot_to_step(symbol: str, lot: float) -> float:
    try:
        specs = mt5_bridge.symbol_specs(symbol)
        minv = float(specs.get("volumeMin", 0.01) or 0.01)
        step = float(specs.get("volumeStep", 0.01) or 0.01) or 0.01
        maxv = float(specs.get("volumeMax", 100.0) or 100.0)
        val = max(minv, min(maxv, float(lot)))
        val = minv + math.floor((val - minv) / step + 1e-9) * step
        return round(max(minv, min(maxv, val)), 2)
    except Exception:
        return round(max(0.01, float(lot or 0.01)), 2)


def _safe_entry_lot(symbol: str, desired_lot: float, entry: float, sl: float, context: str = "entry", risk_pct: float | None = None) -> dict[str, Any]:
    """Single source of truth for first-entry / Telegram lot safety.
    Respects baseLot + lotStep increments, maxLot/maxTotalLots and account-risk ceiling.
    Prevents accidental jumps like 0.01 → 1.42 when volatility sizing sees a tight SL."""
    pyr = SETTINGS_STATE.get("pyramiding", {}) if isinstance(SETTINGS_STATE.get("pyramiding"), dict) else {}
    base = float(pyr.get("baseLot") or 0.01)
    step = float(pyr.get("lotStep") or 0.01) or 0.01
    max_lot = float(pyr.get("maxLot") or base)
    max_total_lots = float(pyr.get("maxTotalLots") or max_lot)
    risk_ceiling = _lot_risk_ceiling(symbol, entry, sl, risk_pct=risk_pct)
    risk_lot = float(risk_ceiling.get("lot") or base)
    # First entries are capped by the smaller of user Max Lot, total-lot cap, and account-risk lot.
    # Account risk is a ceiling, never a suggestion. A configured base lot may
    # describe the preferred ladder, but it must not raise the result above the
    # independently calculated risk lot.
    cap = min(max_lot, max_total_lots, risk_lot)
    desired = float(desired_lot or base)
    # Respect configured increment ladder; never allow arbitrary non-ladder jumps.
    if desired > base:
        laddered = base + math.floor((desired - base) / step + 1e-9) * step
    else:
        laddered = base
    lot = _normalise_lot_to_step(symbol, min(laddered, cap))
    risk_cash = float(risk_ceiling.get("riskCash") or 0.0)
    actual_risk = float(risk_ceiling.get("actualRisk") or 0.0)
    untradeable_at_minimum = bool(
        risk_ceiling.get("minClamped")
        and risk_cash > 0
        and actual_risk > risk_cash + 0.01
    )
    return {"lot": lot, "desiredLot": round(desired, 4), "ladderedLot": round(laddered, 4), "capLot": round(cap, 4),
            "baseLot": base, "lotStep": step, "maxLot": max_lot, "maxTotalLots": max_total_lots,
            "riskCeiling": risk_ceiling, "context": context, "capped": lot < desired - 1e-9,
            "untradeableAtBrokerMinimum": untradeable_at_minimum}


def _protected_entry_payload(
    payload: dict[str, Any],
    context: str,
    trade_plan: dict[str, Any] | None = None,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    """Build a broker-ready entry with a directional stop and the shared risk ceiling.

    UI signal execution, manual tickets, Telegram and pyramiding must all cross the same
    protection boundary. This prevents a missing UI field from becoming an unprotected
    market order and prevents a manually supplied lot from bypassing account-risk limits.
    """
    supplied = dict(payload or {})
    plan = trade_plan if isinstance(trade_plan, dict) else {}
    market = supplied.get("market") if isinstance(supplied.get("market"), dict) else _live_market()
    side = str(
        supplied.get("side")
        or supplied.get("direction")
        or plan.get("side")
        or market.get("side")
        or ""
    ).upper()
    if side not in {"BUY", "SELL"}:
        return None, {"ok": False, "blocked": True, "message": "Protected entry requires an explicit BUY or SELL direction."}

    entry = float(supplied.get("price") or plan.get("entry") or market.get("price") or 0.0)
    if entry <= 0:
        return None, {"ok": False, "blocked": True, "message": "Protected entry requires a current broker price."}

    if supplied.get("sl") in (None, "") and plan.get("sl") not in (None, ""):
        supplied["sl"] = plan.get("sl")
    if supplied.get("tp") in (None, ""):
        supplied["tp"] = next(
            (plan.get(name) for name in ("tp4", "tp3", "tp2", "tp1", "tp") if plan.get(name) not in (None, "")),
            None,
        )
    supplied.update({"side": side, "price": entry})
    order = _order_payload_from_market(supplied)
    try:
        sl = float(order.get("sl") or 0.0)
        tp = float(order.get("tp") or 0.0)
    except (TypeError, ValueError):
        return None, {"ok": False, "blocked": True, "message": "Protected entry received an invalid SL or TP."}
    if sl <= 0 or (side == "BUY" and sl >= entry) or (side == "SELL" and sl <= entry):
        return None, {"ok": False, "blocked": True, "message": f"Protected {side} entry requires an SL on the loss side of {entry:.3f}."}
    if tp > 0 and ((side == "BUY" and tp <= entry) or (side == "SELL" and tp >= entry)):
        return None, {"ok": False, "blocked": True, "message": f"Protected {side} entry requires a TP on the profit side of {entry:.3f}."}

    desired = float(order.get("volume") or 0.01)
    sizing = _safe_entry_lot(str(order.get("symbol") or "XAUUSD"), desired, entry, sl, context)
    risk_source = str((sizing.get("riskCeiling") or {}).get("source") or "")
    if mt5_bridge.live_enabled and risk_source.startswith("fallback"):
        return None, {
            "ok": False,
            "blocked": True,
            "message": "Protected live entry blocked: authoritative account and broker risk-sizing inputs are unavailable.",
            "sizingGuard": sizing,
        }
    if sizing.get("untradeableAtBrokerMinimum"):
        return None, {
            "ok": False,
            "blocked": True,
            "message": "Protected entry blocked: the broker minimum lot would exceed the configured account-risk budget for this stop distance.",
            "sizingGuard": sizing,
        }
    order["volume"] = sizing["lot"]
    order["sizingGuard"] = sizing
    risk_cash = float((sizing.get("riskCeiling") or {}).get("riskCash") or 0.0)
    if risk_cash > 0:
        # The bridge re-prices at the final live tick and may widen the stop to
        # satisfy broker minimum distance. Carry the authoritative cash ceiling
        # so that final broker geometry can never increase risk silently.
        order["maxRiskCash"] = risk_cash
    return order, None




def _ema_last(values: list[float], period: int) -> float:
    """Tiny local EMA helper used by the post-loss governor."""
    if not values:
        return 0.0
    alpha = 2.0 / (period + 1.0)
    ema = float(values[0])
    for v in values[1:]:
        ema = alpha * float(v) + (1.0 - alpha) * ema
    return float(ema)


def _recent_session_edge_stats(minutes: int | None = None) -> dict[str, Any]:
    """Lightweight closed-trade stats from the in-memory trades cache only.

    This intentionally does NOT hit MT5 history. It is used inside the live entry path,
    so it must stay instant even after hours of running or when Burst creates many legs.
    """
    auto = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    minutes = int(minutes or auto.get("edgeGovernorLookbackMinutes", 240) or 240)
    now = time.time()
    cutoff = now - minutes * 60
    rows = []
    try:
        rows.extend((_TRADES_CACHE or {}).get("history") or [])
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_8931", _suppressed_exc)
    try:
        rows.extend(RECENT_CLOSED_TRADE_CACHE or [])
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_8935", _suppressed_exc)
    seen=set(); pnls=[]; by_side={"BUY": [], "SELL": []}; burst_losses=0
    for r in rows:
        try:
            tk = str(r.get("ticket") or r.get("positionId") or id(r))
            if tk in seen:
                continue
            seen.add(tk)
            ts = float(r.get("closeTimestamp") or r.get("_cacheTs") or 0.0)
            if not ts:
                # If timestamp is missing, keep only the most recent cached rows rather than parsing slow strings.
                ts = now
            if ts < cutoff:
                continue
            pnl = float(r.get("pnlUsd") or r.get("profit") or 0.0)
            if abs(pnl) < 1e-9:
                continue
            side = str(r.get("direction") or r.get("side") or "").upper()
            pnls.append(pnl)
            if side in by_side:
                by_side[side].append(pnl)
            if pnl < 0 and "BURST" in str(r.get("comment") or r.get("strategy") or "").upper():
                burst_losses += 1
        except Exception:
            continue
    wins=[x for x in pnls if x>0]; losses=[x for x in pnls if x<0]
    avg_win=sum(wins)/len(wins) if wins else 0.0
    avg_loss=abs(sum(losses)/len(losses)) if losses else 0.0
    gross_win=sum(wins); gross_loss=abs(sum(losses))
    return {"total": len(pnls), "wins": len(wins), "losses": len(losses), "net": round(sum(pnls),2),
            "avgWin": round(avg_win,2), "avgLoss": round(avg_loss,2),
            "lossWinRatio": round(avg_loss/max(avg_win,1e-9),2) if avg_win else (99.0 if avg_loss else 0.0),
            "profitFactor": round(gross_win/max(gross_loss,1e-9),2) if gross_loss else (99.0 if gross_win else 0.0),
            "largestLoss": round(abs(min(losses)) if losses else 0.0,2), "largestWin": round(max(wins) if wins else 0.0,2),
            "bySide": by_side, "burstLosses": burst_losses, "minutes": minutes}


def _entry_quality_metrics(market: dict[str, Any], side: str, decision: dict[str, Any] | None = None) -> dict[str, Any]:
    """Measure entry quality on the strategy's actual trigger timeframe.

    Fast Sniper, Early Intent and armed-retest decisions are M5 systems.  Older
    builds evaluated them against the dashboard's selected timeframe, commonly
    M15, which could both miss a late M5 top and call a clean M5 transition chop.
    """
    decision = decision or {}
    features = decision.get("features") if isinstance(decision.get("features"), dict) else {}
    strategy = str(decision.get("strategy") or "").lower()
    fast_strategy = bool(
        features.get("fastSniper") or features.get("anticipatoryEntry") or
        features.get("retestContinuation") or "fast sniper" in strategy or
        "early intent" in strategy or "early impulse" in strategy
    )
    rows = list(market.get("candles") or [])
    timeframe = str(market.get("timeframe") or (SETTINGS_STATE.get("trading") or {}).get("timeframe") or "M15").upper()
    candle_source = "market_snapshot"
    if fast_strategy:
        symbol = str(market.get("symbol") or (SETTINGS_STATE.get("trading") or {}).get("symbol") or "XAUUSD")
        candidates: list[tuple[float, list[dict[str, Any]]]] = []
        with PREDICTOR_CANDLE_LOCK:
            for key, item in PREDICTOR_CANDLE_CACHE.items():
                if len(key) >= 2 and str(key[0]) == symbol and str(key[1]).upper() == "M5" and isinstance(item, dict):
                    cached_rows = list(item.get("candles") or [])
                    if cached_rows:
                        candidates.append((float(item.get("fetchedAt", 0.0) or 0.0), cached_rows))
        if candidates:
            rows = deepcopy(max(candidates, key=lambda item: item[0])[1])
            timeframe = "M5"
            candle_source = "predictor_cache"
    if len(rows) < 25:
        return {"ok": False, "reason": "not_enough_candles", "timeframe": timeframe, "candleSource": candle_source}
    try:
        closes = [float(x.get("close") or 0.0) for x in rows if x.get("close") is not None]
        highs = [float(x.get("high") or x.get("close") or 0.0) for x in rows[-30:]]
        lows = [float(x.get("low") or x.get("close") or 0.0) for x in rows[-30:]]
        last = rows[-1]
        c = float(last.get("close") or market.get("price") or 0.0)
        # Recompute ATR from the selected timeframe. Reusing an M15 ATR for M5 bars
        # materially understates extension and overstates acceptable late entries.
        trs: list[float] = []
        atr_rows = rows[-16:]
        prev = float(atr_rows[0].get("close") or c)
        for row in atr_rows[1:]:
            high = float(row.get("high") or row.get("close") or prev)
            low = float(row.get("low") or row.get("close") or prev)
            close = float(row.get("close") or prev)
            trs.append(max(high - low, abs(high - prev), abs(low - prev)))
            prev = close
        atr = sum(trs[-14:]) / max(1, len(trs[-14:])) if trs else float(market.get("atr14") or 0.0)
        atr = max(atr, 1e-9)
        ema20 = _ema_last(closes[-80:], 20)
        ema50 = _ema_last(closes[-100:], 50) if len(closes) >= 50 else _ema_last(closes, min(34, len(closes)))

        recent = closes[-20:]
        path = sum(abs(recent[i] - recent[i - 1]) for i in range(1, len(recent))) or 1e-9
        efficiency = abs(recent[-1] - recent[0]) / path
        flips = sum(1 for i in range(2, len(recent)) if (recent[i] - recent[i-1]) * (recent[i-1] - recent[i-2]) < 0)

        auto = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
        leg_bars = max(5, min(int(auto.get("chopRecentLegBars", 7) or 7), 12))
        leg = closes[-leg_bars:]
        leg_path = sum(abs(leg[i] - leg[i-1]) for i in range(1, len(leg))) or 1e-9
        signed_leg = leg[-1] - leg[0]
        recent_efficiency = abs(signed_leg) / leg_path
        recent_flips = sum(1 for i in range(2, len(leg)) if (leg[i] - leg[i-1]) * (leg[i-1] - leg[i-2]) < 0)
        direction_sign = 1.0 if str(side).upper() == "BUY" else -1.0
        directional_move_atr = (signed_leg * direction_sign) / atr

        rng = max(highs) - min(lows) if highs and lows else 0.0
        wickiness = sum(
            (float(r.get("high") or r.get("close") or 0) - float(r.get("low") or r.get("close") or 0)) /
            max(abs(float(r.get("close") or 0) - float(r.get("open") or float(r.get("close") or 0))), 0.01)
            for r in rows[-10:]
        ) / min(10, len(rows))
        extension_atr = abs(c - ema20) / atr
        side = str(side or "").upper()
        reclaim_window = rows[-4:]
        if side == "BUY":
            pullback_reclaim = any(float(r.get("low") or c) <= ema20 + 0.25 * atr for r in reclaim_window) and c > ema20 and c >= ema50 and c >= max(closes[-4:-1] or [c]) - 0.15 * atr
            aligned = c > ema20 and ema20 >= ema50
            late = extension_atr > float(auto.get("maxEntryExtensionAtr", 0.95) or 0.95) and not pullback_reclaim
        elif side == "SELL":
            pullback_reclaim = any(float(r.get("high") or c) >= ema20 - 0.25 * atr for r in reclaim_window) and c < ema20 and c <= ema50 and c <= min(closes[-4:-1] or [c]) + 0.15 * atr
            aligned = c < ema20 and ema20 <= ema50
            late = extension_atr > float(auto.get("maxEntryExtensionAtr", 0.95) or 0.95) and not pullback_reclaim
        else:
            pullback_reclaim = False
            aligned = False
            late = False
        chop = efficiency < float(auto.get("chopEfficiencyMin", 0.22) or 0.22) or flips >= int(auto.get("chopMaxDirectionFlips", 8) or 8) or (wickiness > 5.0 and rng < 2.0 * atr)
        return {
            "ok": True, "side": side, "timeframe": timeframe, "candleSource": candle_source,
            "efficiency": round(efficiency, 3), "flips": flips,
            "recentLegEfficiency": round(recent_efficiency, 3), "recentFlips": recent_flips,
            "directionalMoveAtr": round(directional_move_atr, 2), "rangeAtr": round(rng / atr, 2),
            "extensionAtr": round(extension_atr, 2), "ema20": round(ema20, 3), "ema50": round(ema50, 3),
            "pullbackReclaim": bool(pullback_reclaim), "aligned": bool(aligned), "late": bool(late),
            "chop": bool(chop), "wickiness": round(wickiness, 2), "atr": round(atr, 5),
        }
    except Exception as exc:
        return {"ok": False, "reason": f"metrics_error: {exc}", "timeframe": timeframe, "candleSource": candle_source}


def _entry_quality_governor(decision: dict[str, Any], market: dict[str, Any], source: str = "auto") -> dict[str, Any]:
    """Blocks the five failure modes seen in live screenshots: large-loss asymmetry,
    weak-burst conditions, late entries, chop overtrading and loose scaling.
    Lightweight: uses current market snapshot + in-memory trade cache only.
    """
    auto = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    side = str((decision or {}).get("side") or (decision or {}).get("computedSide") or market.get("side") or "").upper()
    if side not in {"BUY", "SELL"}:
        return {"ok": True, "side": side}
    confidence = _to_float((decision or {}).get("confidence") or (decision or {}).get("qualityScore") or 0.0)
    quality = str((decision or {}).get("quality") or "").upper()
    metrics = _entry_quality_metrics(market, side, decision)
    stats = _recent_session_edge_stats()
    problems=[]
    # 1. Net Edge Governor — if losses are much bigger than wins, stop normal entries and force sniper-only.
    if auto.get("edgeGovernorEnabled", True) and stats.get("total",0) >= int(auto.get("edgeGovernorMinTrades", 6) or 6):
        ratio=float(stats.get("lossWinRatio") or 0.0)
        pf=float(stats.get("profitFactor") or 0.0)
        if ratio >= float(auto.get("defensiveLossWinRatio", 2.0) or 2.0) or (pf and pf < float(auto.get("defensiveProfitFactorFloor", 0.95) or 0.95)):
            min_def=float(auto.get("defensiveModeMinConfidence", 86.0) or 86.0)
            if confidence < min_def or quality not in {"SNIPER", "A+", "A_PLUS"}:
                problems.append(f"Net Edge Governor: avg loss {stats.get('avgLoss')} is too large vs avg win {stats.get('avgWin')} / PF {stats.get('profitFactor')}. Defensive mode requires SNIPER ≥{min_def:.0f}%.")
    # 2. Chop Governor. The long 20-bar window remains the default defence, but a
    # confirmed second leg can override legacy chop when the recent M5 leg is clean.
    # This fixes the live case where a 52.5% retest, 84% confidence and 0.76 MTF score
    # were blocked because the window still contained the preceding opposite trend.
    chop_override = {"allowed": False, "reason": ""}
    if auto.get("chopGovernorEnabled", True) and metrics.get("ok") and metrics.get("chop"):
        features = decision.get("features") if isinstance(decision.get("features"), dict) else {}
        is_retest = bool(features.get("retestContinuation"))
        is_anticipatory = bool(features.get("anticipatoryEntry"))
        mtf_score = _to_float(features.get("mtfScore") or (decision.get("mtfMatrix") or {}).get("score") or 0.0)
        recent_eff = _to_float(metrics.get("recentLegEfficiency"), 0.0)
        recent_flips = int(metrics.get("recentFlips", 99) or 99)
        directional_move = _to_float(metrics.get("directionalMoveAtr"), 0.0)
        retest_allowed = (
            bool(auto.get("chopRetestContinuationEnabled", True)) and is_retest
            and confidence >= float(auto.get("chopRetestMinConfidence", 76.0) or 76.0)
            and recent_eff >= float(auto.get("chopRetestMinLegEfficiency", 0.42) or 0.42)
            and recent_flips <= int(auto.get("chopRetestMaxRecentFlips", 3) or 3)
            and (bool(metrics.get("pullbackReclaim")) or directional_move >= float(auto.get("chopRetestMinMoveAtr", 0.70) or 0.70))
            and mtf_score >= float(auto.get("chopRetestMinMtfScore", 0.10) or 0.10)
        )
        anticipatory_allowed = (
            bool(auto.get("chopAnticipatoryBypassEnabled", True)) and is_anticipatory
            and not bool(metrics.get("late"))
            and recent_flips <= int(auto.get("chopRetestMaxRecentFlips", 3) or 3)
        )
        if retest_allowed:
            chop_override = {"allowed": True, "reason": "confirmed M5 retest continuation with a clean recent directional leg"}
        elif anticipatory_allowed:
            chop_override = {"allowed": True, "reason": "microstructure-qualified anticipatory entry before long-window chop catches up"}
        else:
            min_chop=float(auto.get("chopModeMinConfidence", 88.0) or 88.0)
            allow_scout=bool(auto.get("chopScoutOnly", True)) and quality == "SCOUT" and confidence >= min_chop
            if allow_scout:
                chop_override = {"allowed": True, "reason": "strict high-confidence scout allowance"}
            else:
                problems.append(f"Chop Governor: low trend efficiency {metrics.get('efficiency')} / {metrics.get('flips')} flips; recent leg {metrics.get('recentLegEfficiency')} / {metrics.get('recentFlips')} flips. Waiting for a cleaner transition.")
    # 3. Late Entry Blocker. A completed armed retest establishes a new continuation
    # origin. Do not keep measuring the second leg from the original impulse/EMA stretch.
    features = decision.get("features") if isinstance(decision.get("features"), dict) else {}
    retest_reset = bool(features.get("retestContinuation") and features.get("retestCompleted") and features.get("lateEntryOriginReset"))
    local_ext = 0.0
    if retest_reset and metrics.get("ok"):
        atr_now = max(_to_float(metrics.get("atr")), 1e-9)
        entry_now = _to_float((decision.get("tradePlan") or {}).get("entry") or features.get("retestEntryPrice"))
        trigger_ref = _to_float(features.get("retestTriggerHigh") if side == "BUY" else features.get("retestTriggerLow"), entry_now)
        local_ext = abs(entry_now - trigger_ref) / atr_now
    late_after_reset = bool(metrics.get("late")) and not (retest_reset and local_ext <= float(auto.get("retestLocalMaxExtensionAtr", 0.75) or 0.75))
    if auto.get("lateEntryBlockerEnabled", True) and metrics.get("ok") and late_after_reset:
        problems.append(f"Late Entry Blocker: {side} is {metrics.get('extensionAtr')} ATR from EMA20 and the validated retest origin is still {local_ext:.2f} ATR extended.")
    elif retest_reset:
        metrics["lateEntryOriginReset"] = True
        metrics["retestLocalExtensionAtr"] = round(local_ext, 2)
    ok = not problems
    return {"ok": ok, "blocked": not ok, "message": " | ".join(problems), "entryQuality": {"metrics": metrics, "stats": stats, "source": source, "confidence": confidence, "quality": quality, "chopOverride": chop_override}}


def _scaling_edge_guard(direction: str, market: dict[str, Any], decision: dict[str, Any] | None, mode: str = "scale") -> dict[str, Any]:
    auto = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    metrics = _entry_quality_metrics(market, direction, decision)
    confidence = _to_float((decision or {}).get("confidence") or (decision or {}).get("qualityScore") or 0.0)
    mtf_score = _to_float(((decision or {}).get("features") or {}).get("mtfScore") or ((decision or {}).get("mtfMatrix") or {}).get("score") or 0.0)
    if mode == "burst":
        # Burst is allowed only in extremely clean continuation. This prevents the 0.04/0.06 burst leg
        # from becoming the largest loser of the day in chop or late continuation.
        if metrics.get("ok") and metrics.get("chop"):
            return {"ok": False, "message": f"Burst Safety Lock: blocked in chop/low-efficiency tape ({metrics.get('efficiency')}).", "metrics": metrics}
        bcfg = (SETTINGS_STATE.get("tradingModes", {}).get("protectedBurst", {}) or {})
        burst_max_ext = float(bcfg.get("maxExtensionAtr", 0.85) or 0.85)
        if metrics.get("ok") and (metrics.get("late") or float(metrics.get("extensionAtr") or 0.0) > burst_max_ext) and not metrics.get("pullbackReclaim"):
            return {"ok": False, "message": f"Burst Safety Lock: blocked late add, extension {metrics.get('extensionAtr')} ATR > {burst_max_ext:.2f} without reclaim.", "metrics": metrics}
        min_conf = float(bcfg.get("minConfidence", 82.0) or 82.0)
        if confidence < min_conf:
            return {"ok": False, "message": f"Burst Safety Lock: confidence {confidence:.1f}% below strict floor {min_conf:.1f}%.", "metrics": metrics}
    else:
        min_conf = float(auto.get("scaleOnlyMinConfidence", 84.0) or 84.0)
        if confidence < min_conf:
            return {"ok": False, "message": f"Scaling blocked: confidence {confidence:.1f}% below extremely-clean floor {min_conf:.1f}%.", "metrics": metrics}
        if metrics.get("ok") and (metrics.get("chop") or metrics.get("late")):
            return {"ok": False, "message": "Scaling blocked: not an extremely clean trend continuation.", "metrics": metrics}
    return {"ok": True, "metrics": metrics, "confidence": confidence, "mtfScore": mtf_score}


def _loss_feedback_governor(decision: dict[str, Any], market: dict[str, Any], source: str = "auto") -> dict[str, Any]:
    """V12.54 Loss-Feedback Entry Governor.

    This stops the dangerous sequence the user identified:
        BUY loses -> bot buys again -> second BUY loses -> bot buys again.

    A same-direction re-entry after loss now requires *fresh proof*, not just another
    small green/red candle. It must show a better edge: higher confidence, price moving
    away from the failed exit, M5 EMA reclaim/structure break, and no repeated failed
    strategy. Pyramiding is unaffected because pyramiding is handled separately and only
    after an open trade has protected profit.
    """
    auto = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    if not auto.get("lossFeedbackGovernorEnabled", True):
        return {"ok": True, "enabled": False}
    side = str(decision.get("side") or decision.get("computedSide") or market.get("side") or "").upper()
    if side not in {"BUY", "SELL"}:
        return {"ok": True, "reason": "no_side"}
    now = time.time()
    window_s = float(auto.get("sameDirectionLossWindowMinutes", 90.0) or 90.0) * 60.0
    max_hold_s = float(auto.get("postLossGovernorMaxMinutes", 60.0) or 60.0) * 60.0
    losses = [x for x in list(AUTO_TRADE_STATE.get("lossMemory") or [])
              if str(x.get("side") or "").upper() == side
              and now - float(x.get("ts", 0) or 0) <= min(window_s, max_hold_s)]
    losses.sort(key=lambda x: float(x.get("ts", 0) or 0), reverse=True)
    if not losses:
        return {"ok": True, "sameDirectionLosses": 0}
    last = losses[0]
    conf = _to_float(decision.get("confidence") or decision.get("qualityScore") or 0.0)
    last_conf = _to_float(last.get("confidence") or 0.0)
    min_conf = float(auto.get("postLossReentryMinConfidence", 82.0) or 82.0)
    delta = float(auto.get("postLossReentryConfidenceDelta", 5.0) or 5.0)
    # V12.79: the demand used to be last_conf + delta UNCAPPED — after an 83% loser it wanted
    # >=88.3%, which the engine practically never prints, so BUYs were blocked for the full
    # 90-minute window while a clean rally ran away (July 9: eight blocks straight up the move).
    conf_cap = float(auto.get("postLossConfidenceCap", 85.0) or 85.0)
    atr = valid_live_atr(market)
    if atr is None:
        return {"ok": False, "blocked": True, "reason": "live_atr_unavailable", "message": "Post-loss re-entry blocked: valid live ATR unavailable."}
    cur = _to_float(market.get("price") or 0.0)
    last_price = _to_float(last.get("price") or last.get("entry") or cur)
    signed_move = (cur - last_price) if side == "BUY" else (last_price - cur)
    move_ok = signed_move >= atr * float(auto.get("postLossReentryMinMoveAtr", 0.65) or 0.65)
    conf_ok = conf >= min(conf_cap, max(min_conf, last_conf + delta if last_conf else min_conf))
    same_strategy = False
    try:
        new_strategy = (decision.get("selectedStrategy") or {}).get("name") or decision.get("strategy")
        same_strategy = bool(new_strategy and last.get("strategy") and str(new_strategy) == str(last.get("strategy")))
    except Exception:
        new_strategy = None
    # M5 proof: price must reclaim the fast/medium structure or break a recent minor structure level.
    ema_ok = False
    structure_ok = False
    try:
        symbol = str(market.get("symbol") or (SETTINGS_STATE.get("trading") or {}).get("symbol") or mt5_bridge.symbol or "XAUUSD")
        bars = mt5_bridge.copy_rates(symbol, "M5", max(40, int(auto.get("postLossReentryLookback", 8) or 8) + 25)) if mt5_bridge.status().get("connected") else []
        if bars and len(bars) >= 20:
            closes = [_to_float(b.get("close")) for b in bars]
            highs = [_to_float(b.get("high")) for b in bars]
            lows = [_to_float(b.get("low")) for b in bars]
            lookback = max(3, int(auto.get("postLossReentryLookback", 8) or 8))
            ema20 = _ema_last(closes, 20)
            ema50 = _ema_last(closes, 50) if len(closes) >= 50 else _ema_last(closes, min(34, len(closes)))
            close = closes[-1]
            if side == "BUY":
                ema_ok = close > ema20 and close > ema50 and ema20 >= ema50 * 0.999
                structure_ok = close > max(highs[-lookback-1:-1]) if len(highs) > lookback + 1 else False
            else:
                ema_ok = close < ema20 and close < ema50 and ema20 <= ema50 * 1.001
                structure_ok = close < min(lows[-lookback-1:-1]) if len(lows) > lookback + 1 else False
    except Exception:
        ema_ok = False
        structure_ok = False
    require_ema = bool(auto.get("postLossRequireEmaReclaim", True))
    same_strategy_block = bool(auto.get("postLossBlockSameStrategy", True)) and same_strategy
    # Never take same-direction SCOUTs after a same-side loss unless the user disables this.
    # V12.79 INTERLOCK FIX: V12.71's armed-retest continuations fire at SCOUT quality by
    # default — and this governor auto-failed every post-loss scout, so the tracker's own
    # completed setups (impulse + pullback + rejection close, the literal definition of a
    # fresh edge) could never pass after one same-side loss. A completed retest continuation
    # is exempt from the scout block; everything else about it is still checked.
    is_retest_continuation = bool((decision.get("features") or {}).get("retestContinuation"))
    hard_after = int(auto.get("maxSameDirectionLossesBeforeHardLock", 2) or 2)
    hard_locked = len(losses) >= hard_after
    # The retest exemption applies ONLY after a single same-side loss. Once hard-locked
    # (2+ same-side losses) every scout is blocked again, retest or not — otherwise the
    # exemption would silently satisfy the 'notScout' proof bit and unlock revenge trades.
    scout_block = (bool(auto.get("postLossNoScoutSameDirection", True))
                   and str(decision.get("quality", "")).upper() == "SCOUT"
                   and not (is_retest_continuation and not hard_locked))
    # Proof score intentionally requires multiple independent confirmations. One good candle is not enough.
    proof_bits = {
        "confidenceImproved": conf_ok,
        "movedAwayFromFailedExit": move_ok,
        "emaReclaimed": ema_ok or not require_ema,
        "structureBroken": structure_ok,
        "strategyChanged": not same_strategy_block,
        "notScout": not scout_block,
    }
    proof_score = sum(1 for v in proof_bits.values() if v)
    # V12.79: 5-of-6 after a single loss proved too strict in live trading — "structure break"
    # rarely prints mid-trend and the confidence bar did the real gating anyway. 4-of-6 after
    # one loss, 5-of-6 once hard-locked (2+ same-side losses) keeps the revenge-trade
    # protection while letting a genuinely recovered trend trade again.
    needed = 5 if hard_locked else int(auto.get("postLossProofNeeded", 4) or 4)
    fresh_impulse_override = False
    try:
        fresh_impulse_override = (
            bool(auto.get("postLossFreshImpulseOverride", True))
            and len(losses) == 1
            and not hard_locked
            and move_ok
            and signed_move >= atr * float(auto.get("postLossFreshImpulseMoveAtr", 1.20) or 1.20)
            and (ema_ok or not require_ema)
            and (not scout_block)
            and conf >= float(auto.get("postLossFreshImpulseMinConfidence", 72.0) or 72.0)
        ) or (
            # a COMPLETED armed-retest with real displacement is the strongest fresh-edge
            # signal the bot produces — let it through on its own merits after a single loss.
            is_retest_continuation and len(losses) == 1 and not hard_locked
            and move_ok and (ema_ok or not require_ema)
            and conf >= float(auto.get("postLossRetestMinConfidence", 74.0) or 74.0)
        )
    except Exception:
        fresh_impulse_override = False
    if proof_score < needed and not fresh_impulse_override:
        age_min = (now - float(last.get("ts", now))) / 60.0
        msg = (f"Loss-feedback governor: {side} blocked after {len(losses)} recent {side} loss(es). "
               f"The bot must prove a fresh edge before repeating the failed idea. "
               f"Proof {proof_score}/{needed}: confidence {conf:.1f} needs ≥{max(min_conf, last_conf + delta if last_conf else min_conf):.1f}; "
               f"move from failed exit {signed_move:.2f}/{atr * float(auto.get('postLossReentryMinMoveAtr', 0.65) or 0.65):.2f}; "
               f"EMA reclaim {'yes' if ema_ok else 'no'}; structure break {'yes' if structure_ok else 'no'}; "
               f"same strategy {'yes' if same_strategy else 'no'}; scout {'yes' if scout_block else 'no'}. "
               f"Last loss was {age_min:.0f} min ago.")
        # Throttle alerts so Telegram/UI is not spammed while the governor is correctly holding fire.
        if now - float(AUTO_TRADE_STATE.get("lastLossGovernorAlert", 0.0) or 0.0) > 900:   # V12.79: was 180s — spammed Telegram every scan cycle
            AUTO_TRADE_STATE["lastLossGovernorAlert"] = now
            try:
                _management_alert("Entry blocked after loss", msg[:900], "warning")
            except Exception as _suppressed_exc:
                _report_suppressed_exception("suppressed_exception_line_9224", _suppressed_exc)
        return {"ok": False, "blocked": True, "message": msg, "lossFeedback": {"sameDirectionLosses": len(losses), "lastLoss": last, "proof": proof_bits, "proofScore": proof_score, "needed": needed, "hardLocked": hard_locked}}
    return {"ok": True, "sameDirectionLosses": len(losses), "proof": proof_bits, "proofScore": proof_score, "needed": needed, "freshImpulseOverride": fresh_impulse_override}

def _volatility_normalized_base_lot(symbol: str, entry: float, sl: float, fallback_lot: float) -> dict[str, Any]:
    """Risk-based lot suggestion, now capped by the SAME safe entry-lot governor.
    If AI → firstEntryLotMode is base_lot_only (default), it returns base lot and only the
    win-streak ladder can scale in configured lotStep increments."""
    ai_cfg = SETTINGS_STATE.get("ai", {}) if isinstance(SETTINGS_STATE.get("ai"), dict) else {}
    # V13.53 — "base_lot_only" previously pinned EVERY first entry to base lot, so
    # conviction tiering (SCOUT 0.5x / STANDARD 1x / STRONG 2x) never affected real size.
    # "conviction" mode keeps the risk governor but lets the tier multiplier through.
    _mode = str(ai_cfg.get("firstEntryLotMode", "base_lot_only")).lower()
    if _mode in {"base_lot_only", "base", "fixed"}:
        # V13.54 — NOTE: this pins EVERY first entry to base lot, so conviction tiering
        # (SCOUT 0.5x / STANDARD 1.0x / STRONG 2.0x) never changes real size; it only ever
        # affected pyramid add-ons. That is why every 23-Jul fill was 0.01 regardless of
        # conviction. Set ai.firstEntryLotMode = "conviction" to let the tier multiplier
        # through while the risk governor (_safe_entry_lot) still caps the result.
        safe = _safe_entry_lot(symbol, fallback_lot, entry, sl, "base_lot_only")
        return {**safe, "source": "base_lot_only"}
    ceiling = _lot_risk_ceiling(symbol, entry, sl)
    desired = float(ceiling.get("rawLot") or fallback_lot)
    safe = _safe_entry_lot(symbol, desired, entry, sl, "risk_normalized")
    return {**safe, "source": "risk_normalized", "rawLot": ceiling.get("rawLot"), "riskCash": ceiling.get("riskCash"), "actualRisk": ceiling.get("actualRisk"), "riskPct": ceiling.get("riskPct"), "stopDist": ceiling.get("stopDist")}


def _v15_shadow_payload(market: dict[str, Any], decision: dict[str, Any], active_position: dict[str, Any] | None = None) -> dict[str, Any]:
    """Translate the established live engine snapshot into the V15 shadow contract.

    This path is advisory only: its output is persisted and displayed, but cannot bypass
    any V14 execution, certification, risk, TickGuard or broker gate.
    """
    features = decision.get("features") if isinstance(decision.get("features"), dict) else {}
    confidence = _to_float(decision.get("confidence") or decision.get("qualityScore") or 50) / 100.0
    def score(*names: str, default: float = 0.5) -> float:
        for name in names:
            if name in features and features.get(name) is not None:
                value = _to_float(features.get(name), default)
                return max(0.0, min(1.0, value / 100.0 if abs(value) > 1 else value))
        return default
    atr = max(0.0, _to_float(market.get("atr14") or market.get("atr")))
    atr_base = max(atr, _to_float(market.get("atrBaseline") or market.get("atr_baseline") or atr or 1.0))
    spread = max(0.0, _to_float(market.get("spread")))
    position = active_position or {}
    return {
        "market": {
            "returns": list(market.get("returns") or []),
            "atr": atr, "atr_baseline": atr_base,
            "adx": _to_float(market.get("adx") or features.get("adx") or 0),
            "range_position": score("rangePosition", "range_position"),
            "news_risk": 1.0 if market.get("newsBlackout") else score("newsRisk", default=0.0),
            "liquidity": score("liquidity", default=0.5),
            "session": market.get("session"), "symbol": market.get("symbol"),
        },
        "features": {
            "trend": score("trendScore", "trend", default=confidence),
            "momentum": score("momentumScore", "momentum", default=confidence),
            "structure": score("structureScore", "structure", default=confidence),
            "extension": score("extension", "extensionScore", default=0.5),
            "spread_quality": max(0.0, min(1.0, 1.0 - spread / 1.0)) if spread else 0.5,
            "recovery_evidence": score("recoveryScore", "recovery", default=0.5),
        },
        "broker": {"session": str(market.get("session") or "unknown").lower()},
        "position": {
            "current_r": _to_float(position.get("profitR") or position.get("floatingR")),
            "peak_r": _to_float(position.get("peakR") or position.get("profitR")),
            "age_seconds": _to_float(position.get("ageSeconds") or 0),
            "current_stop_r": _to_float(position.get("currentStopR") or -1),
            "hard_invalidation": bool(decision.get("hardInvalidation")),
            "atr_r": 0.35,
        },
        "burst": {
            "base_protected": bool(position.get("beMoved") or position.get("breakEvenProtected")),
            "base_profit_r": _to_float(position.get("profitR")),
            # V15.0.8 — burst may fire as the base trade APPROACHES its protection point
            # (not only after protection has armed), provided win evidence is strong.
            # `approaching_protection` is derived from the SAME AdaptiveExitEngine arm
            # point the live ratchet uses, so the burst gate and the exit ratchet can
            # never disagree about where "nearly protected" is.
            "approaching_protection": bool(_v15_approaching_protection(position)),
            "min_base_profit_r": 0.35,
            "bridge_ready": bool(_tick_guard_heartbeat_status().get("attested")),
            "exposure_r": 0.0, "max_exposure_r": 1.0,
            "cooldown_active": False,
            "extension": score("extension", "extensionScore", default=0.5),
            "max_extension": 0.8, "risk_reward": 1.5,
        },
    }



# ── V15.0.9 DIRECTIONAL CASCADE GUARD ───────────────────────────────────────
# Why this exists: on 28 Jul XAUUSD fell ~4081 -> ~4017 (a sustained 64-point
# cascade) and the bot took BUY entries INTO it. Nothing stopped it, because the
# only higher-timeframe protection was the HTF hard veto, which requires BOTH the
# D1 AND H4 trend LABELS to already read bearish. Trend labels are lagging
# aggregates: a one-session collapse can leave D1 still labelled bullish from the
# preceding days, so the veto's AND-condition never became true while the move was
# actually happening.
#
# A cascade is not a trend label, it is a VELOCITY event. This measures it directly
# from price displacement so it fires during the move rather than after the labels
# catch up. It is intentionally independent of the AI forecast: it must keep working
# when the model is uncalibrated, which it currently is.
#
# Note on what this is NOT: this does not predict reversals and makes no claim about
# where the move ends. It only asserts that stepping in front of a fast, one-way
# move is a low-quality entry — which is the specific failure observed.

# ── V15.2.0 CASCADE-ALIGNED ENTRY PROPOSER ──────────────────────────────────
# Requested: "when there's a dump, detect it and sell; when there's a pump, detect it
# and buy — on time, not late."
#
# The naive form of that is what destroys momentum systems, and this account already
# has an example of it: the 15:06 SELL at 4025.58 was entered near the session low and
# lost -3.38. A move only becomes measurable once it is extended, so "fire as soon as
# the cascade is detected" is structurally an instruction to enter at the worst price
# available. Chasing is not a tuning problem, it is what the signal definition implies.
#
# What is buildable is the retest form: let the cascade decide DIRECTION, and let the
# existing impulse-retest state machine decide TIMING. That engine already requires a
# pullback into the 23.6-61.8% retracement of the impulse, a rejection close, an anchor
# reclaim, and an RSI reset before it will report CONFIRMED. It refuses to arm at the
# extreme by construction.
#
# The gap this closes: _detect_impulse_retest() gates on `impulse_side == side`, i.e. it
# only ever VALIDATES a side the decision engine already chose. It cannot propose one. So
# in a clean cascade where the base engine returned WAIT, the retest machinery never ran
# for the with-cascade side at all — the setup was invisible rather than rejected.
#
# This proposer runs that same machinery for the cascade-aligned side and returns a
# proposal ONLY on CONFIRMED. It adds no new permission: the proposal is fed back through
# the identical gate chain (pre-live safety, risk sizing, HTF veto, advisory veto, session
# and spread filters). It can only make a setup visible, never approve one.

def _cascade_state(symbol: str | None = None, timeframe: str | None = None, lookback: int = 12) -> dict[str, Any]:
    """TTL-cached wrapper around the cascade detector.

    Called up to six times per scan (entry veto, entry proposer, open-trade management,
    burst gate, cooldown override, telemetry). Each uncached call issues a broker
    copy_rates round-trip plus a full ATR recomputation, so six identical fetches per tick
    was pure waste — and it put broker latency directly on the entry path, which is the one
    place latency actually costs money. Wrapping guarantees every return path is cached,
    rather than only the ones annotated by hand.

    timeframe defaults to the operator's configured trading timeframe rather than a
    hardcoded M5, so the detector and the latch agree with the chart actually being traded.
    """
    tf = str(timeframe or SETTINGS_STATE.get("trading", {}).get("timeframe") or "M5").upper()
    sym = str(symbol or SETTINGS_STATE.get("trading", {}).get("symbol") or "XAUUSD")
    key = f"{sym}|{tf}|{lookback}"
    hit = _CASCADE_CACHE.get(key)
    now = time.time()
    if hit and (now - hit[0]) < _CASCADE_CACHE_TTL:
        return deepcopy(hit[1])
    out = _cascade_state_uncached(sym, tf, lookback)
    if len(_CASCADE_CACHE) > 64:
        _CASCADE_CACHE.clear()
    _CASCADE_CACHE[key] = (now, deepcopy(out))
    return out


def _cascade_aligned_proposal(decision: dict[str, Any], market: dict[str, Any]) -> dict[str, Any] | None:
    """Propose a with-cascade entry when the impulse-retest machinery CONFIRMS it.

    Returns None unless a cascade is active AND the aligned side reports CONFIRMED.
    Never proposes against the cascade. Never proposes on the impulse itself.
    """
    cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    if not cfg.get("cascadeEntryEnabled", True):
        return None
    try:
        casc = _cascade_state(str(market.get("symbol") or "XAUUSD"))
        if not casc.get("active"):
            return None
        aligned_side = "SELL" if casc.get("direction") == "DOWN" else "BUY"
        # If the base engine already wants the aligned side, leave it alone — the normal
        # path handles it and its own retest gating already applies.
        if str(decision.get("side", "")).upper() == aligned_side and str(decision.get("action", "")).upper() == "TAKE_TRADE":
            return None

        symbol = str(market.get("symbol") or "XAUUSD")
        tf = str(SETTINGS_STATE.get("trading", {}).get("timeframe") or "M5")
        candles = mt5_bridge.copy_rates(symbol, tf, 120) or []
        if len(candles) < 20:
            return None

        feats = decision.get("features") if isinstance(decision.get("features"), dict) else {}
        ai_cfg = SETTINGS_STATE.get("ai", {}) if isinstance(SETTINGS_STATE.get("ai"), dict) else {}
        retest = _detect_impulse_retest(candles, aligned_side, feats, {
            "enabled": bool(ai_cfg.get("impulseRetestMode", True)),
            "minMoveAtr": float(ai_cfg.get("impulseRetestMinMoveAtr", 1.45) or 1.45),
            "buyArmRsi": float(ai_cfg.get("impulseRetestBuyArmRsi", 80.0) or 80.0),
            "sellArmRsi": float(ai_cfg.get("impulseRetestSellArmRsi", 20.0) or 20.0),
            "buyResumeRsiMax": float(ai_cfg.get("impulseRetestBuyResumeRsiMax", 78.0) or 78.0),
            "sellResumeRsiMin": float(ai_cfg.get("impulseRetestSellResumeRsiMin", 22.0) or 22.0),
        })
        if str(retest.get("state")) != "CONFIRMED":
            return None

        # ── EXPLICIT ANTI-CHASE GUARD ───────────────────────────────────────
        # CONFIRMED alone is not sufficient here. _detect_impulse_retest treats
        # `abs(price - ema20) <= atr * 0.65` as evidence of a pullback, but inside a
        # sustained one-way move EMA20 trails just behind price continuously, so that
        # clause stays true for the entire cascade — including at the extreme, with no
        # retracement whatsoever. Verified: a pure 30-bar down-impulse with no pullback
        # still reported CONFIRMED. Relying on it here would reproduce the exact 15:06
        # entry-at-the-low failure this feature exists to prevent.
        #
        # So measure the retracement directly from price, independent of any moving
        # average: price must have come back a minimum fraction of the impulse range
        # before an entry is proposed.
        _win = candles[-int(cfg.get("cascadeEntryLookback", 20) or 20):]
        _hi = max(float(c.get("high") or 0) for c in _win)
        _lo = min(float(c.get("low") or 0) for c in _win)
        _rng = max(_hi - _lo, 1e-9)
        _price = float(candles[-1].get("close") or 0)
        _retrace = ((_price - _lo) / _rng) if aligned_side == "SELL" else ((_hi - _price) / _rng)
        _min_retrace = float(cfg.get("cascadeEntryMinRetrace", 0.20) or 0.20)
        _max_retrace = float(cfg.get("cascadeEntryMaxRetrace", 0.75) or 0.75)
        if _retrace < _min_retrace:
            return None   # still at the extreme — this is chasing
        if _retrace > _max_retrace:
            return None   # retraced too far — the cascade is likely over, not resuming

        return {
            **decision,
            "action": "TAKE_TRADE",
            "side": aligned_side,
            "quality": str(cfg.get("cascadeEntryQuality", "SCOUT")).upper(),
            "source": "cascade_aligned_retest",
            "cascade": casc,
            "impulseRetest": retest,
            "retracement": round(_retrace, 3),
            "reasons": [
                f"Cascade-aligned retest entry: {casc.get('reason')}.",
                f"Impulse retest CONFIRMED for {aligned_side} — pullback into "
                f"{retest.get('entryZoneLow')}-{retest.get('entryZoneHigh')}, confirmation close printed, "
                f"RSI reset ({retest.get('rsi')}).",
                f"Retraced {_retrace:.0%} off the extreme (required {_min_retrace:.0%}-{_max_retrace:.0%}).",
                "Entered on the retest, not on the impulse: the cascade sets direction, the retest sets timing.",
            ],
        }
    except Exception as exc:
        _report_suppressed_exception("cascade_aligned_proposal", exc)
        return None


def _cascade_state_uncached(symbol: str | None = None, timeframe: str = "M5", lookback: int = 12) -> dict[str, Any]:
    """Detect an active directional cascade (dump or pump) from raw displacement.

    Returns {active, direction, displacementAtr, purity, atr, lookback, reason}.
    direction is "DOWN" for a dump, "UP" for a pump, "" when inactive.
    Fails OPEN (inactive) if candles are unavailable — this guard may block trades,
    so a data outage must not silently manufacture a block with no evidence.
    """
    cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    out: dict[str, Any] = {"active": False, "direction": "", "displacementAtr": 0.0,
                           "purity": 0.0, "atr": 0.0, "lookback": lookback, "reason": ""}
    if not cfg.get("cascadeGuardEnabled", True):
        out["reason"] = "cascade guard disabled in settings"
        return out
    sym = str(symbol or SETTINGS_STATE.get("trading", {}).get("symbol") or "XAUUSD")
    # V15.2.0 — TTL cache. This function is called up to six times per scan (entry veto,
    # entry proposer, open-trade management, burst gate, cooldown override, telemetry) and
    # each call previously issued its own copy_rates broker round-trip plus a full ATR
    # recomputation. Six identical fetches per tick is pure waste and adds broker latency
    # to the entry path, which is the one place latency actually costs money.
    try:
        candles = mt5_bridge.copy_rates(sym, timeframe, max(lookback + 20, 40)) or []
    except Exception as exc:
        _report_suppressed_exception("cascade_guard_candles", exc)
        out["reason"] = "candles unavailable"
        return out
    if len(candles) < lookback + 5:
        out["reason"] = f"insufficient candles ({len(candles)})"
        return out

    def _f(row: dict[str, Any], key: str) -> float:
        try:
            return float(row.get(key) or 0.0)
        except (TypeError, ValueError):
            return 0.0

    atr = 0.0
    try:
        atr = float(mt5_bridge._atr(candles, 14) or 0.0)
    except Exception:
        atr = 0.0
    if atr <= 0:
        rng = [abs(_f(c, "high") - _f(c, "low")) for c in candles[-20:]]
        atr = (sum(rng) / len(rng)) if rng else 0.0
    if atr <= 0:
        out["reason"] = "ATR unavailable"
        return out

    window = candles[-lookback:]
    first_open = _f(window[0], "open")
    last_close = _f(window[-1], "close")
    if first_open <= 0 or last_close <= 0:
        out["reason"] = "invalid candle prices"
        return out

    net = last_close - first_open
    disp_atr = abs(net) / atr
    direction = "UP" if net > 0 else "DOWN"
    agree = sum(1 for c in window
                if (_f(c, "close") - _f(c, "open") > 0) == (net > 0)
                and _f(c, "close") != _f(c, "open"))
    purity = agree / max(1, len(window))

    min_disp = float(cfg.get("cascadeMinDisplacementAtr", 2.5) or 2.5)
    min_purity = float(cfg.get("cascadeMinPurity", 0.55) or 0.55)
    out.update({"direction": direction, "displacementAtr": round(disp_atr, 3),
                "purity": round(purity, 3), "atr": round(atr, 5)})
    # ── CASCADE LATCH ───────────────────────────────────────────────────────
    # Without this the feature is unreachable, and I verified that: across 38 simulated
    # pullback depths the entry proposer fired ZERO times. The cascade is measured on a
    # rolling 12-bar window, so any retracement deep enough to clear the 20% anti-chase
    # guard also flattens that window and reports "no cascade". The two conditions were
    # mutually exclusive — the same mutually-unreachable-gates bug this project already
    # hit once with the burst engine (base_protected AND profit >= 0.6R).
    #
    # The modelling error was treating a cascade as a per-bar measurement. It is a
    # CONTEXT: a market that has just fallen 7 ATR is still a falling market during the
    # pause. So once detected it latches, and stays latched until it is actually
    # invalidated — retraced too far, or reversed — rather than merely because price
    # stopped moving for a few bars.
    _now = time.time()
    _latch_bars = int(cfg.get("cascadeLatchBars", 10) or 10)
    # V15.2.0 — was hardcoded to 300s (M5). trading.timeframe is operator-configurable, so
    # on M15 the latch expired 3x too early and on M1 it lingered 5x too long.
    _TF_SECONDS = {"M1": 60.0, "M5": 300.0, "M15": 900.0, "M30": 1800.0,
                   "H1": 3600.0, "H4": 14400.0, "D1": 86400.0}
    _tf_sec = _TF_SECONDS.get(str(timeframe).upper(), 300.0)
    with _CASCADE_LATCH_LOCK:
        _latch = deepcopy(_CASCADE_LATCH.get(sym))
    if disp_atr >= min_disp and purity >= min_purity:
        with _CASCADE_LATCH_LOCK:
            # Bounded: drop the oldest entries if a misconfiguration ever fans this out.
            if len(_CASCADE_LATCH) > 32:
                for _k in sorted(_CASCADE_LATCH, key=lambda k: float(_CASCADE_LATCH[k].get("at", 0)))[:16]:
                    _CASCADE_LATCH.pop(_k, None)
            _CASCADE_LATCH[sym] = {"direction": direction, "at": _now, "peakDisp": disp_atr,
                                   "extreme": (min(_f(c, "low") for c in window) if direction == "DOWN"
                                               else max(_f(c, "high") for c in window))}
    elif _latch and (_now - float(_latch.get("at", 0))) <= _latch_bars * _tf_sec:
        # Still inside the latch window. Invalidate only on a genuine reversal: price has
        # retraced past the configured ceiling of the latched impulse.
        _ext = float(_latch.get("extreme", 0) or 0)
        _ref = max(_f(c, "high") for c in window) if _latch.get("direction") == "DOWN" else min(_f(c, "low") for c in window)
        _span = abs(_ref - _ext)
        _back = abs(last_close - _ext)
        _frac = (_back / _span) if _span > 0 else 0.0
        if _frac <= float(cfg.get("cascadeEntryMaxRetrace", 0.75) or 0.75):
            out.update({"direction": str(_latch.get("direction")), "latched": True,
                        "latchAgeSec": round(_now - float(_latch.get("at", 0)), 1),
                        "peakDisplacementAtr": round(float(_latch.get("peakDisp", 0)), 2),
                        "retracedFraction": round(_frac, 3)})
            out["active"] = True
            out["reason"] = (f"latched {_latch.get('direction')} cascade "
                             f"(peak {float(_latch.get('peakDisp',0)):.2f} ATR, retraced {_frac:.0%}, "
                             f"age {out['latchAgeSec']:.0f}s)")
            return out
        with _CASCADE_LATCH_LOCK:
            _CASCADE_LATCH.pop(sym, None)

    if disp_atr >= min_disp and purity >= min_purity:
        out["active"] = True
        out["reason"] = (f"{direction} cascade: {disp_atr:.2f} ATR net displacement over "
                         f"{lookback} {timeframe} candles with {purity:.0%} directional agreement")
    else:
        out["reason"] = (f"no cascade ({disp_atr:.2f} ATR / {purity:.0%} vs thresholds "
                         f"{min_disp:.2f} ATR / {min_purity:.0%})")
    return out


def _v15_approaching_protection(position: dict[str, Any] | None) -> bool:
    """True when an open trade's peak excursion is within ~80% of its adaptive BE arm point.

    Uses the live AdaptiveExitEngine so the burst gate and the exit ratchet share one
    definition of "nearly protected" instead of each hard-coding its own threshold.
    """
    if not isinstance(position, dict):
        return False
    try:
        peak = _to_float(position.get("peakR")) or _to_float(position.get("mfeR")) or 0.0
        if peak <= 0:
            return False
        report = V15_ORCHESTRATOR.exit.decide({
            "current_r": _to_float(position.get("profitR")) or 0.0,
            "peak_r": peak,
            "age_seconds": _to_float(position.get("ageSeconds")) or 0.0,
            "atr_r": _to_float(position.get("atrR")) or 0.30,
            "current_stop_r": _to_float(position.get("stopR")) or -1.0,
            "continuation_probability": 0.5,
            "invalidation_probability": 0.5,
            "recovery_probability": 0.5,
        })
        arm = float((report.get("breathing") or {}).get("arm_point_r") or 0.60)
        return peak >= arm * 0.80
    except Exception as exc:
        _report_suppressed_exception("v15_approaching_protection", exc)
        return False


def _v15_shadow_evaluate(market: dict[str, Any], decision: dict[str, Any], active_position: dict[str, Any] | None = None, source: str = "live_loop") -> dict[str, Any] | None:
    try:
        report = V15_ORCHESTRATOR.evaluate(_v15_shadow_payload(market, decision, active_position), source=source)
        RUNTIME_HEALTH.beat("v15_shadow", detail=f"{report.get('decision_id')} {report.get('health', {}).get('score', 0):.0f}%")
        return report
    except Exception as exc:
        RUNTIME_HEALTH.fail("v15_shadow", exc, operation=source)
        LOGGER.exception("V15 shadow evaluation failed source=%s", source)
        return None


def _auto_trade_tick(reason: str = "manual_tick", precomputed_decision: dict[str, Any] | None = None,
                     precomputed_market: dict[str, Any] | None = None) -> dict[str, Any]:
    status_payload = mt5_bridge.status()
    execution = SETTINGS_STATE.get("execution", {}) if isinstance(SETTINGS_STATE.get("execution"), dict) else {}
    def blocked(message: str, extra: dict[str, Any] | None = None) -> dict[str, Any]:
        result = {"ok": False, "blocked": True, "reason": reason, "message": message, "strictness": decision_engine.strictness_dict(), **(extra or {})}
        trace = AUTO_TRADE_STATE.setdefault("decisionTrace", {})
        if not trace.get("firstBlocker") or trace.get("decisionReason") != reason:
            trace.update({"decisionReason": reason, "firstBlocker": message, "firstBlockedAt": time.time()})
        trace.update({"finalBlocker": message, "finalBlockedAt": time.time()})
        result["decisionTrace"] = dict(trace)
        result["heartbeat"] = _record_auto_heartbeat(result)
        return result
    if kill_switch.status().get("active"):
        return blocked("Emergency kill switch is active.", {"killSwitch": kill_switch.status()})
    if not status_payload.get("connected"):
        if not AUTO_TRADE_STATE.get("disconnectAlerted"):
            AUTO_TRADE_STATE["disconnectAlerted"] = True
            _push_notification("MT5 disconnected", "Auto-entry paused — MT5 connection lost. It resumes automatically once reconnected. Open trades are protected by their broker SL.", "warning")
        return blocked("MT5 is not connected.", {"mt5": status_payload})
    if AUTO_TRADE_STATE.get("disconnectAlerted"):
        AUTO_TRADE_STATE["disconnectAlerted"] = False
        _push_notification("MT5 reconnected", "Connection restored — auto-entry resumed.", "success")
    if not execution.get("liveTradingEnabled") or execution.get("dryRun", True):
        return blocked("Live Trading is OFF / Dry Run is ON.", {"execution": execution})
    if not execution.get("autoTradingEnabled"):
        return blocked("Auto Trading switch is OFF.", {"execution": execution})
    now = time.time()
    # Once a burst campaign closes, do not serially reopen one trade after another on the
    # same exhausted impulse. Existing open baskets may still be managed normally.
    burst_reentry_message = _protected_burst_reentry_lock_message(now) if _protected_burst_enabled() else None
    # V12.59: global entry cooldown must not stop the protected-burst monitor.
    # The base trade sets lastFire; if we honour that same cooldown for an already-open
    # protected basket, Burst can miss the exact momentum window after BE is secured.
    pre_open_positions = None
    burst_cooldown_bypass = False
    if _protected_burst_enabled():
        try:
            pre_open_positions = mt5_bridge.open_positions(bot_only=True) if mt5_bridge.status().get("connected") else []
            burst_cooldown_bypass = bool(pre_open_positions)
        except Exception:
            pre_open_positions = None
    if now - float(AUTO_TRADE_STATE.get("lastFire", 0.0)) < float(AUTO_TRADE_STATE.get("cooldownSeconds", 60)) and not burst_cooldown_bypass:
        return blocked("Auto trading cooldown active.", {"cooldownSeconds": AUTO_TRADE_STATE.get("cooldownSeconds", 60)})
    # Loss-streak circuit breaker — after N consecutive losses, stop and force re-analysis.
    if now < float(AUTO_TRADE_STATE.get("pausedUntil", 0.0)):
        mins = (float(AUTO_TRADE_STATE["pausedUntil"]) - now) / 60
        return blocked(f"Loss-streak circuit breaker active ({AUTO_TRADE_STATE.get('lossStreak')} losses in a row). Re-analysing — auto-entry resumes in {mins:.0f} min.", {"lossStreak": AUTO_TRADE_STATE.get("lossStreak")})
    # Post-loss reanalysis cooldown — never instantly re-enter right after a loss.
    #
    # V15.0.9 — HIGH-CONVICTION OVERRIDE (default OFF, and deliberately hard to satisfy).
    #
    # Requested behaviour: "if a high-probability opportunity appears, ignore the loss
    # cooldown and take it." That is reasonable in principle and dangerous in the obvious
    # implementation, so the conditions below are not arbitrary — each one blocks a
    # specific way the naive version fails:
    #
    #  1. CALIBRATED MODEL ONLY. The forecast is currently uncalibrated (is_calibrated
    #     False until >= 200 labelled outcomes). "95% confident" from hand-tuned
    #     coefficients is not evidence, and letting an unvalidated score switch off a
    #     safety brake is circular: the same scorer that just lost would be authorising
    #     its own retry.
    #
    #  2. MUST TRADE WITH THE CASCADE, NEVER AGAINST IT. This is the condition that
    #     matters most. On the 28 Jul dump the losing BUY entries were bounce setups in
    #     an oversold cascade — exactly the pattern that scores HIGH on continuation and
    #     recovery features. A confidence-only override would have fired on precisely the
    #     trades that lost, and would have made that session worse rather than better.
    #     Requiring cascade alignment means the override can only help you JOIN a strong
    #     move, never catch a falling knife faster.
    #
    #  3. NEVER OVERRIDES THE LOSS-STREAK BREAKER. Handled above and left untouched.
    #     One loss can be noise; N consecutive losses means the current read of the market
    #     is systematically wrong, and no per-trade score should be trusted to overrule
    #     that. Only the short post-loss pause is overridable here.
    if now < float(AUTO_TRADE_STATE.get("postLossUntil", 0.0)):
        secs = float(AUTO_TRADE_STATE["postLossUntil"]) - now
        _ov = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
        _override = False
        _ov_detail: dict[str, Any] = {}
        if _ov.get("cooldownHighConvictionOverride", False):
            _fc = ((_v15_shadow_evaluate(_live_market(), _decision(), None, source="cooldown_override") or {}).get("forecast") or {})
            _win = _to_float(_fc.get("win_probability"))
            _cal = bool(_fc.get("is_calibrated"))
            _bar = float(_ov.get("cooldownOverrideMinWinProbability", 0.75) or 0.75)
            _cs = _cascade_state()
            _sd = str((_decision() or {}).get("side", "")).upper()
            _aligned = bool(_cs.get("active")) and (
                (_sd == "SELL" and _cs.get("direction") == "DOWN") or
                (_sd == "BUY" and _cs.get("direction") == "UP"))
            _ov_detail = {"calibrated": _cal, "winProbability": _win, "requiredWinProbability": _bar,
                          "cascadeAligned": _aligned, "cascade": _cs, "side": _sd}
            _override = bool(_cal and _win is not None and _win >= _bar and _aligned)
            _ov_detail["granted"] = _override
        if not _override:
            _why = ""
            if _ov.get("cooldownHighConvictionOverride", False) and _ov_detail:
                _missing = []
                if not _ov_detail.get("calibrated"):
                    _missing.append("model is not yet calibrated (needs 200+ labelled outcomes)")
                if _ov_detail.get("winProbability") is None or _ov_detail.get("winProbability", 0) < _ov_detail.get("requiredWinProbability", 1):
                    _missing.append(f"win probability below the {_ov_detail.get('requiredWinProbability', 0):.0%} bar")
                if not _ov_detail.get("cascadeAligned"):
                    _missing.append("entry is not aligned with an active cascade")
                _why = " High-conviction override not granted: " + "; ".join(_missing) + "."
            return blocked(
                f"Post-loss reanalysis cooldown: waiting {secs/60:.1f} min after the last losing trade before considering a new entry.{_why}",
                {"postLossSeconds": round(secs), "cooldownOverride": _ov_detail or None})
        AUTO_TRADE_STATE["postLossUntil"] = 0.0
        AUTO_TRADE_STATE["lastCooldownOverride"] = {**_ov_detail, "at": now}
        LOGGER.info("Post-loss cooldown overridden by high-conviction aligned setup: %s", _ov_detail)
    # Capital circuit breakers — daily realized-loss limit + equity drawdown stop.
    cb = _capital_circuit_breaker(blocked)
    if cb is not None:
        return cb
    # V15.2.7: the priority lane passes the exact market snapshot that produced the
    # anticipatory candidate. Re-fetching market data here added another serialized MT5
    # round-trip and could let a fast move outrun its own decision before submission.
    market = deepcopy(precomputed_market) if isinstance(precomputed_market, dict) else _live_market()

    # Session filter: only trade during sessions selected in settings
    trading_cfg = SETTINGS_STATE.get("trading", {}) if isinstance(SETTINGS_STATE.get("trading"), dict) else {}
    allowed_sessions = trading_cfg.get("allowedSessions")
    current_session = market.get("session", "Unknown")
    if allowed_sessions and isinstance(allowed_sessions, list) and current_session not in allowed_sessions:
        return blocked(f"Session filter: '{current_session}' not in your allowed sessions {allowed_sessions}. Change in Settings → Trading Defaults.", {"session": current_session, "allowedSessions": allowed_sessions})

    # Read the actual open bot position (if any) to pass real profitR to pyramid + decision engine.
    open_positions = pre_open_positions if pre_open_positions is not None else (mt5_bridge.open_positions(bot_only=True) if mt5_bridge.status().get("connected") else [])
    active_position: dict[str, Any] | None = open_positions[0] if open_positions else None
    # Flat = the previous basket is fully closed → a brand-new basket starts clean, so clear the
    # "a pyramid add failed this session" lock (it only ever guards the currently-open basket).
    if not active_position and AUTO_TRADE_STATE.get("previousPyramidAddFailed"):
        AUTO_TRADE_STATE["previousPyramidAddFailed"] = False
    if not active_position and burst_reentry_message:
        return blocked(burst_reentry_message, {"protectedBurstReentryUntil": AUTO_TRADE_STATE.get("protectedBurstReentryUntil")})

    # Compute actual profitR from the live position so the pyramid engine
    # cannot be fooled by empty/default values.
    if active_position:
        entry_p = float(active_position.get("entryPrice", 0) or 0)
        cur_p   = float(active_position.get("currentPrice", market.get("price", entry_p)) or entry_p)
        sl_p    = float(active_position.get("sl", entry_p - 10) or entry_p - 10)
        risk    = abs(entry_p - sl_p) or 1.0
        direction = str(active_position.get("direction", "BUY")).upper()
        float_r = (cur_p - entry_p) / risk if direction == "BUY" else (entry_p - cur_p) / risk
        # Populate the fields the pyramid engine gates on — otherwise winStreak=0 and
        # beMoved default block every add. beMoved/locked come from the live protection
        # loop; winStreak from the bot's recent results.
        prot = POSITION_PROTECTION_STATE.get(str(active_position.get("ticket")), {})
        be_moved = bool(prot.get("beMoved"))
        base_lot = float((SETTINGS_STATE.get("pyramiding", {}) or {}).get("baseLot") or 0.01)
        # SL-distance-aware add risk (P5): the base trade's real entry→SL distance, and the add's own
        # structural stop estimate (~current ATR — a fresh add is stopped behind nearby structure).
        atr_now = float(market.get("atr14") or market.get("atr") or 0) or 0.0
        active_position = {**active_position, "profitR": round(float_r, 3), "floatingR": round(float_r, 3),
                           "beMoved": be_moved, "breakEvenProtected": be_moved,
                           "winStreak": int(AUTO_TRADE_STATE.get("winStreak", 0)),
                           "winsSinceLastLoss": int(AUTO_TRADE_STATE.get("winStreak", 0)),
                           "baseLot": base_lot, "currentLots": float(active_position.get("lots") or base_lot),
                           "lockedProfitR": round(max(0.0, float_r - 0.1), 2) if be_moved else 0.0,
                           "baseStopDistance": round(risk, 5),
                           "addStopDistance": round(atr_now, 5) if atr_now > 0 else round(risk, 5),
                           "previousPyramidAddFailed": bool(AUTO_TRADE_STATE.get("previousPyramidAddFailed")),
                           "allPriorAddsProtected": True, "structureValid": True}

    # V12.45 Fast Sniper Lane: use normal decision engine for safety, but allow a separate
    # M5/M15 low-latency trigger to override WAIT/LATE states when it detects a clean momentum shift.
    # This is deliberately NOT M1/noise trading: M15 provides context, M5 provides the trigger.
    normal_matrix = _action_matrix(position=active_position or {}, market=market)
    normal_decision = normal_matrix.get("decision", {}) or {}
    # Use the exact cached anticipatory decision from the 250 ms priority lane. This
    # removes a second predictor pass, prevents direction/threshold drift between detect
    # and submit, and preserves the source tick-age evidence in the execution record.
    fast_decision = deepcopy(precomputed_decision) if isinstance(precomputed_decision, dict) else _fast_sniper_decision(market)
    if fast_decision.get("action") == "TAKE_TRADE" and not active_position:
        matrix = _action_matrix(decision=fast_decision, position=active_position or {}, market=market)
        matrix["fastSniper"] = {k: fast_decision.get(k) for k in ("ok", "reason", "latencyMs", "features")}
        decision = matrix.get("decision", {}) or fast_decision
    else:
        matrix = normal_matrix
        if fast_decision.get("armedRetest"):
            matrix["fastSniper"] = fast_decision
        decision = normal_decision

    # V15.0.5: every real auto-trade scan now produces one shadow evaluation.
    # V15.0.8 — ADVISORY VETO WIRED IN (previously the report was computed and discarded).
    #
    # Before this change the entire v15 intelligence stack — probability engine, regime
    # engine, burst engine, exit engine — ran on every scan, produced a full forecast, was
    # attached to the telemetry matrix, and then had ZERO influence on whether the trade
    # was taken. That is the direct explanation for "how can a 92%-confidence trade fail":
    # the displayed number never touched the decision. Entries were decided entirely by the
    # older rule cascade below (HTF veto, repeat-setup guard, session/news gates).
    #
    # The model is NOT promoted to an authorizer here, and deliberately so: until
    # `is_calibrated` is true (>= 200 labelled outcomes) every probability it emits is a
    # hand-tuned sigmoid, and an uncalibrated model must never be allowed to CREATE
    # exposure. It is wired VETO-ONLY. It can block a setup its own numbers condemn; it
    # can never authorize one the deterministic rules rejected. Veto-only is monotonically
    # safe — the worst case is fewer trades, never more risk per trade.
    auto_cfg_casc = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    _co = AUTO_TRADE_STATE.get("lastCooldownOverride")
    if isinstance(_co, dict) and (now - float(_co.get("at", 0.0))) < 300:
        matrix["cooldownOverride"] = _co
    v15_shadow = _v15_shadow_evaluate(market, decision, active_position, source=reason)
    if v15_shadow:
        matrix["v15Shadow"] = {"decisionId": v15_shadow.get("decision_id"), "health": v15_shadow.get("health"), "forecast": v15_shadow.get("forecast"), "burst": v15_shadow.get("burst"), "exit": v15_shadow.get("exit")}

    _adv_cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    if v15_shadow and not active_position and _adv_cfg.get("v15AdvisoryVetoEnabled", True):
        _fc = v15_shadow.get("forecast") or {}
        _probs = _fc.get("probabilities") or {}
        _win = _to_float(_fc.get("win_probability", _probs.get("tp_before_sl")))
        _inval = _to_float(_probs.get("invalidation"))
        _fastfail = _to_float(_probs.get("fast_fail"))
        _min_win = float(_adv_cfg.get("v15MinWinProbability", 0.42) or 0.42)
        _max_inval = float(_adv_cfg.get("v15MaxInvalidation", 0.72) or 0.72)
        _max_fastfail = float(_adv_cfg.get("v15MaxFastFail", 0.78) or 0.78)
        _veto: list[str] = []
        if _win is not None and _win < _min_win:
            _veto.append(f"modelled win probability {_win:.0%} is below the {_min_win:.0%} floor")
        if _inval is not None and _inval > _max_inval:
            _veto.append(f"invalidation probability {_inval:.0%} exceeds the {_max_inval:.0%} ceiling")
        if _fastfail is not None and _fastfail > _max_fastfail:
            _veto.append(f"fast-fail probability {_fastfail:.0%} exceeds the {_max_fastfail:.0%} ceiling")
        if _veto:
            _features = decision.get("features") if isinstance(decision.get("features"), dict) else {}
            _anticipatory = bool(_features.get("anticipatoryEntry"))
            _calibrated = bool(_fc.get("is_calibrated"))
            _shadow_only = bool(
                _anticipatory and not _calibrated
                and _adv_cfg.get("anticipatoryUncalibratedV15VetoDisabled", True)
            )
            matrix["v15AdvisoryVeto"] = {
                "blocked": not _shadow_only, "shadowOnly": _shadow_only, "reasons": _veto,
                "winProbability": _win, "invalidation": _inval, "fastFail": _fastfail,
                "calibrated": _calibrated, "scoreType": _fc.get("score_type"),
            }
            if not _shadow_only:
                return blocked(
                    "V15 advisory veto: " + "; ".join(_veto) + ". "
                    + ("Model is empirically calibrated." if _calibrated
                       else "Model remains heuristic and this non-anticipatory setup is blocked conservatively."),
                    {"actionMatrix": matrix, "v15AdvisoryVeto": matrix["v15AdvisoryVeto"]})

    # ── V15.0.9 CASCADE COUNTER-ENTRY VETO ──────────────────────────────
    # Blocks entries that step in front of an active dump/pump. This sits ahead of
    # the HTF veto deliberately: the HTF veto reads lagging trend LABELS and requires
    # BOTH D1 and H4 to have already turned, which a single-session cascade can
    # outrun entirely. This reads displacement directly and therefore fires while
    # the move is still in progress.
    if not active_position and auto_cfg_casc.get("cascadeGuardEnabled", True):
        _casc = _cascade_state(str(market.get("symbol") or "XAUUSD"))
        matrix["cascade"] = _casc
        if _casc.get("active"):
            _side = str(decision.get("side", "")).upper()
            _against = (_side == "BUY" and _casc["direction"] == "DOWN") or \
                       (_side == "SELL" and _casc["direction"] == "UP")
            if _against:
                return blocked(
                    f"Cascade counter-entry veto: {_side} blocked during an active "
                    f"{_casc['direction']} cascade. {_casc['reason']}. Catching a fast one-way "
                    f"move is the lowest-quality entry available; wait for the cascade to stall "
                    f"or trade with it on a confirmed retest.",
                    {"cascade": _casc, "actionMatrix": matrix})

    # ── V15.2.0 CASCADE-ALIGNED ENTRY ───────────────────────────────────
    # Placed AFTER the counter-entry veto above, deliberately. The veto can still block
    # this proposal's opposite; the proposal can never resurrect something the veto killed.
    # Everything below (HTF veto, advisory veto, risk, pre-live safety) still applies
    # unchanged — a proposal is a candidate, not an approval.
    if not active_position and str(decision.get("action", "")).upper() != "TAKE_TRADE":
        _prop = _cascade_aligned_proposal(decision, market)
        if _prop:
            # Rebuild the action matrix from the proposed decision. Previously only the local
            # `decision` variable changed while matrix.takeThisTrade remained false from the
            # original WAIT decision, so cascade entries were logged as adopted but could never
            # execute. The proposal now crosses the normal deterministic approval matrix.
            matrix = _action_matrix(decision=_prop, position=active_position or {}, market=market)
            decision = matrix.get("decision", {}) or _prop
            matrix["cascadeEntry"] = {"adopted": True, "side": _prop.get("side"),
                                      "cascade": _prop.get("cascade"),
                                      "retestState": (_prop.get("impulseRetest") or {}).get("state"),
                                      "entryZone": [(_prop.get("impulseRetest") or {}).get("entryZoneLow"),
                                                    (_prop.get("impulseRetest") or {}).get("entryZoneHigh")]}
            LOGGER.info("Cascade-aligned retest entry adopted: %s", matrix["cascadeEntry"])

    # ── V12.72 HTF HARD VETO ────────────────────────────────────────────
    # Direct fix for the July-8 failure: the bot BOUGHT at 4061 while its own alert said
    # "D1 Bearish/H4 Weak Bearish → bias SELL". A short-window regime label ("Strong Bullish
    # Trend" from an M15 bounce) was allowed to overrule the actual higher-timeframe read.
    # Rule: when BOTH D1 and H4 trends oppose the entry side, the entry is blocked. The HTF
    # is the river; an M15 bounce is a ripple. Configurable via automation.htfHardVetoEnabled.
    auto_cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    if not active_position and auto_cfg.get("htfHardVetoEnabled", True):
        feats = decision.get("features", {}) if isinstance(decision.get("features"), dict) else {}
        veto_side = str(decision.get("side", "")).upper()
        d1 = str(feats.get("d1Trend", "")).lower()
        h4 = str(feats.get("h4Trend", "")).lower()
        opposing = "bearish" if veto_side == "BUY" else ("bullish" if veto_side == "SELL" else "")
        if opposing and opposing in d1 and opposing in h4:
            allow_scout = bool(auto_cfg.get("htfVetoAllowScout", False)) and str(decision.get("quality", "")).upper() == "SCOUT"
            if not allow_scout:
                return blocked(
                    f"HTF hard veto: {veto_side} blocked because D1 ({feats.get('d1Trend')}) AND H4 ({feats.get('h4Trend')}) "
                    f"are both {opposing}. The bot will not fight both higher timeframes on a lower-timeframe signal.",
                    {"htfVeto": {"side": veto_side, "d1": feats.get("d1Trend"), "h4": feats.get("h4Trend"),
                                 "htfBias": feats.get("htfDailyBias")}, "actionMatrix": matrix})

    # ── REPEAT-SETUP GUARD ──────────────────────────────────────────────
    # Don't immediately re-fire the SAME direction that just lost unless the market
    # has genuinely changed (price moved structurally OR the HTF bias now agrees).
    # This is the direct fix for the "5 SELLs in 72 seconds into a rally" failure:
    # after the first wrong read, the bot must wait for a DIFFERENT setup.
    auto_cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    if not active_position and auto_cfg.get("blockRepeatFailedSetup", True):
        last = AUTO_TRADE_STATE.get("lastLoser")
        sig_side = str(decision.get("side", market.get("side", ""))).upper()
        if last and sig_side and sig_side == last.get("side") and (now - float(last.get("ts", 0))) < float(auto_cfg.get("repeatBlockMinutes", 20)) * 60:
            cur_price = float(market.get("price") or 0)
            moved = abs(cur_price - float(last.get("price", 0)))
            atr = valid_live_atr(market)
            if atr is None:
                return blocked("Repeat-setup guard blocked: valid live ATR unavailable.", {"repeatGuard": True, "reason": "live_atr_unavailable"})
            htf_bias = str((decision.get("features", {}) or {}).get("htfDailyBias", "")).upper()
            # V13.27 REPEAT-GUARD FIX — two bugs caused ~50 spam blocks of high-quality setups:
            #  (1) threshold was 0.8*ATR (~6.4 points) — on an M5 scalper price rarely moves that
            #      far between setups, so EVERY same-side signal after one loss was blocked for the
            #      full window. Lowered to a scalp-appropriate fraction (default 0.35 ATR ~2.8pts).
            #  (2) it ignored signal quality — a fresh 92%-quality setup is NOT "re-entering the
            #      failed idea". High-quality setups now bypass the guard entirely.
            _rg_frac = float(auto_cfg.get("repeatGuardAtrFrac", 0.35) or 0.35)
            _rg_qual_bypass = float(auto_cfg.get("repeatGuardQualityBypass", 85.0) or 85.0)
            _sig_qual = float(decision.get("confidence", 0) or decision.get("qualityScore", 0) or 0)
            _high_quality = _sig_qual >= _rg_qual_bypass
            if (moved < atr * _rg_frac) and (htf_bias != sig_side) and not _high_quality:
                return blocked(f"Repeat-setup guard: a {sig_side} just lost and price has only moved {moved:.2f}pts (< {_rg_frac:.2f} ATR = {atr*_rg_frac:.1f}pts), quality {_sig_qual:.0f}% below {_rg_qual_bypass:.0f}% bypass, HTF bias {htf_bias or 'neutral'}. Waiting for a genuinely different setup.", {"repeatGuard": True})

    # ── LOSS-FEEDBACK ENTRY GOVERNOR ────────────────────────────────────
    # Stronger than the simple repeat guard: after a losing BUY/SELL the next same-direction
    # entry must prove a new edge. This prevents a sequence of repeated buys into a selloff or
    # repeated sells into a rally.
    if not active_position:
        lg = _loss_feedback_governor(decision, market, source=reason)
        if not lg.get("ok", True):
            return blocked(lg.get("message", "Loss-feedback governor blocked re-entry after recent loss."), {"lossFeedback": lg.get("lossFeedback", lg)})

    # ── V12.62 ENTRY QUALITY GOVERNOR ──────────────────────────────────
    # Stop late entries, reduce chop overtrading and switch to defensive filters when
    # today's average loss is too large versus average win. Runs from cached market/trade data only.
    if not active_position:
        eqg = _entry_quality_governor(decision, market, source=reason)
        if not eqg.get("ok", True):
            return blocked(eqg.get("message", "Entry Quality Governor blocked low-edge entry."), {"entryQuality": eqg.get("entryQuality", eqg)})

    # ── HEDGE / SCALP MODE ──────────────────────────────────────────────
    # On a RETAIL_HEDGING account, a fresh HIGH-QUALITY setup alongside an open trade
    # can be taken as an INDEPENDENT scalp (not a pyramid add) — with the same strict
    # BE/trail/fast-fail protection. Gated on account type so it can never net-off.
    scalp_mode = False
    if active_position and auto_cfg.get("scalpHedgeEnabled") and mt5_bridge.is_hedging():
        q = str(decision.get("quality", "")).upper()
        min_q = str(auto_cfg.get("scalpMinQuality", "STANDARD")).upper()
        allowed_q = {"SNIPER"} if min_q == "SNIPER" else {"STANDARD", "SNIPER"}
        if len(open_positions) < int(auto_cfg.get("scalpMaxConcurrent", 2)) and q in allowed_q:
            scalp_mode = True  # take it as a new independent position, skip the pyramid path

    # ── PROTECTED BURST MODE ─────────────────────────────────────────────
    # When Burst is enabled it replaces pyramiding for clean audit. It opens the base trade normally,
    # then only adds staged protected burst legs after the basket is already secured by AI Dynamic SL.
    if active_position and _protected_burst_enabled() and not scalp_mode:
        burst = _maybe_execute_protected_burst_add(open_positions, market, decision, matrix)
        if burst is not None:
            wrapped = {"ok": bool(burst.get("ok")), "reason": "protected_burst", "message": burst.get("message", "Protected Burst evaluated."), "protectedBurst": burst, "actionMatrix": matrix}
            wrapped["heartbeat"] = _record_auto_heartbeat(wrapped)
            return wrapped

    # ── PYRAMID SAFETY GATE ─────────────────────────────────────────────
    # If a bot position is already open (and we're NOT scalping), ANY new order is a
    # pyramid ADD. It only fires when the existing trade is PROVEN in profit AND the
    # pyramid engine approves — never stacking adds into a loser.
    is_pyramid_add = bool(active_position) and not scalp_mode
    if is_pyramid_add:
        # V12.62: winners scale only when the edge is extremely clean — no chop, no late add,
        # no mediocre confidence. This complements the pyramid engine's own profit/protection gates.
        open_dir_for_scale = str(active_position.get("direction", "")).upper()
        scale_guard = _scaling_edge_guard(open_dir_for_scale, market, decision, mode="pyramid")
        if not scale_guard.get("ok", True):
            return blocked(scale_guard.get("message", "Pyramid/scale blocked: edge not clean enough."), {"scaleGuard": scale_guard})
        profit_r = float(active_position.get("profitR", 0) or 0)
        pyr = matrix.get("pyramiding", {}) if isinstance(matrix.get("pyramiding"), dict) else {}
        pyr_settings = SETTINGS_STATE.get("pyramiding", {}) if isinstance(SETTINGS_STATE.get("pyramiding"), dict) else {}
        # Single source of truth (P3): the app pre-gate uses the SAME first-add profit-R floor the
        # pyramid engine enforces (minProfitRFirstAdd), so they can never disagree at the margin.
        min_profit_r = float(pyr_settings.get("minProfitRFirstAdd", pyramiding_engine.settings.min_profit_r_first_add) or 0.80)
        # Same-direction check: only add in the direction of the open trade
        open_dir = str(active_position.get("direction", "")).upper()
        sig_dir = str(decision.get("side", market.get("side", ""))).upper()
        if profit_r < min_profit_r:
            return blocked(f"Pyramid add BLOCKED: open trade only at {profit_r:.2f}R (needs ≥{min_profit_r:.2f}R proven profit). No adds on flat/losing positions.", {"actionMatrix": matrix, "profitR": profit_r})
        if open_dir and sig_dir and open_dir != sig_dir:
            return blocked(f"Pyramid add BLOCKED: signal {sig_dir} opposes open {open_dir} position. No counter-direction adds.", {"actionMatrix": matrix})
        if not matrix.get("pyramidOnlyIfProven"):
            reasons = (pyr.get("blocks") or matrix.get("blockedReasons") or ["Pyramid engine did not approve this add."])
            return blocked("Pyramid add BLOCKED: " + "; ".join(str(x) for x in reasons[:3]), {"actionMatrix": matrix})

    # V12.52: staged pyramiding runs off the protected basket state, not only fresh entry signals.
    # If every current leg has locked profit with AI Dynamic SL and probability remains high,
    # open exactly ONE incremental add, then wait until that add is protected before adding again.
    if active_position and not scalp_mode and not _protected_burst_enabled():
        staged_add = _maybe_execute_staged_pyramid_add(open_positions, market, decision)
        if staged_add is not None:
            wrapped = {"ok": bool(staged_add.get("ok")), "reason": "staged_pyramid", "message": staged_add.get("message", "Staged pyramid evaluated."), "pyramid": staged_add, "actionMatrix": matrix}
            wrapped["heartbeat"] = _record_auto_heartbeat(wrapped)
            return wrapped

    if not matrix.get("takeThisTrade"):
        reasons = matrix.get("blockedReasons") or decision.get("decisionBlocks") or ["AI action matrix did not approve a trade."]
        msg = "WAIT/BLOCKED: " + "; ".join(str(x) for x in reasons[:3])
        return blocked(msg, {"actionMatrix": matrix, "market": {"symbol": market.get("symbol"), "price": market.get("price"), "session": market.get("session")}})

    quality   = str(decision.get("quality", "STANDARD")).upper()
    base_lot  = float((SETTINGS_STATE.get("pyramiding", {}) or {}).get("baseLot") or 0.01)
    # Stamp the REAL selected strategy into the comment (not just the entry type) so
    # closed-trade history, analytics and learning attribute to the right strategy.
    strategy_name = (decision.get("selectedStrategy", {}) or {}).get("name")
    entry_type = "scalp" if scalp_mode else ("pyramid" if is_pyramid_add else ("scout" if quality == "SCOUT" else "auto"))
    _entry_comment = comment_for(strategy_name, entry_type, mt5_bridge.comment_prefix)
    plan = decision.get("tradePlan", {}) if isinstance(decision.get("tradePlan"), dict) else {}

    # V12.40 audit fix: MT5 market snapshots intentionally report side="WAIT" because the
    # directional side is computed by the decision engine. Do NOT build orders from
    # market.side; use the approved decision side. This also defines `symbol` for
    # volatility-normalized sizing below.
    symbol = str(decision.get("symbol") or market.get("symbol") or trading_cfg.get("symbol") or mt5_bridge.symbol or "XAUUSD")
    signal_side = str(decision.get("side") or decision.get("computedSide") or "").upper()
    if signal_side not in {"BUY", "SELL"}:
        return blocked(f"Approved decision has no executable BUY/SELL side ({signal_side or 'blank'}).", {"actionMatrix": matrix})

    _extra = {"symbol": symbol, "side": signal_side, "comment": _entry_comment, "manualTrigger": False}
    # First entries always carry the REAL structural SL. The broker TP for an
    # unsplittable single-position runner is resolved only after volume is known.
    # A fixed TP4 on a 0.01-lot position caps the entire trade before the dynamic
    # runner engine can manage an exceptional move.
    if not is_pyramid_add:
        if plan.get("sl"):
            _extra["sl"] = plan.get("sl")
    payload = _order_payload_from_market(_extra)
    if v15_shadow:
        payload["v15DecisionId"] = v15_shadow.get("decision_id")
        payload["v15Forecast"] = (v15_shadow.get("forecast") or {}).get("probabilities", {})
    signal_anchor = _signal_event_anchor(decision, market)
    if not signal_anchor:
        return blocked("Approved signal has no stable broker-bar identity; execution failed closed.", {"actionMatrix": matrix})
    payload["operation"] = "PYRAMID" if is_pyramid_add else "OPEN"
    payload["executionId"] = _stable_execution_identity(
        "auto",
        signal_anchor,
        symbol,
        signal_side,
        strategy_name or "",
        entry_type,
        str((active_position or {}).get("ticket") or ""),
    )
    # ── Volatility-normalized BASE lot: size so the trade risks ~riskPerTrade% of equity given
    # the REAL stop distance (constant dollar risk across calm vs volatile/wide-stop regimes).
    # The win-streak ladder then rides ON TOP of this risk-based base. Pyramid ADDs keep the
    # engine's own protected add-sizing.
    vbase = base_lot
    vol_info: dict[str, Any] | None = None
    entry_px = float(payload.get("price") or market.get("price") or 0)
    if auto_cfg.get("volNormalizedSizing", True) and not is_pyramid_add and _extra.get("sl"):
        vol_info = _volatility_normalized_base_lot(payload.get("symbol", symbol), entry_px, float(_extra["sl"]), base_lot)
        vbase = float(vol_info.get("lot") or base_lot)
    if is_pyramid_add:
        # Protected pyramid ADD sizing (adds to an OPEN position) — engine's next add lot.
        pyr = matrix.get("pyramiding", {}) if isinstance(matrix.get("pyramiding"), dict) else {}
        next_lot = float((pyr.get("nextAdd") or {}).get("lot") or pyr.get("nextLot") or base_lot)
        payload["volume"] = max(base_lot, next_lot)
    else:
        pyr_set = SETTINGS_STATE.get("pyramiding", {}) if isinstance(SETTINGS_STATE.get("pyramiding"), dict) else {}
        lot_step = float(pyr_set.get("lotStep") or 0.01)
        ws = int(AUTO_TRADE_STATE.get("winStreak", 0))
        if _protected_burst_enabled():
            # Burst mode needs a clean auditable basket ladder. The base trade is forced to
            # the configured Burst Start Lot, then burst adds become +increment each step.
            bcfg = _protected_burst_cfg()
            desired_lot = float(bcfg.get("startLot") or bcfg.get("perPositionLot") or base_lot or 0.01)
            payload["protectedBurstBase"] = True
        elif quality == "SCOUT":
            desired_lot = vbase
            payload["scoutEntry"] = True
        elif auto_cfg.get("winStreakLotScaling", True):
            # WIN-STREAK LOT LADDER: base/risk base + configured lotStep only, then HARD capped
            # by maxLot/maxTotalLots/account risk. No arbitrary jump to 1.42 lots.
            desired_lot = vbase + lot_step * ws
        else:
            desired_lot = vbase
        # V13.20 CONVICTION TIERING — scale desired_lot by setup quality BEFORE the safe-lot
        # governor (which still caps everything by account risk). Fixes "every trade cents": weak
        # SCOUT setups are skimmed, clean STRONG momentum earns size. Burst mode is exempt (it has
        # its own audited ladder and set desired_lot above).
        if auto_cfg.get("convictionTieringEnabled", True) and not _protected_burst_enabled():
            _q = str(quality or "STANDARD").upper()
            _tier_mult = {
                "SCOUT": float(auto_cfg.get("tierLotMultScout", 0.5) or 0.5),
                "STANDARD": float(auto_cfg.get("tierLotMultStandard", 1.0) or 1.0),
                "STRONG": float(auto_cfg.get("tierLotMultStrong", 2.0) or 2.0),
            }.get(_q, 1.0)
            _decision_features = decision.get("features") if isinstance(decision.get("features"), dict) else {}
            _probe_mult = float(_decision_features.get("probeLotMultiplier", 1.0) or 1.0)
            _probe_mult = max(0.10, min(1.0, _probe_mult))
            # Early-intent and early-impulse probes carry an explicit risk multiplier. Previous
            # builds only stored this value in metadata, so the real order size ignored it.
            # Apply the stricter of the generic SCOUT tier and the probe-specific multiplier.
            _effective_mult = min(_tier_mult, _probe_mult) if _decision_features.get("anticipatoryEntry") else _tier_mult
            desired_lot = max(lot_step, round(desired_lot * _effective_mult, 2))
            payload["convictionTier"] = _q
            payload["tierLotMult"] = _tier_mult
            payload["probeLotMultiplier"] = _probe_mult
            payload["effectiveLotMultiplier"] = _effective_mult
        _probe_risk_pct = None
        if _decision_features.get("anticipatoryEntry"):
            try:
                _probe_risk_pct = float(_decision_features.get("probeRiskPct") or 0.0) or None
            except (TypeError, ValueError):
                _probe_risk_pct = None
        safe_lot = _safe_entry_lot(
            symbol, desired_lot, entry_px,
            float(_extra.get("sl") or payload.get("sl") or entry_px),
            "protected_burst_base" if _protected_burst_enabled() else ("anticipatory_probe" if _decision_features.get("anticipatoryEntry") else ("auto_scout" if quality == "SCOUT" else "auto_entry")),
            risk_pct=_probe_risk_pct,
        )
        if safe_lot.get("untradeableAtBrokerMinimum"):
            return blocked("Entry blocked: broker minimum lot exceeds the configured account-risk budget for this stop.", {"sizingGuard": safe_lot, "actionMatrix": matrix})
        payload["volume"] = safe_lot["lot"]
        payload["maxRiskCash"] = float((safe_lot.get("riskCeiling") or {}).get("riskCash") or 0.0)
        vol_info = {**(vol_info or {}), "safeLot": safe_lot}
    vcheck = _execution_validation_check("auto_trade")
    if not vcheck.get("ok"):
        return blocked(vcheck.get("message", "Validation lock blocked live execution."), {"validation": vcheck.get("validation"), "actionMatrix": matrix})

    # ── V12.70 SPREAD-SPIKE GATE ────────────────────────────────────────
    # Never fire a scalp into a transient spread blowout even if it passes static maxSpread.
    if not is_pyramid_add:
        spike = _spread_spike_gate(market.get("spread"))
        if not spike.get("ok"):
            return blocked(spike.get("message", "Spread spike — entry delayed."), {"spreadGate": spike, "actionMatrix": matrix})

    # ── V12.68 AI ENTRY AUDITOR ─────────────────────────────────────────
    # One structured LLM second-opinion on the engine-approved entry (with chart image).
    # It can VETO, DOWNGRADE to scout size, or tighten the SL toward its invalidation
    # level — it can never create a trade. Fail-open: AI downtime never halts the bot
    # unless failClosed is set.
    audit = None
    if not is_pyramid_add:
        aud_cfg = SETTINGS_STATE.get("aiAuditor", {}) if isinstance(SETTINGS_STATE.get("aiAuditor"), dict) else {}
        _decision_source = str(decision.get("source") or payload.get("source") or "").lower()
        _strategy_upper = str(strategy_name or "").upper()
        _shock_flag = bool(decision.get("shockImpulse") or (decision.get("features") or {}).get("shockImpulse") or payload.get("shockImpulse"))
        _anticipatory_entry = bool((decision.get("features") or {}).get("anticipatoryEntry"))
        _critical_impulse = (
            _decision_source == "cascade_aligned_retest" or
            _shock_flag or _anticipatory_entry or
            ("FAST SNIPER" in _strategy_upper and str((decision.get("features") or {}).get("regime") or "").upper() == "SHOCK")
        )
        _bypass_audit = bool(aud_cfg.get("bypassCriticalImpulseEntries", True)) and _critical_impulse
        if _bypass_audit:
            payload["aiAuditBypassed"] = True
            payload["aiAuditBypassReason"] = "critical_impulse_latency_protection"
        else:
            audit_source = "telegram_approved" if reason == "telegram_approved" else "auto"
            audit = _maybe_ai_entry_audit(decision, market, payload, plan, source=audit_source)
        if audit:
            aud_cfg = SETTINGS_STATE.get("aiAuditor", {}) if isinstance(SETTINGS_STATE.get("aiAuditor"), dict) else {}
            if audit.get("verdict") == "VETO" and aud_cfg.get("vetoPower", True):
                return blocked("AI Entry Auditor VETO: " + str(audit.get("reason") or "contextual defect found."),
                               {"aiAudit": audit, "actionMatrix": matrix})
            if audit.get("verdict") == "DOWNGRADE":
                _blk_bar  = float(aud_cfg.get("downgradeBlockConfidenceBar", 85.0) or 85.0)
                _blk_strats = set(b.strip().upper() for b in str(aud_cfg.get("downgradeBlockStrategies","FSMMS,Fast Sniper M5")).split(","))
                _this_conf  = float(decision.get("confidence") or 0)
                _this_strat = str(strategy_name or "").upper()
                _should_block = (
                    aud_cfg.get("downgradeCanBlock", True) and
                    _this_conf >= _blk_bar and
                    any(b in _this_strat for b in _blk_strats)
                )
                if _should_block:
                    return blocked(
                        f"AI Auditor DOWNGRADE blocked ({_this_strat}, conf {_this_conf:.0f}%): "
                        f"{str(audit.get('reason') or '')[:200]}. "
                        "Per 28-Jul journal: 7/7 downgraded FSMMS entries lost (net -2.29); "
                        "blocking because no lot reduction fixes an entry where price moves immediately wrong.",
                        {"aiAudit": audit, "actionMatrix": matrix, "blockReason": "downgrade_high_conf_fsmms"})
                if aud_cfg.get("downgradeToScout", True) and quality != "SCOUT":
                    quality = "SCOUT"
                    payload["scoutEntry"] = True
                    base_lot_ds = float((SETTINGS_STATE.get("pyramiding", {}) or {}).get("baseLot") or 0.01)
                    payload["volume"] = min(float(payload.get("volume") or base_lot_ds), base_lot_ds)
                    payload["comment"] = comment_for(strategy_name, "scout", mt5_bridge.comment_prefix)
            inv = audit.get("invalidationPrice")
            if inv and aud_cfg.get("tightenSlToInvalidation", True) and payload.get("sl"):
                # audit_entry already bounds-checked: between entry and stop, >= 50% of stop distance.
                payload["sl"] = float(inv)
                payload["aiInvalidationPrice"] = float(inv)
            # The audit may change the stop geometry or downgrade the intended
            # size. Re-run the authoritative lot ceiling after those changes so
            # execution never carries a risk receipt calculated for an older plan.
            post_audit_sizing = _safe_entry_lot(
                symbol,
                float(payload.get("volume") or 0.01),
                entry_px,
                float(payload.get("sl") or entry_px),
                "post_ai_audit",
            )
            if post_audit_sizing.get("untradeableAtBrokerMinimum"):
                return blocked(
                    "Entry blocked after AI audit: broker minimum lot exceeds the recalculated cash-risk budget.",
                    {"aiAudit": audit, "sizingGuard": post_audit_sizing, "actionMatrix": matrix},
                )
            payload["volume"] = min(
                float(payload.get("volume") or post_audit_sizing["lot"]),
                float(post_audit_sizing["lot"]),
            )
            payload["maxRiskCash"] = float(
                (post_audit_sizing.get("riskCeiling") or {}).get("riskCash") or 0.0
            )
            payload["postAuditSizingGuard"] = post_audit_sizing

    semi_auto = (_execution_mode() == "semi_auto")
    if semi_auto and reason != "telegram_approved":
        approval = _telegram_queue_trade_approval(decision, payload, matrix, entry_type)
        if not approval.get("ok"):
            return blocked("Semi-auto mode: executable setup found, but Telegram approval was NOT queued: " + str(approval.get("message", "Telegram is not configured.")), {"telegramApproval": approval, "actionMatrix": matrix})
        return blocked("Semi-auto mode: executable setup sent to Telegram for TAKE / SCOUT / SKIP approval. No MT5 order sent yet.", {"telegramApproval": approval, "actionMatrix": matrix})
    # Crash-safe multi-target mode: when volume is large enough to split into separate broker
    # child orders, each child carries its own TP at TP1-TP4. If the Python app/PC crashes, the
    # broker still owns the target exits. For 0.01-lot accounts we keep the safer single runner
    # with TP4 + app-managed notes/trailing, because it cannot be split without over-allocation.
    tm_cfg = (SETTINGS_STATE.get("trading") or {}).get("tradeManagement") or {}
    use_split = False
    if bool(tm_cfg.get("splitTpOrders", True)) and not is_pyramid_add:
        try:
            specs = mt5_bridge.symbol_specs(payload.get("symbol", symbol))
            minlot = float(specs.get("volumeMin", 0.01) or 0.01)
            use_split = float(payload.get("volume") or 0) >= round(4 * minlot, 2) - 1e-9 and all(plan.get(k) for k in ("tp1", "tp2", "tp3", "tp4"))
        except Exception:
            use_split = False
    if use_split:
        mt_payload = {**payload, "tp1": plan.get("tp1"), "tp2": plan.get("tp2"), "tp3": plan.get("tp3"), "tp4": plan.get("tp4")}
        result = _execute_mt5_multi_serialized(mt_payload, "auto_multi_target")
    else:
        _single_tp_policy = resolve_single_position_broker_tp(
            side=str(payload.get("side") or signal_side),
            entry=float(payload.get("price") or plan.get("entry") or market.get("price") or 0.0),
            sl=float(payload.get("sl") or plan.get("sl") or 0.0),
            plan=plan,
            config=tm_cfg,
        )
        payload["tp"] = _single_tp_policy.tp
        payload["singlePositionTpPolicy"] = _single_tp_policy.as_dict()
        result = _execute_mt5_serialized(payload, "telegram_or_auto")
    _record_execution_memory(result, payload, "auto_trade_split" if use_split else "auto_trade")
    if result.get("ok"):
        AUTO_TRADE_STATE["lastFire"] = now
        _capture_entry_context(result, decision, payload, entry_type, strategy_name)
        result["event"] = _notify_trade_event("auto_trade", result, payload)
    elif is_pyramid_add and not result.get("dryRun"):
        # A real pyramid add was rejected/failed at the broker → lock further adds on THIS basket
        # (the engine's "previous pyramid add failed" gate). Cleared when the basket goes flat or a
        # new day starts. A protected winner must not keep retrying a failing add into the spread.
        AUTO_TRADE_STATE["previousPyramidAddFailed"] = True
        _management_alert("Pyramid add failed", "A protected pyramid add was rejected at the broker — further adds on this basket are locked until it closes. The base trade stays protected.", "danger")
    wrapped = {"ok": bool(result.get("ok")), "reason": reason, "message": result.get("message", "Auto trade evaluated."), "quality": quality, "scoutEntry": quality == "SCOUT", "actionMatrix": matrix, "execution": result, "event": result.get("event"), "sizing": vol_info, "aiAudit": audit}
    wrapped["heartbeat"] = _record_auto_heartbeat(wrapped)
    return wrapped


