@app.get("/api/fast-sniper/status")
def fast_sniper_status():
    """Read-only predictor diagnostics. Never run a new decision from an HTTP poll.

    V15.2.7 called ``_fast_sniper_decision`` here. The Settings page polled this route
    every two seconds, so a status request competed with the 250 ms priority lane for
    MT5 IPC and could exceed the frontend timeout. The UI then said "Backend
    unavailable" even though every other endpoint remained healthy.
    """
    endpoint_started = time.perf_counter()
    auto_cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    now = time.time()
    fast = deepcopy(FAST_SNIPER_STATE.get("last") or {})
    intent_state = deepcopy(FAST_SNIPER_STATE.get("earlyIntent") or {})
    impulse_state = deepcopy(FAST_SNIPER_STATE.get("earlyImpulse") or {})
    for state in (intent_state, impulse_state):
        updated = float(state.get("updatedAt", 0.0) or 0.0)
        if updated and now - updated > max(5.0, _effective_auto_loop_sleep() * 5.0) and state.get("runtimeStatus") not in {"DISABLED", "ERROR"}:
            state["runtimeStatus"] = "STALE"
            state["staleAgeSeconds"] = round(now - updated, 2)
    # Never touch the serialized MT5 IPC lane from a diagnostics request. A wedged
    # native call was making this HTTP endpoint alternate between LIVE and
    # "Backend unavailable" while the API itself remained healthy. The priority
    # scanner publishes a bounded connection heartbeat instead.
    last_mt5 = float(PRIORITY_INTENT_STATE.get("lastMt5ConnectedAt", 0.0) or 0.0)
    cached_mt5 = SETTINGS_STATE.get("mt5") if isinstance(SETTINGS_STATE.get("mt5"), dict) else {}
    mt5_connected = bool(last_mt5 and now - last_mt5 <= 8.0) or bool(cached_mt5.get("connected"))
    mt5_state = {
        "connected": mt5_connected,
        "symbol": PRIORITY_INTENT_STATE.get("lastMt5Symbol") or cached_mt5.get("symbol") or str((SETTINGS_STATE.get("trading") or {}).get("symbol") or "XAUUSD"),
        "source": "priority_heartbeat_cache",
        "heartbeatAgeSeconds": round(max(0.0, now - last_mt5), 3) if last_mt5 else None,
    }
    priority_health = _priority_intent_health()
    priority = deepcopy(PRIORITY_INTENT_STATE)
    priority["health"] = priority_health
    endpoint_status = "LIVE" if priority_health.get("ok") else str(priority_health.get("status") or "starting").upper()
    return {
        "ok": True,
        "endpointStatus": endpoint_status,
        "endpointLatencyMs": round((time.perf_counter() - endpoint_started) * 1000.0, 2),
        "enabled": bool(auto_cfg.get("fastSniperEnabled", True)),
        "mode": "M5 trigger + M15 setup + sub-second MT5 tick predictors + cached higher-timeframe bias",
        "noiseGuard": "Tick microstructure is used by Early Intent and Early Impulse; all order, spread, risk and broker gates remain authoritative.",
        "mtfMatrixEnabled": bool(auto_cfg.get("fastSniperMtfMatrixEnabled", True)),
        "loopSeconds": _effective_auto_loop_sleep(),
        "last": fast,
        "earlyIntent": intent_state,
        "earlyImpulse": impulse_state,
        "priorityIntent": priority,
        "buildId": BUILD_ID,
        "scanner": {
            "lastDecisionAt": FAST_SNIPER_STATE.get("lastAt"),
            "lastDecisionAgeSeconds": round(max(0.0, now - float(FAST_SNIPER_STATE.get("lastAt", 0.0) or 0.0)), 3),
            "bufferedSymbols": list(PREDICTOR_TICK_BUFFERS.keys()),
        },
        "mt5": {"connected": bool(mt5_state.get("connected")), "symbol": mt5_state.get("symbol") or str((SETTINGS_STATE.get("trading") or {}).get("symbol") or "XAUUSD"), "source": mt5_state.get("source"), "heartbeatAgeSeconds": mt5_state.get("heartbeatAgeSeconds")},
        "telegramPollSeconds": (SETTINGS_STATE.get("telegram", {}) or {}).get("callbackPollSeconds", 2.0),
    }


@app.get("/api/fast-sniper/stream")
async def fast_sniper_stream(request: Request):
    """Push cached predictor state without executing strategy or MT5 history work."""
    async def events():
        while not await request.is_disconnected():
            try:
                snapshot = fast_sniper_status()
                yield "event: predictor\n" + "data: " + json.dumps(snapshot, separators=(",", ":"), default=str) + "\n\n"
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                error = {"ok": False, "endpointStatus": "RECOVERING", "message": str(exc)[:250], "buildId": BUILD_ID}
                yield "event: predictor-error\n" + "data: " + json.dumps(error, separators=(",", ":")) + "\n\n"
            await asyncio.sleep(0.5)
    return StreamingResponse(
        events(), media_type="text/event-stream",
        headers={"Cache-Control": "no-cache, no-transform", "Connection": "keep-alive", "X-Accel-Buffering": "no"},
    )


