def _maybe_ai_entry_audit(decision: dict[str, Any], market: dict[str, Any], payload: dict[str, Any],
                          plan: dict[str, Any], source: str = "auto") -> dict[str, Any] | None:
    """V12.68 — run the AI Entry Auditor on an engine-approved entry, if enabled.

    Returns None when the auditor is disabled or not applicable (so callers can skip
    cleanly). Otherwise returns the audit verdict dict and journals it.
    """
    cfg = SETTINGS_STATE.get("aiAuditor", {}) if isinstance(SETTINGS_STATE.get("aiAuditor"), dict) else {}
    if not cfg.get("enabled"):
        return None
    if source == "manual" and not cfg.get("applyToManual", False):
        return None
    if source == "telegram_approved" and not cfg.get("applyToTelegramApproved", False):
        return None
    prov = SETTINGS_STATE.get("aiProvider", {}) if isinstance(SETTINGS_STATE.get("aiProvider"), dict) else {}
    chart_png = None
    if cfg.get("useChartImage", True):
        try:
            tps = [plan.get("tp1"), plan.get("tp2")]
            chart_png = _trade_chart_image(str(payload.get("side") or decision.get("side") or ""),
                                           payload.get("price") or plan.get("entry"),
                                           payload.get("sl") or plan.get("sl"), tps,
                                           subtitle="AI Entry Audit")
        except Exception:
            chart_png = None
    macro = {}
    news = {}
    try:
        macro = macro_feed.snapshot() if hasattr(macro_feed, "snapshot") else {}
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_9754", _suppressed_exc)
    try:
        news = calendar.blackout_status() if hasattr(calendar, "blackout_status") else {}
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_9758", _suppressed_exc)
    mem_stats = {}
    try:
        mem_stats = memory.stats(live_only=True)
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_9763", _suppressed_exc)
    audit = ai_entry_auditor.audit_entry(
        _llm_json_call, cfg, decision, market, payload, plan,
        memory_stats=mem_stats, macro=macro, news=news, chart_png=chart_png,
        provider=str(prov.get("provider", "claude")), api_key=str(prov.get("apiKey", "") or "").strip(),
        model=str(prov.get("model", "") or ""))
    try:
        _journal_record("ai_audit",
                        decision=audit.get("verdict"),
                        side=str(payload.get("side") or decision.get("side") or ""),
                        confidence=decision.get("confidence"),
                        strategy=(decision.get("selectedStrategy") or {}).get("name"),
                        reason=str(audit.get("reason") or "")[:240],
                        confidenceAdjust=audit.get("confidenceAdjust"),
                        invalidationPrice=audit.get("invalidationPrice"),
                        latencyMs=audit.get("latencyMs"), usedChartImage=audit.get("usedChartImage"),
                        skipped=bool(audit.get("skipped")), source=source)
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_9781", _suppressed_exc)
    return audit


def _news_entry_guard() -> dict[str, Any]:
    """Fail closed for new live risk when calendar protection has no evidence."""
    if not mt5_bridge.live_enabled:
        return {"ok": True, "dryRun": True}
    cfg = SETTINGS_STATE.get("automation", {}) if isinstance(SETTINGS_STATE.get("automation"), dict) else {}
    fail_closed = bool(cfg.get("newsFailClosed", True))
    try:
        status = calendar.blackout_status()
        status = status if isinstance(status, dict) else {}
    except Exception as exc:
        status = {"isBlackout": False, "liveConfigured": False, "error": str(exc)}
    if bool(status.get("isBlackout")):
        return {
            "ok": False,
            "blocked": True,
            "newsBlackout": True,
            "message": "New live entry blocked by the high-impact economic-news window.",
            "calendar": status,
        }
    configured = bool(status.get("liveConfigured") or getattr(calendar, "url", ""))
    cache_at = getattr(calendar, "_cache_at", None)
    cache = getattr(calendar, "_cache", None)
    failure_count = int(getattr(calendar, "_failure_count", 0) or 0)
    evidence_available = bool(
        configured
        and cache_at is not None
        and (failure_count == 0 or bool(cache))
    )
    if fail_closed and not evidence_available:
        return {
            "ok": False,
            "blocked": True,
            "newsProtectionUnavailable": True,
            "message": "New live entry blocked: economic-calendar protection is not ready or its refresh failed without a last-known-good cache.",
            "calendar": {
                **status,
                "configured": configured,
                "cacheReady": cache_at is not None,
                "failureCount": failure_count,
            },
        }
    return {
        "ok": True,
        "newsProtectionAvailable": evidence_available,
        "calendar": status,
    }


def _prelive_safety_gate(payload: dict[str, Any], source: str) -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    """Apply the independent V15.0.5 admission gate immediately before MT5 submission."""
    execution = SETTINGS_STATE.get("execution", {}) if isinstance(SETTINGS_STATE.get("execution"), dict) else {}
    cfg = execution.get("preLiveSafety", {}) if isinstance(execution.get("preLiveSafety"), dict) else {}
    trading = SETTINGS_STATE.get("trading", {}) if isinstance(SETTINGS_STATE.get("trading"), dict) else {}
    merged = {
        "mode": cfg.get("mode", execution.get("deploymentMode", "LIVE_RESTRICTED")),
        "symbol": trading.get("symbol", mt5_bridge.symbol),
        "maxTickAgeSeconds": cfg.get("maxTickAgeSeconds", 5.0),
        "maxSpreadPrice": cfg.get("maxSpreadPrice", execution.get("maxSpreadPrice", 0.8)),
        "maxDailyLoss": cfg.get("maxDailyLoss", 100.0),
        "maxConsecutiveLosses": cfg.get("maxConsecutiveLosses", 3),
        "maxOpenPositions": cfg.get("maxOpenPositions", 1),
        "maxRestrictedVolume": cfg.get("maxRestrictedVolume", 0.01),
        "maxEquityDrawdownPct": cfg.get("maxEquityDrawdownPct", 5.0),
        "allowComplexEntries": cfg.get("allowComplexEntries", False),
    }
    try:
        closed = mt5_bridge.closed_bot_trades(days=2) if mt5_bridge.status().get("connected") else []
        today = time.strftime("%Y-%m-%d", time.localtime())
        todays = [row for row in closed if str(row.get("closeTime") or row.get("time") or "").startswith(today)]
        daily_pnl = sum(float(row.get("profit") or row.get("pnl") or 0.0) for row in todays)
        consecutive_losses = 0
        for row in sorted(todays, key=lambda r: str(r.get("closeTime") or r.get("time") or ""), reverse=True):
            if float(row.get("profit") or row.get("pnl") or 0.0) < 0:
                consecutive_losses += 1
            else:
                break
    except Exception as exc:
        RUNTIME_HEALTH.fail("prelive_history", exc)
        daily_pnl = 0.0
        consecutive_losses = 0
    _readiness_now = _cached_readiness_snapshot()
    try:
        decision = PRELIVE_SUPERVISOR.assess(
            payload,
            source=source,
            config=merged,
            mt5_status=mt5_bridge.status(),
            # readiness is evaluated once and reused for both the gate and its explanation
            
            market=_live_market(),
            account=mt5_bridge.account_snapshot(),
            open_positions=mt5_bridge.open_positions(bot_only=False),
            unresolved_commands=len(EXECUTION_LEDGER.unresolved()),
            runtime_ready=bool(_readiness_now.get("tradingReady")),
            runtime_reasons=tuple(_readiness_now.get("reasons") or ()),
            daily_pnl=daily_pnl,
            consecutive_losses=consecutive_losses,
        )
    except Exception as exc:
        RUNTIME_HEALTH.fail("prelive_safety", exc)
        return None, {"ok": False, "blocked": True, "reason": "prelive_safety_error", "message": f"Pre-live safety supervisor failed closed: {exc}"}
    report = decision.to_dict()
    if not decision.ok:
        RUNTIME_HEALTH.fail("prelive_safety", report.get("message", "blocked"), mode=decision.mode)
        return None, report
    RUNTIME_HEALTH.beat("prelive_safety", "admission gates passed", mode=decision.mode, snapshotId=decision.snapshot_id)
    adjusted = dict(decision.payload)
    adjusted["preTradeSnapshotId"] = decision.snapshot_id
    return adjusted, None


def _execute_mt5_serialized(payload: dict[str, Any], source: str) -> dict[str, Any]:
    """Single durable execution gateway used by manual, auto, burst and pyramid paths."""
    news_guard = _news_entry_guard()
    if not news_guard.get("ok"):
        return news_guard
    identity_error = _missing_execution_identity(payload)
    if identity_error:
        return identity_error
    payload = dict(payload)
    payload.setdefault("operation", "OPEN")
    payload.setdefault("executionId", _execution_identity(payload))
    payload, safety_error = _prelive_safety_gate(payload, source)
    if safety_error:
        return safety_error
    payload = payload or {}
    accepted, key, prior = EXECUTION_LEDGER.begin(payload, source)
    if not accepted:
        cached = (prior or {}).get("result")
        return ({**cached, "deduplicated": True, "idempotencyKey": key}
                if isinstance(cached, dict) else {
            "ok": False, "blocked": True, "duplicate": True,
            "message": "Duplicate execution command suppressed.",
            "idempotencyKey": key, "prior": prior,
        })
    started = time.perf_counter()
    try:
        EXECUTION_LEDGER.mark_submitting(key)
        with EXECUTION_SERIAL_LOCK:
            result = mt5_bridge.execute(payload)
        result = result if isinstance(result, dict) else {"ok": False, "message": "Invalid MT5 execution response."}
        result.setdefault("idempotencyKey", key)
        result.setdefault("executionId", _execution_identity(payload))
        result.setdefault("executionSource", source)
        result.setdefault("executionLatencyMs", round((time.perf_counter() - started) * 1000, 2))
        EXECUTION_LEDGER.finish(key, result)
        if result.get("ok"):
            RUNTIME_HEALTH.beat("execution", "last command completed", source=source)
        else:
            RUNTIME_HEALTH.fail("execution", result.get("message", "execution rejected"), source=source)
        return result
    except Exception as exc:
        # Once a command reached SUBMITTING, an exception may mean MT5 accepted it but the
        # acknowledgement was lost. Never retry it until broker reconciliation proves state.
        EXECUTION_LEDGER.fail(key, exc, unknown=True)
        RUNTIME_HEALTH.fail("execution", exc, source=source)
        LOGGER.exception("Execution gateway failed source=%s key=%s", source, key)
        return {"ok": False, "unknown": True, "message": f"Execution outcome uncertain; reconciliation required: {exc}", "idempotencyKey": key, "executionId": _execution_identity(payload)}



def _execute_mt5_mutation_serialized(operation: str, payload: dict[str, Any], source: str) -> dict[str, Any]:
    """Serialize and journal every broker-changing operation, then verify broker state."""
    operation = str(operation or "").upper()
    allowed = {"CLOSE", "PARTIAL_CLOSE", "MODIFY", "MODIFY_SL", "MODIFY_TP", "PLACE_PENDING", "CANCEL_PENDING", "EMERGENCY_CLOSE"}
    if operation not in allowed:
        return {"ok": False, "blocked": True, "message": f"Unsupported broker mutation: {operation}"}
    if operation == "PLACE_PENDING":
        news_guard = _news_entry_guard()
        if not news_guard.get("ok"):
            return news_guard
    command = {**payload, "operation": operation}
    accepted, key, prior = EXECUTION_LEDGER.begin(command, source, lease_seconds=90)
    if not accepted:
        cached = (prior or {}).get("result")
        return cached if isinstance(cached, dict) else {"ok": False, "blocked": True, "duplicate": True, "message": "Duplicate or uncertain broker mutation suppressed pending reconciliation.", "idempotencyKey": key, "prior": prior}
    try:
        with EXECUTION_SERIAL_LOCK:
            pre_positions = mt5_bridge.open_positions(bot_only=False) if operation in {"CLOSE","PARTIAL_CLOSE","EMERGENCY_CLOSE","MODIFY","MODIFY_SL","MODIFY_TP"} else []
            pre_ticket = int(float(payload.get("ticket") or payload.get("position") or 0))
            pre_position = next((x for x in pre_positions if int(float(x.get("ticket") or x.get("position") or 0)) == pre_ticket), None)
            if operation in {"MODIFY", "MODIFY_SL", "MODIFY_TP"}:
                specs = mt5_bridge.symbol_specs(str((pre_position or {}).get("symbol") or payload.get("symbol") or "XAUUSD"))
                tolerance = max(
                    float(specs.get("tradeTickSize") or specs.get("tickSize") or specs.get("point") or 0.01),
                    1e-9,
                )
                if operation in {"MODIFY", "MODIFY_SL"} and payload.get("sl") is not None:
                    requested_sl = float(payload.get("sl") or 0.0)
                    if pre_position is None or requested_sl <= 0:
                        invariant_result = {
                            "ok": False,
                            "blocked": True,
                            "protectionInvariant": True,
                            "message": "Stop removal or modification without authoritative position state is prohibited.",
                            "operation": operation,
                            "request": command,
                            "idempotencyKey": key,
                            "confirmedPosition": pre_position,
                        }
                        EXECUTION_LEDGER.finish(key, invariant_result)
                        return invariant_result
                    current_sl = float((pre_position or {}).get("sl") or 0.0)
                    direction = str((pre_position or {}).get("direction") or (pre_position or {}).get("side") or "").upper()
                    weakens = current_sl > 0 and (
                        (direction == "BUY" and requested_sl < current_sl - tolerance)
                        or (direction == "SELL" and requested_sl > current_sl + tolerance)
                    )
                    if weakens:
                        authorization = payload.get("riskWideningAuthorization")
                        authorization = authorization if isinstance(authorization, dict) else {}
                        trusted_widening_sources = {"dynamic_sl_breathe", "management_trailing"}
                        authorized = bool(
                            source in trusted_widening_sources
                            and payload.get("allowRiskWidening") is True
                            and authorization.get("fresh") is True
                            and str(authorization.get("decisionId") or "").strip()
                            and float(authorization.get("maxRiskCash") or 0.0) > 0
                        )
                        final_risk_cash = 0.0
                        if authorized:
                            entry_price = float((pre_position or {}).get("entryPrice") or (pre_position or {}).get("priceOpen") or 0.0)
                            lots = float((pre_position or {}).get("lots") or (pre_position or {}).get("volume") or 0.0)
                            tick_size = float(specs.get("tradeTickSize") or specs.get("tickSize") or 0.0)
                            tick_value = float(specs.get("tradeTickValueLoss") or specs.get("tradeTickValue") or 0.0)
                            if entry_price <= 0 or lots <= 0 or tick_size <= 0 or tick_value <= 0:
                                authorized = False
                            else:
                                loss_distance = (
                                    max(0.0, entry_price - requested_sl)
                                    if direction == "BUY"
                                    else max(0.0, requested_sl - entry_price)
                                )
                                final_risk_cash = loss_distance / tick_size * tick_value * lots
                                authorized = final_risk_cash <= float(authorization["maxRiskCash"]) + 0.01
                        if not authorized:
                            invariant_result = {
                                "ok": False,
                                "blocked": True,
                                "protectionInvariant": True,
                                "message": "Stop widening requires fresh internal evidence and an independently verified cash-risk cap.",
                                "operation": operation,
                                "request": command,
                                "idempotencyKey": key,
                                "confirmedPosition": pre_position,
                                "calculatedRiskCash": round(final_risk_cash, 2),
                            }
                            EXECUTION_LEDGER.finish(key, invariant_result)
                            return invariant_result
                stale_fields: list[str] = []
                if payload.get("expectedCurrentSl") is not None:
                    actual_sl = float((pre_position or {}).get("sl") or 0.0)
                    if pre_position is None or abs(actual_sl - float(payload["expectedCurrentSl"])) > tolerance:
                        stale_fields.append(f"SL expected {float(payload['expectedCurrentSl']):.8f}, current {actual_sl:.8f}")
                if payload.get("expectedCurrentTp") is not None:
                    actual_tp = float((pre_position or {}).get("tp") or 0.0)
                    if pre_position is None or abs(actual_tp - float(payload["expectedCurrentTp"])) > tolerance:
                        stale_fields.append(f"TP expected {float(payload['expectedCurrentTp']):.8f}, current {actual_tp:.8f}")
                if stale_fields:
                    stale_result = {
                        "ok": False,
                        "blocked": True,
                        "staleDecision": True,
                        "message": "Stale position decision rejected before broker submission: " + "; ".join(stale_fields),
                        "operation": operation,
                        "request": command,
                        "idempotencyKey": key,
                        "confirmedPosition": pre_position,
                    }
                    EXECUTION_LEDGER.finish(key, stale_result)
                    return stale_result
            EXECUTION_LEDGER.mark_submitting(key, lease_seconds=90)
            if operation in {"CLOSE", "PARTIAL_CLOSE", "EMERGENCY_CLOSE"}:
                result = mt5_bridge.close_position(payload)
            elif operation in {"MODIFY", "MODIFY_SL", "MODIFY_TP"}:
                result = mt5_bridge.modify_position(payload)
            elif operation == "PLACE_PENDING":
                result = mt5_bridge.place_pending_stop(payload)
            elif operation == "CANCEL_PENDING":
                result = mt5_bridge.cancel_pending(payload.get("ticket") or payload.get("order"))
        result = result if isinstance(result, dict) else {"ok": False, "message": "Invalid MT5 mutation response."}
        result.setdefault("operation", operation)
        result.setdefault("request", command)
        result.setdefault("idempotencyKey", key)
        # Broker readback is mandatory for live mutations.
        if result.get("ok") and not result.get("dryRun"):
            ticket = int(float(payload.get("ticket") or payload.get("position") or 0))
            positions = mt5_bridge.open_positions(bot_only=False)
            current = next((x for x in positions if int(float(x.get("ticket") or x.get("position") or 0)) == ticket), None)
            if operation in {"PLACE_PENDING", "CANCEL_PENDING"}:
                canonical = EXECUTION_LEDGER.normalize_broker_result(result)
                order_ticket = int(float(canonical.get("order") or payload.get("ticket") or payload.get("order") or 0))
                active_order = mt5_bridge.active_order(order_ticket) if order_ticket else None
                history_order = mt5_bridge.history_order(order_ticket) if order_ticket else None
                if operation == "PLACE_PENDING":
                    result["readbackConfirmed"] = bool(active_order and str(active_order.get("symbol") or "") == str(payload.get("symbol") or active_order.get("symbol") or ""))
                    result["confirmedOrder"] = active_order
                else:
                    result["readbackConfirmed"] = bool(order_ticket and active_order is None and history_order is not None)
                    result["confirmedOrderHistory"] = history_order
                if not result["readbackConfirmed"]:
                    result["ok"] = False; result["unknown"] = True
                    result["message"] = "Pending-order broker readback did not confirm the requested final state; reconciliation required."
            elif operation in {"CLOSE", "PARTIAL_CLOSE", "EMERGENCY_CLOSE"}:
                requested = float(payload.get("volume") or 0.0)
                before = float((pre_position or {}).get("lots") or (pre_position or {}).get("volume") or 0.0)
                after = float((current or {}).get("lots") or (current or {}).get("volume") or 0.0)
                specs = mt5_bridge.symbol_specs(str((pre_position or current or {}).get("symbol") or payload.get("symbol") or "XAUUSD"))
                step = float(specs.get("volumeStep") or specs.get("lotStep") or 0.01)
                if operation in {"CLOSE", "EMERGENCY_CLOSE"} and current is None and before > 0:
                    result["readbackConfirmed"] = True
                elif operation == "PARTIAL_CLOSE" and pre_position is not None and current is not None and requested > 0 and after < before and abs((before-after)-requested) <= max(step,1e-9):
                    result["readbackConfirmed"] = True
                    result["preVolume"] = before; result["postVolume"] = after; result["confirmedClosedVolume"] = before-after
                else:
                    result["ok"] = False
                    result["unknown"] = True
                    result["message"] = "Broker accepted close request but position readback is inconclusive. Reconciliation required."
            else:
                if current is None:
                    result["ok"] = False; result["unknown"] = True
                    result["message"] = "Position missing after modification; reconciliation required."
                else:
                    specs = mt5_bridge.symbol_specs(str(current.get("symbol") or payload.get("symbol") or "XAUUSD"))
                    tick_size = float(specs.get("tickSize") or specs.get("tradeTickSize") or specs.get("point") or 0.01)
                    submitted = result.get("mt5Request") if isinstance(result.get("mt5Request"), dict) else {}
                    # Preflight may move a stop one tick beyond a live broker
                    # stop/freeze boundary. Verify the exact submitted final state,
                    # not the stale pre-adjustment payload.
                    requested_sl = submitted.get("sl") if "sl" in submitted else payload.get("sl")
                    requested_tp = submitted.get("tp") if "tp" in submitted else payload.get("tp")
                    sl_ok = requested_sl is None or abs(float(current.get("sl") or 0.0)-float(requested_sl)) <= max(tick_size, 1e-9)
                    tp_ok = requested_tp is None or abs(float(current.get("tp") or 0.0)-float(requested_tp)) <= max(tick_size, 1e-9)
                    result["readbackConfirmed"] = bool(sl_ok and tp_ok)
                    result["confirmedPosition"] = current
                    if not result["readbackConfirmed"]:
                        result["ok"] = False; result["unknown"] = True
                        result["message"] = "Broker modification response did not match position readback. Reconciliation required."
        if result.get("unknown"):
            EXECUTION_LEDGER.fail(
                key,
                result.get("message", "Uncertain mutation outcome"),
                unknown=True,
                result=result,
            )
        else:
            EXECUTION_LEDGER.finish(key, result)
        return result
    except Exception as exc:
        EXECUTION_LEDGER.fail(key, exc, unknown=True)
        RUNTIME_HEALTH.fail("execution", exc, source=source, operation=operation)
        LOGGER.exception("Mutation gateway failed operation=%s source=%s key=%s", operation, source, key)
        return {"ok": False, "unknown": True, "message": f"Broker mutation outcome uncertain: {exc}", "idempotencyKey": key}


def _execute_mt5_multi_serialized(payload: dict[str, Any], source: str) -> dict[str, Any]:
    identity_error = _missing_execution_identity(payload)
    if identity_error:
        return identity_error
    parent_identity = _execution_identity(payload)
    parent_payload={**payload,"operation":"MULTI_TARGET_OPEN"}
    accepted,key,prior=EXECUTION_LEDGER.begin(parent_payload,source,lease_seconds=180)
    if not accepted:
        cached=(prior or {}).get("result")
        return cached if isinstance(cached,dict) else {"ok":False,"blocked":True,"duplicate":True,"message":"Duplicate or uncertain multi-target command suppressed.","idempotencyKey":key,"prior":prior}
    try:
        EXECUTION_LEDGER.mark_submitting(key,lease_seconds=180)
        plan=mt5_bridge.split_target_plan(payload)
        if not plan.get("ok"):
            result={"ok":False,"blocked":True,"message":plan.get("message") or "Split target plan invalid.","plan":plan,"request":parent_payload}
            EXECUTION_LEDGER.finish(key,result); return result
        children=[]
        for index,leg in enumerate(plan.get("legs") or []):
            child={**leg,"operation":"OPEN","executionId":f"{parent_identity}:leg:{index+1}","parentExecutionId":parent_identity,"legIndex":index+1}
            child_result=_execute_mt5_serialized(child,f"{source}:leg:{index+1}")
            children.append({"legIndex":index+1,"request":child,"result":child_result})
            if child_result.get("unknown") or child_result.get("blocked"):
                break
        oks=[c for c in children if c["result"].get("ok")]
        complete=len(children)==len(plan.get("legs") or []) and len(oks)==len(children)
        partial=bool(oks) and not complete
        result={"ok":complete,"partial":partial,"plan":plan,"children":children,"results":[c["result"] for c in children],
                "message":"All multi-target legs confirmed." if complete else (f"Partial multi-target execution: {len(oks)}/{len(plan.get('legs') or [])} legs confirmed; reconciliation required." if partial else "Multi-target execution blocked or rejected."),
                "request":parent_payload,"idempotencyKey":key}
        if partial or any(c["result"].get("unknown") for c in children): EXECUTION_LEDGER.fail(key,result["message"],unknown=True)
        else: EXECUTION_LEDGER.finish(key,result)
        return result
    except Exception as exc:
        EXECUTION_LEDGER.fail(key,exc,unknown=True); RUNTIME_HEALTH.fail("execution",exc,source=source)
        LOGGER.exception("Multi-target gateway failed source=%s key=%s",source,key)
        return {"ok":False,"unknown":True,"message":f"Multi-target outcome uncertain and requires reconciliation: {exc}","idempotencyKey":key}


def _reconcile_execution_row(row: dict[str, Any]) -> dict[str, Any]:
    key=str(row.get("idempotency_key") or "")
    try: req=json.loads(row.get("request_json") or "{}")
    except Exception: req={}
    try: prior_result=json.loads(row.get("result_json") or "{}")
    except Exception: prior_result={}
    op=str(req.get("operation") or "").upper(); ticket=int(float(req.get("ticket") or req.get("position") or 0))
    positions=mt5_bridge.open_positions(bot_only=False)
    current=next((x for x in positions if int(float(x.get("ticket") or x.get("position") or 0))==ticket),None) if ticket else None
    evidence={"position":current,"operation":op}; status=None
    if op in {"CLOSE","EMERGENCY_CLOSE"} and ticket and current is None: status="RECONCILED"
    elif op in {"MODIFY","MODIFY_SL","MODIFY_TP"} and current is not None:
        submitted = prior_result.get("mt5Request") if isinstance(prior_result.get("mt5Request"), dict) else {}
        requested_sl=submitted.get("sl") if "sl" in submitted else req.get("sl")
        requested_tp=submitted.get("tp") if "tp" in submitted else req.get("tp")
        evidence["submittedRequest"] = submitted or None
        specs=mt5_bridge.symbol_specs(str(current.get("symbol") or req.get("symbol") or "XAUUSD")); tol=float(specs.get("tickSize") or specs.get("point") or .01)
        if (requested_sl is None or abs(float(current.get("sl") or 0)-float(requested_sl))<=tol) and (requested_tp is None or abs(float(current.get("tp") or 0)-float(requested_tp))<=tol): status="RECONCILED"
    elif op=="CANCEL_PENDING":
        active=mt5_bridge.active_order(ticket); hist=mt5_bridge.history_order(ticket); evidence.update({"activeOrder":active,"historyOrder":hist})
        if active is None and hist is not None: status="RECONCILED"
    elif op=="PLACE_PENDING":
        canonical=EXECUTION_LEDGER.normalize_broker_result(prior_result)
        ot=int(float(canonical.get("order") or ticket or 0)); active=mt5_bridge.active_order(ot); evidence["activeOrder"]=active
        if active is not None: status="RECONCILED"
    elif op in {"OPEN","BURST","PYRAMID"}:
        canonical=EXECUTION_LEDGER.normalize_broker_result(prior_result)
        pt=int(float(canonical.get("position") or 0)); match=next((x for x in positions if int(float(x.get("ticket") or x.get("position") or 0))==pt),None) if pt else None
        evidence["positionMatch"]=match
        if match is not None: status="RECONCILED"
    if status: EXECUTION_LEDGER.reconcile(key,status,evidence,None)
    return {"ok":bool(status),"idempotencyKey":key,"status":status or str(row.get("status") or "UNKNOWN"),"evidence":evidence}

async def _automatic_reconciliation_loop() -> None:
    while True:
        try:
            if mt5_bridge.status().get("connected"):
                rows=EXECUTION_LEDGER.unresolved(); resolved=0
                for row in rows[:100]:
                    if _reconcile_execution_row(row).get("ok"): resolved+=1
                RUNTIME_HEALTH.beat("reconciliation","broker reconciliation cycle complete",unresolved=len(rows)-resolved,resolved=resolved)
            else:
                # V15.0.8 — was RUNTIME_HEALTH.fail(). Being unable to reconcile while the
                # broker link is down is an expected idle state, not a component fault, and
                # marking it as a critical failure produced a confusing double-blocker: the
                # operator saw "runtime readiness is not healthy" (reconciliation) stacked on
                # top of the real and self-explanatory "MT5 is disconnected". Trading is still
                # blocked by the MT5 blocker itself, so nothing is loosened here — only the
                # diagnosis is made truthful.
                RUNTIME_HEALTH.beat("reconciliation", "idle — MT5 disconnected; nothing to reconcile", unresolved=len(EXECUTION_LEDGER.unresolved()), idle=True)
        except asyncio.CancelledError: raise
        except Exception as exc:
            RUNTIME_HEALTH.fail("reconciliation",exc); LOGGER.exception("Automatic reconciliation cycle failed")
        await asyncio.sleep(5)


