    row=EXECUTION_LEDGER.get(key)
    if not row: return {"ok":False,"message":"Execution command not found."}
    result=_reconcile_execution_row(row)
    if not result.get("ok"): result["message"]="Broker evidence is still inconclusive; execution remains locked."
    return result


