@app.post("/api/settings")
def update_settings(payload: dict[str, Any] = Body(...)):
    if not isinstance(payload, dict):
        return JSONResponse({"ok": False, "message": "Invalid settings payload."}, status_code=422)
    wrapped = isinstance(payload.get("settings"), dict)
    settings_payload = payload.get("settings") if wrapped else payload
    expected = payload.get("expectedRevision") if wrapped else payload.get("settingsRevision")
    if not isinstance(settings_payload, dict):
        return JSONResponse({"ok": False, "message": "Invalid settings payload: settings must be an object."}, status_code=422)
    clean_payload = _drop_blank_secrets(_strip_runtime_settings_keys(deepcopy(settings_payload)))
    clean_payload.pop("meta", None)
    try:
        # Settings is a single-user local control surface and the frontend serialises its
        # writes. Requiring the page-load revision here caused every save to fail whenever
        # another legitimate maintenance action advanced the revision. The transaction
        # lock and read-back verification still protect disk/runtime consistency.
        result = _update_settings_locked(clean_payload, None)
        result["submittedRevision"] = int(expected) if expected is not None else None
        result["staleRevisionIgnored"] = expected is not None and int(expected) != int(result.get("revision", 0)) - 1
        return result
    except SettingsConflictError as exc:
        return JSONResponse({"ok": False, "conflict": True, "message": str(exc), "currentRevision": exc.current}, status_code=409)
    except ValueError as exc:
        return JSONResponse({"ok": False, "validationError": True, "message": f"Settings rejected: {exc}"}, status_code=422)
    except Exception as exc:
        LOGGER.exception("Settings update failed")
        return JSONResponse({"ok": False, "message": f"Save failed and was rolled back: {exc}"}, status_code=500)


def _update_settings_locked(clean_payload: dict[str, Any], expected_revision: int | None = None) -> dict[str, Any]:
    with SETTINGS_LOCK:
        # Live Trading, Auto Trading and Dry Run are immediate, field-level controls.
        # A full-form Save & Apply request may have been rendered before one of those
        # switches completed, so it must never be allowed to overwrite their newer
        # server-authoritative values. This closes the final stale-form race in both
        # request orders: save->toggle and toggle->save.
        effective_payload = deepcopy(clean_payload)
        incoming_execution = effective_payload.get("execution")
        current_execution = SETTINGS_STATE.get("execution") if isinstance(SETTINGS_STATE.get("execution"), dict) else {}
        if isinstance(incoming_execution, dict):
            for protected_key in ("liveTradingEnabled", "autoTradingEnabled", "dryRun"):
                if protected_key in current_execution:
                    incoming_execution[protected_key] = current_execution[protected_key]
        snap = _settings_snapshot("before_manual_settings_save")
        receipt = _commit_settings_patch(
            effective_payload,
            reason="api_settings",
            expected_revision=expected_revision,
        )
        _remember_rollback_snapshot(snap, "manual_settings_save")
        if isinstance(effective_payload.get("pyramiding"), dict):
            pyramiding_engine.update_settings(SETTINGS_STATE.get("pyramiding", {}))
        public = _safe_public_settings(SETTINGS_STATE)
        public["mt5"] = mt5_bridge.status()
        public["settingsRevision"] = _settings_revision()
        public["serverBuildId"] = BUILD_ID
        public["recoveryState"] = deepcopy(SETTINGS_RECOVERY_STATE)
        return {
            "ok": True,
            "settings": public,
            "revision": _settings_revision(),
            "savedAt": receipt.get("savedAt"),
            "rollbackSnapshot": snap.get("id"),
            "saveReceipt": receipt,
        }


