@app.post("/api/risk/update")
def update_risk(payload: dict[str, Any] = Body(...)):
    if not isinstance(payload, dict):
        return {"ok": False, "blocked": True, "message": "Risk update must be an object."}
    risk_before = deepcopy(RISK_STATE)
    settings_before = deepcopy(SETTINGS_STATE)
    candidate = deepcopy(RISK_STATE)
    rule_name = payload.get("rule") or payload.get("title")
    key_map = {
        "Max Daily Loss": "maxDailyLossPct",
        "Max Drawdown": "maxDrawdownPct",
        "Drawdown Guard": "maxDrawdownPct",
        "Max Risk Per Trade": "maxRiskPerTradePct",
        "Max Open Risk": "maxOpenRiskPct",
        "Open Risk": "maxOpenRiskPct",
        "Max Exposure": "maxExposurePct",
        "Loss Streak Limit": "lossStreakLimit",
        "Circuit Breaker": "circuitBreakerPct",
    }

    def checked_limit(key: str, raw: Any) -> float | int:
        if key not in RISK_LIMIT_BOUNDS:
            raise ValueError(f"Unsupported risk limit: {key}")
        number = _first_number(str(raw))
        if number is None or not math.isfinite(float(number)):
            raise ValueError(f"{key} must be a finite number")
        lo, hi = RISK_LIMIT_BOUNDS[key]
        number = float(number)
        if number < lo or number > hi:
            raise ValueError(f"{key} must be between {lo:g} and {hi:g}")
        return int(number) if key in {"lossStreakLimit", "newsFilterMinutes"} else number

    try:
        if rule_name and ("limit" in payload or "enabled" in payload or "main" in payload):
            mapped = key_map.get(str(rule_name))
            limit_val = payload.get("limit", payload.get("main"))
            if mapped and limit_val not in {None, ""}:
                candidate[mapped] = checked_limit(mapped, limit_val)
            elif not mapped:
                raise ValueError(f"Unsupported operational risk rule: {rule_name}")
            candidate.setdefault("rules", {})[str(rule_name)] = {
                "limit": limit_val,
                "enabled": bool(payload.get("enabled", True)),
            }
        else:
            for key, raw in payload.items():
                if key == "sessionCaps":
                    if not isinstance(raw, dict):
                        raise ValueError("sessionCaps must be an object")
                    caps: dict[str, float] = {}
                    for session, value in raw.items():
                        if not re.fullmatch(r"[A-Za-z][A-Za-z /_-]{0,31}", str(session)):
                            raise ValueError("Invalid session-cap name")
                        number = float(value)
                        if not math.isfinite(number) or number < 0 or number > 10:
                            raise ValueError("Session risk caps must be between 0 and 10 percent")
                        caps[str(session)] = number
                    candidate["sessionCaps"] = caps
                else:
                    candidate[key] = checked_limit(key, raw)

        with SETTINGS_LOCK:
            RISK_STATE.clear()
            RISK_STATE.update(candidate)
            live_risk = SETTINGS_STATE.setdefault("risk", {})
            for key in ("maxDailyLossPct", "maxOpenRiskPct", "maxExposurePct", "circuitBreakerPct"):
                live_risk[key] = RISK_STATE[key]
            live_risk["equityStopLossPct"] = RISK_STATE["maxDrawdownPct"]
            SETTINGS_STATE.setdefault("trading", {})["riskPerTrade"] = RISK_STATE["maxRiskPerTradePct"]
            live_risk["riskPerTradePct"] = RISK_STATE["maxRiskPerTradePct"]
            SETTINGS_STATE.setdefault("automation", {})["lossStreakPause"] = int(RISK_STATE["lossStreakLimit"])
            _save_risk()
            _save_settings("risk_center_update")
    except Exception as exc:
        RISK_STATE.clear()
        RISK_STATE.update(risk_before)
        SETTINGS_STATE.clear()
        SETTINGS_STATE.update(settings_before)
        try:
            # Restore the dedicated risk file only. Re-saving unchanged settings here used to
            # increment the revision and change metadata even when validation rejected the request.
            _save_risk()
        except Exception as restore_exc:
            RUNTIME_HEALTH.fail("risk_settings_restore", restore_exc, operation="risk_update_rollback")
        return {"ok": False, "blocked": True, "message": f"Risk update rejected: {exc}"}
    return {"ok": True, "risk": RISK_STATE, "limits": _risk_limits_view(), "message": f"Risk rule saved: {rule_name or 'limits updated'}."}


