# ── AI Strategy Lab ──────────────────────────────────────────────────────────────────────
def _refresh_strategy_feed() -> int:
    """Pull candidate profiles from the trusted strategy-feed URL (if configured) into the pool."""
    cfg = SETTINGS_STATE.get("strategyLab", {}) if isinstance(SETTINGS_STATE.get("strategyLab"), dict) else {}
    url = str(cfg.get("feedUrl", "") or "").strip()
    if not url:
        return 0
    res = ai_strategy_gen.fetch_feed_candidates(url, str(cfg.get("feedKey", "") or ""))
    return strategy_lab.add_candidates(res.get("candidates", [])) if res.get("ok") else 0


def _run_strategy_lab(bars: int = 60000, progress: Any = None) -> dict[str, Any]:
    """Back-/forward-test every candidate trading style + the live baseline over your history."""
    _refresh_strategy_feed()   # pull any trusted-feed candidates before testing
    connected = bool(mt5_bridge.status().get("connected"))
    candles = _backtest_candles(bars)
    lab_cfg = SETTINGS_STATE.get("strategyLab", {}) if isinstance(SETTINGS_STATE.get("strategyLab"), dict) else {}
    params = _backtest_params({"spread": 0.25, "commission": 0.07, "minSample": 30, "folds": 6,
                               "improveMarginR": float(lab_cfg.get("improveMarginR", 0.05) or 0.05),
                               "dataSource": "mt5_history" if connected else "synthetic_demo"})
    research_engine = _research_engine()
    baseline = research_engine.strictness_dict()
    res = strategy_lab.evaluate(candles, research_engine, list(STRATEGIES_STATE.values()), backtester, baseline, params, progress=progress)
    res["dataSource"] = params["dataSource"]
    LAB_STATE["lastRun"] = time.time()
    LAB_STATE["lastResult"] = res
    return res


@app.get("/api/lab/candidates")
def lab_candidates():
    return {"ok": True, "candidates": strategy_lab.candidates(), "installed": LAB_STATE.get("installedProfile")}


def _alert_lab_recommendation(res: dict[str, Any]) -> None:
    """Fire the notification + top-bar + sound + Telegram alert when the lab finds a NEW better
    candidate (deduped by signature so the same recommendation doesn't re-alert)."""
    rec = res.get("recommendation")
    if rec and res.get("signature") != LAB_STATE.get("lastRecSig"):
        LAB_STATE["lastRecSig"] = res.get("signature")
        _push_notification("AI found a better strategy", f"{rec['name']}: {rec['why'][:150]} Review & install in Analytics → Strategy Lab.", "success", {"sound": True, "strategyLab": True})
        tg = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
        if tg.get("enabled"):
            _telegram_send_text(f"🧠 *GodMode — better strategy found*\n*{rec['name']}*\n{rec['why']}\n\nReview the back/forward test and install it in the dashboard → Analytics → Strategy Lab.")


def _auto_discover_strategy() -> None:
    """Auto-pilot: when NO enabled strategy fits the current market, run the Lab, auto-install the best
    candidate that beats your edge out-of-sample, and alert Telegram with Uninstall/Keep buttons.
    OPT-IN (strategyLab.autoDiscover). Heavily guarded: never during a news blackout, never stacks a
    second install, cooldown-throttled, and only installs a candidate the Lab VALIDATES — so it can
    inform you and save a missed trade WITHOUT ever forcing a losing chop trade."""
    lab_cfg = SETTINGS_STATE.get("strategyLab", {}) if isinstance(SETTINGS_STATE.get("strategyLab"), dict) else {}
    if not lab_cfg.get("autoDiscover"):
        return
    if not mt5_bridge.status().get("connected") or not _market_state().get("open", False):
        return
    if LAB_STATE.get("installedProfile"):
        return  # a discovered strategy is already active — don't stack a second one
    cooldown = float(lab_cfg.get("autoDiscoverCooldownMin", 60) or 60) * 60
    now = time.time()
    if now - float(RECAP_STATE.get("lastAutoDiscover", 0) or 0) < cooldown:
        return
    try:
        dec = _decision()
    except Exception:
        return
    if str(dec.get("action")) == "TAKE_TRADE":
        return  # a strategy already fits — nothing to discover
    if (dec.get("economicCalendar") or {}).get("isBlackout"):
        return  # news blackout — correct to wait
    evals = dec.get("strategyEvaluations") or []
    if evals and any(e.get("passes") for e in evals):
        return  # some strategy already passes — not a fit problem
    RECAP_STATE["lastAutoDiscover"] = now
    res = _run_strategy_lab(60000)
    rec = res.get("recommendation")
    if not rec:
        today = time.strftime("%Y-%m-%d", time.gmtime())
        if RECAP_STATE.get("lastAutoDiscoverNone") != today:
            RECAP_STATE["lastAutoDiscoverNone"] = today
            _telegram_send_text("🔎 *GodMode — auto-scan*\nNo strategy fits the current market, so I scanned the "
                                "Strategy Lab. *Nothing beats your current edge out-of-sample right now*, so I'm "
                                "staying flat (correct — no forced trades). I'll keep watching and alert you the "
                                "moment a validated strategy fits.")
        return
    inst = lab_install({"id": rec["id"]})
    if not inst.get("ok"):
        return
    why = str(rec.get("why", ""))[:320]
    _push_notification("Auto-installed a fitting strategy", f"{rec['name']}: {why}", "success", {"sound": True, "strategyLab": True})
    _telegram_send_text(
        f"🤖 *GodMode — auto-installed a fitting strategy*\n*{rec['name']}*\n{why}\n\n"
        f"It now competes in your rotation with its OWN entry gates (your global config is untouched), so "
        f"you don't miss the setup while you're busy. Tap below to manage it:",
        buttons=[[{"text": "↩️ Uninstall", "callback_data": "gm_lab_uninstall"},
                  {"text": "✅ Keep", "callback_data": "gm_lab_keep"}]])


async def _telegram_command_loop() -> None:
    """Poll Telegram for button taps / commands so you can Uninstall or Keep an auto-installed strategy
    straight from your phone. Low-latency short-poll (~2s by default); no webhook, nothing exposed to the internet. Telegram-
    only and resilient — any error just retries. Handles the auto-discover Uninstall/Keep buttons and the
    /uninstall and /keep text commands as a fallback."""
    while True:
        try:
            tg = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
            token, configured_chat_id = _telegram_creds()
            poll_s = max(1.0, min(float(tg.get("callbackPollSeconds", 2.0) or 2.0), 12.0))
            if not tg.get("enabled") or not token or not configured_chat_id:
                await asyncio.sleep(max(5.0, poll_s)); continue
            offset = int(RECAP_STATE.get("tgUpdateOffset", 0) or 0)
            url = f"https://api.telegram.org/bot{token}/getUpdates?timeout=0&offset={offset}&allowed_updates=%5B%22message%22%2C%22callback_query%22%5D"
            def _fetch() -> dict[str, Any]:
                return json.loads(
                    read_public_https(url, timeout=12).decode("utf-8", "ignore")
                )
            data = await asyncio.get_event_loop().run_in_executor(None, _fetch)
            for upd in data.get("result", []) if isinstance(data, dict) else []:
                RECAP_STATE["tgUpdateOffset"] = int(upd.get("update_id", offset)) + 1
                if not _telegram_update_is_authorized(upd, configured_chat_id):
                    RUNTIME_HEALTH.fail("telegram_auth", "Ignored Telegram update from an unauthorized chat")
                    continue
                RUNTIME_HEALTH.beat("telegram_auth", "authorized chat update")
                cb = upd.get("callback_query") or {}
                msg = upd.get("message") or {}
                action, cb_id = None, cb.get("id")
                if cb:
                    action = str(cb.get("data") or "")
                elif isinstance(msg.get("text"), str):
                    t = msg["text"].strip().lower()
                    if t.startswith("/buy ") or t.startswith("/sell ") or t in {"/buy", "/sell"}:
                        manual_request = _telegram_manual_trade_request(t, upd.get("update_id"))
                        if not manual_request.get("ok"):
                            _telegram_send_text("❌ *Manual trade not queued*\n" + str(manual_request.get("message") or "Invalid command."))
                    elif t.startswith("/be "):
                        action = "gm_pos_be:" + t.split(maxsplit=1)[1].strip()
                    elif t.startswith("/trail "):
                        action = "gm_pos_trail:" + t.split(maxsplit=1)[1].strip()
                    elif t in ("/uninstall", "/uninstall_lab", "uninstall"):
                        action = "gm_lab_uninstall"
                    elif t in ("/keep", "/skip", "keep"):
                        action = "gm_lab_keep"
                    elif t in ("/positions", "positions", "/trades"):
                        action = "gm_positions"
                    elif t in ("/auto", "auto", "/fullauto", "fullauto"):
                        action = "gm_mode_auto"
                    elif t in ("/semi", "semi", "/semiauto", "semiauto"):
                        action = "gm_mode_semi"
                    elif t in ("/mode", "mode", "/modes", "modes"):
                        st=_trading_modes_status()
                        _telegram_send_text(f"🤖 *GodMode modes*\nExecution: *{_execution_mode().replace('_',' ').upper()}*\nActive trading mode: *{st.get('activeMode','normal').replace('_',' ').upper()}*\nBurst: *{'ON' if st.get('protectedBurst',{}).get('enabled') else 'OFF'}*\nPyramid: *{'ON' if st.get('pyramiding',{}).get('enabled') else 'OFF'}*", buttons=_telegram_position_buttons())
                    elif t in ("/burst_on", "burst on", "/burston"):
                        action = "gm_burst_on"
                    elif t in ("/burst_off", "burst off", "/burstoff"):
                        action = "gm_burst_off"
                    elif t in ("/burst_now", "burst now", "/fire_burst", "fire burst", "burst"):
                        action = "gm_burst_now"
                    elif t in ("/pyramid_on", "pyramid on", "/pyramiding_on"):
                        action = "gm_pyramid_on"
                    elif t in ("/pyramid_off", "pyramid off", "/pyramiding_off"):
                        action = "gm_pyramid_off"
                    elif t in ("/kill", "/stop", "kill"):
                        action = "gm_kill"
                    elif t in ("/help", "help"):
                        _telegram_send_text("🤖 *GodMode Telegram controls*\n/auto — switch to automatic execution\n/semi — switch to Telegram approval mode\n/mode — show/change mode\n/positions — manage open trades\n/be <ticket> — move one profitable trade to BE + buffer\n/trail <ticket> — apply a one-time ATR/structure trail\n/buy <lots> [SL] [TP] [symbol] — queue a confirmed manual BUY\n/sell <lots> [SL] [TP] [symbol] — queue a confirmed manual SELL\n/burst_now — evaluate one protected burst batch immediately; safety gates remain active\n/kill — disable auto-entry immediately\nManual orders always require a confirmation button. TAKE / SCOUT / SKIP buttons appear in semi-auto mode when a setup is executable.", buttons=_telegram_position_buttons())
                if action == "gm_lab_uninstall":
                    r = lab_uninstall({})
                    _telegram_send_text("↩️ *Uninstalled.* " + str(r.get("message", "Removed the auto-installed strategy from your rotation.")))
                elif action == "gm_lab_keep":
                    _telegram_send_text("✅ *Kept.* The strategy stays in your rotation with its own gates. Remove it any time in the app or with /uninstall.")
                elif action.startswith("gm_trade_take:"):
                    trade_id = action.split(":", 1)[1]
                    _telegram_execute_pending_trade(trade_id, scout=False)
                elif action.startswith("gm_trade_scout:"):
                    trade_id = action.split(":", 1)[1]
                    _telegram_execute_pending_trade(trade_id, scout=True)
                elif action.startswith("gm_trade_skip:"):
                    trade_id = action.split(":", 1)[1]
                    rec = TELEGRAM_PENDING_TRADES.get(trade_id)
                    if rec:
                        rec["status"] = "skipped"; rec["skippedAt"] = time.time(); _save_pending_trades()
                    _telegram_send_text(f"❌ *Skipped.* Trade approval `{trade_id}` was not sent to MT5.")
                elif action == "gm_burst_on":
                    r=_set_protected_burst_enabled(True, "telegram")
                    _telegram_send_text("⚡ *Protected Burst ON.* Pyramiding has been switched OFF for clean audit. Burst adds only after the base basket is protected; it is not zero-loss martingale.", buttons=_telegram_position_buttons())
                elif action == "gm_burst_off":
                    AUTO_TRADE_STATE["protectedBurstFailedBatch"] = False
                    AUTO_TRADE_STATE["protectedBurstTelegramApproved"] = False
                    r=_set_protected_burst_enabled(False, "telegram")
                    _telegram_send_text("⛔ *Protected Burst OFF.* Normal entries continue. Turn Pyramid ON separately if you want staged winner adds.", buttons=_telegram_position_buttons())
                elif action == "gm_burst_allow_once":
                    AUTO_TRADE_STATE["protectedBurstTelegramApproved"] = True
                    AUTO_TRADE_STATE["lastProtectedBurstTs"] = 0
                    _telegram_send_text("✅ *One Protected Burst batch approved.* The bot will send one batch only if all safety gates are still valid on the next management tick.", buttons=_telegram_position_buttons())
                elif action == "gm_burst_now":
                    _telegram_fire_burst_now()
                elif action == "gm_pyramid_on":
                    r=_set_pyramiding_enabled(True, "telegram")
                    _telegram_send_text("🔺 *Pyramiding ON.* Protected Burst has been switched OFF to keep modes separated and auditable.", buttons=_telegram_position_buttons())
                elif action == "gm_pyramid_off":
                    r=_set_pyramiding_enabled(False, "telegram")
                    _telegram_send_text("🔺 *Pyramiding OFF.*", buttons=_telegram_position_buttons())
                elif action == "gm_kill":
                    kill_switch.activate("Telegram emergency stop")
                    with SETTINGS_LOCK:
                        SETTINGS_STATE.setdefault("execution", {})["autoTradingEnabled"] = False
                        mt5_bridge.set_auto_trading_enabled(False)
                        _save_settings("telegram_kill_switch")
                    _telegram_send_text("🛑 *Emergency stop engaged.* Auto-entry is OFF. Existing broker SL/TP remains on open positions.")
                elif action == "gm_mode_auto":
                    r = _set_execution_mode("auto", "telegram")
                    _telegram_send_text("⚡ *AUTO mode enabled.* Valid setups can fire immediately without Telegram approval. Risk, validation, news blackout and kill-switch gates still apply.", buttons=_telegram_position_buttons())
                elif action == "gm_mode_semi":
                    r = _set_execution_mode("semi_auto", "telegram")
                    _telegram_send_text("✅ *SEMI-AUTO mode enabled.* Valid setups will wait for Telegram TAKE / SCOUT / SKIP approval.", buttons=_telegram_position_buttons())
                elif action == "gm_positions":
                    _telegram_show_positions()
                elif action.startswith("gm_pos_close:"):
                    ticket = action.split(":", 1)[1]
                    res = _execute_mt5_mutation_serialized("CLOSE", {"ticket": ticket, "manualTrigger": True}, "telegram_close")
                    _record_execution_memory(res, {"ticket": ticket}, "telegram_close")
                    _telegram_send_text(("✅ Closed" if res.get("ok") else "❌ Close failed") + f" #{ticket}\n{res.get('message','')}")
                elif action.startswith("gm_pos_be:"):
                    ticket = action.split(":", 1)[1]
                    res = _manual_position_control(ticket, "BE")
                    _record_execution_memory(res, {"ticket": ticket, "sl": res.get("requestedSl")}, "telegram_be")
                    _telegram_send_text(("🟡 BE confirmed" if res.get("ok") else "❌ BE failed") + f" #{ticket}\n{res.get('message','')}")
                elif action.startswith("gm_pos_trail:"):
                    ticket = action.split(":", 1)[1]
                    res = _manual_position_control(ticket, "TRAIL")
                    _record_execution_memory(res, {"ticket": ticket, "sl": res.get("requestedSl")}, "telegram_trail")
                    _telegram_send_text(("📈 Trail confirmed" if res.get("ok") else "❌ Trail failed") + f" #{ticket}\n{res.get('message','')}")
                if cb_id:
                    try:
                        ack = urllib.parse.urlencode({"callback_query_id": cb_id}).encode()
                        ack_request = urllib.request.Request(
                            f"https://api.telegram.org/bot{token}/answerCallbackQuery",
                            data=ack,
                            method="POST",
                        )
                        await asyncio.get_event_loop().run_in_executor(
                            None,
                            lambda: read_public_https(ack_request, timeout=8),
                        )
                    except Exception as _suppressed_exc:
                        _report_suppressed_exception("suppressed_exception_line_10934", _suppressed_exc)
            await asyncio.sleep(poll_s)
        except asyncio.CancelledError:
            raise
        except Exception:
            await asyncio.sleep(5)


