@app.post("/api/trades/manage-live")
def manage_live_trade(payload: dict[str, Any] = Body(...)):
    ticket = payload.get("ticket") or payload.get("position")
    action = str(payload.get("action") or "AUTO").upper().replace("-", "_")
    if not ticket:
        return {"ok": False, "blocked": True, "message": "A broker position ticket is required."}
    if action in {"BE", "BREAK_EVEN", "BREAKEVEN", "MOVE_TO_BREAKEVEN"}:
        return _manual_position_control(ticket, "BE")
    if action in {"TRAIL", "TRAILING", "TRAIL_STRUCTURE"}:
        return _manual_position_control(ticket, "TRAIL")
    if action == "CLOSE":
        return _execute_mt5_mutation_serialized("CLOSE", {"ticket": ticket}, "api_manage_live_close")
    positions = mt5_bridge.open_positions(bot_only=False)
    position = next(
        (
            row
            for row in positions
            if int(float(row.get("ticket") or row.get("position") or 0))
            == int(float(ticket))
        ),
        None,
    )
    if position is None:
        return {"ok": False, "blocked": True, "message": "The requested broker position was not found."}
    recommendation = trade_manager.live_management_decision(position)
    recommended = str(recommendation.get("action") or "HOLD").upper()
    if recommended == "MOVE_TO_BREAKEVEN":
        return {**_manual_position_control(ticket, "BE"), "recommendation": recommendation}
    if recommended == "TRAIL_STRUCTURE":
        return {**_manual_position_control(ticket, "TRAIL"), "recommendation": recommendation}
    return {
        "ok": True,
        "executed": False,
        "action": recommended,
        "recommendation": recommendation,
        "message": "Authoritative live position evaluated; no broker mutation is currently required.",
    }


