@app.post("/api/trades/execute-multi-target")
def execute_multi_target(payload: dict[str, Any] = Body(...)):
    if kill_switch.status().get("active"):
        return {"ok": False, "blocked": True, "message": "Emergency kill switch is active."}
    identity_error = _missing_execution_identity(payload)
    if identity_error:
        return identity_error
    requested_plan = trade_manager.build_child_orders(payload)
    if not requested_plan.get("ok"):
        return {"ok": False, "blocked": True, "tradePlan": requested_plan, "message": "TP1-TP4 plan failed safety validation."}

    protected_payload, protection_error = _protected_entry_payload(payload, "multi_target")
    if protection_error:
        return {**protection_error, "tradePlan": requested_plan}
    protected_payload = protected_payload or {}
    protected_payload["executionId"] = _execution_identity(payload)
    # The shared protected-entry builder intentionally emits one broker TP. Restore
    # the independently validated TP1-TP4 ladder for the split-order gateway.
    for index, child in enumerate(requested_plan.get("childOrders") or [], start=1):
        protected_payload[f"tp{index}"] = child.get("tp")

    protected_plan = trade_manager.build_child_orders(
        {
            **protected_payload,
            "entry": payload.get("entry") or payload.get("price"),
        }
    )
    if not protected_plan.get("ok"):
        return {"ok": False, "blocked": True, "tradePlan": protected_plan, "message": "Risk-capped TP1-TP4 plan failed safety validation."}
    validation = _execution_validation_check("multi_target")
    if not validation.get("ok"):
        return {**validation, "tradePlan": protected_plan}
    bridge_result = _execute_mt5_multi_serialized(protected_payload, "api_multi_target")
    return {"ok": bool(bridge_result.get("ok")), "tradePlan": protected_plan, "execution": bridge_result}


