def _authoritative_pyramiding_context() -> tuple[dict[str, Any] | None, dict[str, Any] | None]:
    """Build pyramid evidence only from current broker/server state.

    Order endpoints must never accept client assertions such as ``profitR``,
    ``beMoved`` or ``marginLevel`` as safety evidence.
    """
    try:
        positions = mt5_bridge.open_positions(bot_only=True)
        if not positions:
            return None, {
                "ok": False,
                "blocked": True,
                "message": "No active GodMode broker position is available to pyramid.",
            }
        symbols = {str(row.get("symbol") or "").upper() for row in positions}
        directions = {str(row.get("direction") or row.get("side") or "").upper() for row in positions}
        if len(symbols) != 1 or directions - {"BUY", "SELL"} or len(directions) != 1:
            return None, {
                "ok": False,
                "blocked": True,
                "message": "Pyramiding blocked: the live bot basket has mixed symbols or directions.",
            }

        positions = sorted(positions, key=lambda row: (str(row.get("openTime") or ""), int(float(row.get("ticket") or 0))))
        base = dict(positions[0])
        symbol = next(iter(symbols))
        direction = next(iter(directions))
        market = dict(_live_market() or {})
        decision = dict(_decision() or {})
        features = decision.get("features") if isinstance(decision.get("features"), dict) else {}
        cleanliness = decision.get("marketCleanliness") if isinstance(decision.get("marketCleanliness"), dict) else {}
        account = mt5_bridge.account_snapshot()
        equity = float(account.get("equity") or 0.0)
        margin = float(account.get("margin") or 0.0)
        if not account.get("connected") or equity <= 0 or margin <= 0:
            return None, {
                "ok": False,
                "blocked": True,
                "message": "Pyramiding blocked: a fresh connected broker account/margin snapshot is required.",
                "account": account,
            }

        entry = float(base.get("entryPrice") or 0.0)
        current = _management_price(direction, market, base)
        state = POSITION_PROTECTION_STATE.get(str(base.get("ticket")), {}) or {}
        initial_risk = float(state.get("riskBasis") or 0.0)
        base_sl = float(base.get("sl") or 0.0)
        if initial_risk <= 0 and base_sl > 0:
            stop_is_original_side = (direction == "BUY" and base_sl < entry) or (direction == "SELL" and base_sl > entry)
            if stop_is_original_side:
                initial_risk = abs(entry - base_sl)
        if entry <= 0 or current <= 0 or initial_risk <= 0:
            return None, {
                "ok": False,
                "blocked": True,
                "message": "Pyramiding blocked: authoritative entry, price and original-risk basis are required.",
            }

        def broker_protected(row: dict[str, Any]) -> bool:
            row_entry = float(row.get("entryPrice") or 0.0)
            row_sl = float(row.get("sl") or 0.0)
            row_side = str(row.get("direction") or "").upper()
            return bool(
                row_entry > 0
                and row_sl > 0
                and (
                    (row_side == "BUY" and row_sl >= row_entry)
                    or (row_side == "SELL" and row_sl <= row_entry)
                )
            )

        protected_flags = [broker_protected(row) for row in positions]
        base_protected = protected_flags[0]
        all_prior_protected = all(protected_flags)
        profit_r = ((current - entry) if direction == "BUY" else (entry - current)) / initial_risk
        locked_profit_r = max(
            0.0,
            ((base_sl - entry) if direction == "BUY" else (entry - base_sl)) / initial_risk,
        )
        current_lots = sum(float(row.get("lots") or row.get("volume") or 0.0) for row in positions)
        current_adds = max(0, len(positions) - 1)
        total_exposure_pct = max(0.0, float(account.get("openRiskPct") or 0.0))
        margin_level = equity / margin * 100.0
        point = float((mt5_bridge.symbol_specs(symbol) or {}).get("point") or 0.01)
        configured_slippage = float((SETTINGS_STATE.get("brokerCosts") or {}).get("slippage") or 0.0)
        slippage_points = float(market.get("slippagePoints") or (configured_slippage / max(point, 1e-9)))
        atr = max(float(market.get("atr14") or market.get("atr") or features.get("atr") or 0.0), point)
        tp = float(base.get("tp") or 0.0)
        room = ((tp - current) if direction == "BUY" else (current - tp)) if tp > 0 else 0.0
        liquidity_room_score = max(0.0, min(100.0, room / max(initial_risk, point) * 50.0))
        matching_decision = str(decision.get("side") or "").upper() == direction
        pullback_confirmed = bool(features.get("pullbackPresent") or features.get("impulseRetestConfirmed"))
        momentum_confirmed = bool(features.get("momentumExpanding") or features.get("trendAligned"))
        extension_values = [
            float(features[name])
            for name in ("atrDistance20", "atrDistance50")
            if features.get(name) is not None
        ]
        extension_atr = min(extension_values) if extension_values else 99.0
        if not matching_decision:
            decision["action"] = "WAIT"
        directional_structure = (
            bool(features.get("structureBullish"))
            if direction == "BUY"
            else bool(features.get("structureBearish"))
        )
        structure_valid = bool(
            matching_decision
            and not decision.get("decisionBlocks")
            and (
                features.get("trendAligned")
                or features.get("weakAlignment")
                or directional_structure
            )
        )

        position = {
            **base,
            "profitR": round(profit_r, 4),
            "floatingR": round(profit_r, 4),
            "beMoved": base_protected,
            "breakEvenProtected": base_protected,
            "allPriorAddsProtected": all_prior_protected,
            "previousAddsProtected": all_prior_protected,
            "pyramidAdds": current_adds,
            "currentAdds": current_adds,
            "baseLot": float((SETTINGS_STATE.get("pyramiding") or {}).get("baseLot") or 0.01),
            "currentLots": round(current_lots, 8),
            "totalExposurePct": total_exposure_pct,
            "currentStackRiskPct": total_exposure_pct,
            "openRiskPct": total_exposure_pct,
            "marginLevelPct": margin_level,
            "lockedProfitR": round(locked_profit_r, 4),
            "floatingProfitMoney": sum(float(row.get("pnlUsd") or row.get("profit") or 0.0) for row in positions),
            "baseStopDistance": initial_risk,
            "addStopDistance": atr,
            "baseRiskPct": float((SETTINGS_STATE.get("trading") or {}).get("riskPerTrade") or 0.5),
            "winStreak": int(AUTO_TRADE_STATE.get("winStreak", 0) or 0),
            "winsSinceLastLoss": int(AUTO_TRADE_STATE.get("winStreak", 0) or 0),
            "previousPyramidAddFailed": bool(AUTO_TRADE_STATE.get("previousPyramidAddFailed")),
            "structureValid": structure_valid,
            "pullbackRetestConfirmed": pullback_confirmed,
            "momentumConfirmed": momentum_confirmed,
            "dailyLossPct": max(0.0, -float(account.get("dailyPnlPct") or 0.0)),
        }
        authoritative_market = {
            **market,
            "symbol": symbol,
            "price": current,
            "structureValid": structure_valid,
            "pullbackRetestConfirmed": pullback_confirmed,
            "momentumConfirmed": momentum_confirmed,
            "volatilityExpansionClean": bool(momentum_confirmed and not features.get("overExtended")),
            "dirtyConditions": not bool(cleanliness.get("isClean", False)),
            "cleanlinessScore": float(cleanliness.get("score") or 0.0),
            "trendAlignmentScore": float(features.get("htfAlignmentScore") or 0.0),
            "liquidityRoomScore": liquidity_room_score,
            "extensionAtr": extension_atr,
            "lateEntry": bool(features.get("overExtended")),
            "momentumDivergence": bool(features.get("momentumDivergence", False)),
            "slippagePoints": slippage_points,
            "newsBlackout": bool((decision.get("economicCalendar") or {}).get("isBlackout", False)),
        }
        return {
            "ok": True,
            "position": position,
            "market": authoritative_market,
            "decision": decision,
            "broker": _broker_execution_quality(),
            "account": account,
        }, None
    except Exception as exc:
        LOGGER.exception("Authoritative pyramiding context failed")
        return None, {
            "ok": False,
            "blocked": True,
            "message": f"Pyramiding blocked: authoritative broker evidence could not be built ({exc}).",
        }


