@app.get("/api/system/why-silent")
def why_silent():
    """V12.89 — one call that walks EVERY gate between 'bot running' and 'trade fired / alert sent'
    and reports which one is currently stopping activity. Built because 'everything is on but
    nothing happens' has too many independent causes to guess: loop dead, MT5 down, market closed,
    toggle off, mode wrong, cooldown, position already open, throttle. This answers it directly."""
    now = time.time()
    tg = SETTINGS_STATE.get("telegram", {}) if isinstance(SETTINGS_STATE.get("telegram"), dict) else {}
    ex = SETTINGS_STATE.get("execution", {}) if isinstance(SETTINGS_STATE.get("execution"), dict) else {}
    try:
        mt5s = mt5_bridge.status()
    except Exception as e:
        mt5s = {"connected": False, "error": str(e)[:120]}
    try:
        mkt = _market_state()
    except Exception as e:
        mkt = {"open": None, "reason": str(e)[:120]}
    loop_alive_at = float(AUTO_TRADE_STATE.get("loopAliveAt", 0.0) or 0.0)
    loop_age = now - loop_alive_at if loop_alive_at else None
    try:
        open_bot = mt5_bridge.open_positions(bot_only=True)
        open_bot_n = len(open_bot) if open_bot else 0
    except Exception:
        open_bot_n = None

    checks = []
    def add(name, ok, detail):
        checks.append({"check": name, "ok": bool(ok), "detail": detail})

    add("Background loop alive", loop_age is not None and loop_age < 30,
        (f"last tick {loop_age:.0f}s ago" if loop_age is not None else "loop has NEVER ticked — backend may have crashed on startup; check the console"))
    add("MT5 connected", mt5s.get("connected"),
        ("connected" if mt5s.get("connected") else f"NOT connected — the whole entry/manage/alert cycle is gated on this. {mt5s.get('error','Start the EA on your MT5 chart and confirm the bridge.')}"))
    add("Market open", mkt.get("open") is True,
        (mkt.get("reason") or "open") + ("" if mkt.get("open") is True else " — watcher and entries skip when closed"))
    add("Telegram enabled", tg.get("enabled"),
        ("on" if tg.get("enabled") else "Telegram master switch is OFF (Settings → Telegram)"))
    add("Fast-sniper alerts toggle", tg.get("sendFastSniperAlerts", False),
        ("on" if tg.get("sendFastSniperAlerts", False) else "‘Send Fast Sniper Alerts’ is OFF — this is the toggle that sends trade-setup alerts; the connection test uses a different path, which is why the test worked but setups are silent"))
    live_ready = bool(ex.get("liveTradingEnabled")) and not bool(ex.get("dryRun", True)) and bool(ex.get("autoTradingEnabled"))
    add("Live execution ready", live_ready,
        ("liveTradingEnabled ON, dryRun OFF, autoTradingEnabled ON" if live_ready else
         f"NOT ready to auto-fire: liveTradingEnabled={ex.get('liveTradingEnabled')} dryRun={ex.get('dryRun', True)} autoTradingEnabled={ex.get('autoTradingEnabled')} (all-on required to place orders; alerts can still fire without this)"))
    add("No bot position already open", open_bot_n == 0,
        (f"{open_bot_n} bot position(s) open — the watcher intentionally stays quiet while a bot trade is live" if open_bot_n else ("none open" if open_bot_n == 0 else "could not read positions (MT5 down)")))

    blockers = [c for c in checks if not c["ok"]]
    primary = blockers[0]["check"] if blockers else None
    verdict = ("Everything required is green — if it's still silent, the market simply has no qualifying setup right now."
               if not blockers else
               f"Primary blocker: {primary}. Fix the red items top-to-bottom; the top one usually explains the rest.")
    return {"ok": True, "verdict": verdict, "checks": checks,
            "loopLastResult": AUTO_TRADE_STATE.get("lastResult"),
            "executionMode": _execution_mode(),
            "lastFastSniperAlertSecondsAgo": (round(now - float(RECAP_STATE.get("lastFastSniperSignalAt", 0.0) or 0.0)) if RECAP_STATE.get("lastFastSniperSignalAt") else None)}


@app.get("/api/news/test")
def news_fetch_test():
    """V12.84 — verbose LIVE fetch diagnostic. Fetches the configured calendar and market-news
    URLs RIGHT NOW (bypassing caches) and reports exactly what happened: HTTP status, error
    string, bytes received, events parsed, and a sample. This turns 'error or empty' on the
    dashboard into a specific, fixable answer."""
    import urllib.request as _rq
    from services.live_market_feeds import _BROWSER_HEADERS as _BH
    from services.safe_http import read_public_https

    def probe(name: str, url: str) -> dict[str, Any]:
        out: dict[str, Any] = {"name": name, "url": url or "", "configured": bool(url)}
        if not url:
            out["result"] = "not_configured"
            return out
        try:
            req = _rq.Request(url, headers=dict(_BH))
            t0 = time.time()
            raw = read_public_https(req, timeout=10)
            out["httpStatus"] = 200
            out["ms"] = round((time.time() - t0) * 1000)
            out["bytes"] = len(raw)
            txt = raw.decode("utf-8", "ignore")
            events: list[Any] = []
            try:
                data = json.loads(txt)
                events = data if isinstance(data, list) else (data.get("events") or data.get("data") or data.get("items") or [])
                out["parsed"] = "json"
            except Exception:
                out["parsed"] = "xml/text" if txt.strip() else "empty"
                if "<item" in txt.lower():
                    events = txt.lower().split("<item")[1:]
            out["eventCount"] = len(events) if isinstance(events, list) else 0
            if isinstance(events, list) and events and isinstance(events[0], dict):
                sample = {k: events[0].get(k) for k in ("title", "impact", "date", "time", "country") if k in events[0]}
                out["firstEvent"] = sample
            out["result"] = "ok" if out["eventCount"] else "ok_but_empty"
        except Exception as exc:
            out["result"] = "fetch_failed"
            out["error"] = f"{type(exc).__name__}: {str(exc)[:200]}"
        return out

    feeds = SETTINGS_STATE.get("dataFeeds", {}) if isinstance(SETTINGS_STATE.get("dataFeeds"), dict) else {}
    return {"ok": True, "userAgentInUse": _BH.get("User-Agent", "")[:80],
            "calendar": probe("economicCalendar", str(feeds.get("economicCalendarUrl") or live_calendar.url or "")),
            "marketNews": probe("marketNews", str(feeds.get("marketNewsUrl") or market_news_feed.url or "")),
            "hint": ("If result=fetch_failed with HTTP 403/1005/1020: the source blocked the request "
                     "(now using a browser User-Agent, which fixes the common case). "
                     "If ok_but_empty: URL wrong shape or genuinely no events (weekend). "
                     "If URLError/timeout: firewall/VPN/DNS on this machine.")}


