@app.post("/api/backtest/dynamic-sl-replay")
def dynamic_sl_tick_replay(payload: dict[str, Any] = Body(default={})):
    supplied_ticks = payload.get("ticks")
    if isinstance(supplied_ticks, list):
        ticks = supplied_ticks
        source = "caller_supplied_quotes"
        synthetic = False
    else:
        pack = tick_backtester.load_ticks(
            str(payload.get("symbol") or "XAUUSD"),
            str(payload.get("source") or "mt5"),
            payload.get("csvPath"),
            max(1, min(int(payload.get("limit", 50_000) or 50_000), 120_000)),
        )
        ticks = pack.get("ticks") or []
        source = str(pack.get("source") or "unknown")
        synthetic = bool(pack.get("syntheticFallback"))
    result = replay_dynamic_sl(
        ticks,
        side=str(payload.get("side") or ""),
        entry=float(payload.get("entry") or 0),
        initial_sl=float(payload.get("initialSl") or 0),
        tick_size=float(payload.get("tickSize") or 0.01),
        point=float(payload.get("point") or 0.01),
        stops_level_points=float(payload.get("stopsLevelPoints") or 0),
        freeze_level_points=float(payload.get("freezeLevelPoints") or 0),
        max_giveback_fraction=float(payload.get("maxGivebackFraction") or 0.45),
        protect_start_r=float(payload.get("protectStartR") or 0.55),
    )
    result.update({
        "marketDataSource": source,
        "synthetic": synthetic,
        "proofEligible": bool(
            result.get("ok")
            and not synthetic
            and len(ticks) >= 100
        ),
    })
    return result


