def _path_get(obj: dict[str, Any], dotted: str, default: Any = None) -> Any:
    cur: Any = obj
    for part in str(dotted).split("."):
        if not isinstance(cur, dict) or part not in cur:
            return default
        cur = cur[part]
    return cur


def _path_set(obj: dict[str, Any], dotted: str, value: Any) -> None:
    cur: Any = obj
    parts = [p for p in str(dotted).split(".") if p]
    for part in parts[:-1]:
        if not isinstance(cur.get(part), dict):
            cur[part] = {}
        cur = cur[part]
    if parts:
        cur[parts[-1]] = value


def _clamp_patch(path: str, value: Any) -> Any:
    bounds = {
        "ai.scoutConfidence": (55.0, 90.0),
        "ai.standardConfidence": (65.0, 92.0),
        "ai.sniperConfidence": (75.0, 98.0),
        "ai.minRiskReward": (1.0, 3.5),
        "ai.maxSpread": (0.15, 0.80),
        "automation.fastSniperMaxExtensionAtr": (0.55, 1.60),
        "automation.fastSniperMinConfidence": (68.0, 90.0),
        "automation.postLossReentryMinConfidence": (74.0, 92.0),
        "automation.postLossReentryConfidenceDelta": (2.0, 12.0),
        "automation.maxSameDirectionLossesBeforeHardLock": (1, 4),
        "trading.tradeManagement.aiDynamicMinLockFraction": (0.40, 0.85),
        "trading.tradeManagement.aiDynamicMaxGivebackFraction": (0.12, 0.50),
        "pyramiding.maxAdds": (0, 5),
        "pyramiding.minProfitRFirstAdd": (0.25, 2.0),
        "pyramiding.minAddConfidence": (70.0, 95.0),
        "ai.efficiencyByMode.balanced": (0.18, 0.60),
        "ai.efficiencyByMode.strict": (0.22, 0.70),
        "ai.confluenceByMode.balanced": (2, 8),
        "ai.confluenceByMode.strict": (3, 10),
        "ai.maxSpreadAtrFrac": (0.02, 0.15),
        "automation.chopEfficiencyMin": (0.12, 0.45),
        "automation.defensiveModeMinConfidence": (78.0, 95.0),
        "automation.maxEntryExtensionAtr": (0.55, 1.60),
    }
    if path in bounds:
        lo, hi = bounds[path]
        try:
            if isinstance(lo, int) and isinstance(hi, int):
                return int(max(lo, min(hi, int(float(value)))))
            return round(float(max(lo, min(hi, float(value)))), 3)
        except Exception:
            return _path_get(SETTINGS_STATE, path)
    return value


