@app.get("/api/ai/performance-review")
def ai_performance_review(period: str = "daily", use_ai: bool = True):
    period = "weekly" if str(period).lower().startswith("week") else "daily"
    local = _build_local_coach_review(period)
    cfg = SETTINGS_STATE.get("aiProvider", {}) if isinstance(SETTINGS_STATE.get("aiProvider"), dict) else {}
    if use_ai and cfg.get("enabled") and cfg.get("apiKey"):
        system, user = _ai_coach_prompt(period, local)
        res = _llm_json_call(str(cfg.get("provider", "claude")), str(cfg.get("apiKey", "")), str(cfg.get("model", "")), system, user, timeout=float(cfg.get("timeoutSeconds", 45) or 45))
        if res.get("ok"):
            local = _merge_ai_review(local, res.get("json") or {})
            local["provider"] = f"{res.get('provider')}:{res.get('model') or 'default'}"
        else:
            local["providerError"] = res.get("message")
    state = _coach_state()
    state.setdefault("reviews", []).insert(0, local)
    state["reviews"] = state["reviews"][:60]
    _save_coach_state(state)
    with SETTINGS_LOCK:
        SETTINGS_STATE.setdefault("aiCoach", {})["lastReview"] = {"period": period, "generatedAt": local.get("generatedAt"), "summary": local.get("summary"), "provider": local.get("provider")}
        _save_settings("ai_performance_review")
    return local


@app.post("/api/ai/optimisation/apply")
def ai_optimisation_apply(payload: dict[str, Any] = Body(default={})):
    review = payload.get("review") if isinstance(payload.get("review"), dict) else None
    if not review:
        review = _build_local_coach_review(str(payload.get("period") or "daily"))
    fixes = review.get("recommendedFixes") if isinstance(review.get("recommendedFixes"), list) else []
    if not fixes:
        return {"ok": False, "message": "No safe recommended fixes to apply."}
    with SETTINGS_LOCK:
        snap = _settings_snapshot("before_ai_fix")
        _remember_rollback_snapshot(snap, "ai_optimisation_apply")
        applied = []
        allowed = set((SETTINGS_STATE.get("aiCoach") or {}).get("safePatchPaths") or [])
        for f in fixes:
            if not isinstance(f, dict): continue
            path = str(f.get("path") or "")
            if path not in allowed: continue
            old = _path_get(SETTINGS_STATE, path)
            new = _clamp_patch(path, f.get("to", f.get("value")))
            if old == new: continue
            _path_set(SETTINGS_STATE, path, new)
            applied.append({"path": path, "from": old, "to": new, "reason": f.get("reason", "")})
        if not applied:
            return {"ok": False, "message": "All fixes were rejected by safety clamps or made no change."}
        SETTINGS_STATE.setdefault("aiCoach", {})["lastAppliedFix"] = {"appliedAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "snapshotId": snap["id"], "patches": applied, "period": review.get("period")}
        _save_settings("ai_optimisation_apply")
        applied_record = deepcopy(SETTINGS_STATE["aiCoach"]["lastAppliedFix"])
    state = _coach_state(); state.setdefault("applied", []).insert(0, applied_record); state["applied"] = state["applied"][:50]; _save_coach_state(state)
    notification_sent = True
    notification_error = ""
    try:
        _management_alert("AI optimisation applied", f"Applied {len(applied)} safe setting fix(es). Rollback snapshot: {snap['id']}", "success")
    except Exception as exc:
        notification_sent = False
        notification_error = str(exc)
        RUNTIME_HEALTH.fail("management_alert", exc, operation="ai_optimisation_applied")
        LOGGER.warning("AI optimisation applied but notification failed: %s", exc, exc_info=True)
    return {"ok": True, "applied": applied, "rollbackSnapshot": snap["id"], "settings": _safe_public_settings(SETTINGS_STATE), "notificationSent": notification_sent, "notificationError": notification_error}


@app.post("/api/ai/optimisation/rollback")
def ai_optimisation_rollback(payload: dict[str, Any] = Body(default={})):
    rb = (SETTINGS_STATE.get("aiCoach", {}) or {}).get("lastRollbackSnapshot") if isinstance(SETTINGS_STATE.get("aiCoach", {}), dict) else {}
    sid = str(payload.get("snapshotId") or (rb or {}).get("snapshotId") or (SETTINGS_STATE.get("aiCoach", {}).get("lastAppliedFix") or {}).get("snapshotId") or "")
    expected = payload.get("expectedRevision")
    explicit_sid = str(payload.get("snapshotId") or "")
    if explicit_sid and not re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,127}", explicit_sid):
        return {"ok": False, "blocked": True, "message": "Invalid rollback snapshot identifier."}
    file = CONFIG_SNAPSHOTS_DIR / f"{sid}.json" if sid else None
    if not sid or not file.exists():
        try:
            candidates = sorted(CONFIG_SNAPSHOTS_DIR.glob("*.json"), key=lambda x: x.stat().st_mtime, reverse=True)
        except Exception:
            candidates = []
        if not candidates:
            return {"ok": False, "message": "No rollback snapshot exists yet. Any Save, AI Fix or Import creates one first."}
        file = candidates[0]
        sid = file.stem
    try:
        snap = json.loads(file.read_text(encoding="utf-8"))
        old = snap.get("settings")
        if not isinstance(old, dict):
            raise ValueError("snapshot has no settings object")
        with SETTINGS_LOCK:
            prior = deepcopy(SETTINGS_STATE)
            receipt = _commit_settings_candidate(
                _strip_runtime_settings_keys(old),
                reason="rollback",
                prior_state=prior,
                expected_revision=int(expected) if expected is not None else None,
                apply_runtime=True,
            )
        state = _coach_state(); state.setdefault("rollbacks", []).insert(0, {"snapshotId": sid, "rolledBackAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())}); _save_coach_state(state)
        public = _safe_public_settings(SETTINGS_STATE); public["mt5"] = mt5_bridge.status(); public["settingsRevision"] = _settings_revision()
        return {"ok": True, "message": f"Rolled back to {sid}", "settings": public, "revision": receipt.get("revision"), "saveReceipt": receipt}
    except SettingsConflictError as exc:
        return JSONResponse({"ok": False, "conflict": True, "message": str(exc), "currentRevision": exc.current}, status_code=409)
    except ValueError as exc:
        return JSONResponse({"ok": False, "message": f"Rollback rejected: {exc}"}, status_code=422)
    except Exception as exc:
        return JSONResponse({"ok": False, "message": f"Rollback failed and current settings were retained: {exc}"}, status_code=500)




@app.get("/api/config/rollback-snapshots")
def config_rollback_snapshots():
    items = []
    try:
        for f in sorted(CONFIG_SNAPSHOTS_DIR.glob("*.json"), key=lambda x: x.stat().st_mtime, reverse=True)[:25]:
            try:
                data = json.loads(f.read_text(encoding="utf-8"))
                items.append({"id": data.get("id") or f.stem, "label": data.get("label", "snapshot"), "createdAt": data.get("createdAt"), "metrics": data.get("metrics", {})})
            except Exception:
                items.append({"id": f.stem, "label": "snapshot", "createdAt": "unknown"})
    except Exception as _suppressed_exc:
        _report_suppressed_exception("suppressed_exception_line_12210", _suppressed_exc)
    return {"ok": True, "items": items}

@app.get("/api/config/export")
def config_export(include_secrets: bool = False):
    # GET exports are always safe to download/cache/share. Secrets can only be
    # re-entered through the protected settings write path; a query parameter
    # must never turn a read endpoint into a credential exfiltration endpoint.
    cfg = _safe_public_settings(_strip_runtime_settings_keys(SETTINGS_STATE))
    return {"ok": True, "schema": "godmode.config.v2", "exportedAt": time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime()), "version": BUILD_ID, "settings": cfg, "secretsIncluded": False, "includeSecretsIgnored": bool(include_secrets)}


@app.post("/api/config/import")
def config_import(payload: dict[str, Any] = Body(...)):
    expected = payload.get("expectedRevision") if isinstance(payload, dict) else None
    data = payload.get("settings") if isinstance(payload, dict) and isinstance(payload.get("settings"), dict) else payload
    if not isinstance(data, dict):
        return JSONResponse({"ok": False, "message": "Invalid config: expected a settings object or {settings:{...}}."}, status_code=422)
    allowed_roots = {"appearance","trading","execution","ai","automation","risk","pyramiding","notifications","telegram","mobile","dataFeeds","aiProvider","aiAuditor","mt5Connection","strategyLab","brokerCosts","validation","aiCoach","tradingModes"}
    stripped = _strip_runtime_settings_keys(data)
    patch = _drop_blank_secrets({k:v for k,v in stripped.items() if k in allowed_roots})
    ignored = sorted(set(stripped.keys()) - allowed_roots)
    applied = sorted(patch.keys())
    if not applied:
        return JSONResponse({"ok": False, "message": f"Nothing imported; no recognised sections found. Ignored: {', '.join(ignored) or 'none'}.", "appliedSections": [], "ignoredSections": ignored}, status_code=422)
    snap = _settings_snapshot("before_config_import")
    try:
        receipt = _commit_settings_patch(patch, reason="config_import", expected_revision=int(expected) if expected is not None else None)
        _remember_rollback_snapshot(snap, "config_import")
        public = _safe_public_settings(SETTINGS_STATE); public["mt5"] = mt5_bridge.status(); public["settingsRevision"] = _settings_revision()
        msg = f"Config imported: {len(applied)} section(s) applied."
        if ignored:
            msg += f" Ignored (not importable): {', '.join(ignored)}."
        return {"ok": True, "message": msg, "appliedSections": applied, "ignoredSections": ignored, "rollbackSnapshot": snap["id"], "settings": public, "revision": receipt.get("revision"), "saveReceipt": receipt}
    except SettingsConflictError as exc:
        return JSONResponse({"ok": False, "conflict": True, "message": str(exc), "currentRevision": exc.current}, status_code=409)
    except ValueError as exc:
        return JSONResponse({"ok": False, "message": f"Config rejected: {exc}"}, status_code=422)
    except Exception as exc:
        return JSONResponse({"ok": False, "message": f"Config import failed and was rolled back: {exc}"}, status_code=500)


