@app.post("/api/config/library/apply")
def config_library_apply(payload: dict[str, Any] = Body(default={})):
    cid = str(payload.get("id") or "")
    prof = next((c for c in _config_library_all() if c.get("id") == cid), None)
    if not prof:
        return {"ok": False, "message": f"Unknown config profile: {cid}"}
    review = {"period":"library", "recommendedFixes":[{"path": p.get("path"), "to": p.get("value"), "reason": f"Config profile: {prof.get('name')}"} for p in prof.get("patches", [])]}
    res = ai_optimisation_apply({"review": review})
    if res.get("ok"):
        with SETTINGS_LOCK:
            SETTINGS_STATE.setdefault("aiCoach", {})["activeConfigId"] = cid
            _save_settings("config_library_apply")
        res["activeConfigId"] = cid
        res["profile"] = prof
    return res


