    cid = "custom_" + str(int(time.time()))
    paths = (SETTINGS_STATE.get("aiCoach") or {}).get("safePatchPaths") or []
    patches = [{"path": path, "value": _path_get(SETTINGS_STATE, path)} for path in paths if _path_get(SETTINGS_STATE, path) is not None]
    item = {"id": cid, "name": name, "description": str(payload.get("description") or "Saved from current safe optimisation settings")[:200], "regimes": ["custom"], "patches": patches}
    with SETTINGS_LOCK:
        SETTINGS_STATE.setdefault("aiCoach", {}).setdefault("configLibrary", []).append(item)
        _save_settings("config_library_save_current")
    return {"ok": True, "item": item, "items": _config_library_all()}



